window.__IMAGE_PRIVACY_SITE__={"locales":[{"code":"zh-Hans","name":"简体中文","appName":"图片打码"},{"code":"zh-Hant","name":"繁體中文","appName":"照片打碼"},{"code":"en-US","name":"English","appName":"Face Blur"},{"code":"fr","name":"Français","appName":"Flou photo"},{"code":"de","name":"Deutsch","appName":"Fotos zensieren"},{"code":"it","name":"Italiano","appName":"Sfoca foto"},{"code":"es-ES","name":"Español","appName":"Difumina fotos"},{"code":"pt-BR","name":"Português (Brasil)","appName":"Desfocar Fotos"},{"code":"pt-PT","name":"Português (Portugal)","appName":"Desfocar Fotos"},{"code":"ja","name":"日本語","appName":"写真ぼかし"},{"code":"ko","name":"한국어","appName":"사진 블러"},{"code":"ru","name":"Русский","appName":"Размытие фото"},{"code":"tr","name":"Türkçe","appName":"Fotoğraf Sansür"},{"code":"ar","name":"العربية","appName":"تمويه الصور","direction":"rtl"},{"code":"nl","name":"Nederlands","appName":"Foto vervagen"},{"code":"sv","name":"Svenska","appName":"Sudda foton"},{"code":"nb","name":"Norsk","appName":"Slør bilder"},{"code":"da","name":"Dansk","appName":"Slør fotos"},{"code":"pl","name":"Polski","appName":"Rozmycie zdjęć"},{"code":"id","name":"Bahasa Indonesia","appName":"Buramkan Foto"},{"code":"th","name":"ไทย","appName":"เบลอรูป"},{"code":"hi","name":"हिन्दी","appName":"फोटो ब्लर"},{"code":"ms","name":"Bahasa Melayu","appName":"Kaburkan Foto"},{"code":"vi","name":"Tiếng Việt","appName":"Làm Mờ Ảnh"},{"code":"fi","name":"Suomi","appName":"Sumenna kuva"},{"code":"ca","name":"Català","appName":"Difumina fotos"},{"code":"cs","name":"Čeština","appName":"Rozmaž fotky"},{"code":"hr","name":"Hrvatski","appName":"Zamagli foto"},{"code":"ro","name":"Română","appName":"Estompează poze"},{"code":"bn","name":"বাংলা","appName":"ফটো ব্লার"},{"code":"sk","name":"Slovenčina","appName":"Rozmaž fotky"},{"code":"sl","name":"Slovenščina","appName":"Zamegli foto"},{"code":"uk","name":"Українська","appName":"Розмиття фото"},{"code":"he","name":"עברית","appName":"טשטוש תמונות","direction":"rtl"},{"code":"el","name":"Ελληνικά","appName":"Θόλωσε φωτό"},{"code":"hu","name":"Magyar","appName":"Fotók elmosása"},{"code":"ta","name":"தமிழ்","appName":"பட மங்கல்"},{"code":"te","name":"తెలుగు","appName":"ఫోటో బ్లర్"},{"code":"mr","name":"मराठी","appName":"फोटो ब्लर"},{"code":"ur","name":"اردو","appName":"فوٹو بلر","direction":"rtl"}],"content":{"en-US":{"linkLabels":{"appleEula":"Apple Standard End User License Agreement","appleCancel":"Apple subscription cancellation","googleManage":"Google Play subscription management","appleRefund":"Apple refund request","googleRefund":"Google Play refund request"},"nav":{"privacy":"Privacy","terms":"Terms","support":"Support","language":"Language","chooseLanguage":"Choose display language","navigationLabel":"Main navigation"},"home":{"eyebrow":"{appName} · Privacy first","title":"Your privacy stays on your device.","lead":"Image recognition, editing, and secure export are completed on your device. This site provides clear privacy, terms, and support information.","points":["On-device recognition","No account","Secure export"],"cards":[{"title":"Privacy Policy","description":"Learn about photo permissions, on-device processing, temporary files, purchases, and support emails.","action":"View policy"},{"title":"Terms of Use","description":"Learn about Premium, auto-renewal, restoring purchases, cancellations, and refunds.","action":"View terms"},{"title":"Need help?","description":"Browse common questions or contact us by email.","action":"Get support"}]},"footer":{"privacy":"Privacy","terms":"Terms","support":"Support"},"privacy":{"title":"Privacy Policy","lead":"This policy explains how {appName} handles on-device images, app-store purchases, and support emails.","sections":[{"title":"1. Scope and contact","paragraphs":["This Privacy Policy applies to the iOS, iPadOS, and Android versions of {appName}, as well as this privacy, terms, and support website.","For privacy questions, email {email}."]},{"title":"2. Images are processed on your device","callout":{"title":"Your images are not uploaded to our servers.","body":"Image selection, OCR, sensitive-content detection, editing, and export are performed on your device. The App has no cloud image recognition, cloud sync, or account service."},"paragraphs":["When you export, the App creates a new image and removes removable privacy metadata, including EXIF, GPS, embedded text or OCR data, original thumbnails, and editing data. Your original image is not changed or overwritten.","If an image you explicitly select is stored in iCloud Photos or another system cloud-media service, the system photo framework may retrieve it over a network. This is not an upload by the App or cloud-based recognition."]},{"title":"3. Temporary files and technical records","paragraphs":["During recognition and editing, the App may keep necessary working files in a private temporary area on your device. Relevant temporary images and recoverable editing data are cleared after a successful save, when you abandon editing, or when the session ends. If saving fails, necessary state may remain so you can retry.","For operation and troubleshooting, the App may keep minimal technical information locally, such as rule, system, and OCR-engine versions, processing time, and error codes that do not contain original text. These records do not contain original images, complete OCR text, sensitive text, payment credentials, or store-account information, and are not used for advertising, profiling, or tracking."]},{"title":"4. Permissions","paragraphs":["The photo permission is used to show and process images you authorize. Camera permission is requested only when you choose to take a photo in the App. Permission to save to your photo library is requested only when you confirm export and have valid Premium access.","The App does not request location, contacts, microphone, Bluetooth, or notification permissions. You can change permissions in system settings at any time."]},{"title":"5. Purchases and store services","paragraphs":["The App uses Apple StoreKit or Google Play Billing to offer products, show store-provided localized prices, complete purchases, restore purchases, manage subscriptions, and confirm Premium access.","Apple and Google respectively handle store accounts, payments, billing, transaction records, refunds, and subscriptions. The App does not receive or store full payment-card information, store-account passwords, or other payment credentials. App Store and Google Play purchases are separate and cannot be moved or restored across platforms."]},{"title":"6. Advertising, tracking, analytics, and this website","paragraphs":["The App does not include advertising, attribution, behavioral analytics, third-party analytics, third-party crash reporting, or third-party tracking SDKs. This website has no advertising or analytics cookies and no traffic-analysis or tracking scripts."]},{"title":"7. Support emails","paragraphs":["We receive your email address, message, and any screenshots, recordings, order numbers, or attachments only when you choose to contact support. We use them only to handle your request, not for advertising or marketing. Do not send passwords, payment passwords, full card details, or unnecessary private images.","Support emails are retained for as long as needed to handle a request and meet necessary recordkeeping needs. You may request deletion of support emails we still hold."]},{"title":"8. Deletion, children, and updates","paragraphs":["Uninstalling the App can remove App data on your device. Exported images must be deleted from your photo library by you. Uninstalling does not cancel subscriptions or delete transaction records held by Apple or Google.","The App does not require an account and does not build profiles of children or other users through advertising or behavioral analytics. If a parent or guardian believes that a child provided personal information through support email, they may contact us to request deletion.","If image processing, permissions, payment methods, website hosting, or applicable platform rules change, we will update this policy and its date and provide additional notice where required."]}]},"terms":{"title":"Terms of Use","lead":"These terms explain {appName}'s on-device processing, Premium, auto-renewal, restoring purchases, cancellations, and refunds.","sections":[{"title":"1. Acceptance and platform rules","paragraphs":["By downloading, purchasing, or using {appName}, you agree to these terms and the rules that apply through the App Store or Google Play where you make a purchase. If you do not agree, do not continue to use or purchase the App.","The iOS and iPadOS versions are also subject to Apple's applicable license terms."],"links":["appleEula"]},{"title":"2. License","paragraphs":["Subject to these terms and platform rules, you may install and use the App on devices you own or control. This limited, non-exclusive, non-transferable license does not transfer ownership of the App, software, icon, text, or other content.","You must have the right to process each image you select, take, or export, and are responsible for violations of another person's privacy, likeness, intellectual-property, or other rights."]},{"title":"3. On-device processing and Premium","paragraphs":["Recognition, editing, cropping, stickers, watermarks, and manual redaction have no usage limits. Saving an exported image requires valid Premium access.","The App offers weekly and monthly auto-renewing subscriptions and a one-time lifetime purchase. Actual prices, currency, taxes, billing periods, availability, and regions are those shown and confirmed in the App Store or Google Play purchase interface. The App has no free trial or unlisted paid plan."]},{"title":"4. Auto-renewal and cancellation","paragraphs":["Weekly and monthly subscriptions renew and are charged for the period shown in the store purchase interface until you cancel through the purchasing platform. Deleting the App does not cancel a subscription. Unless the store provides a refund or other treatment, you can normally use the subscription through the end of the paid period after cancellation."],"links":["appleCancel","googleManage"]},{"title":"5. Purchases, restoration, and refunds","paragraphs":["Premium access is granted only after the App Store or Google Play confirms a valid transaction. Canceled, failed, or pending transactions do not grant access before successful confirmation.","Restore Purchases can restore only restorable lifetime access or a currently active subscription from the original purchasing platform. App Store purchases can be restored only in the App Store, and Google Play purchases only in Google Play; access cannot be transferred, assigned, or restored between them.","Refunds are handled by the store that completed the transaction under its rules, purchase region, and applicable law. Premium access is removed if the store confirms a refund or revocation, the subscription expires, or the transaction becomes invalid."],"links":["appleRefund","googleRefund"]},{"title":"6. Offline use and availability","paragraphs":["Image recognition, editing, and export are performed on your device. Retrieving system cloud photos, loading products, purchasing, restoring purchases, and confirming subscription status may require a network connection and the relevant app-store service.","Device, system, network, store-service, or image-file issues can temporarily make some functions unavailable. The App does not create, extend, or transfer Premium access if a store cannot confirm it."]},{"title":"7. Appropriate use, updates, and limitation of liability","paragraphs":["Do not use the App for unlawful activities, bypass purchase verification, interfere with or damage the App, distribute malicious code, copy, distribute, reverse engineer, or attempt to obtain source code without permission, or infringe the rights in App content, user images, or another person.","You may stop using and uninstall the App at any time. We may release updates to fix issues, improve stability, adapt to systems, or meet platform requirements.","To the extent permitted by applicable law, the App is provided as is and as available. These terms do not exclude liability that cannot lawfully be excluded or limit mandatory consumer rights. We may update these terms and their date if features, payment methods, platform rules, or applicable law change, and will provide additional notice where required. For questions, email {email}."]}]},"support":{"title":"Support","lead":"Check the common questions first. If your issue remains unresolved, contact us by email.","emailTitle":"{appName} support email","emailLead":"You can email us about permissions, saving, purchases, restoring purchases, privacy, or language display.","beforeEmail":{"title":"When you contact us","paragraphs":["Please include your platform, device model, system version, and App version; the steps before the issue; and the expected and actual result. If needed, attach a screenshot or recording with private information redacted.","For purchase issues, you may provide the store order number. Do not send account passwords, payment passwords, full card details, original images, or unredacted sensitive images."]},"faqs":[{"question":"Are images uploaded to a server?","answer":"No. Image selection, OCR, sensitive-content detection, editing, and export are performed on your device. A system service may retrieve a cloud image you explicitly selected, but this is not an App upload or cloud recognition."},{"question":"Which permissions does the App need?","answer":"Photo permission is for images you authorize; camera permission is used only when you choose to take a photo; and photo-library save permission is requested only when you confirm export. You can change permissions in system settings."},{"question":"Why does export require Premium?","answer":"Recognition and editing have no usage limits. Valid Premium access is required only when you choose Save Now to export the processed image."},{"question":"My purchase succeeded but Premium is missing.","answer":"Check your network and store service, use the original purchasing account, and select Restore Purchases in the App's Premium or purchase screen. If the issue continues, email your platform, App version, and order number; do not buy again."},{"question":"How do I manage or cancel a subscription?","answer":"Manage an active subscription through the system subscription-management entry in App settings or the Apple or Google Play help pages. Deleting the App does not cancel a subscription."},{"question":"Why did saving fail?","answer":"Check available device storage, photo-library save permission, and whether the original image can still be read, then retry. A failed save does not clear the current edit. If it continues, email a redacted error screenshot and steps to reproduce."},{"question":"Which image formats are supported?","answer":"{appName} processes one still image at a time and supports most common image formats. Availability of some formats can depend on the device and system version. Video, PDF, RAW/DNG, and batch processing are not currently supported."},{"question":"How do I delete data?","answer":"Uninstalling the App can remove App data on the device; exported images must be deleted from the system photo library by you. Uninstalling does not cancel a subscription or remove Apple or Google purchase records. Email us to request deletion of support emails we still hold."}],"officialHelpTitle":"Official purchase help"}},"zh-Hant":{"linkLabels":{"appleEula":"Apple 標準最終使用者授權協議","appleCancel":"Apple 取消訂閱說明","googleManage":"Google Play 訂閱管理說明","appleRefund":"Apple 退款申請說明","googleRefund":"Google Play 退款申請說明"},"nav":{"privacy":"隱私政策","terms":"使用條款","support":"支持","language":"語言","chooseLanguage":"選擇顯示語言","navigationLabel":"主要導覽"},"home":{"eyebrow":"{appName} · Privacy first","title":"隱私，留在你的裝置裡。","lead":"圖片識別、編輯和安全匯出均在裝置本地完成。這裡提供清晰的隱私說明、使用條款和支持資訊。","points":["本地識別","無帳號","安全匯出"],"cards":[{"title":"隱私政策","description":"了解照片權限、本地處理、暫存檔案、購買和支持郵件。","action":"查看政策"},{"title":"使用條款","description":"了解 Premium、自動續訂、恢復購買、取消訂閱和退款。","action":"查看條款"},{"title":"需要幫助？","description":"查看常見問題，或透過支持郵箱聯絡我們。","action":"獲得支持"}]},"footer":{"privacy":"隱私","terms":"條款","support":"支持"},"privacy":{"title":"隱私政策","lead":"本政策說明 {appName} 如何處理裝置本地圖片、應用商店購買資訊和支持郵件。","sections":[{"title":"1. 適用範圍與聯絡","paragraphs":["本隱私政策適用於 {appName} App 的 iOS、iPadOS 和 Android 版本，以及本隱私、條款與支持網站。","如有隱私問題，請發送郵件至 {email}。"]},{"title":"2. 圖片在裝置本地處理","callout":{"title":"你的圖片不會上傳到我們的伺服器。","body":"圖片選擇、OCR 文字識別、敏感內容識別、編輯和匯出均在裝置本地完成。App 不提供雲端圖片識別、雲端同步或帳號。"},"paragraphs":["匯出時，App 會建立一張新圖片，並清除可清除的 EXIF、GPS、嵌入文字／OCR 資料、原始縮圖和編輯資料等隱私中繼資料。原圖不會被修改或覆寫。","如你明確選擇的照片僅儲存於 iCloud Photos 或系統雲端媒體中，系統照片框架可能需要連網取回原圖；這不是 App 上傳圖片或雲端識別。"]},{"title":"3. 本地暫存檔案與技術記錄","paragraphs":["識別和編輯期間，App 可在裝置私有暫存區域儲存必要工作檔案。儲存成功、放棄編輯或本次工作階段結束後，相關暫存圖片和可復原編輯資料會被清除。儲存失敗時會保留必要狀態，以便重試。","為運作和排查問題，App 可在裝置本地記錄最少技術資訊，例如規則版本、系統版本、OCR 引擎版本、處理耗時和不包含原文的錯誤原因碼。這些記錄不包含原圖、完整 OCR 文字、敏感文字、付款憑據或商店帳號資訊，也不會用於廣告、行為分析或追蹤。"]},{"title":"4. 權限","paragraphs":["照片存取權限用於顯示你授權的照片、選擇圖片並在本地處理；相機權限只在你主動使用 App 內相機拍攝圖片時請求；儲存到照片圖庫的權限只在你確認匯出且擁有有效 Premium 權益後儲存新圖片時請求。","App 不請求位置、聯絡人、麥克風、藍牙或通知權限。你可隨時在系統設定中修改權限。"]},{"title":"5. 購買與商店服務","paragraphs":["App 使用 Apple StoreKit 或 Google Play Billing 提供商品、顯示商店回傳的本地化價格、完成購買、恢復購買、管理訂閱和確認 Premium 權益。","Apple 或 Google 分別負責商店帳號、付款、帳單、交易記錄、退款和訂閱服務。App 不接收或儲存完整支付卡資訊、商店帳號密碼或其他付款憑據。App Store 與 Google Play 的購買彼此獨立，不能跨平台轉移或恢復。"]},{"title":"6. 廣告、追蹤、統計與網站","paragraphs":["App 不接入廣告、行為分析、歸因、第三方統計、第三方崩潰分析或第三方使用者追蹤 SDK。本網站不設定廣告或分析 Cookie，也不包含流量統計或追蹤腳本。"]},{"title":"7. 支持郵件","paragraphs":["只有當你主動發送支持郵件時，我們才會收到你的郵箱地址、郵件內容，以及你自願附上的截圖、錄影、訂單號或其他附件。這些資訊只用於處理支持請求，不用於廣告或行銷。請勿發送帳號密碼、支付密碼、完整銀行卡資訊，或不必要的私人圖片。","支持郵件會在處理請求和必要留檔所需期間保留。你可申請刪除我們仍持有的支持郵件。"]},{"title":"8. 刪除、兒童與更新","paragraphs":["解除安裝 App 可刪除裝置內的 App 資料；已匯出到系統相簿的圖片需在相簿中自行刪除。解除安裝 App 不會取消訂閱，也不會刪除 Apple 或 Google 儲存的交易記錄。","App 不要求註冊帳號，也不透過廣告或行為分析建立兒童或其他使用者的輪廓。若家長或監護人認為兒童透過支持郵件提供了個人資訊，可以聯絡我們處理刪除請求。","如圖片處理方式、權限、付款方式、網站託管安排或適用平台規則發生變化，我們會更新本政策和頁面日期；如適用規則要求，也會提供額外通知。"]}]},"terms":{"title":"使用條款","lead":"本條款說明 {appName} 的本地處理、Premium、自動續訂、恢復購買、取消和退款規則。","sections":[{"title":"1. 接受條款與平台規則","paragraphs":["下載、購買或使用 {appName}，即表示你同意本條款以及購買所在 App Store 或 Google Play 對你適用的規則。若你不同意，請不要繼續使用或購買。","iOS／iPadOS 版本還適用 Apple 的相關許可條款。"],"links":["appleEula"]},{"title":"2. 使用許可","paragraphs":["在遵守本條款和平台規則的前提下，你可以在自己擁有或控制的裝置上安裝和使用 App。此許可是有限的、非獨占且不可轉讓的，不代表 App、軟體、圖示、文字或其他內容的所有權發生轉移。","你應確保自己有權處理所選擇、拍攝或匯出的圖片，並自行承擔違反他人隱私、肖像、智慧財產權或其他權利的責任。"]},{"title":"3. 本地處理與 Premium","paragraphs":["識別、編輯、裁切、貼圖、水印和手動遮擋不設次數或額度限制。儲存匯出需要有效 Premium 權益。","App 提供按週自動續訂訂閱、按月自動續訂訂閱和一次性購買的終身權益。實際價格、幣別、稅費、計費週期、可購買性和適用地區，以 App Store 或 Google Play 系統購買介面顯示並由你確認的資訊為準。App 不提供免費試用或其他未列出的付費方案。"]},{"title":"4. 自動續訂與取消","paragraphs":["週訂閱和月訂閱會按商店購買介面顯示的週期自動續訂並收費，直到你在購買平台取消。刪除 App 不會自動取消訂閱。除非購買平台另有退款或其他處理，取消後你通常仍可使用訂閱至目前已付費週期結束。"],"links":["appleCancel","googleManage"]},{"title":"5. 購買、恢復購買與退款","paragraphs":["只有 App Store 或 Google Play 確認有效交易後，App 才會授予 Premium 權益。取消、失敗或待處理交易在確認成功前不授予權益。","恢復購買只能恢復原購買平台中可恢復的終身權益或目前有效訂閱。App Store 購買只能在 App Store 中恢復；Google Play 購買只能在 Google Play 中恢復；兩邊權益不能跨平台遷移、轉讓或恢復。","退款由完成交易的應用商店依其規則、購買地區和適用法律處理。商店確認退款、撤銷、訂閱到期或交易失效後，對應 Premium 權益會被移除。"],"links":["appleRefund","googleRefund"]},{"title":"6. 離線使用與可用性","paragraphs":["圖片識別、編輯和匯出在裝置本地完成。系統雲端照片取回、商品載入、購買、恢復購買和訂閱狀態確認可能需要網路及對應應用商店服務。","裝置、系統、網路、商店服務或圖片檔案本身的問題，可能使部分功能暫時不可用。App 不會在商店無法確認時自行建立、延長或轉移 Premium 權益。"]},{"title":"7. 合理使用、更新與責任限制","paragraphs":["不得利用 App 從事違法活動、繞過購買驗證、干擾或破壞 App、傳播惡意程式碼、未經許可複製、散布、反編譯或試圖取得 App 原始碼，或侵犯 App 內容、使用者圖片或他人的權利。","你可隨時停止使用並解除安裝 App。我們可能為修復問題、提升穩定性、適配系統或滿足平台要求發布更新。","在適用法律允許的範圍內，App 按現狀和可用狀態提供。本條款不排除法律不得排除的責任，也不限制你依法享有的強制性消費者權利。如產品功能、付款方式、平台規則或適用法律發生變化，我們可能更新本條款和頁面日期；如變化實質影響使用者權利，將按適用要求提供額外通知。如有問題，請發送郵件至 {email}。"]}]},"support":{"title":"支持","lead":"先查看常見問題。問題仍未解決時，請透過支持郵箱聯絡我們。","emailTitle":"{appName} 支持郵箱","emailLead":"權限、儲存、購買、恢復購買、隱私或語言顯示問題都可以來信。","beforeEmail":{"title":"來信時請提供","paragraphs":["請提供使用的平台、裝置型號、系統版本和 App 版本；出現問題前的操作、預期結果和實際結果；必要時附上已遮擋私人資訊的截圖或錄影。","購買問題可以提供商店訂單號，但請勿發送帳號密碼、支付密碼、完整銀行卡資訊、原圖或未遮擋的敏感圖片。"]},"faqs":[{"question":"圖片會上傳到伺服器嗎？","answer":"不會。圖片選擇、OCR、敏感內容識別、編輯和匯出均在裝置本地完成。系統可能為你明確選擇的雲端照片取回原圖，但這不是 App 上傳圖片或雲端識別。"},{"question":"App 需要哪些權限？","answer":"照片權限用於選擇和讀取你授權的圖片；相機權限僅在你主動拍照時使用；儲存權限僅在確認匯出新圖片時請求。你可隨時在系統設定中修改權限。"},{"question":"為什麼匯出時需要 Premium？","answer":"圖片識別和編輯沒有次數限制。只有在你點擊「立即儲存」匯出處理後的新圖片時，才需要有效 Premium 權益。"},{"question":"購買成功後沒有顯示 Premium，怎麼辦？","answer":"先確認網路和商店服務可用，並使用原購買帳號。在 App 的 Premium 或購買頁面點擊「恢復購買」。如果問題持續，請郵件提供平台、App 版本和訂單號；請勿重複購買。"},{"question":"如何管理或取消訂閱？","answer":"有效訂閱可在 App 設定中透過系統訂閱管理入口處理，也可參閱 Apple 或 Google Play 的訂閱管理說明。刪除 App 不會自動取消訂閱。"},{"question":"為什麼儲存失敗？","answer":"請檢查裝置可用儲存空間、相簿儲存權限和原圖是否仍可讀取，然後重試。儲存失敗不會清空目前編輯狀態。如果仍失敗，請發送已遮擋的錯誤截圖和重現步驟。"},{"question":"支援哪些圖片格式？","answer":"{appName} 目前用於處理單張靜態圖片，支援大多數常見圖片格式。部分格式的可用性可能因裝置和系統版本而異。影片、PDF、RAW／DNG 和批次處理暫不支援。"},{"question":"如何刪除資料？","answer":"解除安裝 App 可刪除裝置內的 App 資料；已匯出的圖片需在系統相簿中自行刪除。解除安裝不會取消訂閱或刪除 Apple／Google 的購買記錄。若要刪除我們仍持有的支持郵件，請發送郵件說明。"}],"officialHelpTitle":"官方購買幫助"}},"ar":{"linkLabels":{"appleEula":"اتفاقية ترخيص المستخدم النهائي القياسية من Apple ‏(EULA)","appleCancel":"تعليمات إلغاء اشتراك Apple","googleManage":"تعليمات الإلغاء في Google Play","appleRefund":"اطلب استرداد المبلغ من شركة آبل","googleRefund":"معلومات استرداد الأموال في Google Play"},"nav":{"privacy":"سياسة الخصوصية","terms":"شروط الاستخدام","support":"الدعم","language":"لغة","chooseLanguage":"حدد لغة العرض","navigationLabel":"التنقل الرئيسي"},"home":{"eyebrow":"{appName} · Privacy first","title":"لا يتم تحميل صورك إلى خوادمنا.","lead":"يتم اختيار الصور والتعرّف الضوئي على النصوص واكتشاف المحتوى الحساس والتحرير والتصدير على الجهاز. لا يوفر التطبيق تعرّفًا سحابيًا على الصور أو مزامنة سحابية أو حسابات. عند التصدير، تُنشأ صورة جديدة وتُزال بيانات الخصوصية الوصفية القابلة للحذف. تُحذف ملفات العمل المؤقتة بعد الحفظ الناجح أو إلغاء التحرير أو انتهاء الجلسة؛ وإذا فشل الحفظ فقد تُحتفظ بالحالة اللازمة لإعادة المحاولة.","points":["بيانات التطبيق","المنتجات المدفوعة والأسعار","الدعم"],"cards":[{"title":"سياسة الخصوصية","description":"لا يتم تحميل صورك إلى خوادمنا.","action":"سياسة الخصوصية"},{"title":"شروط الاستخدام","description":"لا توجد حدود لاستخدام التعرّف أو التحرير. يتطلب تصدير الصورة المعالجة فقط صلاحية Premium سارية. يوفر التطبيق اشتراكًا أسبوعيًا وآخر شهريًا يتجددان تلقائيًا، وشراءً واحدًا لصلاحية مدى الحياة، من دون تجربة مجانية. مشتريات App Store وGoogle Play منفصلة ولا يمكن نقلها بين المنصتين.","action":"شروط الاستخدام"},{"title":"هل تحتاج إلى مساعدة؟","description":"ابدأ بالأسئلة الشائعة أدناه. وإذا استمرت المشكلة، فتواصل معنا عبر عنوان البريد الإلكتروني للدعم.","action":"الدعم"}]},"footer":{"privacy":"سياسة الخصوصية","terms":"شروط الاستخدام","support":"الدعم"},"privacy":{"title":"سياسة الخصوصية","lead":"توضح هذه السياسة كيفية تعامل {appName} مع البيانات الموجودة على الجهاز ومعلومات الشراء من متجر التطبيقات ورسائل الدعم.","sections":[{"title":"1. النطاق والتواصل","paragraphs":["تنطبق هذه السياسة على تطبيق {appName} لأنظمة iOS وiPadOS وAndroid، وعلى موقع الخصوصية والشروط والدعم هذا.","للاستفسارات المتعلقة بالخصوصية، يرجى مراسلتنا عبر البريد الإلكتروني. {email}"]},{"title":"2. بيانات التطبيق","callout":{"title":"لا يتم تحميل صورك إلى خوادمنا.","body":"يتم اختيار الصور والتعرّف الضوئي على النصوص واكتشاف المحتوى الحساس والتحرير والتصدير على الجهاز. لا يوفر التطبيق تعرّفًا سحابيًا على الصور أو مزامنة سحابية أو حسابات. عند التصدير، تُنشأ صورة جديدة وتُزال بيانات الخصوصية الوصفية القابلة للحذف. تُحذف ملفات العمل المؤقتة بعد الحفظ الناجح أو إلغاء التحرير أو انتهاء الجلسة؛ وإذا فشل الحفظ فقد تُحتفظ بالحالة اللازمة لإعادة المحاولة."},"paragraphs":[]},{"title":"3. الأذونات والإعلانات والتتبع","paragraphs":["يُستخدم الوصول إلى الصور فقط لعرض الصور التي تسمح بها ومعالجتها. تُستخدم الكاميرا فقط عندما تختار التقاط صورة داخل التطبيق. يُطلب إذن الحفظ في مكتبة الصور فقط عند تأكيد التصدير مع صلاحية Premium سارية. لا يطلب التطبيق الموقع أو جهات الاتصال أو الميكروفون أو Bluetooth أو الإشعارات.","لا يستخدم معرّفًا إعلانيًا أو يدمج حزم SDK تابعة لجهات خارجية للإعلانات أو التحليلات أو الإحالة أو الإبلاغ عن الأعطال.","لا يدمج التطبيق أداة تابعة لجهة خارجية للإبلاغ عن الأعطال. وفقًا لإعدادات جهازك ومتجرك، قد تعالج Apple أو Google معلومات تشخيص النظام بموجب قواعد الخصوصية الخاصة بكل منهما وتوفر معلومات تقنية تُستخدم للتحقيق في الأعطال أو مشكلات الأداء."]},{"title":"4. خدمات متجر التطبيقات والوصول إلى الشبكة","paragraphs":["يستخدم التطبيق Apple StoreKit أو Google Play Billing لتحميل المنتجات وعرض الأسعار المحلية التي يعيدها المتجر وإتمام عمليات الشراء واستعادتها وإدارة الاشتراكات وتأكيد الاستحقاقات. يُستخدم الوصول إلى الشبكة فقط لهذه الوظائف الرسمية لمتجر Apple أو Google.","تتولى Apple أو Google مسؤولية حسابات المتجر والمدفوعات والفوترة والمعاملات واسترداد الأموال وخدمات الاشتراك. لا يعالج التطبيق سوى معلومات المتجر اللازمة لتأكيد المنتجات والاستحقاقات، ولا يتلقى بيانات اعتماد الدفع الكاملة أو يحفظها."]},{"title":"5. رسائل الدعم والموقع الإلكتروني","paragraphs":["لا يقرأ التطبيق معلومات بريدك الإلكتروني تلقائيًا. لا تتلقى قناة الدعم عنوان بريدك الإلكتروني ورسالتك وأي لقطة شاشة أو تسجيل شاشة أو رقم طلب أو مرفق آخر تقدمه طواعية إلا عندما تختار إرسال رسالة دعم. تُستخدم هذه المعلومات فقط لمعالجة طلبك ولا تُستخدم للإعلانات أو التسويق. لا ترسل كلمات مرور الحساب أو الدفع أو أرقام البطاقات كاملة.","لا يعيّن هذا الموقع ملفات تعريف ارتباط للإعلانات أو التحليلات، ولا يتضمن تحليلات لحركة الزيارات أو نصوصًا برمجية للتتبع."]},{"title":"6. الاحتفاظ والحذف","paragraphs":["احذف البيانات الموجودة على الجهاز بإلغاء تثبيت التطبيق. وعلى Android يمكنك أيضًا استخدام خيار النظام «محو البيانات».","تدير Apple أو Google سجلات الشراء في المتجر. ويُعاد تأكيد الاستحقاقات القابلة للاستعادة وفقًا لقواعد المتجر.","يُحتفظ برسائل الدعم طوال المدة اللازمة لمعالجة الطلب والوفاء بمتطلبات حفظ السجلات الضرورية. يمكنك مراسلتنا لطلب حذف مراسلات الدعم التي ما زلنا نحتفظ بها."]},{"title":"7. أمن البيانات","paragraphs":["يستخدم التطبيق المعالجة على الجهاز والحد الأدنى من الأذونات ومسارات الشراء الرسمية لمتجر التطبيقات للحد من عمليات نقل البيانات غير الضرورية. لا تُستخدم رسائل الدعم إلا لمعالجة الطلبات الواردة، مع تطبيق ضمانات معقولة تناسب طبيعة المعلومات.","لا يمكن ضمان الأمان الكامل لأي جهاز أو شبكة أو وسيلة تخزين إلكترونية. لا تُضمّن معلومات حساسة غير مرتبطة في رسالة دعم."]},{"title":"8. الأطفال والمراهقون","paragraphs":["لا يتطلب التطبيق حسابًا ولا ينشئ ملفات تعريف للأطفال أو المستخدمين الآخرين من خلال الإعلانات أو التحليلات السلوكية. يمكن لولي الأمر أو الوصي الذي يعتقد أن طفلًا قدّم معلومات شخصية عبر رسالة دعم التواصل معنا لمعالجة الأمر."]},{"title":"9. خياراتك وحقوقك","paragraphs":["تدير البيانات الموجودة على الجهاز من خلال جهازك. وتدير Apple أو Google حسابات المتجر وسجلات الشراء. لا يستطيع التطبيق تعديل سجلات المعاملات التي يحتفظ بها متجر التطبيقات أو حذفها نيابةً عنك.","إذا تغيرت ممارسات بيانات التطبيق أو قواعد المنصة أو ترتيبات استضافة الموقع، فسنحدّث هذه السياسة والتاريخ الظاهر على هذه الصفحة، ونقدم إشعارًا إضافيًا عندما تتطلب القواعد المعمول بها ذلك.","للاستفسارات المتعلقة بالخصوصية، يرجى مراسلتنا عبر البريد الإلكتروني. {email}"]}]},"terms":{"title":"شروط الاستخدام","lead":"شروط استخدام {appName}.","sections":[{"title":"1. قبول هذه الشروط وقواعد المنصة","paragraphs":["بتحميل أو شراء أو استخدام تطبيق {appName}، فإنك توافق على هذه الشروط وعلى القواعد المطبقة عليك في متجر التطبيقات الذي أجريت فيه عملية الشراء. إذا كنت لا توافق، فلا تستمر في استخدام التطبيق أو إجراء أي عملية شراء.","تنطبق هذه الشروط على تنزيلك للتطبيق وشرائه واستخدامه. وتخضع نسختا iOS وiPadOS أيضًا لـ"],"links":["appleEula"]},{"title":"2. المنتجات المدفوعة والأسعار","paragraphs":["لا توجد حدود لاستخدام التعرّف أو التحرير. يتطلب تصدير الصورة المعالجة فقط صلاحية Premium سارية. يوفر التطبيق اشتراكًا أسبوعيًا وآخر شهريًا يتجددان تلقائيًا، وشراءً واحدًا لصلاحية مدى الحياة، من دون تجربة مجانية. مشتريات App Store وGoogle Play منفصلة ولا يمكن نقلها بين المنصتين.","السعر الفعلي والعملة والضرائب وفترة الفوترة وأهلية الشراء هي المعلومات التي تظهر ويجري تأكيدها على شاشة الشراء في نظام App Store أو Google Play. تفرض منصة الشراء الرسوم وتدير الدفع من خلال حسابك في المتجر. لا يقدم التطبيق فترة تجريبية مجانية للاشتراك أو خططًا مدفوعة أخرى."]},{"title":"3. التجديد التلقائي والإلغاء","paragraphs":["تتجدد الاشتراكات الأسبوعية والشهرية تلقائيًا وتُفرض رسوم فترة الفوترة الظاهرة على شاشة الشراء في النظام حتى تلغيها من خلال منصة الشراء. لا يؤدي حذف {appName} إلى إلغاء الاشتراك تلقائيًا. ما لم تقدم منصة الشراء استردادًا للأموال أو معالجة أخرى، يمكنك الاستمرار في استخدام الاشتراك حتى نهاية الفترة المدفوعة الحالية بعد إيقاف التجديد التلقائي."],"links":["appleCancel","googleManage"]},{"title":"4. عمليات الشراء والاستعادة واسترداد الأموال","paragraphs":["تُنجز عمليات الشراء واستعادتها من خلال متجر Apple أو Google الرسمي. لا يُمنح الاستحقاق إلا بعد أن يؤكد المتجر معاملة صالحة. لا تمنح المعاملات الملغاة أو الفاشلة أو المعلقة استحقاقًا قبل التأكيد الناجح. يمكن لاستعادة عمليات الشراء أن تعيد الوصول مدى الحياة والاشتراك النشط حاليًا. عمليات الشراء في App Store وGoogle Play منفصلة، ولا يمكن استعادتها أو نقلها بين المنصات.","يتولى متجر التطبيقات الذي أتم المعاملة عمليات استرداد الأموال وفقًا لقواعده ومنطقة الشراء والقانون المعمول به. يُزال الاستحقاق المقابل بعد أن يؤكد المتجر استرداد الأموال أو الإلغاء أو انتهاء الاشتراك أو عدم صلاحية المعاملة."],"links":["appleRefund","googleRefund"]},{"title":"5. الاستخدام دون اتصال والتوفر","paragraphs":["يتم اختيار الصور والتعرّف الضوئي على النصوص واكتشاف المحتوى الحساس والتحرير والتصدير على الجهاز. لا يوفر التطبيق تعرّفًا سحابيًا على الصور أو مزامنة سحابية أو حسابات. عند التصدير، تُنشأ صورة جديدة وتُزال بيانات الخصوصية الوصفية القابلة للحذف. تُحذف ملفات العمل المؤقتة بعد الحفظ الناجح أو إلغاء التحرير أو انتهاء الجلسة؛ وإذا فشل الحفظ فقد تُحتفظ بالحالة اللازمة لإعادة المحاولة."]},{"title":"6. الاستخدام المقبول والملكية الفكرية","paragraphs":["يجب ألا تستخدم التطبيق في نشاط غير قانوني، أو تتحايل على التحقق من الشراء، أو تضر بالتطبيق، أو توزع تعليمات برمجية ضارة، أو تنسخ التطبيق أو توزعه دون إذن، أو تنتهك الحقوق المتعلقة بمحتوى التطبيق أو الملكية الفكرية لشخص آخر.","يمكنك التوقف عن استخدام التطبيق وإلغاء تثبيته في أي وقت. وقد نصدر تحديثات لإصلاح المشكلات أو دعم أنظمة التشغيل أو تحسين الاستقرار أو استيفاء متطلبات المنصة. قد تجعل مشكلات الجهاز أو النظام أو الشبكة أو خدمة المتجر بعض الميزات غير متاحة مؤقتًا.","في حدود ما يسمح به القانون المعمول به، يُقدم التطبيق بحسب توفره. لا تستبعد هذه الشروط المسؤولية التي لا يجوز استبعادها قانونًا، ولا تحد من حقوق المستهلك الإلزامية المتاحة لك.","إذا تغيرت ميزات المنتج أو طرق الدفع أو قواعد المنصة أو القانون المعمول به، فقد نحدّث هذه الشروط والتاريخ الظاهر على الصفحة. وإذا أثر تغيير جوهريًا في حقوق المستخدمين، فسنقدم إشعارًا إضافيًا حسبما يلزم.","للاستفسار عن هذه الشروط، أو عمليات الشراء، أو استخدام التطبيق، يرجى مراسلتنا عبر البريد الإلكتروني. {email}"]}]},"support":{"title":"الدعم","lead":"ابدأ بالأسئلة الشائعة أدناه. وإذا استمرت المشكلة، فتواصل معنا عبر عنوان البريد الإلكتروني للدعم.","emailTitle":"البريد الإلكتروني للدعم {appName}","emailLead":"ابدأ بالأسئلة الشائعة أدناه. وإذا استمرت المشكلة، فتواصل معنا عبر عنوان البريد الإلكتروني للدعم.","beforeEmail":{"title":"ما يجب تضمينه في رسالتك","paragraphs":["في حال وجود مشكلة في الشراء، يمكنك تضمين رقم طلب متجر التطبيقات، لكن لا ترسل كلمة مرور حسابك أو الدفع أو بيانات البطاقة كاملة."],"bullets":["المنصة وطراز الجهاز وإصدار نظام التشغيل وإصدار التطبيق؛","ما فعلته قبل المشكلة وما توقعته وما حدث بالفعل؛ و","إذا لزم الأمر، لقطة شاشة أو تسجيل للشاشة مع إخفاء المعلومات الخاصة."]},"faqs":[{"question":"هل يتم تحميل الصور إلى خادم؟","answer":"يتم اختيار الصور والتعرّف الضوئي على النصوص واكتشاف المحتوى الحساس والتحرير والتصدير على الجهاز. لا يوفر التطبيق تعرّفًا سحابيًا على الصور أو مزامنة سحابية أو حسابات. عند التصدير، تُنشأ صورة جديدة وتُزال بيانات الخصوصية الوصفية القابلة للحذف. تُحذف ملفات العمل المؤقتة بعد الحفظ الناجح أو إلغاء التحرير أو انتهاء الجلسة؛ وإذا فشل الحفظ فقد تُحتفظ بالحالة اللازمة لإعادة المحاولة."},{"question":"الأذونات والإعلانات والتتبع","answer":"يُستخدم الوصول إلى الصور فقط لعرض الصور التي تسمح بها ومعالجتها. تُستخدم الكاميرا فقط عندما تختار التقاط صورة داخل التطبيق. يُطلب إذن الحفظ في مكتبة الصور فقط عند تأكيد التصدير مع صلاحية Premium سارية. لا يطلب التطبيق الموقع أو جهات الاتصال أو الميكروفون أو Bluetooth أو الإشعارات."},{"question":"المنتجات المدفوعة والأسعار","answer":"لا توجد حدود لاستخدام التعرّف أو التحرير. يتطلب تصدير الصورة المعالجة فقط صلاحية Premium سارية. يوفر التطبيق اشتراكًا أسبوعيًا وآخر شهريًا يتجددان تلقائيًا، وشراءً واحدًا لصلاحية مدى الحياة، من دون تجربة مجانية. مشتريات App Store وGoogle Play منفصلة ولا يمكن نقلها بين المنصتين."},{"question":"الحفظ وتنسيقات الصور","answer":"إذا فشل الحفظ، فتحقق من المساحة المتاحة وإذن الحفظ في مكتبة الصور وإمكانية قراءة الصورة الأصلية ثم أعد المحاولة. يعالج التطبيق صورة ثابتة واحدة في كل مرة ويدعم معظم التنسيقات الشائعة؛ وقد يعتمد بعضها على الجهاز وإصدار النظام. لا يدعم حاليًا الفيديو أو PDF أو RAW/DNG أو المعالجة المجمعة."},{"question":"كيف أغير اللغة؟","answer":"يدعم التطبيق 40 لغة ويمكن تغيير اللغة من إعداداته. إذا كان العرض غير صحيح، فأرسل لغة الجهاز واللغة المحددة في التطبيق بالبريد الإلكتروني."},{"question":"الاستعادة والإلغاء واسترداد الأموال","answer":"تُنجز عمليات الشراء واستعادتها من خلال متجر Apple أو Google الرسمي. لا يُمنح الاستحقاق إلا بعد أن يؤكد المتجر معاملة صالحة. لا تمنح المعاملات الملغاة أو الفاشلة أو المعلقة استحقاقًا قبل التأكيد الناجح. يمكن لاستعادة عمليات الشراء أن تعيد الوصول مدى الحياة والاشتراك النشط حاليًا. عمليات الشراء في App Store وGoogle Play منفصلة، ولا يمكن استعادتها أو نقلها بين المنصات."},{"question":"الخصوصية وحذف البيانات","answer":"احذف البيانات الموجودة على الجهاز بإلغاء تثبيت التطبيق. وعلى Android يمكنك أيضًا استخدام خيار النظام «محو البيانات». تدير Apple أو Google سجلات الشراء في المتجر. ويُعاد تأكيد الاستحقاقات القابلة للاستعادة وفقًا لقواعد المتجر. يُحتفظ برسائل الدعم طوال المدة اللازمة لمعالجة الطلب والوفاء بمتطلبات حفظ السجلات الضرورية. يمكنك مراسلتنا لطلب حذف مراسلات الدعم التي ما زلنا نحتفظ بها."}],"officialHelpTitle":"مساعدة سريعة"}},"bn":{"linkLabels":{"appleEula":"Apple-এর মানক শেষ ব্যবহারকারী লাইসেন্স চুক্তি (EULA)","appleCancel":"অ্যাপল সাবস্ক্রিপশন বাতিল করার নির্দেশাবলী","googleManage":"Google Play বাতিল করার নির্দেশনা","appleRefund":"অ্যাপলের কাছে রিফান্ডের জন্য অনুরোধ করুন","googleRefund":"Google Play অর্থ ফেরতের তথ্য"},"nav":{"privacy":"গোপনীয়তা নীতি","terms":"ব্যবহারের শর্তাবলী","support":"সহায়তা","language":"ভাষা","chooseLanguage":"প্রদর্শনের ভাষা নির্বাচন করুন","navigationLabel":"প্রাথমিক নেভিগেশন"},"home":{"eyebrow":"{appName} · Privacy first","title":"আপনার ছবি আমাদের সার্ভারে আপলোড করা হয় না।","lead":"ছবি নির্বাচন, OCR, সংবেদনশীল বিষয় শনাক্তকরণ, সম্পাদনা ও রপ্তানি ডিভাইসেই সম্পন্ন হয়। অ্যাপটি ক্লাউড ছবি শনাক্তকরণ, ক্লাউড সিঙ্ক বা অ্যাকাউন্ট দেয় না। রপ্তানির সময় নতুন ছবি তৈরি হয় এবং অপসারণযোগ্য ব্যক্তিগত মেটাডেটা মুছে ফেলা হয়। সফলভাবে সংরক্ষণ, সম্পাদনা বাতিল বা সেশন শেষ হওয়ার পর অস্থায়ী কাজের ফাইল মুছে যায়; সংরক্ষণ ব্যর্থ হলে আবার চেষ্টা করার জন্য প্রয়োজনীয় অবস্থা রাখা হতে পারে।","points":["অ্যাপের ডেটা","অর্থপ্রদত্ত পণ্য ও মূল্য","সহায়তা"],"cards":[{"title":"গোপনীয়তা নীতি","description":"আপনার ছবি আমাদের সার্ভারে আপলোড করা হয় না।","action":"গোপনীয়তা নীতি"},{"title":"ব্যবহারের শর্তাবলী","description":"শনাক্তকরণ ও সম্পাদনায় ব্যবহারের সীমা নেই। প্রক্রিয়া করা ছবি রপ্তানির জন্যই শুধু বৈধ Premium প্রয়োজন। বিনামূল্যের ট্রায়াল ছাড়া স্বয়ংক্রিয় নবায়নযোগ্য সাপ্তাহিক ও মাসিক সাবস্ক্রিপশন এবং এককালীন আজীবন ক্রয় রয়েছে। App Store ও Google Play-এর ক্রয় আলাদা এবং প্ল্যাটফর্মের মধ্যে স্থানান্তর করা যায় না।","action":"ব্যবহারের শর্তাবলী"},{"title":"সাহায্য প্রয়োজন?","description":"প্রথমে নিচের সাধারণ প্রশ্নগুলো দেখুন। সমস্যা থেকে গেলে সহায়তা ইমেল ঠিকানার মাধ্যমে আমাদের সঙ্গে যোগাযোগ করুন।","action":"সহায়তা"}]},"footer":{"privacy":"গোপনীয়তা নীতি","terms":"ব্যবহারের শর্তাবলী","support":"সহায়তা"},"privacy":{"title":"গোপনীয়তা নীতি","lead":"এই নীতিতে {appName} কীভাবে ডিভাইসে থাকা ডেটা, অ্যাপ স্টোরের কেনাকাটার তথ্য ও সহায়তা ইমেল পরিচালনা করে তা ব্যাখ্যা করা হয়েছে।","sections":[{"title":"1. পরিধি ও যোগাযোগ","paragraphs":["এই নীতি iOS, iPadOS ও Android-এর জন্য {appName} অ্যাপ এবং এই গোপনীয়তা, শর্তাবলি ও সহায়তা ওয়েবসাইটে প্রযোজ্য।","গোপনীয়তা সংক্রান্ত প্রশ্নের জন্য, ইমেল করুন {email}"]},{"title":"2. অ্যাপের ডেটা","callout":{"title":"আপনার ছবি আমাদের সার্ভারে আপলোড করা হয় না।","body":"ছবি নির্বাচন, OCR, সংবেদনশীল বিষয় শনাক্তকরণ, সম্পাদনা ও রপ্তানি ডিভাইসেই সম্পন্ন হয়। অ্যাপটি ক্লাউড ছবি শনাক্তকরণ, ক্লাউড সিঙ্ক বা অ্যাকাউন্ট দেয় না। রপ্তানির সময় নতুন ছবি তৈরি হয় এবং অপসারণযোগ্য ব্যক্তিগত মেটাডেটা মুছে ফেলা হয়। সফলভাবে সংরক্ষণ, সম্পাদনা বাতিল বা সেশন শেষ হওয়ার পর অস্থায়ী কাজের ফাইল মুছে যায়; সংরক্ষণ ব্যর্থ হলে আবার চেষ্টা করার জন্য প্রয়োজনীয় অবস্থা রাখা হতে পারে।"},"paragraphs":[]},{"title":"3. অনুমতি, বিজ্ঞাপন ও ট্র্যাকিং","paragraphs":["ফটো অ্যাক্সেস শুধু আপনার অনুমোদিত ছবি দেখানো ও প্রক্রিয়ার জন্য ব্যবহৃত হয়। অ্যাপে ছবি তোলার বিকল্প বেছে নিলেই কেবল ক্যামেরা ব্যবহার হয়। বৈধ Premium নিয়ে রপ্তানি নিশ্চিত করলেই কেবল ফটো লাইব্রেরিতে সংরক্ষণের অনুমতি চাওয়া হয়। অ্যাপটি অবস্থান, পরিচিতি, মাইক্রোফোন, Bluetooth বা বিজ্ঞপ্তির অনুমতি চায় না।","এটি বিজ্ঞাপন শনাক্তকারী ব্যবহার করে না এবং বিজ্ঞাপন, বিশ্লেষণ, অ্যাট্রিবিউশন বা ক্র্যাশ রিপোর্টিংয়ের জন্য তৃতীয় পক্ষের SDK সংযুক্ত করে না।","অ্যাপটি তৃতীয় পক্ষের ক্র্যাশ রিপোর্টিং টুল সংযুক্ত করে না। আপনার ডিভাইস ও স্টোর সেটিংস অনুযায়ী Apple বা Google তাদের নিজ নিজ গোপনীয়তা নিয়মের অধীনে সিস্টেমের রোগনির্ণয় তথ্য প্রক্রিয়া করতে এবং ক্র্যাশ বা কর্মক্ষমতার সমস্যা তদন্তে ব্যবহৃত কারিগরি তথ্য দিতে পারে।"]},{"title":"4. অ্যাপ স্টোর পরিষেবা ও নেটওয়ার্ক অ্যাক্সেস","paragraphs":["অ্যাপটি পণ্য লোড করা, স্টোর থেকে পাঠানো স্থানীয় মূল্য দেখানো, কেনাকাটা সম্পন্ন করা, কেনাকাটা পুনরুদ্ধার করা, সাবস্ক্রিপশন পরিচালনা করা এবং এনটাইটেলমেন্ট নিশ্চিত করার জন্য Apple StoreKit বা Google Play Billing ব্যবহার করে। নেটওয়ার্ক অ্যাক্সেস শুধু Apple বা Google-এর এই সরকারি স্টোর সুবিধাগুলোর জন্য ব্যবহৃত হয়।","স্টোর অ্যাকাউন্ট, পেমেন্ট, বিলিং, লেনদেন, অর্থ ফেরত ও সাবস্ক্রিপশন পরিষেবার দায়িত্ব Apple বা Google-এর। অ্যাপটি শুধু পণ্য ও এনটাইটেলমেন্ট নিশ্চিত করতে প্রয়োজনীয় স্টোর তথ্য প্রক্রিয়া করে এবং সম্পূর্ণ পেমেন্ট পরিচয়পত্র গ্রহণ বা সংরক্ষণ করে না।"]},{"title":"5. সহায়তা ইমেল ও ওয়েবসাইট","paragraphs":["অ্যাপটি স্বয়ংক্রিয়ভাবে আপনার ইমেলের তথ্য পড়ে না। আপনি সহায়তা ইমেল পাঠানোর সিদ্ধান্ত নিলেই শুধু সহায়তা চ্যানেল আপনার ইমেল ঠিকানা, বার্তা এবং আপনার স্বেচ্ছায় দেওয়া স্ক্রিনশট, স্ক্রিন রেকর্ডিং, অর্ডার নম্বর বা অন্য সংযুক্তি পায়। এই তথ্য শুধু আপনার অনুরোধ পরিচালনা করতে ব্যবহৃত হয়, বিজ্ঞাপন বা বিপণনের জন্য নয়। অ্যাকাউন্ট বা পেমেন্ট পাসওয়ার্ড কিংবা সম্পূর্ণ কার্ড নম্বর পাঠাবেন না।","এই ওয়েবসাইট বিজ্ঞাপন বা বিশ্লেষণ কুকি সেট করে না এবং এতে ট্রাফিক বিশ্লেষণ বা ট্র্যাকিং স্ক্রিপ্ট নেই।"]},{"title":"6. সংরক্ষণ ও মুছে ফেলা","paragraphs":["অ্যাপটি আনইনস্টল করে ডিভাইসে থাকা ডেটা মুছুন। Android-এ সিস্টেমের ডেটা মুছুন বিকল্পও ব্যবহার করতে পারেন।","স্টোরের কেনাকাটার রেকর্ড Apple বা Google পরিচালনা করে। পুনরুদ্ধারযোগ্য এনটাইটেলমেন্ট স্টোরের নিয়ম অনুযায়ী আবার নিশ্চিত করা হয়।","সহায়তা ইমেল অনুরোধ পরিচালনা ও প্রয়োজনীয় রেকর্ড রাখার শর্ত পূরণে যত দিন প্রয়োজন, তত দিন রাখা হয়। আমাদের কাছে এখনও থাকা সহায়তা চিঠিপত্র মুছে ফেলার অনুরোধ ইমেলে করতে পারেন।"]},{"title":"7. ডেটা নিরাপত্তা","paragraphs":["অপ্রয়োজনীয় ডেটা স্থানান্তর কমাতে অ্যাপটি ডিভাইসে প্রক্রিয়াকরণ, ন্যূনতম অনুমতি ও অ্যাপ স্টোরের সরকারি কেনাকাটা প্রক্রিয়া ব্যবহার করে। সহায়তা ইমেল শুধু আসা অনুরোধ পরিচালনায় ব্যবহৃত হয় এবং তথ্যের প্রকৃতি অনুযায়ী যুক্তিসঙ্গত সুরক্ষা ব্যবস্থা নেওয়া হয়।","কোনো ডিভাইস, নেটওয়ার্ক বা বৈদ্যুতিন সংরক্ষণ পদ্ধতি সম্পূর্ণ নিরাপদ হওয়ার নিশ্চয়তা দেওয়া যায় না। সহায়তা ইমেলে অপ্রাসঙ্গিক সংবেদনশীল তথ্য দেবেন না।"]},{"title":"8. শিশু ও কিশোর-কিশোরী","paragraphs":["অ্যাপটির জন্য অ্যাকাউন্ট প্রয়োজন হয় না এবং এটি বিজ্ঞাপন বা আচরণগত বিশ্লেষণের মাধ্যমে শিশু বা অন্য ব্যবহারকারীর প্রোফাইল তৈরি করে না। কোনো শিশু সহায়তা ইমেলের মাধ্যমে ব্যক্তিগত তথ্য দিয়েছে বলে মনে হলে অভিভাবক বা আইনি অভিভাবক বিষয়টি সমাধানের জন্য আমাদের সঙ্গে যোগাযোগ করতে পারেন।"]},{"title":"9. আপনার পছন্দ ও অধিকার","paragraphs":["আপনি আপনার ডিভাইসের মাধ্যমে ডিভাইসে থাকা ডেটা পরিচালনা করেন। Apple বা Google স্টোর অ্যাকাউন্ট ও কেনাকাটার রেকর্ড পরিচালনা করে। অ্যাপটি আপনার হয়ে অ্যাপ স্টোরে রাখা লেনদেনের রেকর্ড পরিবর্তন বা মুছে ফেলতে পারে না।","অ্যাপের ডেটা ব্যবহারের পদ্ধতি, প্ল্যাটফর্মের নিয়ম বা ওয়েবসাইট হোস্টিংয়ের ব্যবস্থা বদলালে আমরা এই নীতি ও পৃষ্ঠায় দেখানো তারিখ হালনাগাদ করব এবং প্রযোজ্য নিয়মে প্রয়োজন হলে অতিরিক্ত বিজ্ঞপ্তি দেব।","গোপনীয়তা সংক্রান্ত প্রশ্নের জন্য, ইমেল করুন {email}"]}]},"terms":{"title":"ব্যবহারের শর্তাবলী","lead":"{appName} ব্যবহারের শর্তাবলী।","sections":[{"title":"1. এই শর্তাবলী এবং প্ল্যাটফর্মের নিয়মাবলী মেনে নেওয়া","paragraphs":["{appName} ডাউনলোড, ক্রয় বা ব্যবহার করার মাধ্যমে, আপনি এই শর্তাবলীতে এবং যে অ্যাপ স্টোর থেকে আপনি কেনাকাটা করছেন, সেখানকার প্রযোজ্য নিয়মাবলীতে সম্মত হচ্ছেন। আপনি যদি সম্মত না হন, তবে অ্যাপটি ব্যবহার করা বা কোনো কেনাকাটা করা থেকে বিরত থাকুন।","আপনার অ্যাপ ডাউনলোড, কেনা ও ব্যবহারের ক্ষেত্রে এই শর্তাবলি প্রযোজ্য। iOS ও iPadOS সংস্করণগুলো আরও যে শর্তের অধীন:"],"links":["appleEula"]},{"title":"2. অর্থপ্রদত্ত পণ্য ও মূল্য","paragraphs":["শনাক্তকরণ ও সম্পাদনায় ব্যবহারের সীমা নেই। প্রক্রিয়া করা ছবি রপ্তানির জন্যই শুধু বৈধ Premium প্রয়োজন। বিনামূল্যের ট্রায়াল ছাড়া স্বয়ংক্রিয় নবায়নযোগ্য সাপ্তাহিক ও মাসিক সাবস্ক্রিপশন এবং এককালীন আজীবন ক্রয় রয়েছে। App Store ও Google Play-এর ক্রয় আলাদা এবং প্ল্যাটফর্মের মধ্যে স্থানান্তর করা যায় না।","প্রকৃত মূল্য, মুদ্রা, কর, বিলিং সময়কাল ও কেনার যোগ্যতা হলো App Store বা Google Play-এর সিস্টেম কেনাকাটা স্ক্রিনে দেখানো ও নিশ্চিত করা তথ্য। কেনাকাটা প্ল্যাটফর্ম আপনার স্টোর অ্যাকাউন্টের মাধ্যমে মূল্য নেয় ও পেমেন্ট পরিচালনা করে। অ্যাপটি সাবস্ক্রিপশনের বিনামূল্যে ট্রায়াল বা অন্য কোনো অর্থপ্রদত্ত পরিকল্পনা দেয় না।"]},{"title":"3. স্বয়ংক্রিয় নবায়ন ও বাতিলকরণ","paragraphs":["সাপ্তাহিক ও মাসিক সাবস্ক্রিপশন স্বয়ংক্রিয়ভাবে নবায়ন হয় এবং কেনাকাটা প্ল্যাটফর্মের মাধ্যমে বাতিল না করা পর্যন্ত সিস্টেম কেনাকাটা স্ক্রিনে দেখানো বিলিং সময়কালের জন্য মূল্য নেওয়া হয়। {appName} মুছে ফেললে সাবস্ক্রিপশন স্বয়ংক্রিয়ভাবে বাতিল হয় না। কেনাকাটা প্ল্যাটফর্ম অর্থ ফেরত বা অন্য ব্যবস্থা না দিলে, স্বয়ংক্রিয় নবায়ন বন্ধ করার পর বর্তমান অর্থপ্রদত্ত সময়কাল শেষ হওয়া পর্যন্ত সাবস্ক্রিপশন ব্যবহার করতে পারবেন।"],"links":["appleCancel","googleManage"]},{"title":"4. কেনাকাটা, পুনরুদ্ধার ও অর্থ ফেরত","paragraphs":["কেনাকাটা ও কেনাকাটা পুনরুদ্ধার Apple বা Google-এর সরকারি স্টোরের মাধ্যমে সম্পন্ন হয়। স্টোর বৈধ লেনদেন নিশ্চিত করার পরেই এনটাইটেলমেন্ট দেওয়া হয়। বাতিল, ব্যর্থ বা মুলতবি লেনদেন সফলভাবে নিশ্চিত হওয়ার আগে এনটাইটেলমেন্ট দেয় না। কেনাকাটা পুনরুদ্ধার আজীবন অ্যাক্সেস ও বর্তমানে সক্রিয় সাবস্ক্রিপশন পুনরুদ্ধার করতে পারে। App Store ও Google Play-এর কেনাকাটা আলাদা এবং প্ল্যাটফর্মের মধ্যে পুনরুদ্ধার বা স্থানান্তর করা যায় না।","অর্থ ফেরত লেনদেন সম্পন্ন করা অ্যাপ স্টোর তার নিয়ম, কেনাকাটার অঞ্চল ও প্রযোজ্য আইন অনুযায়ী পরিচালনা করে। স্টোর অর্থ ফেরত, প্রত্যাহার, সাবস্ক্রিপশন শেষ হওয়া বা অবৈধ লেনদেন নিশ্চিত করার পর সংশ্লিষ্ট এনটাইটেলমেন্ট সরিয়ে দেওয়া হয়।"],"links":["appleRefund","googleRefund"]},{"title":"5. অফলাইন ব্যবহার ও প্রাপ্যতা","paragraphs":["ছবি নির্বাচন, OCR, সংবেদনশীল বিষয় শনাক্তকরণ, সম্পাদনা ও রপ্তানি ডিভাইসেই সম্পন্ন হয়। অ্যাপটি ক্লাউড ছবি শনাক্তকরণ, ক্লাউড সিঙ্ক বা অ্যাকাউন্ট দেয় না। রপ্তানির সময় নতুন ছবি তৈরি হয় এবং অপসারণযোগ্য ব্যক্তিগত মেটাডেটা মুছে ফেলা হয়। সফলভাবে সংরক্ষণ, সম্পাদনা বাতিল বা সেশন শেষ হওয়ার পর অস্থায়ী কাজের ফাইল মুছে যায়; সংরক্ষণ ব্যর্থ হলে আবার চেষ্টা করার জন্য প্রয়োজনীয় অবস্থা রাখা হতে পারে।"]},{"title":"6. গ্রহণযোগ্য ব্যবহার ও মেধাস্বত্ব","paragraphs":["আপনি বেআইনি কার্যকলাপে অ্যাপটি ব্যবহার করতে, কেনাকাটা যাচাই এড়িয়ে যেতে, অ্যাপের ক্ষতি করতে, ক্ষতিকর কোড বিতরণ করতে, অনুমতি ছাড়া অ্যাপের অনুলিপি বা বিতরণ করতে কিংবা অ্যাপের সামগ্রীর অধিকার বা অন্যের মেধাস্বত্ব লঙ্ঘন করতে পারবেন না।","আপনি যেকোনো সময় অ্যাপ ব্যবহার বন্ধ করে আনইনস্টল করতে পারেন। সমস্যা ঠিক করা, অপারেটিং সিস্টেম সমর্থন, স্থিতিশীলতা বাড়ানো বা প্ল্যাটফর্মের শর্ত পূরণের জন্য আমরা হালনাগাদ প্রকাশ করতে পারি। ডিভাইস, সিস্টেম, নেটওয়ার্ক বা স্টোর পরিষেবার সমস্যায় কিছু সুবিধা সাময়িকভাবে অনুপলব্ধ হতে পারে।","প্রযোজ্য আইন যতটা অনুমতি দেয়, অ্যাপটি প্রাপ্যতা অনুযায়ী দেওয়া হয়। এই শর্তাবলি আইনত বাদ দেওয়া যায় না এমন দায় বাদ দেয় না বা আপনার বাধ্যতামূলক ভোক্তা অধিকার সীমিত করে না।","পণ্যের সুবিধা, পেমেন্টের পদ্ধতি, প্ল্যাটফর্মের নিয়ম বা প্রযোজ্য আইন বদলালে আমরা এই শর্তাবলি ও পৃষ্ঠায় দেখানো তারিখ হালনাগাদ করতে পারি। কোনো পরিবর্তন ব্যবহারকারীর অধিকারকে উল্লেখযোগ্যভাবে প্রভাবিত করলে প্রয়োজন অনুযায়ী অতিরিক্ত বিজ্ঞপ্তি দেব।","এই শর্তাবলী, কেনাকাটা বা অ্যাপের ব্যবহার সম্পর্কে কোনো প্রশ্ন থাকলে, ইমেল করুন। {email}"]}]},"support":{"title":"সহায়তা","lead":"প্রথমে নিচের সাধারণ প্রশ্নগুলো দেখুন। সমস্যা থেকে গেলে সহায়তা ইমেল ঠিকানার মাধ্যমে আমাদের সঙ্গে যোগাযোগ করুন।","emailTitle":"{appName} সাপোর্ট ইমেল","emailLead":"প্রথমে নিচের সাধারণ প্রশ্নগুলো দেখুন। সমস্যা থেকে গেলে সহায়তা ইমেল ঠিকানার মাধ্যমে আমাদের সঙ্গে যোগাযোগ করুন।","beforeEmail":{"title":"ইমেলে যা দেবেন","paragraphs":["কেনাকাটার সমস্যায় অ্যাপ স্টোরের অর্ডার নম্বর দিতে পারেন, তবে অ্যাকাউন্ট বা পেমেন্ট পাসওয়ার্ড কিংবা কার্ডের সম্পূর্ণ তথ্য পাঠাবেন না।"],"bullets":["আপনার প্ল্যাটফর্ম, ডিভাইসের মডেল, অপারেটিং সিস্টেম সংস্করণ ও অ্যাপ সংস্করণ;","সমস্যার আগে আপনি কী করেছিলেন, কী আশা করেছিলেন এবং আসলে কী ঘটেছিল; এবং","প্রয়োজনে, ব্যক্তিগত তথ্য গোপন রেখে একটি স্ক্রিনশট বা স্ক্রিন রেকর্ডিং।"]},"faqs":[{"question":"ছবিগুলো কি কোনো সার্ভারে আপলোড করা হয়?","answer":"ছবি নির্বাচন, OCR, সংবেদনশীল বিষয় শনাক্তকরণ, সম্পাদনা ও রপ্তানি ডিভাইসেই সম্পন্ন হয়। অ্যাপটি ক্লাউড ছবি শনাক্তকরণ, ক্লাউড সিঙ্ক বা অ্যাকাউন্ট দেয় না। রপ্তানির সময় নতুন ছবি তৈরি হয় এবং অপসারণযোগ্য ব্যক্তিগত মেটাডেটা মুছে ফেলা হয়। সফলভাবে সংরক্ষণ, সম্পাদনা বাতিল বা সেশন শেষ হওয়ার পর অস্থায়ী কাজের ফাইল মুছে যায়; সংরক্ষণ ব্যর্থ হলে আবার চেষ্টা করার জন্য প্রয়োজনীয় অবস্থা রাখা হতে পারে।"},{"question":"অনুমতি, বিজ্ঞাপন ও ট্র্যাকিং","answer":"ফটো অ্যাক্সেস শুধু আপনার অনুমোদিত ছবি দেখানো ও প্রক্রিয়ার জন্য ব্যবহৃত হয়। অ্যাপে ছবি তোলার বিকল্প বেছে নিলেই কেবল ক্যামেরা ব্যবহার হয়। বৈধ Premium নিয়ে রপ্তানি নিশ্চিত করলেই কেবল ফটো লাইব্রেরিতে সংরক্ষণের অনুমতি চাওয়া হয়। অ্যাপটি অবস্থান, পরিচিতি, মাইক্রোফোন, Bluetooth বা বিজ্ঞপ্তির অনুমতি চায় না।"},{"question":"অর্থপ্রদত্ত পণ্য ও মূল্য","answer":"শনাক্তকরণ ও সম্পাদনায় ব্যবহারের সীমা নেই। প্রক্রিয়া করা ছবি রপ্তানির জন্যই শুধু বৈধ Premium প্রয়োজন। বিনামূল্যের ট্রায়াল ছাড়া স্বয়ংক্রিয় নবায়নযোগ্য সাপ্তাহিক ও মাসিক সাবস্ক্রিপশন এবং এককালীন আজীবন ক্রয় রয়েছে। App Store ও Google Play-এর ক্রয় আলাদা এবং প্ল্যাটফর্মের মধ্যে স্থানান্তর করা যায় না।"},{"question":"সংরক্ষণ ও ছবির ফরম্যাট","answer":"সংরক্ষণ ব্যর্থ হলে খালি জায়গা, ফটো লাইব্রেরিতে সংরক্ষণের অনুমতি এবং মূল ছবি পড়া যাচ্ছে কি না পরীক্ষা করে আবার চেষ্টা করুন। অ্যাপটি একবারে একটি স্থির ছবি প্রক্রিয়া করে এবং অধিকাংশ প্রচলিত ফরম্যাট সমর্থন করে; কিছু ফরম্যাট ডিভাইস ও সিস্টেম সংস্করণের ওপর নির্ভরশীল। ভিডিও, PDF, RAW/DNG এবং ব্যাচ প্রক্রিয়াকরণ বর্তমানে সমর্থিত নয়।"},{"question":"ভাষা কীভাবে বদলাব?","answer":"অ্যাপটি ৪০টি ভাষা সমর্থন করে এবং অ্যাপের সেটিংসে ভাষা বদলানো যায়। প্রদর্শন ঠিক না হলে ডিভাইসের ভাষা ও অ্যাপে নির্বাচিত ভাষা ইমেল করুন।"},{"question":"পুনরুদ্ধার, বাতিলকরণ ও অর্থ ফেরত","answer":"কেনাকাটা ও কেনাকাটা পুনরুদ্ধার Apple বা Google-এর সরকারি স্টোরের মাধ্যমে সম্পন্ন হয়। স্টোর বৈধ লেনদেন নিশ্চিত করার পরেই এনটাইটেলমেন্ট দেওয়া হয়। বাতিল, ব্যর্থ বা মুলতবি লেনদেন সফলভাবে নিশ্চিত হওয়ার আগে এনটাইটেলমেন্ট দেয় না। কেনাকাটা পুনরুদ্ধার আজীবন অ্যাক্সেস ও বর্তমানে সক্রিয় সাবস্ক্রিপশন পুনরুদ্ধার করতে পারে। App Store ও Google Play-এর কেনাকাটা আলাদা এবং প্ল্যাটফর্মের মধ্যে পুনরুদ্ধার বা স্থানান্তর করা যায় না।"},{"question":"গোপনীয়তা ও ডেটা মুছে ফেলা","answer":"অ্যাপটি আনইনস্টল করে ডিভাইসে থাকা ডেটা মুছুন। Android-এ সিস্টেমের ডেটা মুছুন বিকল্পও ব্যবহার করতে পারেন। স্টোরের কেনাকাটার রেকর্ড Apple বা Google পরিচালনা করে। পুনরুদ্ধারযোগ্য এনটাইটেলমেন্ট স্টোরের নিয়ম অনুযায়ী আবার নিশ্চিত করা হয়। সহায়তা ইমেল অনুরোধ পরিচালনা ও প্রয়োজনীয় রেকর্ড রাখার শর্ত পূরণে যত দিন প্রয়োজন, তত দিন রাখা হয়। আমাদের কাছে এখনও থাকা সহায়তা চিঠিপত্র মুছে ফেলার অনুরোধ ইমেলে করতে পারেন।"}],"officialHelpTitle":"দ্রুত সাহায্য"}},"ca":{"linkLabels":{"appleEula":"l'Acord de llicència estàndard d'Apple per a l'usuari final (EULA)","appleCancel":"Instruccions de cancel·lació de la subscripció a Apple","googleManage":"Instruccions de cancel·lació de Google Play","appleRefund":"Sol·licita un reemborsament a Apple","googleRefund":"Informació sobre reembossaments de Google Play"},"nav":{"privacy":"Política de privacitat","terms":"Condicions d'ús","support":"Suport","language":"Llengua","chooseLanguage":"Selecciona l'idioma de visualització","navigationLabel":"Navegació principal"},"home":{"eyebrow":"{appName} · Privacy first","title":"Les teves imatges no es pugen als nostres servidors.","lead":"La selecció d’imatges, l’OCR, la detecció de contingut sensible, l’edició i l’exportació es fan al dispositiu. L’app no ofereix reconeixement d’imatges al núvol, sincronització al núvol ni comptes. En exportar es crea una imatge nova i s’eliminen les metadades privades que es poden esborrar. Els fitxers temporals s’eliminen després de desar correctament, en abandonar l’edició o en acabar la sessió; si falla el desament, es pot conservar l’estat necessari per tornar-ho a provar.","points":["Dades de l'aplicació","Productes de pagament i preus","Suport"],"cards":[{"title":"Política de privacitat","description":"Les teves imatges no es pugen als nostres servidors.","action":"Política de privacitat"},{"title":"Condicions d'ús","description":"El reconeixement i l’edició no tenen límits d’ús. Només l’exportació de la imatge processada requereix accés Premium vàlid. L’app ofereix subscripcions setmanals i mensuals amb renovació automàtica i una compra única de per vida, sense prova gratuïta. Les compres de l’App Store i Google Play són independents i no es poden transferir entre plataformes.","action":"Condicions d'ús"},{"title":"Necessites ajuda?","description":"Comença per les preguntes freqüents següents. Si el problema continua, contacta amb nosaltres mitjançant l'adreça electrònica d'assistència.","action":"Suport"}]},"footer":{"privacy":"Política de privacitat","terms":"Condicions d'ús","support":"Suport"},"privacy":{"title":"Política de privacitat","lead":"Aquesta Política explica com {appName} tracta les dades del dispositiu, la informació de compres de la botiga d'aplicacions i els correus d'assistència.","sections":[{"title":"1. Àmbit d'aplicació i contacte","paragraphs":["Aquesta Política s'aplica a l'aplicació {appName} per a iOS, iPadOS i Android, i a aquest lloc web de privadesa, condicions i assistència.","Per a preguntes sobre privadesa, envieu un correu electrònic {email}"]},{"title":"2. Dades de l'aplicació","callout":{"title":"Les teves imatges no es pugen als nostres servidors.","body":"La selecció d’imatges, l’OCR, la detecció de contingut sensible, l’edició i l’exportació es fan al dispositiu. L’app no ofereix reconeixement d’imatges al núvol, sincronització al núvol ni comptes. En exportar es crea una imatge nova i s’eliminen les metadades privades que es poden esborrar. Els fitxers temporals s’eliminen després de desar correctament, en abandonar l’edició o en acabar la sessió; si falla el desament, es pot conservar l’estat necessari per tornar-ho a provar."},"paragraphs":[]},{"title":"3. Permisos, publicitat i seguiment","paragraphs":["L’accés a les fotos només s’utilitza per mostrar i processar les imatges que autoritzes. La càmera només s’utilitza quan tries fer una foto dins de l’app. El permís per desar a la fototeca només es demana quan confirmes l’exportació amb accés Premium vàlid. L’app no demana ubicació, contactes, micròfon, Bluetooth ni notificacions.","No utilitza cap identificador publicitari ni integra SDK de tercers de publicitat, analítica, atribució o informes d'errors.","L'aplicació no integra cap eina de tercers d'informes d'errors. Segons la configuració del dispositiu i de la botiga, Apple o Google pot tractar informació de diagnòstic del sistema d'acord amb les seves normes de privadesa i proporcionar informació tècnica utilitzada per investigar errors o problemes de rendiment."]},{"title":"4. Serveis de la botiga d'aplicacions i accés a la xarxa","paragraphs":["L'aplicació utilitza Apple StoreKit o Google Play Billing per carregar productes, mostrar els preus localitzats que retorna la botiga, completar compres, restaurar compres, gestionar subscripcions i confirmar drets. L'accés a la xarxa només s'utilitza per a aquestes funcions oficials de les botigues d'Apple o Google.","Apple o Google és responsable dels comptes de la botiga, els pagaments, la facturació, les transaccions, els reembossaments i els serveis de subscripció. L'aplicació només tracta la informació de la botiga necessària per confirmar productes i drets, i no rep ni desa les credencials de pagament completes."]},{"title":"5. Correus d'assistència i lloc web","paragraphs":["L'aplicació no llegeix automàticament la informació del teu correu electrònic. Només quan decideixes enviar un correu d'assistència, el canal d'assistència rep la teva adreça electrònica, el missatge i qualsevol captura de pantalla, enregistrament de pantalla, número de comanda o altre fitxer adjunt que proporcionis voluntàriament. Aquesta informació només s'utilitza per gestionar la teva sol·licitud i no s'utilitza per a publicitat ni màrqueting. No enviïs contrasenyes de comptes, contrasenyes de pagament ni números de targeta complets.","Aquest lloc web no estableix galetes de publicitat o analítica i no inclou analítica de trànsit ni scripts de seguiment."]},{"title":"6. Conservació i supressió","paragraphs":["Per suprimir les dades del dispositiu, desinstal·la l'aplicació. A Android, també pots utilitzar l'opció del sistema Esborra les dades.","Apple o Google gestiona els registres de compres de la botiga. Els drets restaurables es tornen a confirmar segons les regles de la botiga.","Els correus d'assistència es conserven durant el temps necessari per gestionar la sol·licitud i complir els requisits necessaris de manteniment de registres. Pots enviar-nos un correu per sol·licitar la supressió de la correspondència d'assistència que encara conservem."]},{"title":"7. Seguretat de les dades","paragraphs":["L'aplicació utilitza el tractament al dispositiu, permisos mínims i els processos oficials de compra de la botiga d'aplicacions per reduir les transferències de dades innecessàries. Els correus d'assistència només s'utilitzen per gestionar les sol·licituds rebudes, amb mesures de protecció raonables adequades a la naturalesa de la informació.","No es pot garantir que cap dispositiu, xarxa o mètode d'emmagatzematge electrònic sigui completament segur. No incloguis informació sensible no relacionada en un correu d'assistència."]},{"title":"8. Infants i adolescents","paragraphs":["L'aplicació no requereix cap compte i no crea perfils d'infants ni d'altres usuaris mitjançant publicitat o analítica de comportament. Un pare, una mare o un tutor que consideri que un infant ha proporcionat informació personal mitjançant un correu d'assistència pot contactar amb nosaltres perquè tractem la qüestió."]},{"title":"9. Les teves opcions i drets","paragraphs":["Gestiones les dades del dispositiu mitjançant el mateix dispositiu. Apple o Google gestiona els comptes de la botiga i els registres de compres. L'aplicació no pot modificar ni suprimir en nom teu els registres de transaccions que conserva una botiga d'aplicacions.","Si canvien les pràctiques de dades de l'aplicació, les regles de la plataforma o els serveis d'allotjament del lloc web, actualitzarem aquesta Política i la data que es mostra a la pàgina, i proporcionarem un avís addicional quan ho exigeixin les regles aplicables.","Per a preguntes sobre privadesa, envieu un correu electrònic {email}"]}]},"terms":{"title":"Condicions d'ús","lead":"Condicions d'ús de {appName}.","sections":[{"title":"1. Acceptació d'aquests Termes i les normes de la plataforma","paragraphs":["En descarregar, comprar o utilitzar {appName}, accepteu aquestes Condicions i les normes que s'apliquen a la botiga d'aplicacions on feu una compra. Si no hi esteu d'acord, no continueu utilitzant l'aplicació ni fent cap compra.","Aquestes Condicions s'apliquen a la descàrrega, la compra i l'ús de l'aplicació. Les versions per a iOS i iPadOS també estan subjectes a"],"links":["appleEula"]},{"title":"2. Productes de pagament i preus","paragraphs":["El reconeixement i l’edició no tenen límits d’ús. Només l’exportació de la imatge processada requereix accés Premium vàlid. L’app ofereix subscripcions setmanals i mensuals amb renovació automàtica i una compra única de per vida, sense prova gratuïta. Les compres de l’App Store i Google Play són independents i no es poden transferir entre plataformes.","El preu real, la moneda, els impostos, el període de facturació i l'elegibilitat per comprar són les dades que es mostren i es confirmen a la pantalla de compra del sistema de l'App Store o Google Play. La plataforma de compra cobra i gestiona el pagament mitjançant el teu compte de la botiga. L'aplicació no ofereix cap prova gratuïta de subscripció ni altres plans de pagament."]},{"title":"3. Renovació automàtica i cancel·lació","paragraphs":["Les subscripcions setmanals i mensuals es renoven automàticament i es cobren durant el període de facturació que es mostra a la pantalla de compra del sistema fins que les cancel·lis mitjançant la plataforma de compra. Suprimir {appName} no cancel·la automàticament una subscripció. Tret que la plataforma de compra proporcioni un reembossament o un altre tractament, pots continuar utilitzant la subscripció fins al final del període de pagament actual després de desactivar la renovació automàtica."],"links":["appleCancel","googleManage"]},{"title":"4. Compres, restauració i reembossaments","paragraphs":["Les compres i la restauració de compres es completen mitjançant la botiga oficial d'Apple o Google. Només es concedeix un dret quan la botiga confirma una transacció vàlida. Les transaccions cancel·lades, fallides o pendents no concedeixen cap dret abans de confirmar-se correctament. La restauració de compres pot restaurar l'accés de per vida i una subscripció activa en aquell moment. Les compres de l'App Store i Google Play són independents i no es poden restaurar ni transferir entre plataformes.","Els reembossaments els gestiona la botiga d'aplicacions que ha completat la transacció, segons les seves regles, la regió de compra i la legislació aplicable. El dret corresponent s'elimina quan la botiga confirma un reembossament, una revocació, el venciment de la subscripció o una transacció no vàlida."],"links":["appleRefund","googleRefund"]},{"title":"5. Ús sense connexió i disponibilitat","paragraphs":["La selecció d’imatges, l’OCR, la detecció de contingut sensible, l’edició i l’exportació es fan al dispositiu. L’app no ofereix reconeixement d’imatges al núvol, sincronització al núvol ni comptes. En exportar es crea una imatge nova i s’eliminen les metadades privades que es poden esborrar. Els fitxers temporals s’eliminen després de desar correctament, en abandonar l’edició o en acabar la sessió; si falla el desament, es pot conservar l’estat necessari per tornar-ho a provar."]},{"title":"6. Ús acceptable i propietat intel·lectual","paragraphs":["No pots utilitzar l'aplicació per a activitats il·legals; eludir la verificació de compres; danyar l'aplicació; distribuir codi maliciós; copiar o distribuir l'aplicació sense permís; ni infringir drets sobre el contingut de l'aplicació o la propietat intel·lectual d'una altra persona.","Pots deixar d'utilitzar i desinstal·lar l'aplicació en qualsevol moment. Podem publicar actualitzacions per corregir problemes, oferir compatibilitat amb sistemes operatius, millorar l'estabilitat o complir els requisits de la plataforma. Els problemes del dispositiu, el sistema, la xarxa o el servei de la botiga poden fer que algunes funcions no estiguin disponibles temporalment.","En la mesura permesa per la legislació aplicable, l'aplicació es proporciona segons la seva disponibilitat. Aquestes Condicions no exclouen responsabilitats que no es puguin excloure legalment ni limiten els drets obligatoris dels consumidors que et corresponen.","Si canvien les funcions del producte, els mètodes de pagament, les regles de la plataforma o la legislació aplicable, podem actualitzar aquestes Condicions i la data de la pàgina. Si un canvi afecta significativament els drets dels usuaris, proporcionarem un avís addicional segons sigui necessari.","Si teniu preguntes sobre aquestes Condicions, compres o ús de l'aplicació, envieu un correu electrònic a {email}"]}]},"support":{"title":"Suport","lead":"Comença per les preguntes freqüents següents. Si el problema continua, contacta amb nosaltres mitjançant l'adreça electrònica d'assistència.","emailTitle":"Correu electrònic d'assistència de {appName}","emailLead":"Comença per les preguntes freqüents següents. Si el problema continua, contacta amb nosaltres mitjançant l'adreça electrònica d'assistència.","beforeEmail":{"title":"Què has d'incloure al correu","paragraphs":["Per a un problema de compra, pots incloure el número de comanda de la botiga d'aplicacions, però no enviïs la contrasenya del compte, la contrasenya de pagament ni les dades completes de la targeta."],"bullets":["la teva plataforma, el model del dispositiu, la versió del sistema operatiu i la versió de l'aplicació;","què vas fer abans del problema, què esperaves i què va passar realment; i","si cal, una captura de pantalla o una gravació de pantalla amb informació privada oculta."]},"faqs":[{"question":"Les imatges es pugen a algun servidor?","answer":"La selecció d’imatges, l’OCR, la detecció de contingut sensible, l’edició i l’exportació es fan al dispositiu. L’app no ofereix reconeixement d’imatges al núvol, sincronització al núvol ni comptes. En exportar es crea una imatge nova i s’eliminen les metadades privades que es poden esborrar. Els fitxers temporals s’eliminen després de desar correctament, en abandonar l’edició o en acabar la sessió; si falla el desament, es pot conservar l’estat necessari per tornar-ho a provar."},{"question":"Permisos, publicitat i seguiment","answer":"L’accés a les fotos només s’utilitza per mostrar i processar les imatges que autoritzes. La càmera només s’utilitza quan tries fer una foto dins de l’app. El permís per desar a la fototeca només es demana quan confirmes l’exportació amb accés Premium vàlid. L’app no demana ubicació, contactes, micròfon, Bluetooth ni notificacions."},{"question":"Productes de pagament i preus","answer":"El reconeixement i l’edició no tenen límits d’ús. Només l’exportació de la imatge processada requereix accés Premium vàlid. L’app ofereix subscripcions setmanals i mensuals amb renovació automàtica i una compra única de per vida, sense prova gratuïta. Les compres de l’App Store i Google Play són independents i no es poden transferir entre plataformes."},{"question":"Desament i formats d’imatge","answer":"Si el desament falla, comprova l’espai disponible, el permís per desar a la fototeca i que la imatge original encara es pugui llegir, i torna-ho a provar. L’app processa una imatge fixa cada vegada i admet la majoria de formats habituals; alguns depenen del dispositiu i la versió del sistema. Actualment no admet vídeo, PDF, RAW/DNG ni processament per lots."},{"question":"Com puc canviar l'idioma?","answer":"L'aplicació admet 40 idiomes i l'idioma es pot canviar a la configuració de l'aplicació. Si la visualització no és correcta, envia per correu l'idioma del dispositiu i l'idioma seleccionat a l'aplicació."},{"question":"Restauració, cancel·lació i reembossaments","answer":"Les compres i la restauració de compres es completen mitjançant la botiga oficial d'Apple o Google. Només es concedeix un dret quan la botiga confirma una transacció vàlida. Les transaccions cancel·lades, fallides o pendents no concedeixen cap dret abans de confirmar-se correctament. La restauració de compres pot restaurar l'accés de per vida i una subscripció activa en aquell moment. Les compres de l'App Store i Google Play són independents i no es poden restaurar ni transferir entre plataformes."},{"question":"Privadesa i supressió de dades","answer":"Per suprimir les dades del dispositiu, desinstal·la l'aplicació. A Android, també pots utilitzar l'opció del sistema Esborra les dades. Apple o Google gestiona els registres de compres de la botiga. Els drets restaurables es tornen a confirmar segons les regles de la botiga. Els correus d'assistència es conserven durant el temps necessari per gestionar la sol·licitud i complir els requisits necessaris de manteniment de registres. Pots enviar-nos un correu per sol·licitar la supressió de la correspondència d'assistència que encara conservem."}],"officialHelpTitle":"Ajuda ràpida"}},"cs":{"linkLabels":{"appleEula":"Standardní licenční smlouva Apple s koncovým uživatelem (EULA)","appleCancel":"Pokyny pro zrušení předplatného Apple","googleManage":"Pokyny ke zrušení v Google Play","appleRefund":"Žádost o vrácení peněz od společnosti Apple","googleRefund":"Informace o vrácení peněz Google Play"},"nav":{"privacy":"Zásady ochrany osobních údajů","terms":"Podmínky použití","support":"Podpora","language":"Jazyk","chooseLanguage":"Vyberte jazyk zobrazení","navigationLabel":"Primární navigace"},"home":{"eyebrow":"{appName} · Privacy first","title":"Vaše obrázky se nenahrávají na naše servery.","lead":"Výběr obrázků, OCR, rozpoznání citlivého obsahu, úpravy a export probíhají v zařízení. Aplikace nenabízí cloudové rozpoznávání obrázků, synchronizaci s cloudem ani účty. Při exportu se vytvoří nový obrázek a odstraní se odstranitelná soukromá metadata. Dočasné pracovní soubory se smažou po úspěšném uložení, při zrušení úprav nebo ukončení relace; pokud se uložení nezdaří, může být zachován stav nutný k opakování.","points":["Data aplikace","Placené produkty a ceny","Podpora"],"cards":[{"title":"Zásady ochrany osobních údajů","description":"Vaše obrázky se nenahrávají na naše servery.","action":"Zásady ochrany osobních údajů"},{"title":"Podmínky použití","description":"Rozpoznávání a úpravy nemají limit použití. Platný přístup Premium je nutný pouze k exportu zpracovaného obrázku. Aplikace nabízí automaticky obnovované týdenní a měsíční předplatné a jednorázový doživotní nákup bez bezplatné zkušební verze. Nákupy v App Storu a Google Play jsou oddělené a nelze je převádět mezi platformami.","action":"Podmínky použití"},{"title":"Potřebujete pomoc?","description":"Nejprve si přečtěte časté dotazy níže. Pokud problém trvá, kontaktujte nás přes e-mail podpory.","action":"Podpora"}]},"footer":{"privacy":"Zásady ochrany osobních údajů","terms":"Podmínky použití","support":"Podpora"},"privacy":{"title":"Zásady ochrany osobních údajů","lead":"Tyto Zásady vysvětlují, jak {appName} nakládá s daty v zařízení, údaji o nákupech z obchodu a e-maily podpory.","sections":[{"title":"1. Rozsah a kontakt","paragraphs":["Tyto Zásady se vztahují na aplikaci {appName} pro iOS, iPadOS a Android a na tento web o soukromí, podmínkách a podpoře.","V případě dotazů ohledně ochrany osobních údajů nám napište e-mail {email}"]},{"title":"2. Data aplikace","callout":{"title":"Vaše obrázky se nenahrávají na naše servery.","body":"Výběr obrázků, OCR, rozpoznání citlivého obsahu, úpravy a export probíhají v zařízení. Aplikace nenabízí cloudové rozpoznávání obrázků, synchronizaci s cloudem ani účty. Při exportu se vytvoří nový obrázek a odstraní se odstranitelná soukromá metadata. Dočasné pracovní soubory se smažou po úspěšném uložení, při zrušení úprav nebo ukončení relace; pokud se uložení nezdaří, může být zachován stav nutný k opakování."},"paragraphs":[]},{"title":"3. Oprávnění, reklamy a sledování","paragraphs":["Přístup k fotografiím slouží pouze k zobrazení a zpracování obrázků, které povolíte. Fotoaparát se používá jen tehdy, když se rozhodnete pořídit fotografii v aplikaci. Oprávnění k uložení do knihovny fotografií se žádá pouze při potvrzení exportu s platným přístupem Premium. Aplikace nežádá o polohu, kontakty, mikrofon, Bluetooth ani oznámení.","Nepoužívá reklamní identifikátor a nezapojuje externí SDK pro reklamu, analytiku, atribuci nebo hlášení pádů.","Aplikace nezapojuje externí nástroj pro hlášení pádů. Podle nastavení zařízení a obchodu mohou Apple nebo Google zpracovávat systémové diagnostické údaje podle vlastních pravidel ochrany soukromí a poskytovat technické informace k prošetření pádů nebo problémů s výkonem."]},{"title":"4. Služby obchodu a přístup k síti","paragraphs":["Aplikace používá Apple StoreKit nebo Google Play Billing k načítání produktů, zobrazení místních cen vrácených obchodem, provádění a obnovení nákupů, správě předplatných a potvrzení oprávnění. Síť používá pouze pro tyto oficiální funkce obchodu Apple nebo Google.","Za účty obchodu, platby, fakturaci, transakce, vrácení peněz a předplatná odpovídá Apple nebo Google. Aplikace zpracovává jen údaje obchodu nutné k potvrzení produktů a oprávnění a nepřijímá ani neukládá úplné platební údaje."]},{"title":"5. E-maily podpory a web","paragraphs":["Aplikace automaticky nečte vaše e-mailové údaje. Kanál podpory obdrží vaši adresu, zprávu a dobrovolně přiložené snímky či záznamy obrazovky, číslo objednávky nebo jiné přílohy pouze tehdy, když odešlete e-mail podpoře. Údaje slouží jen k vyřízení požadavku, nikoli reklamě nebo marketingu. Neposílejte hesla účtu či platby ani úplná čísla karet.","Tento web nenastavuje reklamní nebo analytické soubory cookie a neobsahuje skripty analýzy provozu nebo sledování."]},{"title":"6. Uchovávání a odstranění","paragraphs":["Data v zařízení odstraníte odinstalováním aplikace. V Androidu můžete také použít systémovou možnost „Vymazat data“.","Záznamy nákupů spravuje Apple nebo Google. Obnovitelná oprávnění se znovu potvrzují podle pravidel obchodu.","E-maily podpory uchováváme po dobu potřebnou k vyřízení požadavku a splnění nezbytných evidenčních povinností. E-mailem můžete požádat o odstranění podpůrné korespondence, kterou ještě uchováváme."]},{"title":"7. Zabezpečení dat","paragraphs":["Aplikace používá zpracování v zařízení, minimální oprávnění a oficiální nákupní procesy obchodů, aby omezila zbytečný přenos dat. E-maily podpory slouží jen k vyřízení příchozích požadavků a chrání je přiměřená opatření odpovídající povaze informací.","U žádného zařízení, sítě nebo elektronického úložiště nelze zaručit úplnou bezpečnost. Do e-mailu podpoře nepřidávejte nesouvisející citlivé informace."]},{"title":"8. Děti a dospívající","paragraphs":["Aplikace nevyžaduje účet a nevytváří profily dětí ani jiných uživatelů pomocí reklamy nebo analýzy chování. Rodič či opatrovník, který se domnívá, že dítě poslalo osobní údaje v e-mailu podpoře, nás může kontaktovat, abychom záležitost vyřešili."]},{"title":"9. Vaše volby a práva","paragraphs":["Místní data spravujete prostřednictvím zařízení. Účty obchodu a záznamy nákupů spravuje Apple nebo Google. Aplikace nemůže vaším jménem měnit ani mazat záznamy transakcí uchovávané obchodem.","Pokud se změní datové postupy aplikace, pravidla platforem nebo hosting webu, aktualizujeme tyto Zásady a datum na stránce a poskytneme další oznámení, pokud to platná pravidla vyžadují.","V případě dotazů ohledně ochrany osobních údajů nám napište e-mail {email}"]}]},"terms":{"title":"Podmínky použití","lead":"{appName} Podmínky použití.","sections":[{"title":"1. Souhlas s těmito Podmínkami a pravidly platformy","paragraphs":["Stažením, zakoupením nebo používáním aplikace {appName} souhlasíte s těmito Podmínkami a s pravidly, která se na vás vztahují v obchodě s aplikacemi, kde provádíte nákup. Pokud s nimi nesouhlasíte, aplikaci dále nepoužívejte ani neprovádějte nákup.","Tyto Podmínky se vztahují na stažení, nákup a používání aplikace. Pro verze iOS a iPadOS platí také"],"links":["appleEula"]},{"title":"2. Placené produkty a ceny","paragraphs":["Rozpoznávání a úpravy nemají limit použití. Platný přístup Premium je nutný pouze k exportu zpracovaného obrázku. Aplikace nabízí automaticky obnovované týdenní a měsíční předplatné a jednorázový doživotní nákup bez bezplatné zkušební verze. Nákupy v App Storu a Google Play jsou oddělené a nelze je převádět mezi platformami.","Skutečná cena, měna, daně, fakturační období a možnost nákupu odpovídají údajům zobrazeným a potvrzeným na systémové nákupní obrazovce App Store nebo Google Play. Platforma účtuje a spravuje platbu přes účet obchodu. Aplikace nenabízí bezplatné zkušební předplatné ani jiné placené plány."]},{"title":"3. Automatické obnovení a zrušení","paragraphs":["Týdenní a měsíční předplatná se automaticky obnovují a účtují za období uvedené na nákupní obrazovce, dokud je nezrušíte přes nákupní platformu. Smazání {appName} předplatné automaticky nezruší. Pokud platforma neposkytne vrácení peněz nebo jiné řešení, můžete po vypnutí obnovování používat předplatné do konce již zaplaceného období."],"links":["appleCancel","googleManage"]},{"title":"4. Nákupy, obnovení a vrácení peněz","paragraphs":["Nákupy a obnovení probíhají přes oficiální obchod Apple nebo Google. Oprávnění se udělí až po potvrzení platné transakce obchodem. Zrušené, neúspěšné nebo čekající transakce před potvrzením oprávnění neudělují. Obnovení může vrátit doživotní přístup a aktuálně aktivní předplatné. Nákupy App Store a Google Play jsou nezávislé a nelze je obnovit ani převést mezi platformami.","Vrácení peněz vyřizuje obchod, který transakci dokončil, podle vlastních pravidel, oblasti nákupu a platných zákonů. Oprávnění se odebere po potvrzení vrácení, odvolání, skončení předplatného nebo neplatné transakce."],"links":["appleRefund","googleRefund"]},{"title":"5. Offline použití a dostupnost","paragraphs":["Výběr obrázků, OCR, rozpoznání citlivého obsahu, úpravy a export probíhají v zařízení. Aplikace nenabízí cloudové rozpoznávání obrázků, synchronizaci s cloudem ani účty. Při exportu se vytvoří nový obrázek a odstraní se odstranitelná soukromá metadata. Dočasné pracovní soubory se smažou po úspěšném uložení, při zrušení úprav nebo ukončení relace; pokud se uložení nezdaří, může být zachován stav nutný k opakování."]},{"title":"6. Přijatelné použití a duševní vlastnictví","paragraphs":["Aplikaci nesmíte používat k nezákonné činnosti, obcházet ověření nákupů, poškozovat aplikaci, šířit škodlivý kód, kopírovat nebo distribuovat aplikaci bez svolení ani porušovat práva k obsahu aplikace nebo duševní vlastnictví jiných osob.","Aplikaci můžete kdykoli přestat používat a odinstalovat. Můžeme vydávat aktualizace k opravě problémů, podpoře systémů, zlepšení stability nebo splnění požadavků platforem. Problémy zařízení, systému, sítě nebo obchodu mohou některé funkce dočasně znepřístupnit.","V rozsahu povoleném platnými zákony je aplikace poskytována v dostupném stavu. Tyto Podmínky nevylučují odpovědnost, kterou nelze zákonně vyloučit, a neomezují povinná práva spotřebitelů.","Pokud se změní funkce, způsoby platby, pravidla platforem nebo zákony, můžeme aktualizovat Podmínky a datum stránky. Pokud změna podstatně ovlivní práva uživatelů, poskytneme požadované další oznámení.","S dotazy ohledně těchto Podmínek, nákupů nebo používání aplikace se obraťte na e-mail {email}"]}]},"support":{"title":"Podpora","lead":"Nejprve si přečtěte časté dotazy níže. Pokud problém trvá, kontaktujte nás přes e-mail podpory.","emailTitle":"E-mail podpory {appName}","emailLead":"Nejprve si přečtěte časté dotazy níže. Pokud problém trvá, kontaktujte nás přes e-mail podpory.","beforeEmail":{"title":"Co uvést v e-mailu","paragraphs":["U problému s nákupem můžete uvést číslo objednávky, ale neposílejte heslo účtu či platby ani úplné údaje karty."],"bullets":["platformu, model zařízení, verzi systému a verzi aplikace;","kroky před problémem, očekávaný a skutečný výsledek; a","v případě potřeby snímek obrazovky nebo záznam obrazovky se skrytými soukromými informacemi."]},"faqs":[{"question":"Nahrávají se obrázky na server?","answer":"Výběr obrázků, OCR, rozpoznání citlivého obsahu, úpravy a export probíhají v zařízení. Aplikace nenabízí cloudové rozpoznávání obrázků, synchronizaci s cloudem ani účty. Při exportu se vytvoří nový obrázek a odstraní se odstranitelná soukromá metadata. Dočasné pracovní soubory se smažou po úspěšném uložení, při zrušení úprav nebo ukončení relace; pokud se uložení nezdaří, může být zachován stav nutný k opakování."},{"question":"Oprávnění, reklamy a sledování","answer":"Přístup k fotografiím slouží pouze k zobrazení a zpracování obrázků, které povolíte. Fotoaparát se používá jen tehdy, když se rozhodnete pořídit fotografii v aplikaci. Oprávnění k uložení do knihovny fotografií se žádá pouze při potvrzení exportu s platným přístupem Premium. Aplikace nežádá o polohu, kontakty, mikrofon, Bluetooth ani oznámení."},{"question":"Placené produkty a ceny","answer":"Rozpoznávání a úpravy nemají limit použití. Platný přístup Premium je nutný pouze k exportu zpracovaného obrázku. Aplikace nabízí automaticky obnovované týdenní a měsíční předplatné a jednorázový doživotní nákup bez bezplatné zkušební verze. Nákupy v App Storu a Google Play jsou oddělené a nelze je převádět mezi platformami."},{"question":"Ukládání a formáty obrázků","answer":"Pokud se uložení nezdaří, zkontrolujte volné místo, oprávnění ukládat do knihovny fotografií a čitelnost původního obrázku a zkuste to znovu. Aplikace zpracovává vždy jeden statický obrázek a podporuje většinu běžných formátů; některé závisí na zařízení a verzi systému. Video, PDF, RAW/DNG a dávkové zpracování zatím nejsou podporovány."},{"question":"Jak změním jazyk?","answer":"Aplikace podporuje 40 jazyků, které lze změnit v nastavení. Při chybném zobrazení uveďte e-mailem jazyk zařízení a jazyk vybraný v aplikaci."},{"question":"Obnovení, zrušení a vrácení peněz","answer":"Nákupy a obnovení probíhají přes oficiální obchod Apple nebo Google. Oprávnění se udělí až po potvrzení platné transakce obchodem. Zrušené, neúspěšné nebo čekající transakce před potvrzením oprávnění neudělují. Obnovení může vrátit doživotní přístup a aktuálně aktivní předplatné. Nákupy App Store a Google Play jsou nezávislé a nelze je obnovit ani převést mezi platformami."},{"question":"Soukromí a odstranění dat","answer":"Data v zařízení odstraníte odinstalováním aplikace. V Androidu můžete také použít systémovou možnost „Vymazat data“. Záznamy nákupů spravuje Apple nebo Google. Obnovitelná oprávnění se znovu potvrzují podle pravidel obchodu. E-maily podpory uchováváme po dobu potřebnou k vyřízení požadavku a splnění nezbytných evidenčních povinností. E-mailem můžete požádat o odstranění podpůrné korespondence, kterou ještě uchováváme."}],"officialHelpTitle":"Rychlá pomoc"}},"da":{"linkLabels":{"appleEula":"Apples standardlicensaftale for slutbrugere (EULA)","appleCancel":"Instruktioner til opsigelse af Apple-abonnement","googleManage":"Vejledning til opsigelse i Google Play","appleRefund":"Anmod om en refusion fra Apple","googleRefund":"Oplysninger om refusion i Google Play"},"nav":{"privacy":"Privatlivspolitik","terms":"Brugsbetingelser","support":"Support","language":"Sprog","chooseLanguage":"Vælg visningssprog","navigationLabel":"Primær navigation"},"home":{"eyebrow":"{appName} · Privacy first","title":"Dine billeder uploades ikke til vores servere.","lead":"Billedvalg, OCR, registrering af følsomt indhold, redigering og eksport foregår på enheden. Appen tilbyder ikke billedgenkendelse eller synkronisering i skyen og har ingen konti. Ved eksport oprettes et nyt billede, og fjernbare private metadata slettes. Midlertidige arbejdsfiler fjernes efter vellykket lagring, når redigeringen opgives, eller sessionen slutter; hvis lagringen mislykkes, kan den nødvendige tilstand bevares til et nyt forsøg.","points":["Appdata","Betalte produkter og priser","Support"],"cards":[{"title":"Privatlivspolitik","description":"Dine billeder uploades ikke til vores servere.","action":"Privatlivspolitik"},{"title":"Brugsbetingelser","description":"Genkendelse og redigering har ingen brugsgrænser. Kun eksport af det behandlede billede kræver gyldig Premium-adgang. Appen tilbyder automatisk fornyede uge- og månedsabonnementer samt et engangskøb med livstidsadgang, uden gratis prøveperiode. Køb i App Store og Google Play er separate og kan ikke overføres mellem platformene.","action":"Brugsbetingelser"},{"title":"Brug for hjælp?","description":"Start med de ofte stillede spørgsmål nedenfor. Hvis problemet fortsætter, skal du kontakte os via supportmailadressen.","action":"Support"}]},"footer":{"privacy":"Privatlivspolitik","terms":"Brugsbetingelser","support":"Support"},"privacy":{"title":"Privatlivspolitik","lead":"Denne politik forklarer, hvordan {appName} håndterer data på enheden, købsoplysninger fra appbutikken og supportmails.","sections":[{"title":"1. Omfang og kontakt","paragraphs":["Denne politik gælder for appen {appName} til iOS, iPadOS og Android samt dette websted med privatlivspolitik, vilkår og support.","For spørgsmål om privatlivets fred, send en e-mail {email}"]},{"title":"2. Appdata","callout":{"title":"Dine billeder uploades ikke til vores servere.","body":"Billedvalg, OCR, registrering af følsomt indhold, redigering og eksport foregår på enheden. Appen tilbyder ikke billedgenkendelse eller synkronisering i skyen og har ingen konti. Ved eksport oprettes et nyt billede, og fjernbare private metadata slettes. Midlertidige arbejdsfiler fjernes efter vellykket lagring, når redigeringen opgives, eller sessionen slutter; hvis lagringen mislykkes, kan den nødvendige tilstand bevares til et nyt forsøg."},"paragraphs":[]},{"title":"3. Tilladelser, annoncering og sporing","paragraphs":["Fotoadgang bruges kun til at vise og behandle billeder, du godkender. Kameraet bruges kun, når du vælger at tage et foto i appen. Tilladelse til at gemme i fotobiblioteket anmodes kun, når du bekræfter eksport med gyldig Premium-adgang. Appen anmoder ikke om placering, kontakter, mikrofon, Bluetooth eller notifikationer.","Den bruger ikke et annonce-id og integrerer ikke SDK'er fra tredjeparter til annoncering, analyse, attribuering eller rapportering af nedbrud.","Appen integrerer ikke et værktøj fra en tredjepart til rapportering af nedbrud. Afhængigt af dine enheds- og butiksindstillinger kan Apple eller Google behandle systemdiagnostik efter deres respektive privatlivsregler og levere tekniske oplysninger, der bruges til at undersøge nedbrud eller problemer med ydeevnen."]},{"title":"4. Appbutikkens tjenester og netværksadgang","paragraphs":["Appen bruger Apple StoreKit eller Google Play Billing til at indlæse produkter, vise lokaliserede priser fra butikken, gennemføre køb, gendanne køb, administrere abonnementer og bekræfte adgange. Netværksadgang bruges kun til disse officielle butikstjenester fra Apple eller Google.","Apple eller Google er ansvarlig for butikskonti, betalinger, fakturering, transaktioner, refusioner og abonnementstjenester. Appen behandler kun de butiksoplysninger, der er nødvendige for at bekræfte produkter og adgange, og modtager eller gemmer ikke fuldstændige betalingsoplysninger."]},{"title":"5. Supportmails og websted","paragraphs":["Appen læser ikke automatisk dine mailoplysninger. Kun når du selv vælger at sende en supportmail, modtager supportkanalen din mailadresse, besked og eventuelle skærmbilleder, skærmoptagelser, ordrenumre eller andre bilag, som du frivilligt vedhæfter. Oplysningerne bruges kun til at behandle din henvendelse og ikke til annoncering eller markedsføring. Send ikke adgangskoder til konti eller betaling eller fulde kortnumre.","Dette websted indstiller ikke annonce- eller analysecookies og indeholder ikke trafikanalyse eller sporingsscripts."]},{"title":"6. Opbevaring og sletning","paragraphs":["Slet data på enheden ved at afinstallere appen. På Android kan du også bruge systemets funktion Ryd data.","Købsregistreringer administreres af Apple eller Google. Adgange, der kan gendannes, bekræftes igen efter butikkens regler.","Supportmails opbevares, så længe det er nødvendigt for at behandle henvendelsen og opfylde nødvendige krav til journalføring. Du kan sende os en mail for at anmode om sletning af supportkorrespondance, som vi stadig opbevarer."]},{"title":"7. Datasikkerhed","paragraphs":["Appen bruger behandling på enheden, færrest mulige tilladelser og officielle købsforløb i appbutikken for at reducere unødvendige dataoverførsler. Supportmails bruges kun til at behandle indgående henvendelser og beskyttes med rimelige foranstaltninger, der passer til oplysningernes karakter.","Ingen enhed, intet netværk og ingen elektronisk lagringsmetode kan garanteres at være fuldstændig sikker. Medtag ikke uvedkommende følsomme oplysninger i en supportmail."]},{"title":"8. Børn og unge","paragraphs":["Appen kræver ikke en konto og opbygger ikke profiler af børn eller andre brugere gennem annoncering eller adfærdsanalyse. En forælder eller værge, som mener, at et barn har sendt personoplysninger via en supportmail, kan kontakte os for at få sagen behandlet."]},{"title":"9. Dine valg og rettigheder","paragraphs":["Du administrerer data på enheden via din enhed. Apple eller Google administrerer butikskonti og købsregistreringer. Appen kan ikke ændre eller slette transaktionsregistreringer, som en appbutik opbevarer på dine vegne.","Hvis appens datapraksis, platformregler eller webstedets hosting ændres, opdaterer vi denne politik og datoen på siden og giver yderligere meddelelse, hvor gældende regler kræver det.","For spørgsmål om privatlivets fred, send en e-mail {email}"]}]},"terms":{"title":"Brugsbetingelser","lead":"{appName} Brugsbetingelser.","sections":[{"title":"1. Accept af disse vilkår og platformregler","paragraphs":["Ved at downloade, købe eller bruge {appName} accepterer du disse vilkår og de regler, der gælder for dig i den appbutik, hvor du foretager et køb. Hvis du ikke accepterer, skal du ikke fortsætte med at bruge appen eller foretage et køb.","Disse vilkår gælder for din download, dit køb og din brug af appen. iOS- og iPadOS-versionerne er også underlagt"],"links":["appleEula"]},{"title":"2. Betalte produkter og priser","paragraphs":["Genkendelse og redigering har ingen brugsgrænser. Kun eksport af det behandlede billede kræver gyldig Premium-adgang. Appen tilbyder automatisk fornyede uge- og månedsabonnementer samt et engangskøb med livstidsadgang, uden gratis prøveperiode. Køb i App Store og Google Play er separate og kan ikke overføres mellem platformene.","Den faktiske pris, valuta, skatter, faktureringsperiode og købsmulighed er de oplysninger, som vises og bekræftes på systemets købsskærm i App Store eller Google Play. Købsplatformen opkræver og administrerer betalingen via din butikskonto. Appen tilbyder ikke en gratis abonnementsprøveperiode eller andre betalingsplaner."]},{"title":"3. Automatisk fornyelse og opsigelse","paragraphs":["Ugentlige og månedlige abonnementer fornyes automatisk og debiteres for den faktureringsperiode, der vises på systemets købsskærm, indtil du opsiger via købsplatformen. Et abonnement opsiges ikke automatisk, når {appName} slettes. Medmindre købsplatformen giver en refusion eller anden behandling, kan du fortsætte med at bruge abonnementet indtil udgangen af den aktuelle betalte periode, efter at automatisk fornyelse er slået fra."],"links":["appleCancel","googleManage"]},{"title":"4. Køb, gendannelse og refusion","paragraphs":["Køb og gendannelse af køb gennemføres via den officielle Apple- eller Google-butik. En adgang tildeles først, når butikken har bekræftet en gyldig transaktion. Annullerede, mislykkede eller afventende transaktioner giver ikke adgang før en vellykket bekræftelse. Gendannelse af køb kan gendanne livstidsadgang og et aktuelt aktivt abonnement. Køb i App Store og Google Play er adskilte og kan ikke gendannes eller overføres på tværs af platforme.","Refusioner håndteres af den appbutik, der gennemførte transaktionen, efter dens regler, købsområdet og gældende lov. Den tilhørende adgang fjernes, når butikken bekræfter en refusion, tilbagekaldelse, udløbet abonnement eller ugyldig transaktion."],"links":["appleRefund","googleRefund"]},{"title":"5. Offlinebrug og tilgængelighed","paragraphs":["Billedvalg, OCR, registrering af følsomt indhold, redigering og eksport foregår på enheden. Appen tilbyder ikke billedgenkendelse eller synkronisering i skyen og har ingen konti. Ved eksport oprettes et nyt billede, og fjernbare private metadata slettes. Midlertidige arbejdsfiler fjernes efter vellykket lagring, når redigeringen opgives, eller sessionen slutter; hvis lagringen mislykkes, kan den nødvendige tilstand bevares til et nyt forsøg."]},{"title":"6. Acceptabel brug og immaterielle rettigheder","paragraphs":["Du må ikke bruge appen til ulovlig aktivitet, omgå købsbekræftelse, beskadige appen, distribuere skadelig kode, kopiere eller distribuere appen uden tilladelse eller krænke rettigheder til appens indhold eller en anden persons immaterielle rettigheder.","Du kan til enhver tid stoppe med at bruge og afinstallere appen. Vi kan udgive opdateringer for at løse problemer, understøtte operativsystemer, forbedre stabiliteten eller opfylde platformkrav. Problemer med enheden, systemet, netværket eller butikstjenesten kan gøre visse funktioner midlertidigt utilgængelige.","I det omfang gældende lov tillader det, leveres appen, som den er tilgængelig. Disse vilkår udelukker ikke ansvar, der ikke lovligt kan udelukkes, og begrænser ikke ufravigelige forbrugerrettigheder, du har.","Hvis produktfunktioner, betalingsmetoder, platformregler eller gældende lov ændres, kan vi opdatere disse vilkår og datoen på siden. Hvis en ændring påvirker brugernes rettigheder væsentligt, giver vi yderligere meddelelse som påkrævet.","Ved spørgsmål om disse vilkår, køb eller brug af appen, send en e-mail {email}"]}]},"support":{"title":"Support","lead":"Start med de ofte stillede spørgsmål nedenfor. Hvis problemet fortsætter, skal du kontakte os via supportmailadressen.","emailTitle":"{appName} support-e-mail","emailLead":"Start med de ofte stillede spørgsmål nedenfor. Hvis problemet fortsætter, skal du kontakte os via supportmailadressen.","beforeEmail":{"title":"Hvad du skal medtage i din mail","paragraphs":["Ved et købsproblem kan du medtage appbutikkens ordrenummer, men du må ikke sende adgangskoden til din konto eller betaling eller fulde kortoplysninger."],"bullets":["din platform, enhedsmodel, version af operativsystemet og appversion;","hvad du gjorde før problemet, hvad du forventede, og hvad der faktisk skete; og","om nødvendigt, et skærmbillede eller en skærmoptagelse med skjulte private oplysninger."]},"faqs":[{"question":"Bliver billeder uploadet til en server?","answer":"Billedvalg, OCR, registrering af følsomt indhold, redigering og eksport foregår på enheden. Appen tilbyder ikke billedgenkendelse eller synkronisering i skyen og har ingen konti. Ved eksport oprettes et nyt billede, og fjernbare private metadata slettes. Midlertidige arbejdsfiler fjernes efter vellykket lagring, når redigeringen opgives, eller sessionen slutter; hvis lagringen mislykkes, kan den nødvendige tilstand bevares til et nyt forsøg."},{"question":"Tilladelser, annoncering og sporing","answer":"Fotoadgang bruges kun til at vise og behandle billeder, du godkender. Kameraet bruges kun, når du vælger at tage et foto i appen. Tilladelse til at gemme i fotobiblioteket anmodes kun, når du bekræfter eksport med gyldig Premium-adgang. Appen anmoder ikke om placering, kontakter, mikrofon, Bluetooth eller notifikationer."},{"question":"Betalte produkter og priser","answer":"Genkendelse og redigering har ingen brugsgrænser. Kun eksport af det behandlede billede kræver gyldig Premium-adgang. Appen tilbyder automatisk fornyede uge- og månedsabonnementer samt et engangskøb med livstidsadgang, uden gratis prøveperiode. Køb i App Store og Google Play er separate og kan ikke overføres mellem platformene."},{"question":"Lagring og billedformater","answer":"Hvis lagring mislykkes, skal du kontrollere ledig plads, tilladelsen til at gemme i fotobiblioteket og at originalbilledet stadig kan læses og derefter prøve igen. Appen behandler ét stillbillede ad gangen og understøtter de fleste almindelige formater; nogle afhænger af enhed og systemversion. Video, PDF, RAW/DNG og batchbehandling understøttes ikke i øjeblikket."},{"question":"Hvordan ændrer jeg sproget?","answer":"Appen understøtter 40 sprog, som kan ændres i appens indstillinger. Hvis visningen er forkert, skal du sende en mail med enhedens sprog og det sprog, der er valgt i appen."},{"question":"Gendannelse, opsigelse og refusion","answer":"Køb og gendannelse af køb gennemføres via den officielle Apple- eller Google-butik. En adgang tildeles først, når butikken har bekræftet en gyldig transaktion. Annullerede, mislykkede eller afventende transaktioner giver ikke adgang før en vellykket bekræftelse. Gendannelse af køb kan gendanne livstidsadgang og et aktuelt aktivt abonnement. Køb i App Store og Google Play er adskilte og kan ikke gendannes eller overføres på tværs af platforme."},{"question":"Privatliv og sletning af data","answer":"Slet data på enheden ved at afinstallere appen. På Android kan du også bruge systemets funktion Ryd data. Købsregistreringer administreres af Apple eller Google. Adgange, der kan gendannes, bekræftes igen efter butikkens regler. Supportmails opbevares, så længe det er nødvendigt for at behandle henvendelsen og opfylde nødvendige krav til journalføring. Du kan sende os en mail for at anmode om sletning af supportkorrespondance, som vi stadig opbevarer."}],"officialHelpTitle":"Hurtig hjælp"}},"de":{"linkLabels":{"appleEula":"Apple-Standard-Endbenutzer-Lizenzvereinbarung (EULA)","appleCancel":"Anleitung zur Kündigung des Apple-Abonnements","googleManage":"Anleitung zur Kündigung bei Google Play","appleRefund":"Fordern Sie eine Rückerstattung von Apple an.","googleRefund":"Informationen zu Google Play-Erstattungen"},"nav":{"privacy":"Datenschutzrichtlinie","terms":"Nutzungsbedingungen","support":"Support","language":"Sprache","chooseLanguage":"Anzeigesprache auswählen","navigationLabel":"Primärnavigation"},"home":{"eyebrow":"{appName} · Privacy first","title":"Ihre Bilder werden nicht auf unsere Server hochgeladen.","lead":"Bildauswahl, OCR, Erkennung sensibler Inhalte, Bearbeitung und Export erfolgen auf Ihrem Gerät. Die App bietet weder cloudbasierte Bilderkennung noch Cloud-Synchronisierung oder Konten. Beim Export wird ein neues Bild erstellt und entfernbare private Metadaten werden gelöscht. Temporäre Arbeitsdateien werden nach erfolgreichem Speichern, beim Verwerfen der Bearbeitung oder am Sitzungsende entfernt; nach einem Speicherfehler kann der für einen erneuten Versuch nötige Zustand erhalten bleiben.","points":["App-Daten","Kostenpflichtige Produkte und Preise","Support"],"cards":[{"title":"Datenschutzrichtlinie","description":"Ihre Bilder werden nicht auf unsere Server hochgeladen.","action":"Datenschutzrichtlinie"},{"title":"Nutzungsbedingungen","description":"Erkennung und Bearbeitung sind ohne Nutzungslimit verfügbar. Nur der Export des bearbeiteten Bildes erfordert einen gültigen Premium-Zugang. Angeboten werden automatisch verlängernde Wochen- und Monatsabonnements sowie ein einmaliger lebenslanger Kauf, ohne kostenlose Testphase. Käufe im App Store und bei Google Play sind getrennt und nicht plattformübergreifend übertragbar.","action":"Nutzungsbedingungen"},{"title":"Brauchen Sie Hilfe?","description":"Lies zunächst die folgenden häufigen Fragen. Wenn das Problem weiterhin besteht, kontaktiere uns über die Support-E-Mail-Adresse.","action":"Support"}]},"footer":{"privacy":"Datenschutzrichtlinie","terms":"Nutzungsbedingungen","support":"Support"},"privacy":{"title":"Datenschutzrichtlinie","lead":"Diese Richtlinie erklärt, wie {appName} Daten auf dem Gerät, Kaufinformationen des App-Stores und Support-E-Mails behandelt.","sections":[{"title":"1. Geltungsbereich und Kontakt","paragraphs":["Diese Richtlinie gilt für die App {appName} für iOS, iPadOS und Android sowie für diese Datenschutz-, Nutzungsbedingungen- und Support-Website.","Bei Fragen zum Datenschutz senden Sie bitte eine E-Mail. {email}"]},{"title":"2. App-Daten","callout":{"title":"Ihre Bilder werden nicht auf unsere Server hochgeladen.","body":"Bildauswahl, OCR, Erkennung sensibler Inhalte, Bearbeitung und Export erfolgen auf Ihrem Gerät. Die App bietet weder cloudbasierte Bilderkennung noch Cloud-Synchronisierung oder Konten. Beim Export wird ein neues Bild erstellt und entfernbare private Metadaten werden gelöscht. Temporäre Arbeitsdateien werden nach erfolgreichem Speichern, beim Verwerfen der Bearbeitung oder am Sitzungsende entfernt; nach einem Speicherfehler kann der für einen erneuten Versuch nötige Zustand erhalten bleiben."},"paragraphs":[]},{"title":"3. Berechtigungen, Werbung und Tracking","paragraphs":["Der Fotozugriff dient nur dazu, von Ihnen freigegebene Bilder anzuzeigen und zu verarbeiten. Die Kamera wird nur verwendet, wenn Sie in der App ein Foto aufnehmen. Die Berechtigung zum Speichern in der Fotomediathek wird nur beim bestätigten Export mit gültigem Premium-Zugang angefordert. Die App fordert keinen Zugriff auf Standort, Kontakte, Mikrofon, Bluetooth oder Mitteilungen an.","Sie verwendet keine Werbe-ID und bindet keine Drittanbieter-SDKs für Werbung, Analyse, Attribution oder Absturzberichte ein.","Die App bindet kein Drittanbieter-Tool für Absturzberichte ein. Abhängig von deinen Geräte- und Store-Einstellungen können Apple oder Google Systemdiagnosedaten nach ihren eigenen Datenschutzregeln verarbeiten und technische Informationen bereitstellen, die zur Untersuchung von Abstürzen oder Leistungsproblemen verwendet werden."]},{"title":"4. App-Store-Dienste und Netzwerkzugriff","paragraphs":["Die App verwendet Apple StoreKit oder Google Play Billing, um Produkte zu laden, vom Store gelieferte lokalisierte Preise anzuzeigen, Käufe abzuschließen und wiederherzustellen, Abonnements zu verwalten und Berechtigungen zu bestätigen. Der Netzwerkzugriff wird nur für diese offiziellen Store-Funktionen von Apple oder Google verwendet.","Apple oder Google ist für Store-Konten, Zahlungen, Abrechnung, Transaktionen, Erstattungen und Abonnementdienste verantwortlich. Die App verarbeitet nur die Store-Informationen, die zur Bestätigung von Produkten und Berechtigungen erforderlich sind, und erhält oder speichert keine vollständigen Zahlungsdaten."]},{"title":"5. Support-E-Mails und Website","paragraphs":["Die App liest deine E-Mail-Daten nicht automatisch. Nur wenn du eine Support-E-Mail sendest, erhält der Support-Kanal deine E-Mail-Adresse, Nachricht und freiwillig beigefügte Screenshots, Bildschirmaufnahmen, Bestellnummern oder andere Anhänge. Diese Informationen werden ausschließlich zur Bearbeitung deiner Anfrage und nicht für Werbung oder Marketing verwendet. Sende keine Konto- oder Zahlungspasswörter und keine vollständigen Kartennummern.","Diese Website setzt keine Werbe- oder Analyse-Cookies ein und enthält keine Skripte zur Besucheranalyse oder Nachverfolgung."]},{"title":"6. Aufbewahrung und Löschung","paragraphs":["Deinstalliere die App, um Daten auf dem Gerät zu löschen. Unter Android kannst du zusätzlich die Systemoption „Daten löschen“ verwenden.","Kaufaufzeichnungen werden von Apple oder Google verwaltet. Wiederherstellbare Berechtigungen werden nach den Regeln des Stores erneut bestätigt.","Support-E-Mails werden so lange aufbewahrt, wie es zur Bearbeitung der Anfrage und zur Erfüllung notwendiger Aufzeichnungspflichten erforderlich ist. Du kannst uns per E-Mail auffordern, noch vorhandene Support-Korrespondenz zu löschen."]},{"title":"7. Datensicherheit","paragraphs":["Die App nutzt Verarbeitung auf dem Gerät, minimale Berechtigungen und offizielle App-Store-Kaufabläufe, um unnötige Datenübertragungen zu verringern. Support-E-Mails dienen nur der Bearbeitung eingehender Anfragen und werden mit angemessenen, der Art der Informationen entsprechenden Maßnahmen geschützt.","Für kein Gerät, Netzwerk oder elektronisches Speicherverfahren kann vollständige Sicherheit garantiert werden. Füge einer Support-E-Mail keine sachfremden sensiblen Informationen bei."]},{"title":"8. Kinder und Jugendliche","paragraphs":["Die App erfordert kein Konto und erstellt durch Werbung oder Verhaltensanalyse keine Profile von Kindern oder anderen Nutzern. Eltern oder Erziehungsberechtigte, die annehmen, dass ein Kind in einer Support-E-Mail personenbezogene Daten übermittelt hat, können uns zur Klärung kontaktieren."]},{"title":"9. Deine Auswahlmöglichkeiten und Rechte","paragraphs":["Du verwaltest lokale Daten über dein Gerät. Apple oder Google verwaltet Store-Konten und Kaufaufzeichnungen. Die App kann die von einem App-Store gespeicherten Transaktionsaufzeichnungen nicht in deinem Namen ändern oder löschen.","Wenn sich die Datenpraktiken der App, Plattformregeln oder das Hosting der Website ändern, aktualisieren wir diese Richtlinie und das Datum auf dieser Seite und geben einen zusätzlichen Hinweis, sofern anwendbare Regeln dies verlangen.","Bei Fragen zum Datenschutz senden Sie bitte eine E-Mail. {email}"]}]},"terms":{"title":"Nutzungsbedingungen","lead":"{appName} Nutzungsbedingungen.","sections":[{"title":"1. Annahme der Nutzungsbedingungen und Plattformregeln","paragraphs":["Durch das Herunterladen, Kaufen oder Verwenden von {appName} stimmen Sie diesen Nutzungsbedingungen und den für Sie geltenden Regeln des App Stores, in dem Sie den Kauf tätigen, zu. Wenn Sie nicht zustimmen, verwenden Sie die App bitte nicht weiter und tätigen Sie keinen Kauf.","Diese Bedingungen gelten für Download, Kauf und Nutzung der App. Für die iOS- und iPadOS-Versionen gilt außerdem die"],"links":["appleEula"]},{"title":"2. Kostenpflichtige Produkte und Preise","paragraphs":["Erkennung und Bearbeitung sind ohne Nutzungslimit verfügbar. Nur der Export des bearbeiteten Bildes erfordert einen gültigen Premium-Zugang. Angeboten werden automatisch verlängernde Wochen- und Monatsabonnements sowie ein einmaliger lebenslanger Kauf, ohne kostenlose Testphase. Käufe im App Store und bei Google Play sind getrennt und nicht plattformübergreifend übertragbar.","Tatsächlicher Preis, Währung, Steuern, Abrechnungszeitraum und Kaufberechtigung entsprechen den Angaben, die im System-Kaufbildschirm des App Store oder von Google Play angezeigt und von dir bestätigt werden. Die Kaufplattform belastet und verwaltet die Zahlung über dein Store-Konto. Die App bietet weder einen kostenlosen Abonnement-Testzeitraum noch weitere kostenpflichtige Tarife."]},{"title":"3. Automatische Verlängerung und Kündigung","paragraphs":["Wochen- und Monatsabonnements verlängern sich automatisch und werden für den im System-Kaufbildschirm angegebenen Zeitraum abgerechnet, bis du sie über die Kaufplattform kündigst. Durch das Löschen von {appName} wird ein Abonnement nicht automatisch gekündigt. Sofern die Kaufplattform keine Erstattung oder andere Behandlung vorsieht, kannst du das Abonnement nach Deaktivierung der automatischen Verlängerung bis zum Ende des bereits bezahlten Zeitraums nutzen."],"links":["appleCancel","googleManage"]},{"title":"4. Käufe, Wiederherstellung und Erstattungen","paragraphs":["Käufe und Kaufwiederherstellungen erfolgen über den offiziellen Store von Apple oder Google. Eine Berechtigung wird erst erteilt, nachdem der Store eine gültige Transaktion bestätigt hat. Stornierte, fehlgeschlagene oder ausstehende Transaktionen erteilen vor erfolgreicher Bestätigung keine Berechtigung. Die Kaufwiederherstellung kann lebenslangen Zugriff und ein derzeit aktives Abonnement wiederherstellen. Käufe im App Store und bei Google Play sind voneinander getrennt und können nicht plattformübergreifend wiederhergestellt oder übertragen werden.","Erstattungen werden vom App-Store, der die Transaktion abgeschlossen hat, gemäß seinen Regeln, der Kaufregion und geltendem Recht bearbeitet. Die zugehörige Berechtigung wird entfernt, nachdem der Store eine Erstattung, einen Widerruf, das Ende eines Abonnements oder eine ungültige Transaktion bestätigt hat."],"links":["appleRefund","googleRefund"]},{"title":"5. Offline-Nutzung und Verfügbarkeit","paragraphs":["Bildauswahl, OCR, Erkennung sensibler Inhalte, Bearbeitung und Export erfolgen auf Ihrem Gerät. Die App bietet weder cloudbasierte Bilderkennung noch Cloud-Synchronisierung oder Konten. Beim Export wird ein neues Bild erstellt und entfernbare private Metadaten werden gelöscht. Temporäre Arbeitsdateien werden nach erfolgreichem Speichern, beim Verwerfen der Bearbeitung oder am Sitzungsende entfernt; nach einem Speicherfehler kann der für einen erneuten Versuch nötige Zustand erhalten bleiben."]},{"title":"6. Zulässige Nutzung und geistiges Eigentum","paragraphs":["Du darfst die App nicht für rechtswidrige Aktivitäten verwenden, Kaufprüfungen umgehen, die App beschädigen, Schadcode verbreiten, die App ohne Erlaubnis kopieren oder verteilen oder Rechte an App-Inhalten oder das geistige Eigentum anderer verletzen.","Du kannst die Nutzung jederzeit beenden und die App deinstallieren. Wir können Aktualisierungen veröffentlichen, um Probleme zu beheben, Betriebssysteme zu unterstützen, die Stabilität zu verbessern oder Plattformanforderungen zu erfüllen. Probleme mit Gerät, System, Netzwerk oder Store-Dienst können einzelne Funktionen vorübergehend unzugänglich machen.","Soweit nach geltendem Recht zulässig, wird die App nach Verfügbarkeit bereitgestellt. Diese Bedingungen schließen keine Haftung aus, die rechtlich nicht ausgeschlossen werden darf, und beschränken keine zwingenden Verbraucherrechte.","Wenn sich Produktfunktionen, Zahlungsmethoden, Plattformregeln oder geltendes Recht ändern, können wir diese Bedingungen und das Datum auf dieser Seite aktualisieren. Wenn eine Änderung Nutzerrechte wesentlich betrifft, geben wir den erforderlichen zusätzlichen Hinweis.","Bei Fragen zu diesen Nutzungsbedingungen, Käufen oder der Nutzung der App senden Sie bitte eine E-Mail an [E-Mail-Adresse einfügen]. {email}"]}]},"support":{"title":"Support","lead":"Lies zunächst die folgenden häufigen Fragen. Wenn das Problem weiterhin besteht, kontaktiere uns über die Support-E-Mail-Adresse.","emailTitle":"{appName} Support-E-Mail","emailLead":"Lies zunächst die folgenden häufigen Fragen. Wenn das Problem weiterhin besteht, kontaktiere uns über die Support-E-Mail-Adresse.","beforeEmail":{"title":"Angaben für deine E-Mail","paragraphs":["Bei einem Kaufproblem kannst du die Bestellnummer des App-Stores angeben. Sende jedoch weder dein Konto- oder Zahlungspasswort noch vollständige Kartendaten."],"bullets":["Plattform, Gerätemodell, Betriebssystemversion und App-Version;","deine Schritte vor dem Problem sowie erwartetes und tatsächliches Ergebnis; und","Bei Bedarf ein Screenshot oder eine Bildschirmaufnahme, bei der private Informationen unkenntlich gemacht werden."]},"faqs":[{"question":"Werden Bilder auf einen Server hochgeladen?","answer":"Bildauswahl, OCR, Erkennung sensibler Inhalte, Bearbeitung und Export erfolgen auf Ihrem Gerät. Die App bietet weder cloudbasierte Bilderkennung noch Cloud-Synchronisierung oder Konten. Beim Export wird ein neues Bild erstellt und entfernbare private Metadaten werden gelöscht. Temporäre Arbeitsdateien werden nach erfolgreichem Speichern, beim Verwerfen der Bearbeitung oder am Sitzungsende entfernt; nach einem Speicherfehler kann der für einen erneuten Versuch nötige Zustand erhalten bleiben."},{"question":"Berechtigungen, Werbung und Tracking","answer":"Der Fotozugriff dient nur dazu, von Ihnen freigegebene Bilder anzuzeigen und zu verarbeiten. Die Kamera wird nur verwendet, wenn Sie in der App ein Foto aufnehmen. Die Berechtigung zum Speichern in der Fotomediathek wird nur beim bestätigten Export mit gültigem Premium-Zugang angefordert. Die App fordert keinen Zugriff auf Standort, Kontakte, Mikrofon, Bluetooth oder Mitteilungen an."},{"question":"Kostenpflichtige Produkte und Preise","answer":"Erkennung und Bearbeitung sind ohne Nutzungslimit verfügbar. Nur der Export des bearbeiteten Bildes erfordert einen gültigen Premium-Zugang. Angeboten werden automatisch verlängernde Wochen- und Monatsabonnements sowie ein einmaliger lebenslanger Kauf, ohne kostenlose Testphase. Käufe im App Store und bei Google Play sind getrennt und nicht plattformübergreifend übertragbar."},{"question":"Speichern und Bildformate","answer":"Wenn das Speichern fehlschlägt, prüfen Sie freien Speicherplatz, die Berechtigung für die Fotomediathek und ob das Originalbild noch lesbar ist, und versuchen Sie es erneut. Die App verarbeitet jeweils ein Standbild und unterstützt die meisten gängigen Bildformate; einige Formate hängen von Gerät und Systemversion ab. Videos, PDF, RAW/DNG und Stapelverarbeitung werden derzeit nicht unterstützt."},{"question":"Wie ändere ich die Sprache?","answer":"Die App unterstützt 40 Sprachen, die in den App-Einstellungen geändert werden können. Bei falscher Anzeige nenne uns per E-Mail die Gerätesprache und die in der App ausgewählte Sprache."},{"question":"Wiederherstellung, Kündigung und Erstattungen","answer":"Käufe und Kaufwiederherstellungen erfolgen über den offiziellen Store von Apple oder Google. Eine Berechtigung wird erst erteilt, nachdem der Store eine gültige Transaktion bestätigt hat. Stornierte, fehlgeschlagene oder ausstehende Transaktionen erteilen vor erfolgreicher Bestätigung keine Berechtigung. Die Kaufwiederherstellung kann lebenslangen Zugriff und ein derzeit aktives Abonnement wiederherstellen. Käufe im App Store und bei Google Play sind voneinander getrennt und können nicht plattformübergreifend wiederhergestellt oder übertragen werden."},{"question":"Datenschutz und Datenlöschung","answer":"Deinstalliere die App, um Daten auf dem Gerät zu löschen. Unter Android kannst du zusätzlich die Systemoption „Daten löschen“ verwenden. Kaufaufzeichnungen werden von Apple oder Google verwaltet. Wiederherstellbare Berechtigungen werden nach den Regeln des Stores erneut bestätigt. Support-E-Mails werden so lange aufbewahrt, wie es zur Bearbeitung der Anfrage und zur Erfüllung notwendiger Aufzeichnungspflichten erforderlich ist. Du kannst uns per E-Mail auffordern, noch vorhandene Support-Korrespondenz zu löschen."}],"officialHelpTitle":"Schnelle Hilfe"}},"el":{"linkLabels":{"appleEula":"Τυπική άδεια τελικού χρήστη της Apple (EULA)","appleCancel":"Οδηγίες ακύρωσης συνδρομής Apple","googleManage":"Οδηγίες ακύρωσης Google Play","appleRefund":"Αίτημα επιστροφής χρημάτων από την Apple","googleRefund":"Πληροφορίες επιστροφής χρημάτων Google Play"},"nav":{"privacy":"Πολιτική Απορρήτου","terms":"Όροι Χρήσης","support":"Υποστήριξη","language":"Γλώσσα","chooseLanguage":"Επιλογή γλώσσας εμφάνισης","navigationLabel":"Κύρια πλοήγηση"},"home":{"eyebrow":"{appName} · Privacy first","title":"Οι εικόνες σας δεν μεταφορτώνονται στους διακομιστές μας.","lead":"Η επιλογή εικόνων, το OCR, ο εντοπισμός ευαίσθητου περιεχομένου, η επεξεργασία και η εξαγωγή γίνονται στη συσκευή. Η εφαρμογή δεν προσφέρει αναγνώριση εικόνων ή συγχρονισμό στο cloud ούτε λογαριασμούς. Κατά την εξαγωγή δημιουργείται νέα εικόνα και αφαιρούνται τα διαγράψιμα ιδιωτικά μεταδεδομένα. Τα προσωρινά αρχεία εργασίας διαγράφονται μετά από επιτυχή αποθήκευση, εγκατάλειψη της επεξεργασίας ή λήξη της συνεδρίας· αν η αποθήκευση αποτύχει, μπορεί να διατηρηθεί η απαραίτητη κατάσταση για νέα προσπάθεια.","points":["Δεδομένα εφαρμογής","Προϊόντα επί πληρωμή και τιμές","Υποστήριξη"],"cards":[{"title":"Πολιτική Απορρήτου","description":"Οι εικόνες σας δεν μεταφορτώνονται στους διακομιστές μας.","action":"Πολιτική Απορρήτου"},{"title":"Όροι Χρήσης","description":"Η αναγνώριση και η επεξεργασία δεν έχουν όριο χρήσης. Μόνο η εξαγωγή της επεξεργασμένης εικόνας απαιτεί έγκυρη πρόσβαση Premium. Προσφέρονται εβδομαδιαίες και μηνιαίες συνδρομές αυτόματης ανανέωσης και μία εφάπαξ ισόβια αγορά, χωρίς δωρεάν δοκιμή. Οι αγορές App Store και Google Play είναι ξεχωριστές και δεν μεταφέρονται μεταξύ πλατφορμών.","action":"Όροι Χρήσης"},{"title":"Χρειάζεστε βοήθεια;","description":"Δείτε πρώτα τις συχνές ερωτήσεις παρακάτω. Αν το πρόβλημα παραμένει, επικοινωνήστε μέσω του email υποστήριξης.","action":"Υποστήριξη"}]},"footer":{"privacy":"Πολιτική Απορρήτου","terms":"Όροι Χρήσης","support":"Υποστήριξη"},"privacy":{"title":"Πολιτική Απορρήτου","lead":"Η παρούσα Πολιτική εξηγεί πώς το {appName} χειρίζεται δεδομένα στη συσκευή, πληροφορίες αγορών από το κατάστημα και email υποστήριξης.","sections":[{"title":"1. Πεδίο εφαρμογής και επικοινωνία","paragraphs":["Η παρούσα Πολιτική ισχύει για την εφαρμογή {appName} σε iOS, iPadOS και Android και για αυτόν τον ιστότοπο απορρήτου, όρων και υποστήριξης.","Για ερωτήσεις σχετικά με το απόρρητο, στείλτε email στο email σας. {email}"]},{"title":"2. Δεδομένα εφαρμογής","callout":{"title":"Οι εικόνες σας δεν μεταφορτώνονται στους διακομιστές μας.","body":"Η επιλογή εικόνων, το OCR, ο εντοπισμός ευαίσθητου περιεχομένου, η επεξεργασία και η εξαγωγή γίνονται στη συσκευή. Η εφαρμογή δεν προσφέρει αναγνώριση εικόνων ή συγχρονισμό στο cloud ούτε λογαριασμούς. Κατά την εξαγωγή δημιουργείται νέα εικόνα και αφαιρούνται τα διαγράψιμα ιδιωτικά μεταδεδομένα. Τα προσωρινά αρχεία εργασίας διαγράφονται μετά από επιτυχή αποθήκευση, εγκατάλειψη της επεξεργασίας ή λήξη της συνεδρίας· αν η αποθήκευση αποτύχει, μπορεί να διατηρηθεί η απαραίτητη κατάσταση για νέα προσπάθεια."},"paragraphs":[]},{"title":"3. Άδειες, διαφημίσεις και παρακολούθηση","paragraphs":["Η πρόσβαση στις φωτογραφίες χρησιμοποιείται μόνο για εμφάνιση και επεξεργασία εικόνων που εγκρίνετε. Η κάμερα χρησιμοποιείται μόνο όταν επιλέγετε λήψη μέσα στην εφαρμογή. Η άδεια αποθήκευσης στη βιβλιοθήκη ζητείται μόνο όταν επιβεβαιώνετε εξαγωγή με έγκυρη πρόσβαση Premium. Η εφαρμογή δεν ζητά τοποθεσία, επαφές, μικρόφωνο, Bluetooth ή ειδοποιήσεις.","Δεν χρησιμοποιεί αναγνωριστικό διαφήμισης και δεν ενσωματώνει SDK τρίτων για διαφημίσεις, αναλύσεις, απόδοση ή αναφορές σφαλμάτων.","Η εφαρμογή δεν ενσωματώνει εργαλείο αναφοράς σφαλμάτων τρίτου. Ανάλογα με τις ρυθμίσεις συσκευής και καταστήματος, η Apple ή η Google μπορεί να επεξεργάζεται διαγνωστικές πληροφορίες συστήματος σύμφωνα με τους κανόνες απορρήτου της και να παρέχει τεχνικά δεδομένα για διερεύνηση σφαλμάτων ή προβλημάτων απόδοσης."]},{"title":"4. Υπηρεσίες καταστήματος και πρόσβαση δικτύου","paragraphs":["Η εφαρμογή χρησιμοποιεί Apple StoreKit ή Google Play Billing για φόρτωση προϊόντων, εμφάνιση τοπικών τιμών από το κατάστημα, ολοκλήρωση και επαναφορά αγορών, διαχείριση συνδρομών και επιβεβαίωση δικαιωμάτων. Η πρόσβαση δικτύου χρησιμοποιείται μόνο για αυτές τις επίσημες λειτουργίες καταστήματος Apple ή Google.","Η Apple ή η Google είναι υπεύθυνη για λογαριασμούς καταστήματος, πληρωμές, χρεώσεις, συναλλαγές, επιστροφές χρημάτων και υπηρεσίες συνδρομών. Η εφαρμογή επεξεργάζεται μόνο τις πληροφορίες καταστήματος που απαιτούνται για επιβεβαίωση προϊόντων και δικαιωμάτων και δεν λαμβάνει ούτε αποθηκεύει πλήρη στοιχεία πληρωμής."]},{"title":"5. Email υποστήριξης και ιστότοπος","paragraphs":["Η εφαρμογή δεν διαβάζει αυτόματα τα στοιχεία email σας. Μόνο όταν στέλνετε email υποστήριξης, το κανάλι υποστήριξης λαμβάνει τη διεύθυνση, το μήνυμα και τυχόν στιγμιότυπα, εγγραφές οθόνης, αριθμούς παραγγελιών ή άλλα συνημμένα που παρέχετε οικειοθελώς. Οι πληροφορίες χρησιμοποιούνται μόνο για τον χειρισμό του αιτήματος και όχι για διαφήμιση ή μάρκετινγκ. Μην στέλνετε κωδικούς λογαριασμού ή πληρωμής ή πλήρεις αριθμούς καρτών.","Ο ιστότοπος δεν τοποθετεί cookie διαφημίσεων ή αναλύσεων και δεν περιλαμβάνει δέσμες ενεργειών ανάλυσης επισκεψιμότητας ή παρακολούθησης."]},{"title":"6. Διατήρηση και διαγραφή","paragraphs":["Απεγκαταστήστε την εφαρμογή για να διαγράψετε δεδομένα στη συσκευή. Στο Android μπορείτε επίσης να χρησιμοποιήσετε την επιλογή συστήματος «Εκκαθάριση δεδομένων».","Τα αρχεία αγορών διαχειρίζονται από την Apple ή την Google. Τα επαναφέρσιμα δικαιώματα επιβεβαιώνονται ξανά σύμφωνα με τους κανόνες του καταστήματος.","Τα email υποστήριξης διατηρούνται όσο χρειάζεται για τον χειρισμό του αιτήματος και την εκπλήρωση απαραίτητων απαιτήσεων τήρησης αρχείων. Μπορείτε να ζητήσετε με email τη διαγραφή αλληλογραφίας υποστήριξης που εξακολουθούμε να διατηρούμε."]},{"title":"7. Ασφάλεια δεδομένων","paragraphs":["Η εφαρμογή χρησιμοποιεί επεξεργασία στη συσκευή, ελάχιστες άδειες και επίσημες διαδικασίες αγοράς καταστημάτων για τη μείωση περιττών μεταφορών δεδομένων. Τα email υποστήριξης χρησιμοποιούνται μόνο για εισερχόμενα αιτήματα, με εύλογες διασφαλίσεις κατάλληλες για τη φύση των πληροφοριών.","Δεν μπορεί να εγγυηθεί η απόλυτη ασφάλεια συσκευής, δικτύου ή ηλεκτρονικής αποθήκευσης. Μην συμπεριλαμβάνετε άσχετες ευαίσθητες πληροφορίες σε email υποστήριξης."]},{"title":"8. Παιδιά και έφηβοι","paragraphs":["Η εφαρμογή δεν απαιτεί λογαριασμό και δεν δημιουργεί προφίλ παιδιών ή άλλων χρηστών μέσω διαφημίσεων ή ανάλυσης συμπεριφοράς. Γονέας ή κηδεμόνας που πιστεύει ότι ένα παιδί έστειλε προσωπικές πληροφορίες σε email υποστήριξης μπορεί να επικοινωνήσει μαζί μας για χειρισμό του ζητήματος."]},{"title":"9. Επιλογές και δικαιώματά σας","paragraphs":["Διαχειρίζεστε τα τοπικά δεδομένα μέσω της συσκευής. Η Apple ή η Google διαχειρίζεται λογαριασμούς καταστήματος και αρχεία αγορών. Η εφαρμογή δεν μπορεί να αλλάξει ή να διαγράψει εκ μέρους σας αρχεία συναλλαγών που διατηρεί ένα κατάστημα.","Αν αλλάξουν οι πρακτικές δεδομένων της εφαρμογής, οι κανόνες πλατφόρμας ή η φιλοξενία του ιστοτόπου, θα ενημερώσουμε την Πολιτική και την ημερομηνία της σελίδας και θα παρέχουμε πρόσθετη ειδοποίηση όπου απαιτείται.","Για ερωτήσεις σχετικά με το απόρρητο, στείλτε email στο email σας. {email}"]}]},"terms":{"title":"Όροι Χρήσης","lead":"Όροι Χρήσης {appName}.","sections":[{"title":"1. Αποδοχή αυτών των Όρων και των κανόνων της πλατφόρμας","paragraphs":["Με τη λήψη, την αγορά ή τη χρήση του {appName}, συμφωνείτε με αυτούς τους Όρους και τους κανόνες που ισχύουν για εσάς στο κατάστημα εφαρμογών όπου πραγματοποιείτε μια αγορά. Εάν δεν συμφωνείτε, μην συνεχίσετε να χρησιμοποιείτε την εφαρμογή ή να πραγματοποιείτε μια αγορά.","Οι Όροι ισχύουν για τη λήψη, αγορά και χρήση της εφαρμογής. Οι εκδόσεις iOS και iPadOS υπόκεινται επίσης στην"],"links":["appleEula"]},{"title":"2. Προϊόντα επί πληρωμή και τιμές","paragraphs":["Η αναγνώριση και η επεξεργασία δεν έχουν όριο χρήσης. Μόνο η εξαγωγή της επεξεργασμένης εικόνας απαιτεί έγκυρη πρόσβαση Premium. Προσφέρονται εβδομαδιαίες και μηνιαίες συνδρομές αυτόματης ανανέωσης και μία εφάπαξ ισόβια αγορά, χωρίς δωρεάν δοκιμή. Οι αγορές App Store και Google Play είναι ξεχωριστές και δεν μεταφέρονται μεταξύ πλατφορμών.","Η πραγματική τιμή, το νόμισμα, οι φόροι, η περίοδος χρέωσης και η δυνατότητα αγοράς είναι οι πληροφορίες που εμφανίζονται και επιβεβαιώνονται στην οθόνη αγοράς του App Store ή Google Play. Η πλατφόρμα χρεώνει και διαχειρίζεται την πληρωμή μέσω του λογαριασμού καταστήματος. Η εφαρμογή δεν προσφέρει δωρεάν δοκιμή συνδρομής ή άλλα προγράμματα."]},{"title":"3. Αυτόματη ανανέωση και ακύρωση","paragraphs":["Οι εβδομαδιαίες και μηνιαίες συνδρομές ανανεώνονται αυτόματα και χρεώνονται για την περίοδο της οθόνης αγοράς έως ότου ακυρωθούν μέσω της πλατφόρμας. Η διαγραφή του {appName} δεν ακυρώνει αυτόματα συνδρομή. Εκτός αν η πλατφόρμα παρέχει επιστροφή ή άλλη μεταχείριση, μπορείτε να χρησιμοποιείτε τη συνδρομή έως το τέλος της πληρωμένης περιόδου μετά την απενεργοποίηση της ανανέωσης."],"links":["appleCancel","googleManage"]},{"title":"4. Αγορές, επαναφορά και επιστροφές","paragraphs":["Οι αγορές και η επαναφορά γίνονται μέσω του επίσημου καταστήματος Apple ή Google. Δικαίωμα χορηγείται μόνο αφού το κατάστημα επιβεβαιώσει έγκυρη συναλλαγή. Ακυρωμένες, αποτυχημένες ή εκκρεμείς συναλλαγές δεν χορηγούν δικαίωμα πριν επιβεβαιωθούν. Η επαναφορά μπορεί να ανακτήσει ισόβια πρόσβαση και ενεργή συνδρομή. Οι αγορές App Store και Google Play είναι ανεξάρτητες και δεν επαναφέρονται ή μεταφέρονται μεταξύ πλατφορμών.","Οι επιστροφές χρημάτων διεκπεραιώνονται από το κατάστημα που ολοκλήρωσε τη συναλλαγή, σύμφωνα με τους κανόνες του, την περιοχή αγοράς και το ισχύον δίκαιο. Το δικαίωμα αφαιρείται μετά την επιβεβαίωση επιστροφής, ανάκλησης, λήξης συνδρομής ή άκυρης συναλλαγής."],"links":["appleRefund","googleRefund"]},{"title":"5. Χρήση εκτός σύνδεσης και διαθεσιμότητα","paragraphs":["Η επιλογή εικόνων, το OCR, ο εντοπισμός ευαίσθητου περιεχομένου, η επεξεργασία και η εξαγωγή γίνονται στη συσκευή. Η εφαρμογή δεν προσφέρει αναγνώριση εικόνων ή συγχρονισμό στο cloud ούτε λογαριασμούς. Κατά την εξαγωγή δημιουργείται νέα εικόνα και αφαιρούνται τα διαγράψιμα ιδιωτικά μεταδεδομένα. Τα προσωρινά αρχεία εργασίας διαγράφονται μετά από επιτυχή αποθήκευση, εγκατάλειψη της επεξεργασίας ή λήξη της συνεδρίας· αν η αποθήκευση αποτύχει, μπορεί να διατηρηθεί η απαραίτητη κατάσταση για νέα προσπάθεια."]},{"title":"6. Αποδεκτή χρήση και πνευματική ιδιοκτησία","paragraphs":["Δεν επιτρέπεται να χρησιμοποιείτε την εφαρμογή για παράνομη δραστηριότητα, να παρακάμπτετε την επαλήθευση αγορών, να προκαλείτε ζημιά, να διανέμετε κακόβουλο κώδικα, να αντιγράφετε ή να διανέμετε χωρίς άδεια ή να παραβιάζετε δικαιώματα περιεχομένου ή πνευματική ιδιοκτησία άλλων.","Μπορείτε να σταματήσετε να χρησιμοποιείτε και να απεγκαταστήσετε την εφαρμογή οποτεδήποτε. Ενδέχεται να εκδίδουμε ενημερώσεις για διόρθωση προβλημάτων, υποστήριξη συστημάτων, βελτίωση σταθερότητας ή συμμόρφωση με απαιτήσεις πλατφόρμας. Προβλήματα συσκευής, συστήματος, δικτύου ή καταστήματος μπορεί να καταστήσουν προσωρινά μη διαθέσιμες ορισμένες λειτουργίες.","Στον βαθμό που επιτρέπεται από το ισχύον δίκαιο, η εφαρμογή παρέχεται όπως είναι διαθέσιμη. Οι Όροι δεν αποκλείουν ευθύνη που δεν μπορεί νόμιμα να αποκλειστεί και δεν περιορίζουν υποχρεωτικά δικαιώματα καταναλωτών.","Αν αλλάξουν λειτουργίες, μέθοδοι πληρωμής, κανόνες πλατφόρμας ή νόμοι, ενδέχεται να ενημερώσουμε τους Όρους και την ημερομηνία. Αν αλλαγή επηρεάζει ουσιωδώς δικαιώματα χρηστών, θα παρέχουμε την απαιτούμενη πρόσθετη ειδοποίηση.","Για ερωτήσεις σχετικά με αυτούς τους Όρους, αγορές ή χρήση της εφαρμογής, στείλτε email {email}"]}]},"support":{"title":"Υποστήριξη","lead":"Δείτε πρώτα τις συχνές ερωτήσεις παρακάτω. Αν το πρόβλημα παραμένει, επικοινωνήστε μέσω του email υποστήριξης.","emailTitle":"Μήνυμα ηλεκτρονικού ταχυδρομείου υποστήριξης {appName}","emailLead":"Δείτε πρώτα τις συχνές ερωτήσεις παρακάτω. Αν το πρόβλημα παραμένει, επικοινωνήστε μέσω του email υποστήριξης.","beforeEmail":{"title":"Τι να συμπεριλάβετε στο email","paragraphs":["Για πρόβλημα αγοράς μπορείτε να δώσετε τον αριθμό παραγγελίας, αλλά όχι κωδικό λογαριασμού ή πληρωμής ούτε πλήρη στοιχεία κάρτας."],"bullets":["πλατφόρμα, μοντέλο συσκευής, έκδοση λειτουργικού και έκδοση εφαρμογής;","ενέργειες πριν από το πρόβλημα, αναμενόμενο και πραγματικό αποτέλεσμα; και","εάν χρειάζεται, ένα στιγμιότυπο οθόνης ή μια εγγραφή οθόνης με κρυφές προσωπικές πληροφορίες."]},"faqs":[{"question":"Μεταφορτώνονται οι εικόνες σε διακομιστή;","answer":"Η επιλογή εικόνων, το OCR, ο εντοπισμός ευαίσθητου περιεχομένου, η επεξεργασία και η εξαγωγή γίνονται στη συσκευή. Η εφαρμογή δεν προσφέρει αναγνώριση εικόνων ή συγχρονισμό στο cloud ούτε λογαριασμούς. Κατά την εξαγωγή δημιουργείται νέα εικόνα και αφαιρούνται τα διαγράψιμα ιδιωτικά μεταδεδομένα. Τα προσωρινά αρχεία εργασίας διαγράφονται μετά από επιτυχή αποθήκευση, εγκατάλειψη της επεξεργασίας ή λήξη της συνεδρίας· αν η αποθήκευση αποτύχει, μπορεί να διατηρηθεί η απαραίτητη κατάσταση για νέα προσπάθεια."},{"question":"Άδειες, διαφημίσεις και παρακολούθηση","answer":"Η πρόσβαση στις φωτογραφίες χρησιμοποιείται μόνο για εμφάνιση και επεξεργασία εικόνων που εγκρίνετε. Η κάμερα χρησιμοποιείται μόνο όταν επιλέγετε λήψη μέσα στην εφαρμογή. Η άδεια αποθήκευσης στη βιβλιοθήκη ζητείται μόνο όταν επιβεβαιώνετε εξαγωγή με έγκυρη πρόσβαση Premium. Η εφαρμογή δεν ζητά τοποθεσία, επαφές, μικρόφωνο, Bluetooth ή ειδοποιήσεις."},{"question":"Προϊόντα επί πληρωμή και τιμές","answer":"Η αναγνώριση και η επεξεργασία δεν έχουν όριο χρήσης. Μόνο η εξαγωγή της επεξεργασμένης εικόνας απαιτεί έγκυρη πρόσβαση Premium. Προσφέρονται εβδομαδιαίες και μηνιαίες συνδρομές αυτόματης ανανέωσης και μία εφάπαξ ισόβια αγορά, χωρίς δωρεάν δοκιμή. Οι αγορές App Store και Google Play είναι ξεχωριστές και δεν μεταφέρονται μεταξύ πλατφορμών."},{"question":"Αποθήκευση και μορφές εικόνας","answer":"Αν η αποθήκευση αποτύχει, ελέγξτε τον ελεύθερο χώρο, την άδεια αποθήκευσης στη βιβλιοθήκη και αν η αρχική εικόνα παραμένει αναγνώσιμη και δοκιμάστε ξανά. Η εφαρμογή επεξεργάζεται μία στατική εικόνα κάθε φορά και υποστηρίζει τις περισσότερες κοινές μορφές· ορισμένες εξαρτώνται από τη συσκευή και την έκδοση συστήματος. Βίντεο, PDF, RAW/DNG και μαζική επεξεργασία δεν υποστηρίζονται προς το παρόν."},{"question":"Πώς αλλάζω γλώσσα;","answer":"Η εφαρμογή υποστηρίζει 40 γλώσσες που αλλάζουν στις ρυθμίσεις. Αν η εμφάνιση είναι λάθος, αναφέρετε με email τη γλώσσα συσκευής και την επιλεγμένη γλώσσα."},{"question":"Επαναφορά, ακύρωση και επιστροφές","answer":"Οι αγορές και η επαναφορά γίνονται μέσω του επίσημου καταστήματος Apple ή Google. Δικαίωμα χορηγείται μόνο αφού το κατάστημα επιβεβαιώσει έγκυρη συναλλαγή. Ακυρωμένες, αποτυχημένες ή εκκρεμείς συναλλαγές δεν χορηγούν δικαίωμα πριν επιβεβαιωθούν. Η επαναφορά μπορεί να ανακτήσει ισόβια πρόσβαση και ενεργή συνδρομή. Οι αγορές App Store και Google Play είναι ανεξάρτητες και δεν επαναφέρονται ή μεταφέρονται μεταξύ πλατφορμών."},{"question":"Απόρρητο και διαγραφή δεδομένων","answer":"Απεγκαταστήστε την εφαρμογή για να διαγράψετε δεδομένα στη συσκευή. Στο Android μπορείτε επίσης να χρησιμοποιήσετε την επιλογή συστήματος «Εκκαθάριση δεδομένων». Τα αρχεία αγορών διαχειρίζονται από την Apple ή την Google. Τα επαναφέρσιμα δικαιώματα επιβεβαιώνονται ξανά σύμφωνα με τους κανόνες του καταστήματος. Τα email υποστήριξης διατηρούνται όσο χρειάζεται για τον χειρισμό του αιτήματος και την εκπλήρωση απαραίτητων απαιτήσεων τήρησης αρχείων. Μπορείτε να ζητήσετε με email τη διαγραφή αλληλογραφίας υποστήριξης που εξακολουθούμε να διατηρούμε."}],"officialHelpTitle":"Γρήγορη βοήθεια"}},"es-ES":{"linkLabels":{"appleEula":"Contrato de licencia estándar de usuario final de Apple (EULA)","appleCancel":"Instrucciones para cancelar la suscripción a Apple","googleManage":"Instrucciones para cancelar en Google Play","appleRefund":"Solicita un reembolso a Apple.","googleRefund":"Información sobre reembolsos de Google Play"},"nav":{"privacy":"política de privacidad","terms":"Condiciones de uso","support":"Soporte","language":"Idioma","chooseLanguage":"Seleccione el idioma de visualización","navigationLabel":"Navegación principal"},"home":{"eyebrow":"{appName} · Privacy first","title":"Tus imágenes no se suben a nuestros servidores.","lead":"La selección de imágenes, el OCR, la detección de contenido sensible, la edición y la exportación se realizan en tu dispositivo. La app no ofrece reconocimiento de imágenes en la nube, sincronización en la nube ni cuentas. Al exportar se crea una imagen nueva y se eliminan los metadatos privados que pueden borrarse. Los archivos de trabajo temporales se eliminan tras guardar correctamente, al abandonar la edición o al finalizar la sesión; si el guardado falla, puede conservarse el estado necesario para volver a intentarlo.","points":["Datos de la app","Productos de pago y precios","Soporte"],"cards":[{"title":"política de privacidad","description":"Tus imágenes no se suben a nuestros servidores.","action":"política de privacidad"},{"title":"Condiciones de uso","description":"El reconocimiento y la edición no tienen límites de uso. Solo la exportación de la imagen procesada requiere acceso Premium válido. La app ofrece suscripciones semanales y mensuales con renovación automática y una compra única de por vida, sin prueba gratuita. Las compras de App Store y Google Play son independientes y no pueden transferirse entre plataformas.","action":"Condiciones de uso"},{"title":"¿Necesitar ayuda?","description":"Consulta primero las preguntas frecuentes. Si el problema continúa, contacta con nosotros mediante el correo de asistencia.","action":"Soporte"}]},"footer":{"privacy":"política de privacidad","terms":"Condiciones de uso","support":"Soporte"},"privacy":{"title":"Política de privacidad","lead":"Esta Política explica cómo {appName} trata los datos del dispositivo, la información de compra de la tienda y los correos de asistencia.","sections":[{"title":"1. Alcance y contacto","paragraphs":["Esta Política se aplica a la app {appName} para iOS, iPadOS y Android, y a este sitio web de privacidad, condiciones y asistencia.","Para preguntas sobre privacidad, envíe un correo electrónico {email}"]},{"title":"2. Datos de la app","callout":{"title":"Tus imágenes no se suben a nuestros servidores.","body":"La selección de imágenes, el OCR, la detección de contenido sensible, la edición y la exportación se realizan en tu dispositivo. La app no ofrece reconocimiento de imágenes en la nube, sincronización en la nube ni cuentas. Al exportar se crea una imagen nueva y se eliminan los metadatos privados que pueden borrarse. Los archivos de trabajo temporales se eliminan tras guardar correctamente, al abandonar la edición o al finalizar la sesión; si el guardado falla, puede conservarse el estado necesario para volver a intentarlo."},"paragraphs":[]},{"title":"3. Permisos, publicidad y seguimiento","paragraphs":["El acceso a fotos se usa solo para mostrar y procesar las imágenes que autorices. La cámara se utiliza únicamente cuando eliges tomar una foto en la app. El permiso para guardar en la fototeca solo se solicita cuando confirmas la exportación con acceso Premium válido. La app no solicita ubicación, contactos, micrófono, Bluetooth ni notificaciones.","No utiliza identificadores publicitarios ni integra SDK de terceros para publicidad, análisis, atribución o informes de fallos.","La app no integra herramientas de terceros para informar de fallos. Según los ajustes del dispositivo y de la tienda, Apple o Google puede tratar información de diagnóstico del sistema conforme a sus normas de privacidad y facilitar información técnica para investigar fallos o problemas de rendimiento."]},{"title":"4. Servicios de la tienda y acceso a la red","paragraphs":["La app usa Apple StoreKit o Google Play Billing para cargar productos, mostrar los precios localizados devueltos por la tienda, completar y restaurar compras, gestionar suscripciones y confirmar derechos. El acceso a la red se utiliza únicamente para estas funciones oficiales de Apple o Google.","Apple o Google se encarga de las cuentas de la tienda, pagos, facturación, transacciones, reembolsos y servicios de suscripción. La app solo trata la información de la tienda necesaria para confirmar productos y derechos, y no recibe ni guarda credenciales de pago completas."]},{"title":"5. Correos de asistencia y sitio web","paragraphs":["La app no lee automáticamente la información de tu correo. El canal de asistencia solo recibe tu dirección, mensaje y las capturas, grabaciones de pantalla, números de pedido u otros archivos que facilites voluntariamente cuando envías un correo de asistencia. La información se usa únicamente para atender tu solicitud y no para publicidad o marketing. No envíes contraseñas de cuenta o pago ni números de tarjeta completos.","Este sitio web no instala cookies publicitarias o analíticas ni incluye scripts de análisis de tráfico o seguimiento."]},{"title":"6. Conservación y eliminación","paragraphs":["Desinstala la app para borrar los datos del dispositivo. En Android también puedes usar la opción del sistema «Borrar datos».","Apple o Google gestiona los registros de compra. Los derechos restaurables se vuelven a confirmar según las normas de la tienda.","Los correos de asistencia se conservan durante el tiempo necesario para atender la solicitud y cumplir los requisitos imprescindibles de registro. Puedes escribirnos para pedir que eliminemos la correspondencia de asistencia que aún conservemos."]},{"title":"7. Seguridad de los datos","paragraphs":["La app usa procesamiento en el dispositivo, permisos mínimos y procesos de compra oficiales para reducir transferencias innecesarias. Los correos de asistencia solo se usan para atender solicitudes y se protegen con medidas razonables adecuadas a la naturaleza de la información.","No puede garantizarse la seguridad absoluta de ningún dispositivo, red o método de almacenamiento electrónico. No incluyas información sensible ajena al problema en un correo de asistencia."]},{"title":"8. Niños y adolescentes","paragraphs":["La app no requiere una cuenta ni crea perfiles de niños u otros usuarios mediante publicidad o análisis de comportamiento. Si un padre, madre o tutor cree que un menor facilitó información personal por correo de asistencia, puede contactarnos para que atendamos el caso."]},{"title":"9. Tus opciones y derechos","paragraphs":["Tú gestionas los datos locales desde el dispositivo. Apple o Google gestiona las cuentas de la tienda y los registros de compra. La app no puede modificar ni eliminar en tu nombre los registros de transacciones conservados por una tienda.","Si cambian las prácticas de datos de la app, las normas de las plataformas o el alojamiento del sitio, actualizaremos esta Política y la fecha de la página, y avisaremos adicionalmente cuando las normas aplicables lo exijan.","Para preguntas sobre privacidad, envíe un correo electrónico {email}"]}]},"terms":{"title":"Condiciones de uso","lead":"Términos de uso de {appName}.","sections":[{"title":"1. Aceptación de estos Términos y reglas de la plataforma","paragraphs":["Al descargar, comprar o usar {appName}, aceptas estos Términos y las normas que te rigen en la tienda de aplicaciones donde realizas la compra. Si no estás de acuerdo, no sigas usando la aplicación ni realices ninguna compra.","Estas Condiciones se aplican a la descarga, compra y uso de la app. Las versiones para iOS y iPadOS también están sujetas al"],"links":["appleEula"]},{"title":"2. Productos de pago y precios","paragraphs":["El reconocimiento y la edición no tienen límites de uso. Solo la exportación de la imagen procesada requiere acceso Premium válido. La app ofrece suscripciones semanales y mensuales con renovación automática y una compra única de por vida, sin prueba gratuita. Las compras de App Store y Google Play son independientes y no pueden transferirse entre plataformas.","El precio real, la moneda, los impuestos, el periodo de facturación y la posibilidad de compra son los datos mostrados y confirmados en la pantalla de compra del sistema de App Store o Google Play. La plataforma cobra y gestiona el pago mediante tu cuenta de la tienda. La app no ofrece una prueba gratuita de suscripción ni otros planes de pago."]},{"title":"3. Renovación automática y cancelación","paragraphs":["Las suscripciones semanales y mensuales se renuevan automáticamente y se cobran por el periodo indicado en la pantalla de compra hasta que las canceles en la plataforma. Eliminar {appName} no cancela automáticamente una suscripción. Salvo que la plataforma conceda un reembolso u otro tratamiento, podrás seguir usando la suscripción hasta el final del periodo pagado tras desactivar la renovación automática."],"links":["appleCancel","googleManage"]},{"title":"4. Compras, restauración y reembolsos","paragraphs":["Las compras y su restauración se realizan mediante la tienda oficial de Apple o Google. Solo se concede un derecho cuando la tienda confirma una transacción válida. Las transacciones canceladas, fallidas o pendientes no conceden derechos antes de confirmarse. Restaurar compras puede recuperar el acceso de por vida y una suscripción activa. Las compras de App Store y Google Play son independientes y no pueden restaurarse ni transferirse entre plataformas.","Los reembolsos los gestiona la tienda que completó la transacción según sus normas, la región de compra y la legislación aplicable. El derecho correspondiente se elimina cuando la tienda confirma un reembolso, una revocación, el vencimiento de la suscripción o una transacción no válida."],"links":["appleRefund","googleRefund"]},{"title":"5. Uso sin conexión y disponibilidad","paragraphs":["La selección de imágenes, el OCR, la detección de contenido sensible, la edición y la exportación se realizan en tu dispositivo. La app no ofrece reconocimiento de imágenes en la nube, sincronización en la nube ni cuentas. Al exportar se crea una imagen nueva y se eliminan los metadatos privados que pueden borrarse. Los archivos de trabajo temporales se eliminan tras guardar correctamente, al abandonar la edición o al finalizar la sesión; si el guardado falla, puede conservarse el estado necesario para volver a intentarlo."]},{"title":"6. Uso aceptable y propiedad intelectual","paragraphs":["No debes usar la app para actividades ilegales; eludir la verificación de compras; dañar la app; distribuir código malicioso; copiar o distribuir la app sin permiso; ni infringir derechos sobre su contenido o la propiedad intelectual de terceros.","Puedes dejar de usar y desinstalar la app en cualquier momento. Podemos publicar actualizaciones para corregir problemas, admitir sistemas operativos, mejorar la estabilidad o cumplir requisitos de las plataformas. Los problemas del dispositivo, sistema, red o servicios de la tienda pueden hacer que algunas funciones no estén disponibles temporalmente.","En la medida permitida por la legislación aplicable, la app se proporciona según disponibilidad. Estas Condiciones no excluyen responsabilidades que legalmente no puedan excluirse ni limitan tus derechos obligatorios como consumidor.","Si cambian las funciones, los métodos de pago, las normas de las plataformas o la legislación aplicable, podemos actualizar estas Condiciones y la fecha de la página. Si un cambio afecta sustancialmente a los derechos de los usuarios, daremos el aviso adicional exigido.","Para preguntas sobre estos Términos, compras o uso de la aplicación, envíe un correo electrónico {email}"]}]},"support":{"title":"Soporte","lead":"Consulta primero las preguntas frecuentes. Si el problema continúa, contacta con nosotros mediante el correo de asistencia.","emailTitle":"Correo electrónico de soporte de {appName}","emailLead":"Consulta primero las preguntas frecuentes. Si el problema continúa, contacta con nosotros mediante el correo de asistencia.","beforeEmail":{"title":"Qué incluir en el correo","paragraphs":["Para problemas de compra puedes incluir el número de pedido de la tienda, pero no envíes la contraseña de tu cuenta o de pago ni la información completa de tu tarjeta."],"bullets":["tu plataforma, modelo del dispositivo, versión del sistema y versión de la app;","qué hiciste antes del problema, qué esperabas y qué ocurrió realmente; y","Si es necesario, se puede proporcionar una captura de pantalla o una grabación de pantalla con la información privada oculta."]},"faqs":[{"question":"¿Se suben las imágenes a algún servidor?","answer":"La selección de imágenes, el OCR, la detección de contenido sensible, la edición y la exportación se realizan en tu dispositivo. La app no ofrece reconocimiento de imágenes en la nube, sincronización en la nube ni cuentas. Al exportar se crea una imagen nueva y se eliminan los metadatos privados que pueden borrarse. Los archivos de trabajo temporales se eliminan tras guardar correctamente, al abandonar la edición o al finalizar la sesión; si el guardado falla, puede conservarse el estado necesario para volver a intentarlo."},{"question":"Permisos, publicidad y seguimiento","answer":"El acceso a fotos se usa solo para mostrar y procesar las imágenes que autorices. La cámara se utiliza únicamente cuando eliges tomar una foto en la app. El permiso para guardar en la fototeca solo se solicita cuando confirmas la exportación con acceso Premium válido. La app no solicita ubicación, contactos, micrófono, Bluetooth ni notificaciones."},{"question":"Productos de pago y precios","answer":"El reconocimiento y la edición no tienen límites de uso. Solo la exportación de la imagen procesada requiere acceso Premium válido. La app ofrece suscripciones semanales y mensuales con renovación automática y una compra única de por vida, sin prueba gratuita. Las compras de App Store y Google Play son independientes y no pueden transferirse entre plataformas."},{"question":"Guardado y formatos de imagen","answer":"Si el guardado falla, comprueba el espacio disponible, el permiso para guardar en la fototeca y que la imagen original siga siendo legible; después, inténtalo de nuevo. La app procesa una imagen fija cada vez y admite la mayoría de los formatos habituales; algunos dependen del dispositivo y la versión del sistema. Actualmente no admite vídeo, PDF, RAW/DNG ni procesamiento por lotes."},{"question":"¿Cómo cambio el idioma?","answer":"La app admite 40 idiomas y se puede cambiar desde sus ajustes. Si no se muestra correctamente, indica por correo el idioma del dispositivo y el elegido en la app."},{"question":"Restauración, cancelación y reembolsos","answer":"Las compras y su restauración se realizan mediante la tienda oficial de Apple o Google. Solo se concede un derecho cuando la tienda confirma una transacción válida. Las transacciones canceladas, fallidas o pendientes no conceden derechos antes de confirmarse. Restaurar compras puede recuperar el acceso de por vida y una suscripción activa. Las compras de App Store y Google Play son independientes y no pueden restaurarse ni transferirse entre plataformas."},{"question":"Privacidad y eliminación de datos","answer":"Desinstala la app para borrar los datos del dispositivo. En Android también puedes usar la opción del sistema «Borrar datos». Apple o Google gestiona los registros de compra. Los derechos restaurables se vuelven a confirmar según las normas de la tienda. Los correos de asistencia se conservan durante el tiempo necesario para atender la solicitud y cumplir los requisitos imprescindibles de registro. Puedes escribirnos para pedir que eliminemos la correspondencia de asistencia que aún conservemos."}],"officialHelpTitle":"Ayuda rápida"}},"fi":{"linkLabels":{"appleEula":"Applen vakioitua loppukäyttäjän lisenssisopimusta (EULA)","appleCancel":"Apple-tilauksen peruutusohjeet","googleManage":"Google Playn peruutusohjeet","appleRefund":"Pyydä hyvitystä Applelta","googleRefund":"Google Playn hyvitystiedot"},"nav":{"privacy":"Tietosuojakäytäntö","terms":"Käyttöehdot","support":"Tuki","language":"Kieli","chooseLanguage":"Valitse näyttökieli","navigationLabel":"Ensisijainen navigointi"},"home":{"eyebrow":"{appName} · Privacy first","title":"Kuviasi ei lähetetä palvelimillemme.","lead":"Kuvien valinta, OCR, arkaluonteisen sisällön tunnistus, muokkaus ja vienti tehdään laitteella. Sovellus ei tarjoa pilvipohjaista kuvantunnistusta, pilvisynkronointia tai käyttäjätilejä. Viennissä luodaan uusi kuva ja poistettavissa olevat yksityiset metatiedot poistetaan. Tilapäiset työtiedostot poistetaan onnistuneen tallennuksen, muokkauksen hylkäämisen tai istunnon päättymisen jälkeen; tallennuksen epäonnistuessa uudelleenyritykseen tarvittava tila voidaan säilyttää.","points":["Sovelluksen tiedot","Maksulliset tuotteet ja hinnat","Tuki"],"cards":[{"title":"Tietosuojakäytäntö","description":"Kuviasi ei lähetetä palvelimillemme.","action":"Tietosuojakäytäntö"},{"title":"Käyttöehdot","description":"Tunnistuksella ja muokkauksella ei ole käyttörajoja. Vain käsitellyn kuvan vienti vaatii voimassa olevan Premium-käyttöoikeuden. Tarjolla on automaattisesti uusiutuvat viikko- ja kuukausitilaukset sekä kertaluonteinen elinikäinen osto ilman maksutonta kokeilua. App Storen ja Google Playn ostot ovat erillisiä eikä niitä voi siirtää alustojen välillä.","action":"Käyttöehdot"},{"title":"Tarvitsetko apua?","description":"Aloita alla olevista usein kysytyistä kysymyksistä. Jos ongelma jatkuu, ota meihin yhteyttä tukisähköpostiosoitteella.","action":"Tuki"}]},"footer":{"privacy":"Tietosuojakäytäntö","terms":"Käyttöehdot","support":"Tuki"},"privacy":{"title":"Tietosuojakäytäntö","lead":"Tässä tietosuojakäytännössä kerrotaan, miten {appName} käsittelee laitteella olevia tietoja, sovelluskaupan ostotietoja ja tukisähköposteja.","sections":[{"title":"1. Soveltamisala ja yhteystiedot","paragraphs":["Tämä tietosuojakäytäntö koskee {appName}-sovelluksen iOS-, iPadOS- ja Android-versioita sekä tätä tietosuoja-, käyttöehto- ja tukisivustoa.","Tietosuojakysymyksissä lähetä sähköpostia {email}"]},{"title":"2. Sovelluksen tiedot","callout":{"title":"Kuviasi ei lähetetä palvelimillemme.","body":"Kuvien valinta, OCR, arkaluonteisen sisällön tunnistus, muokkaus ja vienti tehdään laitteella. Sovellus ei tarjoa pilvipohjaista kuvantunnistusta, pilvisynkronointia tai käyttäjätilejä. Viennissä luodaan uusi kuva ja poistettavissa olevat yksityiset metatiedot poistetaan. Tilapäiset työtiedostot poistetaan onnistuneen tallennuksen, muokkauksen hylkäämisen tai istunnon päättymisen jälkeen; tallennuksen epäonnistuessa uudelleenyritykseen tarvittava tila voidaan säilyttää."},"paragraphs":[]},{"title":"3. Käyttöoikeudet, mainonta ja seuranta","paragraphs":["Kuvien käyttöoikeutta käytetään vain hyväksymiesi kuvien näyttämiseen ja käsittelyyn. Kameraa käytetään vain, kun päätät ottaa kuvan sovelluksessa. Oikeutta tallentaa kuvakirjastoon pyydetään vain, kun vahvistat viennin voimassa olevalla Premium-käyttöoikeudella. Sovellus ei pyydä sijainnin, yhteystietojen, mikrofonin, Bluetoothin tai ilmoitusten käyttöoikeutta.","Se ei käytä mainostunnistetta eikä sisällä kolmannen osapuolen mainonta-, analytiikka-, attribuutio- tai kaatumisraportointiohjelmistokehityspaketteja.","Sovellus ei sisällä kolmannen osapuolen kaatumisraportointityökalua. Laite- ja kauppa-asetustesi mukaan Apple tai Google voi käsitellä järjestelmän diagnostiikkatietoja omien tietosuojasääntöjensä mukaisesti ja toimittaa teknisiä tietoja kaatumisten tai suorituskykyongelmien tutkimiseen."]},{"title":"4. Sovelluskaupan palvelut ja verkkoyhteys","paragraphs":["Sovellus käyttää Apple StoreKitiä tai Google Play Billingiä tuotteiden lataamiseen, kaupan palauttamien paikallisten hintojen näyttämiseen, ostosten suorittamiseen ja palauttamiseen, tilausten hallintaan sekä käyttöoikeuksien vahvistamiseen. Verkkoyhteyttä käytetään vain näihin Applen tai Googlen virallisiin kauppatoimintoihin.","Apple tai Google vastaa kauppatileistä, maksuista, laskutuksesta, tapahtumista, hyvityksistä ja tilauspalveluista. Sovellus käsittelee vain tuotteiden ja käyttöoikeuksien vahvistamiseen tarvittavia kaupan tietoja eikä vastaanota tai tallenna täydellisiä maksutietoja."]},{"title":"5. Tukisähköpostit ja verkkosivusto","paragraphs":["Sovellus ei lue sähköpostitietojasi automaattisesti. Vain kun päätät lähettää tukisähköpostin, tukikanava vastaanottaa sähköpostiosoitteesi, viestisi sekä vapaaehtoisesti toimittamasi kuvakaappauksen, näyttötallenteen, tilausnumeron tai muun liitteen. Tietoja käytetään vain pyyntösi käsittelyyn, ei mainontaan tai markkinointiin. Älä lähetä tilin tai maksamisen salasanoja tai täydellisiä korttinumeroita.","Tämä verkkosivusto ei aseta mainonta- tai analytiikkaevästeitä eikä sisällä liikenneanalytiikkaa tai seurantakomentosarjoja."]},{"title":"6. Säilyttäminen ja poistaminen","paragraphs":["Poista laitteella olevat tiedot poistamalla sovellus. Androidissa voit käyttää myös järjestelmän Tyhjennä tiedot -toimintoa.","Apple tai Google hallinnoi kaupan ostotietoja. Palautettavat käyttöoikeudet vahvistetaan uudelleen kaupan sääntöjen mukaisesti.","Tukisähköpostit säilytetään niin kauan kuin pyynnön käsittely ja välttämättömät kirjanpitovaatimukset edellyttävät. Voit pyytää meitä sähköpostitse poistamaan edelleen hallussamme olevan tukikirjeenvaihdon."]},{"title":"7. Tietoturva","paragraphs":["Sovellus vähentää tarpeettomia tiedonsiirtoja käsittelemällä tietoja laitteella, käyttämällä mahdollisimman vähän käyttöoikeuksia ja hyödyntämällä sovelluskaupan virallisia ostotapoja. Tukisähköposteja käytetään vain saapuvien pyyntöjen käsittelyyn, ja ne suojataan tietojen luonteeseen nähden kohtuullisin keinoin.","Minkään laitteen, verkon tai sähköisen tallennustavan täydellistä turvallisuutta ei voida taata. Älä sisällytä tukisähköpostiin asiaan liittymättömiä arkaluonteisia tietoja."]},{"title":"8. Lapset ja nuoret","paragraphs":["Sovellus ei vaadi tiliä eikä muodosta lapsista tai muista käyttäjistä profiileja mainonnan tai käyttäytymisanalytiikan avulla. Vanhempi tai huoltaja, joka uskoo lapsen antaneen henkilötietoja tukisähköpostilla, voi ottaa meihin yhteyttä asian käsittelemiseksi."]},{"title":"9. Valintasi ja oikeutesi","paragraphs":["Hallitset laitteella olevia tietoja laitteesi kautta. Apple tai Google hallinnoi kauppatilejä ja ostotietoja. Sovellus ei voi puolestasi muuttaa tai poistaa sovelluskaupan säilyttämiä tapahtumatietoja.","Jos sovelluksen tietojenkäsittelytavat, alustasäännöt tai verkkosivuston ylläpitojärjestelyt muuttuvat, päivitämme tämän käytännön ja sivulla näkyvän päivämäärän sekä annamme lisäilmoituksen sovellettavien sääntöjen sitä edellyttäessä.","Tietosuojakysymyksissä lähetä sähköpostia {email}"]}]},"terms":{"title":"Käyttöehdot","lead":"{appName} Käyttöehdot.","sections":[{"title":"1. Näiden ehtojen ja alustan sääntöjen hyväksyminen","paragraphs":["Lataamalla, ostamalla tai käyttämällä {appName} -sovellusta hyväksyt nämä ehdot ja sinua koskevat säännöt sovelluskaupassa, jossa teet ostoksen. Jos et hyväksy näitä ehtoja, älä jatka sovelluksen käyttöä tai tee ostosta.","Nämä ehdot koskevat sovelluksen lataamista, ostamista ja käyttämistä. iOS- ja iPadOS-versioihin sovelletaan lisäksi"],"links":["appleEula"]},{"title":"2. Maksulliset tuotteet ja hinnat","paragraphs":["Tunnistuksella ja muokkauksella ei ole käyttörajoja. Vain käsitellyn kuvan vienti vaatii voimassa olevan Premium-käyttöoikeuden. Tarjolla on automaattisesti uusiutuvat viikko- ja kuukausitilaukset sekä kertaluonteinen elinikäinen osto ilman maksutonta kokeilua. App Storen ja Google Playn ostot ovat erillisiä eikä niitä voi siirtää alustojen välillä.","Todellinen hinta, valuutta, verot, laskutusjakso ja ostokelpoisuus määräytyvät App Storen tai Google Playn järjestelmän ostonäkymässä näytettävien ja vahvistettavien tietojen mukaan. Ostoalusta veloittaa ja hallinnoi maksua kauppatilisi kautta. Sovellus ei tarjoa tilauksen maksutonta kokeilua tai muita maksullisia vaihtoehtoja."]},{"title":"3. Automaattinen uusiutuminen ja peruuttaminen","paragraphs":["Viikko- ja kuukausitilaukset uusiutuvat automaattisesti, ja niistä veloitetaan järjestelmän ostonäkymässä näkyvän laskutusjakson mukaisesti, kunnes peruutat tilauksen ostoalustalla. {appName}-sovelluksen poistaminen ei peruuta tilausta automaattisesti. Ellei ostoalusta myönnä hyvitystä tai muuta käsittelyä, voit käyttää tilausta nykyisen maksetun jakson loppuun asti automaattisen uusiutumisen poistamisen jälkeen."],"links":["appleCancel","googleManage"]},{"title":"4. Ostokset, palauttaminen ja hyvitykset","paragraphs":["Ostokset ja niiden palauttaminen suoritetaan Applen tai Googlen virallisen kaupan kautta. Käyttöoikeus myönnetään vasta, kun kauppa vahvistaa kelvollisen tapahtuman. Peruutetut, epäonnistuneet tai odottavat tapahtumat eivät anna käyttöoikeutta ennen onnistunutta vahvistusta. Ostosten palauttaminen voi palauttaa elinikäisen käyttöoikeuden ja sillä hetkellä aktiivisen tilauksen. App Storen ja Google Playn ostokset ovat erillisiä, eikä niitä voi palauttaa tai siirtää alustojen välillä.","Hyvitykset käsittelee tapahtuman suorittanut sovelluskauppa omien sääntöjensä, ostoalueen ja sovellettavan lain mukaisesti. Vastaava käyttöoikeus poistetaan, kun kauppa vahvistaa hyvityksen, peruutuksen, tilauksen päättymisen tai kelpaamattoman tapahtuman."],"links":["appleRefund","googleRefund"]},{"title":"5. Offlinekäyttö ja saatavuus","paragraphs":["Kuvien valinta, OCR, arkaluonteisen sisällön tunnistus, muokkaus ja vienti tehdään laitteella. Sovellus ei tarjoa pilvipohjaista kuvantunnistusta, pilvisynkronointia tai käyttäjätilejä. Viennissä luodaan uusi kuva ja poistettavissa olevat yksityiset metatiedot poistetaan. Tilapäiset työtiedostot poistetaan onnistuneen tallennuksen, muokkauksen hylkäämisen tai istunnon päättymisen jälkeen; tallennuksen epäonnistuessa uudelleenyritykseen tarvittava tila voidaan säilyttää."]},{"title":"6. Hyväksyttävä käyttö ja immateriaalioikeudet","paragraphs":["Et saa käyttää sovellusta lainvastaiseen toimintaan, kiertää ostoksen vahvistusta, vahingoittaa sovellusta, levittää haitallista koodia, kopioida tai jakaa sovellusta ilman lupaa tai loukata sovelluksen sisältöön tai toisen henkilön immateriaalioikeuksiin liittyviä oikeuksia.","Voit lopettaa sovelluksen käytön ja poistaa sen milloin tahansa. Saatamme julkaista päivityksiä ongelmien korjaamiseksi, käyttöjärjestelmien tukemiseksi, vakauden parantamiseksi tai alustavaatimusten täyttämiseksi. Laite-, järjestelmä-, verkko- tai kauppapalveluongelmat voivat tehdä joistakin ominaisuuksista tilapäisesti käytöstä poissa olevia.","Sovellus tarjotaan saatavuuden mukaan sovellettavan lain sallimassa laajuudessa. Nämä ehdot eivät poista vastuuta, jota ei voi lain mukaan poistaa, eivätkä rajoita sinulle kuuluvia pakottavia kuluttajaoikeuksia.","Jos tuotteen ominaisuudet, maksutavat, alustan säännöt tai sovellettava laki muuttuvat, voimme päivittää näitä ehtoja ja sivulla näkyvää päivämäärää. Jos muutos vaikuttaa olennaisesti käyttäjien oikeuksiin, ilmoitamme siitä lisäksi vaatimusten mukaisesti.","Jos sinulla on kysyttävää näistä ehdoista, ostoista tai sovelluksen käytöstä, lähetä sähköpostia {email}"]}]},"support":{"title":"Tuki","lead":"Aloita alla olevista usein kysytyistä kysymyksistä. Jos ongelma jatkuu, ota meihin yhteyttä tukisähköpostiosoitteella.","emailTitle":"{appName} -tukisähköposti","emailLead":"Aloita alla olevista usein kysytyistä kysymyksistä. Jos ongelma jatkuu, ota meihin yhteyttä tukisähköpostiosoitteella.","beforeEmail":{"title":"Mitä sähköpostiin tulee sisällyttää","paragraphs":["Jos asia koskee ostosta, voit ilmoittaa sovelluskaupan tilausnumeron, mutta älä lähetä tilisi tai maksamisen salasanaa tai täydellisiä korttitietoja."],"bullets":["alustasi, laitemallisi, käyttöjärjestelmäversiosi ja sovellusversiosi;","mitä teit ennen ongelmaa, mitä odotit ja mitä todella tapahtui; sekä","tarvittaessa kuvakaappaus tai näytön tallennus, josta yksityisiä tietoja on piilotettu."]},"faqs":[{"question":"Ladataanko kuvat palvelimelle?","answer":"Kuvien valinta, OCR, arkaluonteisen sisällön tunnistus, muokkaus ja vienti tehdään laitteella. Sovellus ei tarjoa pilvipohjaista kuvantunnistusta, pilvisynkronointia tai käyttäjätilejä. Viennissä luodaan uusi kuva ja poistettavissa olevat yksityiset metatiedot poistetaan. Tilapäiset työtiedostot poistetaan onnistuneen tallennuksen, muokkauksen hylkäämisen tai istunnon päättymisen jälkeen; tallennuksen epäonnistuessa uudelleenyritykseen tarvittava tila voidaan säilyttää."},{"question":"Käyttöoikeudet, mainonta ja seuranta","answer":"Kuvien käyttöoikeutta käytetään vain hyväksymiesi kuvien näyttämiseen ja käsittelyyn. Kameraa käytetään vain, kun päätät ottaa kuvan sovelluksessa. Oikeutta tallentaa kuvakirjastoon pyydetään vain, kun vahvistat viennin voimassa olevalla Premium-käyttöoikeudella. Sovellus ei pyydä sijainnin, yhteystietojen, mikrofonin, Bluetoothin tai ilmoitusten käyttöoikeutta."},{"question":"Maksulliset tuotteet ja hinnat","answer":"Tunnistuksella ja muokkauksella ei ole käyttörajoja. Vain käsitellyn kuvan vienti vaatii voimassa olevan Premium-käyttöoikeuden. Tarjolla on automaattisesti uusiutuvat viikko- ja kuukausitilaukset sekä kertaluonteinen elinikäinen osto ilman maksutonta kokeilua. App Storen ja Google Playn ostot ovat erillisiä eikä niitä voi siirtää alustojen välillä."},{"question":"Tallentaminen ja kuvamuodot","answer":"Jos tallennus epäonnistuu, tarkista vapaa tila, kuvakirjaston tallennusoikeus ja alkuperäisen kuvan luettavuus ja yritä uudelleen. Sovellus käsittelee yhden still-kuvan kerrallaan ja tukee useimpia yleisiä muotoja; osa riippuu laitteesta ja järjestelmäversiosta. Videoita, PDF-, RAW/DNG-tiedostoja ja eräkäsittelyä ei tällä hetkellä tueta."},{"question":"Miten vaihdan kielen?","answer":"Sovellus tukee 40 kieltä, ja kielen voi vaihtaa sovelluksen asetuksista. Jos kieli näkyy väärin, ilmoita sähköpostitse laitteen kieli ja sovelluksessa valittu kieli."},{"question":"Palauttaminen, peruuttaminen ja hyvitykset","answer":"Ostokset ja niiden palauttaminen suoritetaan Applen tai Googlen virallisen kaupan kautta. Käyttöoikeus myönnetään vasta, kun kauppa vahvistaa kelvollisen tapahtuman. Peruutetut, epäonnistuneet tai odottavat tapahtumat eivät anna käyttöoikeutta ennen onnistunutta vahvistusta. Ostosten palauttaminen voi palauttaa elinikäisen käyttöoikeuden ja sillä hetkellä aktiivisen tilauksen. App Storen ja Google Playn ostokset ovat erillisiä, eikä niitä voi palauttaa tai siirtää alustojen välillä."},{"question":"Tietosuoja ja tietojen poistaminen","answer":"Poista laitteella olevat tiedot poistamalla sovellus. Androidissa voit käyttää myös järjestelmän Tyhjennä tiedot -toimintoa. Apple tai Google hallinnoi kaupan ostotietoja. Palautettavat käyttöoikeudet vahvistetaan uudelleen kaupan sääntöjen mukaisesti. Tukisähköpostit säilytetään niin kauan kuin pyynnön käsittely ja välttämättömät kirjanpitovaatimukset edellyttävät. Voit pyytää meitä sähköpostitse poistamaan edelleen hallussamme olevan tukikirjeenvaihdon."}],"officialHelpTitle":"Pika-apu"}},"fr":{"linkLabels":{"appleEula":"Contrat de licence utilisateur final standard d’Apple (EULA)","appleCancel":"Instructions d'annulation d'abonnement Apple","googleManage":"Instructions d’annulation Google Play","appleRefund":"Demander un remboursement à Apple","googleRefund":"Informations sur les remboursements Google Play"},"nav":{"privacy":"politique de confidentialité","terms":"Conditions d'utilisation","support":"Assistance","language":"Langue","chooseLanguage":"Sélectionnez la langue d'affichage","navigationLabel":"Navigation principale"},"home":{"eyebrow":"{appName} · Privacy first","title":"Vos images ne sont pas téléversées vers nos serveurs.","lead":"La sélection des images, l’OCR, la détection des contenus sensibles, la retouche et l’exportation sont effectués sur votre appareil. L’app ne propose ni reconnaissance d’images dans le cloud, ni synchronisation cloud, ni compte. Une nouvelle image est créée à l’exportation et les métadonnées privées amovibles sont supprimées. Les fichiers de travail temporaires sont effacés après une sauvegarde réussie, l’abandon de la retouche ou la fin de la session ; l’état nécessaire peut être conservé en cas d’échec afin de réessayer.","points":["Données de l’app","Produits payants et prix","Assistance"],"cards":[{"title":"politique de confidentialité","description":"Vos images ne sont pas téléversées vers nos serveurs.","action":"politique de confidentialité"},{"title":"Conditions d'utilisation","description":"La reconnaissance et la retouche n’ont aucune limite d’utilisation. Seule l’exportation de l’image traitée nécessite un accès Premium valide. L’app propose des abonnements hebdomadaire et mensuel à renouvellement automatique ainsi qu’un achat unique à vie, sans essai gratuit. Les achats App Store et Google Play sont distincts et ne peuvent pas être transférés entre les plateformes.","action":"Conditions d'utilisation"},{"title":"Besoin d'aide ?","description":"Commencez par consulter les questions fréquentes ci-dessous. Si le problème persiste, contactez-nous à l’adresse e-mail d’assistance.","action":"Assistance"}]},"footer":{"privacy":"politique de confidentialité","terms":"Conditions d'utilisation","support":"Assistance"},"privacy":{"title":"Politique de confidentialité","lead":"La présente Politique explique comment {appName} traite les données stockées sur l’appareil, les informations d’achat de la boutique d’applications et les e-mails d’assistance.","sections":[{"title":"1. Portée et contact","paragraphs":["La présente Politique s’applique à l’app {appName} pour iOS, iPadOS et Android, ainsi qu’à ce site consacré à la confidentialité, aux conditions et à l’assistance.","Pour toute question relative à la confidentialité, veuillez envoyer un courriel. {email}"]},{"title":"2. Données de l’app","callout":{"title":"Vos images ne sont pas téléversées vers nos serveurs.","body":"La sélection des images, l’OCR, la détection des contenus sensibles, la retouche et l’exportation sont effectués sur votre appareil. L’app ne propose ni reconnaissance d’images dans le cloud, ni synchronisation cloud, ni compte. Une nouvelle image est créée à l’exportation et les métadonnées privées amovibles sont supprimées. Les fichiers de travail temporaires sont effacés après une sauvegarde réussie, l’abandon de la retouche ou la fin de la session ; l’état nécessaire peut être conservé en cas d’échec afin de réessayer."},"paragraphs":[]},{"title":"3. Autorisations, publicité et suivi","paragraphs":["L’accès aux photos sert uniquement à afficher et traiter les images que vous autorisez. L’appareil photo n’est utilisé que lorsque vous choisissez de prendre une photo. L’autorisation d’enregistrer dans la photothèque n’est demandée que lorsque vous confirmez l’exportation avec un accès Premium valide. L’app ne demande pas l’accès à la position, aux contacts, au microphone, au Bluetooth ou aux notifications.","Elle n’utilise aucun identifiant publicitaire et n’intègre aucun SDK tiers de publicité, d’analyse, d’attribution ou de signalement des plantages.","L’app n’intègre aucun outil tiers de signalement des plantages. Selon les réglages de votre appareil et de la boutique, Apple ou Google peut traiter des informations de diagnostic système conformément à ses propres règles de confidentialité et fournir des informations techniques servant à examiner les plantages ou les problèmes de performances."]},{"title":"4. Services de la boutique d’applications et accès au réseau","paragraphs":["L’app utilise Apple StoreKit ou Google Play Billing pour charger les produits, afficher les prix localisés renvoyés par la boutique, effectuer et restaurer les achats, gérer les abonnements et confirmer les droits. L’accès au réseau est utilisé uniquement pour ces fonctions officielles des boutiques Apple ou Google.","Apple ou Google est responsable des comptes de boutique, des paiements, de la facturation, des transactions, des remboursements et des services d’abonnement. L’app traite uniquement les informations de la boutique nécessaires pour confirmer les produits et les droits, et ne reçoit ni ne stocke les données de paiement complètes."]},{"title":"5. E-mails d’assistance et site web","paragraphs":["L’app ne lit pas automatiquement vos informations de messagerie. Le canal d’assistance reçoit votre adresse e-mail, votre message et les captures d’écran, enregistrements d’écran, numéros de commande ou autres pièces jointes que vous fournissez volontairement uniquement lorsque vous choisissez d’envoyer un e-mail d’assistance. Ces informations servent uniquement à traiter votre demande et ne sont pas utilisées à des fins publicitaires ou commerciales. N’envoyez pas de mot de passe de compte ou de paiement, ni de numéro de carte complet.","Ce site web n’installe aucun cookie publicitaire ou analytique et ne contient aucun script d’analyse du trafic ou de suivi."]},{"title":"6. Conservation et suppression","paragraphs":["Supprimez les données stockées sur l’appareil en désinstallant l’app. Sur Android, vous pouvez également utiliser l’option système « Effacer les données ».","Les enregistrements d’achat sont gérés par Apple ou Google. Les droits restaurables sont confirmés de nouveau conformément aux règles de la boutique.","Les e-mails d’assistance sont conservés pendant la durée nécessaire au traitement de la demande et au respect des obligations indispensables de tenue de registres. Vous pouvez nous écrire pour demander la suppression des échanges d’assistance que nous détenons encore."]},{"title":"7. Sécurité des données","paragraphs":["L’app utilise le traitement sur l’appareil, des autorisations minimales et les processus d’achat officiels des boutiques d’applications afin de limiter les transferts de données inutiles. Les e-mails d’assistance servent uniquement à traiter les demandes reçues et font l’objet de mesures de protection raisonnables adaptées à la nature des informations.","Aucun appareil, réseau ou moyen de stockage électronique ne peut être garanti comme totalement sécurisé. N’incluez pas d’informations sensibles sans rapport avec votre demande dans un e-mail d’assistance."]},{"title":"8. Enfants et adolescents","paragraphs":["L’app ne nécessite pas de compte et ne crée pas de profils d’enfants ou d’autres utilisateurs au moyen de la publicité ou de l’analyse comportementale. Un parent ou tuteur estimant qu’un enfant a fourni des informations personnelles dans un e-mail d’assistance peut nous contacter afin que la situation soit traitée."]},{"title":"9. Vos choix et vos droits","paragraphs":["Vous gérez les données locales depuis votre appareil. Apple ou Google gère les comptes de boutique et les enregistrements d’achat. L’app ne peut pas modifier ni supprimer à votre place les enregistrements de transaction conservés par une boutique d’applications.","Si les pratiques de l’app en matière de données, les règles des plateformes ou les modalités d’hébergement du site changent, nous mettrons à jour la présente Politique et la date affichée sur cette page, et fournirons un avis supplémentaire lorsque les règles applicables l’exigent.","Pour toute question relative à la confidentialité, veuillez envoyer un courriel. {email}"]}]},"terms":{"title":"Conditions d'utilisation","lead":"{appName} Conditions d'utilisation.","sections":[{"title":"1. Acceptation des conditions et des règles de la plateforme","paragraphs":["En téléchargeant, achetant ou utilisant {appName}, vous acceptez les présentes conditions d'utilisation ainsi que les règles applicables sur la plateforme de téléchargement d'applications où vous effectuez votre achat. Si vous n'acceptez pas ces conditions, veuillez cesser d'utiliser l'application et de l'acheter.","Les présentes Conditions s’appliquent au téléchargement, à l’achat et à l’utilisation de l’app. Les versions iOS et iPadOS sont également soumises au"],"links":["appleEula"]},{"title":"2. Produits payants et prix","paragraphs":["La reconnaissance et la retouche n’ont aucune limite d’utilisation. Seule l’exportation de l’image traitée nécessite un accès Premium valide. L’app propose des abonnements hebdomadaire et mensuel à renouvellement automatique ainsi qu’un achat unique à vie, sans essai gratuit. Les achats App Store et Google Play sont distincts et ne peuvent pas être transférés entre les plateformes.","Le prix réel, la devise, les taxes, la période de facturation et l’admissibilité à l’achat correspondent aux informations affichées et confirmées sur l’écran d’achat système de l’App Store ou de Google Play. La plateforme d’achat prélève et gère le paiement par l’intermédiaire de votre compte de boutique. L’app ne propose ni essai gratuit d’abonnement ni autre formule payante."]},{"title":"3. Renouvellement automatique et annulation","paragraphs":["Les abonnements hebdomadaires et mensuels sont renouvelés automatiquement et facturés pour la période indiquée sur l’écran d’achat système jusqu’à ce que vous les annuliez sur la plateforme d’achat. La suppression de {appName} n’annule pas automatiquement un abonnement. Sauf remboursement ou autre mesure de la plateforme d’achat, vous pouvez continuer à utiliser l’abonnement jusqu’à la fin de la période déjà payée après avoir désactivé le renouvellement automatique."],"links":["appleCancel","googleManage"]},{"title":"4. Achats, restauration et remboursements","paragraphs":["Les achats et leur restauration sont effectués par la boutique officielle Apple ou Google. Un droit est accordé uniquement après confirmation d’une transaction valide par la boutique. Une transaction annulée, échouée ou en attente n’accorde aucun droit avant sa confirmation. La restauration des achats peut rétablir l’accès à vie et un abonnement actuellement actif. Les achats effectués sur l’App Store et Google Play sont indépendants et ne peuvent être ni restaurés ni transférés d’une plateforme à l’autre.","Les remboursements sont traités par la boutique d’applications ayant effectué la transaction, conformément à ses règles, à la région d’achat et au droit applicable. Le droit correspondant est supprimé lorsque la boutique confirme un remboursement, une révocation, l’expiration d’un abonnement ou l’invalidité d’une transaction."],"links":["appleRefund","googleRefund"]},{"title":"5. Utilisation hors ligne et disponibilité","paragraphs":["La sélection des images, l’OCR, la détection des contenus sensibles, la retouche et l’exportation sont effectués sur votre appareil. L’app ne propose ni reconnaissance d’images dans le cloud, ni synchronisation cloud, ni compte. Une nouvelle image est créée à l’exportation et les métadonnées privées amovibles sont supprimées. Les fichiers de travail temporaires sont effacés après une sauvegarde réussie, l’abandon de la retouche ou la fin de la session ; l’état nécessaire peut être conservé en cas d’échec afin de réessayer."]},{"title":"6. Utilisation acceptable et propriété intellectuelle","paragraphs":["Vous ne devez pas utiliser l’app pour une activité illégale, contourner la vérification des achats, endommager l’app, diffuser du code malveillant, copier ou distribuer l’app sans autorisation, ni porter atteinte aux droits relatifs au contenu de l’app ou à la propriété intellectuelle d’un tiers.","Vous pouvez cesser d’utiliser l’app et la désinstaller à tout moment. Nous pouvons publier des mises à jour afin de corriger des problèmes, de prendre en charge les systèmes d’exploitation, d’améliorer la stabilité ou de respecter les exigences des plateformes. Des problèmes liés à l’appareil, au système, au réseau ou aux services de la boutique peuvent rendre certaines fonctions temporairement indisponibles.","Dans la mesure permise par le droit applicable, l’app est fournie selon sa disponibilité. Les présentes Conditions n’excluent aucune responsabilité ne pouvant légalement être exclue et ne limitent pas les droits impératifs des consommateurs dont vous bénéficiez.","Si les fonctions du produit, les modes de paiement, les règles des plateformes ou le droit applicable changent, nous pouvons mettre à jour les présentes Conditions et la date affichée sur cette page. Si une modification affecte substantiellement les droits des utilisateurs, nous fournirons un avis supplémentaire comme l’exigent les règles applicables.","Pour toute question concernant ces conditions, vos achats ou l'utilisation de l'application, veuillez nous contacter par e-mail. {email}"]}]},"support":{"title":"Assistance","lead":"Commencez par consulter les questions fréquentes ci-dessous. Si le problème persiste, contactez-nous à l’adresse e-mail d’assistance.","emailTitle":"{appName} Courriel d'assistance","emailLead":"Commencez par consulter les questions fréquentes ci-dessous. Si le problème persiste, contactez-nous à l’adresse e-mail d’assistance.","beforeEmail":{"title":"Informations à inclure dans votre e-mail","paragraphs":["Pour un problème d’achat, vous pouvez indiquer le numéro de commande de la boutique d’applications, mais n’envoyez pas le mot de passe de votre compte ou de paiement, ni les informations complètes de votre carte."],"bullets":["votre plateforme, le modèle de l’appareil, la version du système d’exploitation et la version de l’app ;","les actions effectuées avant le problème, le résultat attendu et le résultat obtenu ; et","Si nécessaire, une capture d'écran ou un enregistrement d'écran avec les informations privées masquées."]},"faqs":[{"question":"Les images sont-elles envoyées vers un serveur ?","answer":"La sélection des images, l’OCR, la détection des contenus sensibles, la retouche et l’exportation sont effectués sur votre appareil. L’app ne propose ni reconnaissance d’images dans le cloud, ni synchronisation cloud, ni compte. Une nouvelle image est créée à l’exportation et les métadonnées privées amovibles sont supprimées. Les fichiers de travail temporaires sont effacés après une sauvegarde réussie, l’abandon de la retouche ou la fin de la session ; l’état nécessaire peut être conservé en cas d’échec afin de réessayer."},{"question":"Autorisations, publicité et suivi","answer":"L’accès aux photos sert uniquement à afficher et traiter les images que vous autorisez. L’appareil photo n’est utilisé que lorsque vous choisissez de prendre une photo. L’autorisation d’enregistrer dans la photothèque n’est demandée que lorsque vous confirmez l’exportation avec un accès Premium valide. L’app ne demande pas l’accès à la position, aux contacts, au microphone, au Bluetooth ou aux notifications."},{"question":"Produits payants et prix","answer":"La reconnaissance et la retouche n’ont aucune limite d’utilisation. Seule l’exportation de l’image traitée nécessite un accès Premium valide. L’app propose des abonnements hebdomadaire et mensuel à renouvellement automatique ainsi qu’un achat unique à vie, sans essai gratuit. Les achats App Store et Google Play sont distincts et ne peuvent pas être transférés entre les plateformes."},{"question":"Enregistrement et formats d’image","answer":"Si l’enregistrement échoue, vérifiez l’espace disponible, l’autorisation d’enregistrer dans la photothèque et l’accès à l’image d’origine, puis réessayez. L’app traite une image fixe à la fois et prend en charge la plupart des formats courants ; certains formats dépendent de l’appareil et du système. Les vidéos, PDF, RAW/DNG et le traitement par lots ne sont pas pris en charge actuellement."},{"question":"Comment changer de langue ?","answer":"L’app prend en charge 40 langues, que vous pouvez sélectionner dans ses réglages. Si l’affichage est incorrect, indiquez par e-mail la langue de l’appareil et celle sélectionnée dans l’app."},{"question":"Restauration, annulation et remboursements","answer":"Les achats et leur restauration sont effectués par la boutique officielle Apple ou Google. Un droit est accordé uniquement après confirmation d’une transaction valide par la boutique. Une transaction annulée, échouée ou en attente n’accorde aucun droit avant sa confirmation. La restauration des achats peut rétablir l’accès à vie et un abonnement actuellement actif. Les achats effectués sur l’App Store et Google Play sont indépendants et ne peuvent être ni restaurés ni transférés d’une plateforme à l’autre."},{"question":"Confidentialité et suppression des données","answer":"Supprimez les données stockées sur l’appareil en désinstallant l’app. Sur Android, vous pouvez également utiliser l’option système « Effacer les données ». Les enregistrements d’achat sont gérés par Apple ou Google. Les droits restaurables sont confirmés de nouveau conformément aux règles de la boutique. Les e-mails d’assistance sont conservés pendant la durée nécessaire au traitement de la demande et au respect des obligations indispensables de tenue de registres. Vous pouvez nous écrire pour demander la suppression des échanges d’assistance que nous détenons encore."}],"officialHelpTitle":"Aide rapide"}},"he":{"linkLabels":{"appleEula":"הסכם הרישיון הסטנדרטי של Apple למשתמש קצה (EULA)","appleCancel":"הוראות לביטול מנוי של אפל","googleManage":"הוראות ביטול ב-Google Play","appleRefund":"בקשת החזר כספי מאפל","googleRefund":"מידע על החזרים כספיים ב-Google Play"},"nav":{"privacy":"מדיניות פרטיות","terms":"תנאי שימוש","support":"תמיכה","language":"שָׂפָה","chooseLanguage":"בחירת שפת תצוגה","navigationLabel":"ניווט ראשי"},"home":{"eyebrow":"{appName} · Privacy first","title":"התמונות שלך אינן מועלות לשרתים שלנו.","lead":"בחירת תמונות, OCR, זיהוי תוכן רגיש, עריכה וייצוא מתבצעים במכשיר. האפליקציה אינה מציעה זיהוי תמונות בענן, סנכרון בענן או חשבונות. בעת הייצוא נוצרת תמונה חדשה ומוסרים נתוני מטא פרטיים שניתן למחוק. קובצי עבודה זמניים נמחקים לאחר שמירה מוצלחת, ביטול העריכה או סיום ההפעלה; אם השמירה נכשלת, ייתכן שהמצב הנדרש יישמר לניסיון חוזר.","points":["נתוני האפליקציה","מוצרים בתשלום ומחירים","תמיכה"],"cards":[{"title":"מדיניות פרטיות","description":"התמונות שלך אינן מועלות לשרתים שלנו.","action":"מדיניות פרטיות"},{"title":"תנאי שימוש","description":"לזיהוי ולעריכה אין מגבלת שימוש. רק ייצוא התמונה המעובדת דורש גישת Premium תקפה. האפליקציה מציעה מנויים שבועיים וחודשיים המתחדשים אוטומטית ורכישה חד-פעמית לכל החיים, ללא תקופת ניסיון חינם. רכישות ב-App Store וב-Google Play נפרדות ואינן ניתנות להעברה בין הפלטפורמות.","action":"תנאי שימוש"},{"title":"צריכים עזרה?","description":"מומלץ להתחיל בשאלות הנפוצות שלהלן. אם הבעיה נמשכת, יש לפנות אלינו באמצעות כתובת הדוא״ל לתמיכה.","action":"תמיכה"}]},"footer":{"privacy":"מדיניות פרטיות","terms":"תנאי שימוש","support":"תמיכה"},"privacy":{"title":"מדיניות פרטיות","lead":"מדיניות זו מסבירה כיצד {appName} מטפל בנתונים במכשיר, בפרטי רכישה מחנות האפליקציות ובהודעות דוא״ל לתמיכה.","sections":[{"title":"1. היקף ויצירת קשר","paragraphs":["מדיניות זו חלה על האפליקציה {appName} עבור iOS,‏ iPadOS ו-Android, וכן על אתר הפרטיות, התנאים והתמיכה הזה.","לשאלות בנוגע לפרטיות, שלחו דוא\"ל {email}"]},{"title":"2. נתוני האפליקציה","callout":{"title":"התמונות שלך אינן מועלות לשרתים שלנו.","body":"בחירת תמונות, OCR, זיהוי תוכן רגיש, עריכה וייצוא מתבצעים במכשיר. האפליקציה אינה מציעה זיהוי תמונות בענן, סנכרון בענן או חשבונות. בעת הייצוא נוצרת תמונה חדשה ומוסרים נתוני מטא פרטיים שניתן למחוק. קובצי עבודה זמניים נמחקים לאחר שמירה מוצלחת, ביטול העריכה או סיום ההפעלה; אם השמירה נכשלת, ייתכן שהמצב הנדרש יישמר לניסיון חוזר."},"paragraphs":[]},{"title":"3. הרשאות, פרסום ומעקב","paragraphs":["הגישה לתמונות משמשת רק להצגה ולעיבוד של תמונות שאישרת. המצלמה משמשת רק כאשר בוחרים לצלם בתוך האפליקציה. הרשאה לשמור בספריית התמונות מתבקשת רק בעת אישור ייצוא עם גישת Premium תקפה. האפליקציה אינה מבקשת מיקום, אנשי קשר, מיקרופון, Bluetooth או התראות.","היא אינה משתמשת במזהה פרסום ואינה משלבת ערכות SDK של צד שלישי לפרסום, לניתוח, לשיוך או לדיווח על קריסות.","האפליקציה אינה משלבת כלי צד שלישי לדיווח על קריסות. בהתאם להגדרות המכשיר והחנות שלך, Apple או Google עשויה לעבד פרטי אבחון של המערכת לפי כללי הפרטיות שלה ולספק מידע טכני המשמש לבדיקת קריסות או בעיות ביצועים."]},{"title":"4. שירותי חנות האפליקציות וגישה לרשת","paragraphs":["האפליקציה משתמשת ב-Apple StoreKit או ב-Google Play Billing כדי לטעון מוצרים, להציג מחירים מקומיים שמוחזרים מהחנות, להשלים רכישות, לשחזר רכישות, לנהל מינויים ולאשר הרשאות. הגישה לרשת משמשת רק עבור היכולות הרשמיות האלה של חנות Apple או Google.","Apple או Google אחראית לחשבונות החנות, לתשלומים, לחיובים, לעסקאות, להחזרים כספיים ולשירותי מינויים. האפליקציה מעבדת רק את פרטי החנות הדרושים לאישור מוצרים והרשאות, ואינה מקבלת או שומרת פרטי תשלום מלאים."]},{"title":"5. הודעות דוא״ל לתמיכה והאתר","paragraphs":["האפליקציה אינה קוראת את פרטי הדוא״ל שלך באופן אוטומטי. רק כאשר בחרת לשלוח הודעת דוא״ל לתמיכה, ערוץ התמיכה מקבל את כתובת הדוא״ל שלך, את ההודעה וכל צילום מסך, הקלטת מסך, מספר הזמנה או קובץ מצורף אחר שמסרת מרצונך. מידע זה משמש רק לטיפול בבקשתך ואינו משמש לפרסום או לשיווק. אין לשלוח סיסמאות לחשבון או לתשלום או מספרי כרטיס מלאים.","אתר זה אינו מגדיר קובצי Cookie לפרסום או לניתוח ואינו כולל ניתוח תעבורה או סקריפטים למעקב."]},{"title":"6. שמירה ומחיקה","paragraphs":["כדי למחוק נתונים במכשיר, יש להסיר את האפליקציה. ב-Android ניתן להשתמש גם באפשרות המערכת \"מחיקת נתונים\".","רשומות הרכישה בחנות מנוהלות על ידי Apple או Google. הרשאות שניתנות לשחזור מאושרות מחדש לפי כללי החנות.","הודעות דוא״ל לתמיכה נשמרות כל עוד הדבר נחוץ לטיפול בבקשה ולעמידה בדרישות נדרשות לשמירת רשומות. ניתן לשלוח לנו הודעת דוא״ל כדי לבקש את מחיקת התכתובות עם התמיכה שעדיין שמורות אצלנו."]},{"title":"7. אבטחת נתונים","paragraphs":["האפליקציה משתמשת בעיבוד במכשיר, בהרשאות מזעריות ובתהליכי הרכישה הרשמיים של חנות האפליקציות כדי לצמצם העברות נתונים שאינן נחוצות. הודעות דוא״ל לתמיכה משמשות רק לטיפול בבקשות נכנסות, תוך נקיטת אמצעי הגנה סבירים המתאימים לאופי המידע.","לא ניתן להבטיח שמכשיר, רשת או שיטת אחסון אלקטרונית כלשהם יהיו מאובטחים לחלוטין. אין לכלול מידע רגיש שאינו קשור לנושא בהודעת דוא״ל לתמיכה."]},{"title":"8. ילדים ובני נוער","paragraphs":["האפליקציה אינה דורשת חשבון ואינה יוצרת פרופילים של ילדים או משתמשים אחרים באמצעות פרסום או ניתוח התנהגות. הורה או אפוטרופוס שסבור שילד מסר מידע אישי בהודעת דוא״ל לתמיכה יכול לפנות אלינו כדי שהנושא יטופל."]},{"title":"9. הבחירות והזכויות שלך","paragraphs":["נתונים במכשיר מנוהלים על ידך באמצעות המכשיר. Apple או Google מנהלת את חשבונות החנות ואת רשומות הרכישה. האפליקציה אינה יכולה לשנות או למחוק בשמך רשומות עסקאות המוחזקות על ידי חנות אפליקציות.","אם נוהלי הנתונים של האפליקציה, כללי הפלטפורמה או הסדרי אחסון האתר ישתנו, נעדכן מדיניות זו ואת התאריך המוצג בדף, ונספק הודעה נוספת כאשר הכללים החלים דורשים זאת.","לשאלות בנוגע לפרטיות, שלחו דוא\"ל {email}"]}]},"terms":{"title":"תנאי שימוש","lead":"תנאי שימוש של {appName}.","sections":[{"title":"1. קבלת תנאים אלה וכללי הפלטפורמה","paragraphs":["על ידי הורדה, רכישה או שימוש ב-{appName}, הנך מסכים לתנאים אלה ולכללים החלים עליך בחנות האפליקציות בה תבצע רכישה. אם אינך מסכים, אל תמשיך להשתמש באפליקציה או לבצע רכישה.","תנאים אלה חלים על ההורדה, הרכישה והשימוש שלך באפליקציה. גרסאות iOS ו-iPadOS כפופות גם ל"],"links":["appleEula"]},{"title":"2. מוצרים בתשלום ומחירים","paragraphs":["לזיהוי ולעריכה אין מגבלת שימוש. רק ייצוא התמונה המעובדת דורש גישת Premium תקפה. האפליקציה מציעה מנויים שבועיים וחודשיים המתחדשים אוטומטית ורכישה חד-פעמית לכל החיים, ללא תקופת ניסיון חינם. רכישות ב-App Store וב-Google Play נפרדות ואינן ניתנות להעברה בין הפלטפורמות.","המחיר, המטבע, המסים, תקופת החיוב והזכאות לרכישה בפועל הם המידע שמוצג ומאושר במסך הרכישה של מערכת App Store או Google Play. פלטפורמת הרכישה מחייבת ומנהלת את התשלום דרך חשבון החנות שלך. האפליקציה אינה מציעה תקופת ניסיון חינם למינוי או תוכניות אחרות בתשלום."]},{"title":"3. חידוש אוטומטי וביטול","paragraphs":["מינויים שבועיים וחודשיים מתחדשים אוטומטית ומחויבים עבור תקופת החיוב שמוצגת במסך הרכישה של המערכת עד לביטולם דרך פלטפורמת הרכישה. מחיקת {appName} אינה מבטלת מינוי באופן אוטומטי. אלא אם פלטפורמת הרכישה מספקת החזר כספי או טיפול אחר, ניתן להמשיך להשתמש במינוי עד לתום התקופה הנוכחית ששולמה לאחר כיבוי החידוש האוטומטי."],"links":["appleCancel","googleManage"]},{"title":"4. רכישות, שחזור והחזרים כספיים","paragraphs":["רכישות ושחזור רכישות מתבצעים דרך החנות הרשמית של Apple או Google. הרשאה ניתנת רק לאחר שהחנות מאשרת עסקה תקפה. עסקאות שבוטלו, נכשלו או ממתינות אינן מעניקות הרשאה לפני אישור מוצלח. שחזור רכישות יכול לשחזר גישה לכל החיים ומינוי הפעיל כעת. רכישות ב-App Store וב-Google Play נפרדות ולא ניתן לשחזר או להעביר אותן בין פלטפורמות.","החזרים כספיים מטופלים על ידי חנות האפליקציות שהשלימה את העסקה, לפי כלליה, אזור הרכישה והדין החל. ההרשאה המתאימה מוסרת לאחר שהחנות מאשרת החזר כספי, ביטול, פקיעת מינוי או עסקה בלתי תקפה."],"links":["appleRefund","googleRefund"]},{"title":"5. שימוש במצב לא מקוון וזמינות","paragraphs":["בחירת תמונות, OCR, זיהוי תוכן רגיש, עריכה וייצוא מתבצעים במכשיר. האפליקציה אינה מציעה זיהוי תמונות בענן, סנכרון בענן או חשבונות. בעת הייצוא נוצרת תמונה חדשה ומוסרים נתוני מטא פרטיים שניתן למחוק. קובצי עבודה זמניים נמחקים לאחר שמירה מוצלחת, ביטול העריכה או סיום ההפעלה; אם השמירה נכשלת, ייתכן שהמצב הנדרש יישמר לניסיון חוזר."]},{"title":"6. שימוש מקובל וקניין רוחני","paragraphs":["אין להשתמש באפליקציה לפעילות בלתי חוקית; לעקוף אימות רכישה; לפגוע באפליקציה; להפיץ קוד זדוני; להעתיק או להפיץ את האפליקציה ללא רשות; או להפר זכויות בתוכן האפליקציה או קניין רוחני של אדם אחר.","באפשרותך להפסיק להשתמש באפליקציה ולהסיר אותה בכל עת. אנו עשויים לפרסם עדכונים כדי לתקן בעיות, לתמוך במערכות הפעלה, לשפר יציבות או לעמוד בדרישות הפלטפורמה. בעיות במכשיר, במערכת, ברשת או בשירות החנות עלולות להפוך תכונות מסוימות ללא זמינות באופן זמני.","במידה המותרת לפי הדין החל, האפליקציה מסופקת בהתאם לזמינותה. תנאים אלה אינם מחריגים אחריות שלא ניתן להחריג כדין ואינם מגבילים זכויות צרכניות מחייבות העומדות לרשותך.","אם תכונות המוצר, אמצעי התשלום, כללי הפלטפורמה או הדין החל ישתנו, אנו עשויים לעדכן תנאים אלה ואת התאריך המוצג בדף. אם שינוי ישפיע באופן מהותי על זכויות המשתמשים, נספק הודעה נוספת כנדרש.","לשאלות בנוגע לתנאים אלה, רכישות או שימוש באפליקציה, שלחו דוא\"ל {email}"]}]},"support":{"title":"תמיכה","lead":"מומלץ להתחיל בשאלות הנפוצות שלהלן. אם הבעיה נמשכת, יש לפנות אלינו באמצעות כתובת הדוא״ל לתמיכה.","emailTitle":"דוא\"ל תמיכה של {appName}","emailLead":"מומלץ להתחיל בשאלות הנפוצות שלהלן. אם הבעיה נמשכת, יש לפנות אלינו באמצעות כתובת הדוא״ל לתמיכה.","beforeEmail":{"title":"מה לכלול בהודעת הדוא״ל","paragraphs":["במקרה של בעיית רכישה, אפשר לכלול את מספר ההזמנה מחנות האפליקציות, אך אין לשלוח את סיסמת החשבון או התשלום או את פרטי הכרטיס המלאים."],"bullets":["הפלטפורמה, דגם המכשיר, גרסת מערכת ההפעלה וגרסת האפליקציה;","מה עשית לפני הבעיה, למה ציפית ומה קרה בפועל; וכן","במידת הצורך, צילום מסך או הקלטת מסך עם מידע פרטי מוסתר."]},"faqs":[{"question":"האם התמונות מועלות לשרת?","answer":"בחירת תמונות, OCR, זיהוי תוכן רגיש, עריכה וייצוא מתבצעים במכשיר. האפליקציה אינה מציעה זיהוי תמונות בענן, סנכרון בענן או חשבונות. בעת הייצוא נוצרת תמונה חדשה ומוסרים נתוני מטא פרטיים שניתן למחוק. קובצי עבודה זמניים נמחקים לאחר שמירה מוצלחת, ביטול העריכה או סיום ההפעלה; אם השמירה נכשלת, ייתכן שהמצב הנדרש יישמר לניסיון חוזר."},{"question":"הרשאות, פרסום ומעקב","answer":"הגישה לתמונות משמשת רק להצגה ולעיבוד של תמונות שאישרת. המצלמה משמשת רק כאשר בוחרים לצלם בתוך האפליקציה. הרשאה לשמור בספריית התמונות מתבקשת רק בעת אישור ייצוא עם גישת Premium תקפה. האפליקציה אינה מבקשת מיקום, אנשי קשר, מיקרופון, Bluetooth או התראות."},{"question":"מוצרים בתשלום ומחירים","answer":"לזיהוי ולעריכה אין מגבלת שימוש. רק ייצוא התמונה המעובדת דורש גישת Premium תקפה. האפליקציה מציעה מנויים שבועיים וחודשיים המתחדשים אוטומטית ורכישה חד-פעמית לכל החיים, ללא תקופת ניסיון חינם. רכישות ב-App Store וב-Google Play נפרדות ואינן ניתנות להעברה בין הפלטפורמות."},{"question":"שמירה ופורמטים של תמונות","answer":"אם השמירה נכשלת, יש לבדוק מקום פנוי, הרשאה לשמור בספריית התמונות והאם ניתן עדיין לקרוא את התמונה המקורית, ואז לנסות שוב. האפליקציה מעבדת תמונה סטטית אחת בכל פעם ותומכת ברוב הפורמטים הנפוצים; חלקם תלויים במכשיר ובגרסת המערכת. וידאו, PDF, RAW/DNG ועיבוד באצווה אינם נתמכים כעת."},{"question":"כיצד משנים את השפה?","answer":"האפליקציה תומכת ב-40 שפות וניתן לשנות את השפה בהגדרות האפליקציה. אם התצוגה אינה תקינה, יש לשלוח בדוא״ל את שפת המכשיר ואת השפה שנבחרה באפליקציה."},{"question":"שחזור, ביטול והחזרים כספיים","answer":"רכישות ושחזור רכישות מתבצעים דרך החנות הרשמית של Apple או Google. הרשאה ניתנת רק לאחר שהחנות מאשרת עסקה תקפה. עסקאות שבוטלו, נכשלו או ממתינות אינן מעניקות הרשאה לפני אישור מוצלח. שחזור רכישות יכול לשחזר גישה לכל החיים ומינוי הפעיל כעת. רכישות ב-App Store וב-Google Play נפרדות ולא ניתן לשחזר או להעביר אותן בין פלטפורמות."},{"question":"פרטיות ומחיקת נתונים","answer":"כדי למחוק נתונים במכשיר, יש להסיר את האפליקציה. ב-Android ניתן להשתמש גם באפשרות המערכת \"מחיקת נתונים\". רשומות הרכישה בחנות מנוהלות על ידי Apple או Google. הרשאות שניתנות לשחזור מאושרות מחדש לפי כללי החנות. הודעות דוא״ל לתמיכה נשמרות כל עוד הדבר נחוץ לטיפול בבקשה ולעמידה בדרישות נדרשות לשמירת רשומות. ניתן לשלוח לנו הודעת דוא״ל כדי לבקש את מחיקת התכתובות עם התמיכה שעדיין שמורות אצלנו."}],"officialHelpTitle":"עזרה מהירה"}},"hi":{"linkLabels":{"appleEula":"Apple का मानक अंतिम उपयोगकर्ता लाइसेंस अनुबंध (EULA)","appleCancel":"Apple सदस्यता रद्द करने के निर्देश","googleManage":"Google Play रद्द करने के निर्देश","appleRefund":"Apple से रिफंड का अनुरोध करें","googleRefund":"Google Play रिफ़ंड की जानकारी"},"nav":{"privacy":"गोपनीयता नीति","terms":"उपयोग की शर्तें","support":"सहायता","language":"भाषा","chooseLanguage":"प्रदर्शन भाषा चुनें","navigationLabel":"प्राथमिक नेविगेशन"},"home":{"eyebrow":"{appName} · Privacy first","title":"आपकी इमेज हमारे सर्वर पर अपलोड नहीं की जाती हैं।","lead":"इमेज चुनना, OCR, संवेदनशील सामग्री पहचानना, संपादन और निर्यात आपके डिवाइस पर होता है। ऐप क्लाउड इमेज पहचान, क्लाउड सिंक या खाता सुविधा नहीं देता। निर्यात के समय नई इमेज बनाई जाती है और हटाए जा सकने वाले निजी मेटाडेटा मिटा दिए जाते हैं। सफलतापूर्वक सहेजने, संपादन छोड़ने या सत्र समाप्त होने के बाद अस्थायी फ़ाइलें हटा दी जाती हैं; सहेजना विफल होने पर दोबारा प्रयास के लिए आवश्यक स्थिति रखी जा सकती है।","points":["ऐप डेटा","सशुल्क उत्पाद और कीमतें","सहायता"],"cards":[{"title":"गोपनीयता नीति","description":"आपकी इमेज हमारे सर्वर पर अपलोड नहीं की जाती हैं।","action":"गोपनीयता नीति"},{"title":"उपयोग की शर्तें","description":"पहचान और संपादन पर उपयोग सीमा नहीं है। केवल प्रोसेस की गई इमेज निर्यात करने के लिए वैध Premium चाहिए। ऐप बिना मुफ़्त ट्रायल के स्वतः नवीनीकृत साप्ताहिक और मासिक सदस्यता तथा एक बार की आजीवन खरीद देता है। App Store और Google Play की खरीद अलग हैं और प्लेटफ़ॉर्म के बीच स्थानांतरित नहीं की जा सकतीं।","action":"उपयोग की शर्तें"},{"title":"मदद की ज़रूरत है?","description":"पहले नीचे दिए सामान्य प्रश्न देखें। अगर समस्या बनी रहती है, तो सहायता ईमेल पते के माध्यम से हमसे संपर्क करें।","action":"सहायता"}]},"footer":{"privacy":"गोपनीयता नीति","terms":"उपयोग की शर्तें","support":"सहायता"},"privacy":{"title":"गोपनीयता नीति","lead":"यह नीति बताती है कि {appName} डिवाइस पर मौजूद डेटा, ऐप स्टोर खरीद जानकारी और सहायता ईमेल को कैसे संभालता है।","sections":[{"title":"1. कार्यक्षेत्र और संपर्क","paragraphs":["यह नीति iOS, iPadOS और Android के लिए {appName} ऐप तथा इस गोपनीयता, शर्तें और सहायता वेबसाइट पर लागू होती है।","गोपनीयता संबंधी प्रश्नों के लिए, ईमेल करें {email}"]},{"title":"2. ऐप डेटा","callout":{"title":"आपकी इमेज हमारे सर्वर पर अपलोड नहीं की जाती हैं।","body":"इमेज चुनना, OCR, संवेदनशील सामग्री पहचानना, संपादन और निर्यात आपके डिवाइस पर होता है। ऐप क्लाउड इमेज पहचान, क्लाउड सिंक या खाता सुविधा नहीं देता। निर्यात के समय नई इमेज बनाई जाती है और हटाए जा सकने वाले निजी मेटाडेटा मिटा दिए जाते हैं। सफलतापूर्वक सहेजने, संपादन छोड़ने या सत्र समाप्त होने के बाद अस्थायी फ़ाइलें हटा दी जाती हैं; सहेजना विफल होने पर दोबारा प्रयास के लिए आवश्यक स्थिति रखी जा सकती है।"},"paragraphs":[]},{"title":"3. अनुमतियाँ, विज्ञापन और ट्रैकिंग","paragraphs":["फ़ोटो एक्सेस का उपयोग केवल आपकी अनुमति वाली इमेज दिखाने और प्रोसेस करने के लिए होता है। कैमरा केवल तब उपयोग होता है जब आप ऐप में फ़ोटो लेना चुनते हैं। फ़ोटो लाइब्रेरी में सहेजने की अनुमति केवल वैध Premium के साथ निर्यात की पुष्टि करते समय माँगी जाती है। ऐप स्थान, संपर्क, माइक्रोफ़ोन, Bluetooth या सूचनाओं की अनुमति नहीं माँगता।","यह विज्ञापन पहचानकर्ता का उपयोग नहीं करता और विज्ञापन, विश्लेषण, एट्रिब्यूशन या क्रैश रिपोर्टिंग के लिए तृतीय-पक्ष SDK शामिल नहीं करता।","ऐप तृतीय-पक्ष क्रैश रिपोर्टिंग टूल शामिल नहीं करता। आपके डिवाइस और स्टोर की सेटिंग के आधार पर, Apple या Google अपने संबंधित गोपनीयता नियमों के तहत सिस्टम निदान जानकारी संसाधित कर सकता है और क्रैश या प्रदर्शन समस्याओं की जाँच के लिए तकनीकी जानकारी दे सकता है।"]},{"title":"4. ऐप स्टोर सेवाएँ और नेटवर्क पहुँच","paragraphs":["ऐप उत्पाद लोड करने, स्टोर द्वारा लौटाई गई स्थानीय कीमतें दिखाने, खरीद पूरी करने, खरीद बहाल करने, सदस्यताएँ प्रबंधित करने और पात्रताएँ पुष्टि करने के लिए Apple StoreKit या Google Play Billing का उपयोग करता है। नेटवर्क पहुँच का उपयोग केवल Apple या Google की इन आधिकारिक स्टोर सुविधाओं के लिए किया जाता है।","स्टोर खातों, भुगतान, बिलिंग, लेन-देन, रिफ़ंड और सदस्यता सेवाओं की ज़िम्मेदारी Apple या Google की है। ऐप केवल उत्पादों और पात्रताओं की पुष्टि के लिए आवश्यक स्टोर जानकारी संसाधित करता है और भुगतान के पूरे क्रेडेंशियल प्राप्त या संग्रहीत नहीं करता।"]},{"title":"5. सहायता ईमेल और वेबसाइट","paragraphs":["ऐप आपकी ईमेल जानकारी अपने-आप नहीं पढ़ता। जब आप सहायता ईमेल भेजना चुनते हैं, तभी सहायता माध्यम को आपका ईमेल पता, संदेश और आपके द्वारा स्वेच्छा से दिया गया कोई स्क्रीनशॉट, स्क्रीन रिकॉर्डिंग, ऑर्डर नंबर या अन्य अटैचमेंट प्राप्त होता है। इस जानकारी का उपयोग केवल आपके अनुरोध को संभालने के लिए किया जाता है, विज्ञापन या मार्केटिंग के लिए नहीं। खाते या भुगतान के पासवर्ड अथवा पूरे कार्ड नंबर न भेजें।","यह वेबसाइट विज्ञापन या विश्लेषण कुकी सेट नहीं करती और इसमें ट्रैफ़िक विश्लेषण या ट्रैकिंग स्क्रिप्ट शामिल नहीं हैं।"]},{"title":"6. प्रतिधारण और हटाना","paragraphs":["ऐप अनइंस्टॉल करके डिवाइस पर मौजूद डेटा हटाएँ। Android पर आप सिस्टम के डेटा मिटाएँ विकल्प का भी उपयोग कर सकते हैं।","स्टोर खरीद रिकॉर्ड Apple या Google द्वारा प्रबंधित किए जाते हैं। बहाल की जा सकने वाली पात्रताओं की स्टोर के नियमों के तहत फिर से पुष्टि की जाती है।","सहायता ईमेल अनुरोध को संभालने और आवश्यक रिकॉर्ड-रखरखाव आवश्यकताओं को पूरा करने के लिए जितने समय आवश्यक हों, उतने समय रखे जाते हैं। हमारे पास अब भी मौजूद सहायता पत्राचार को हटाने का अनुरोध आप ईमेल से कर सकते हैं।"]},{"title":"7. डेटा सुरक्षा","paragraphs":["ऐप अनावश्यक डेटा ट्रांसफ़र कम करने के लिए डिवाइस पर संसाधन, न्यूनतम अनुमतियों और ऐप स्टोर की आधिकारिक खरीद प्रक्रियाओं का उपयोग करता है। सहायता ईमेल का उपयोग केवल आने वाले अनुरोध संभालने के लिए किया जाता है और जानकारी की प्रकृति के अनुरूप उचित सुरक्षा उपाय अपनाए जाते हैं।","किसी भी डिवाइस, नेटवर्क या इलेक्ट्रॉनिक संग्रहण विधि को पूरी तरह सुरक्षित होने की गारंटी नहीं दी जा सकती। सहायता ईमेल में असंबंधित संवेदनशील जानकारी शामिल न करें।"]},{"title":"8. बच्चे और किशोर","paragraphs":["ऐप को खाते की आवश्यकता नहीं है और यह विज्ञापन या व्यवहार विश्लेषण के माध्यम से बच्चों या अन्य उपयोगकर्ताओं की प्रोफ़ाइल नहीं बनाता। यदि माता-पिता या अभिभावक को लगता है कि किसी बच्चे ने सहायता ईमेल के माध्यम से व्यक्तिगत जानकारी दी है, तो वे मामले के समाधान के लिए हमसे संपर्क कर सकते हैं।"]},{"title":"9. आपके विकल्प और अधिकार","paragraphs":["आप अपने डिवाइस के माध्यम से डिवाइस पर मौजूद डेटा का प्रबंधन करते हैं। Apple या Google स्टोर खाते और खरीद रिकॉर्ड प्रबंधित करता है। ऐप आपकी ओर से ऐप स्टोर द्वारा रखे गए लेन-देन रिकॉर्ड को बदल या हटा नहीं सकता।","अगर ऐप की डेटा प्रक्रियाएँ, प्लेटफ़ॉर्म के नियम या वेबसाइट होस्टिंग की व्यवस्था बदलती है, तो हम इस नीति और पेज पर दिखाई गई तारीख को अपडेट करेंगे और लागू नियमों के अनुसार आवश्यक होने पर अतिरिक्त सूचना देंगे।","गोपनीयता संबंधी प्रश्नों के लिए, ईमेल करें {email}"]}]},"terms":{"title":"उपयोग की शर्तें","lead":"{appName} उपयोग की शर्तें।","sections":[{"title":"1. इन नियमों और प्लेटफ़ॉर्म के नियमों को स्वीकार करना","paragraphs":["{appName} को डाउनलोड, खरीद या उपयोग करके, आप इन शर्तों और उस ऐप स्टोर के नियमों से सहमत होते हैं जहाँ आप खरीदारी करते हैं। यदि आप सहमत नहीं हैं, तो ऐप का उपयोग जारी न रखें या खरीदारी न करें।","ये शर्तें आपके द्वारा ऐप डाउनलोड करने, खरीदने और उपयोग करने पर लागू होती हैं। iOS और iPadOS संस्करणों पर यह भी लागू होता है:"],"links":["appleEula"]},{"title":"2. सशुल्क उत्पाद और कीमतें","paragraphs":["पहचान और संपादन पर उपयोग सीमा नहीं है। केवल प्रोसेस की गई इमेज निर्यात करने के लिए वैध Premium चाहिए। ऐप बिना मुफ़्त ट्रायल के स्वतः नवीनीकृत साप्ताहिक और मासिक सदस्यता तथा एक बार की आजीवन खरीद देता है। App Store और Google Play की खरीद अलग हैं और प्लेटफ़ॉर्म के बीच स्थानांतरित नहीं की जा सकतीं।","वास्तविक कीमत, मुद्रा, कर, बिलिंग अवधि और खरीद पात्रता वही जानकारी है जो App Store या Google Play की सिस्टम खरीद स्क्रीन पर दिखाई और पुष्टि की जाती है। खरीद प्लेटफ़ॉर्म आपके स्टोर खाते के माध्यम से शुल्क लेता और भुगतान प्रबंधित करता है। ऐप सदस्यता का मुफ़्त परीक्षण या कोई अन्य सशुल्क योजना प्रदान नहीं करता।"]},{"title":"3. अपने-आप नवीनीकरण और रद्द करना","paragraphs":["साप्ताहिक और मासिक सदस्यताएँ अपने-आप नवीनीकृत होती हैं और सिस्टम खरीद स्क्रीन पर दिखाई गई बिलिंग अवधि के लिए तब तक शुल्क लिया जाता है, जब तक आप खरीद प्लेटफ़ॉर्म से उन्हें रद्द नहीं करते। {appName} हटाने से सदस्यता अपने-आप रद्द नहीं होती। जब तक खरीद प्लेटफ़ॉर्म रिफ़ंड या अन्य व्यवस्था न दे, अपने-आप नवीनीकरण बंद करने के बाद आप वर्तमान सशुल्क अवधि के अंत तक सदस्यता का उपयोग जारी रख सकते हैं।"],"links":["appleCancel","googleManage"]},{"title":"4. खरीदारियाँ, बहाली और रिफ़ंड","paragraphs":["खरीद और खरीद बहाली Apple या Google के आधिकारिक स्टोर के माध्यम से पूरी होती है। स्टोर द्वारा मान्य लेन-देन की पुष्टि के बाद ही पात्रता दी जाती है। रद्द, विफल या लंबित लेन-देन सफल पुष्टि से पहले पात्रता नहीं देते। खरीद बहाली आजीवन पहुँच और वर्तमान में सक्रिय सदस्यता बहाल कर सकती है। App Store और Google Play की खरीदारियाँ अलग हैं और उन्हें अलग-अलग प्लेटफ़ॉर्म पर बहाल या हस्तांतरित नहीं किया जा सकता।","रिफ़ंड उस ऐप स्टोर द्वारा उसके नियमों, खरीद क्षेत्र और लागू कानून के अनुसार संभाला जाता है जिसने लेन-देन पूरा किया था। स्टोर द्वारा रिफ़ंड, निरस्तीकरण, सदस्यता समाप्ति या अमान्य लेन-देन की पुष्टि के बाद संबंधित पात्रता हटा दी जाती है।"],"links":["appleRefund","googleRefund"]},{"title":"5. ऑफ़लाइन उपयोग और उपलब्धता","paragraphs":["इमेज चुनना, OCR, संवेदनशील सामग्री पहचानना, संपादन और निर्यात आपके डिवाइस पर होता है। ऐप क्लाउड इमेज पहचान, क्लाउड सिंक या खाता सुविधा नहीं देता। निर्यात के समय नई इमेज बनाई जाती है और हटाए जा सकने वाले निजी मेटाडेटा मिटा दिए जाते हैं। सफलतापूर्वक सहेजने, संपादन छोड़ने या सत्र समाप्त होने के बाद अस्थायी फ़ाइलें हटा दी जाती हैं; सहेजना विफल होने पर दोबारा प्रयास के लिए आवश्यक स्थिति रखी जा सकती है।"]},{"title":"6. स्वीकार्य उपयोग और बौद्धिक संपदा","paragraphs":["आप ऐप का उपयोग गैरकानूनी गतिविधि के लिए नहीं कर सकते; खरीद सत्यापन को दरकिनार नहीं कर सकते; ऐप को नुकसान नहीं पहुँचा सकते; दुर्भावनापूर्ण कोड वितरित नहीं कर सकते; अनुमति के बिना ऐप की प्रतिलिपि या वितरण नहीं कर सकते; या ऐप की सामग्री के अधिकारों अथवा किसी अन्य व्यक्ति की बौद्धिक संपदा का उल्लंघन नहीं कर सकते।","आप किसी भी समय ऐप का उपयोग बंद करके उसे अनइंस्टॉल कर सकते हैं। हम समस्याएँ ठीक करने, ऑपरेटिंग सिस्टम का समर्थन करने, स्थिरता सुधारने या प्लेटफ़ॉर्म की आवश्यकताएँ पूरी करने के लिए अपडेट जारी कर सकते हैं। डिवाइस, सिस्टम, नेटवर्क या स्टोर सेवा की समस्याएँ कुछ सुविधाओं को अस्थायी रूप से अनुपलब्ध कर सकती हैं।","लागू कानून द्वारा अनुमत सीमा तक, ऐप उपलब्धता के अनुसार प्रदान किया जाता है। ये शर्तें ऐसी ज़िम्मेदारी को बाहर नहीं करतीं जिसे कानूनन बाहर नहीं किया जा सकता और आपको उपलब्ध अनिवार्य उपभोक्ता अधिकारों को सीमित नहीं करतीं।","अगर उत्पाद की सुविधाएँ, भुगतान विधियाँ, प्लेटफ़ॉर्म के नियम या लागू कानून बदलते हैं, तो हम इन शर्तों और पेज पर दिखाई गई तारीख को अपडेट कर सकते हैं। यदि कोई बदलाव उपयोगकर्ताओं के अधिकारों को महत्वपूर्ण रूप से प्रभावित करता है, तो हम आवश्यकतानुसार अतिरिक्त सूचना देंगे।","इन नियमों और शर्तों, खरीदारी या ऐप के उपयोग से संबंधित प्रश्नों के लिए, ईमेल करें। {email}"]}]},"support":{"title":"सहायता","lead":"पहले नीचे दिए सामान्य प्रश्न देखें। अगर समस्या बनी रहती है, तो सहायता ईमेल पते के माध्यम से हमसे संपर्क करें।","emailTitle":"{appName} समर्थन ईमेल","emailLead":"पहले नीचे दिए सामान्य प्रश्न देखें। अगर समस्या बनी रहती है, तो सहायता ईमेल पते के माध्यम से हमसे संपर्क करें।","beforeEmail":{"title":"अपने ईमेल में क्या शामिल करें","paragraphs":["खरीद संबंधी समस्या के लिए आप ऐप स्टोर ऑर्डर नंबर शामिल कर सकते हैं, लेकिन अपने खाते या भुगतान का पासवर्ड अथवा कार्ड की पूरी जानकारी न भेजें।"],"bullets":["अपना प्लेटफ़ॉर्म, डिवाइस मॉडल, ऑपरेटिंग सिस्टम संस्करण और ऐप संस्करण;","समस्या से पहले आपने क्या किया, आप क्या अपेक्षा कर रहे थे और वास्तव में क्या हुआ; और","यदि आवश्यक हो, तो निजी जानकारी को छुपाते हुए स्क्रीनशॉट या स्क्रीन रिकॉर्डिंग।"]},"faqs":[{"question":"क्या इमेज किसी सर्वर पर अपलोड होती हैं?","answer":"इमेज चुनना, OCR, संवेदनशील सामग्री पहचानना, संपादन और निर्यात आपके डिवाइस पर होता है। ऐप क्लाउड इमेज पहचान, क्लाउड सिंक या खाता सुविधा नहीं देता। निर्यात के समय नई इमेज बनाई जाती है और हटाए जा सकने वाले निजी मेटाडेटा मिटा दिए जाते हैं। सफलतापूर्वक सहेजने, संपादन छोड़ने या सत्र समाप्त होने के बाद अस्थायी फ़ाइलें हटा दी जाती हैं; सहेजना विफल होने पर दोबारा प्रयास के लिए आवश्यक स्थिति रखी जा सकती है।"},{"question":"अनुमतियाँ, विज्ञापन और ट्रैकिंग","answer":"फ़ोटो एक्सेस का उपयोग केवल आपकी अनुमति वाली इमेज दिखाने और प्रोसेस करने के लिए होता है। कैमरा केवल तब उपयोग होता है जब आप ऐप में फ़ोटो लेना चुनते हैं। फ़ोटो लाइब्रेरी में सहेजने की अनुमति केवल वैध Premium के साथ निर्यात की पुष्टि करते समय माँगी जाती है। ऐप स्थान, संपर्क, माइक्रोफ़ोन, Bluetooth या सूचनाओं की अनुमति नहीं माँगता।"},{"question":"सशुल्क उत्पाद और कीमतें","answer":"पहचान और संपादन पर उपयोग सीमा नहीं है। केवल प्रोसेस की गई इमेज निर्यात करने के लिए वैध Premium चाहिए। ऐप बिना मुफ़्त ट्रायल के स्वतः नवीनीकृत साप्ताहिक और मासिक सदस्यता तथा एक बार की आजीवन खरीद देता है। App Store और Google Play की खरीद अलग हैं और प्लेटफ़ॉर्म के बीच स्थानांतरित नहीं की जा सकतीं।"},{"question":"सहेजना और इमेज फ़ॉर्मैट","answer":"सहेजना विफल हो तो खाली स्टोरेज, फ़ोटो लाइब्रेरी में सहेजने की अनुमति और मूल इमेज पढ़े जाने की स्थिति जाँचकर फिर प्रयास करें। ऐप एक समय में एक स्थिर इमेज प्रोसेस करता है और अधिकांश सामान्य फ़ॉर्मेट समर्थित हैं; कुछ डिवाइस और सिस्टम संस्करण पर निर्भर हैं। वीडियो, PDF, RAW/DNG और बैच प्रोसेसिंग अभी समर्थित नहीं हैं।"},{"question":"भाषा कैसे बदलें?","answer":"ऐप 40 भाषाओं का समर्थन करता है और भाषा ऐप की सेटिंग में बदली जा सकती है। प्रदर्शन गलत होने पर डिवाइस की भाषा और ऐप में चुनी गई भाषा ईमेल करें।"},{"question":"बहाली, रद्द करना और रिफ़ंड","answer":"खरीद और खरीद बहाली Apple या Google के आधिकारिक स्टोर के माध्यम से पूरी होती है। स्टोर द्वारा मान्य लेन-देन की पुष्टि के बाद ही पात्रता दी जाती है। रद्द, विफल या लंबित लेन-देन सफल पुष्टि से पहले पात्रता नहीं देते। खरीद बहाली आजीवन पहुँच और वर्तमान में सक्रिय सदस्यता बहाल कर सकती है। App Store और Google Play की खरीदारियाँ अलग हैं और उन्हें अलग-अलग प्लेटफ़ॉर्म पर बहाल या हस्तांतरित नहीं किया जा सकता।"},{"question":"गोपनीयता और डेटा हटाना","answer":"ऐप अनइंस्टॉल करके डिवाइस पर मौजूद डेटा हटाएँ। Android पर आप सिस्टम के डेटा मिटाएँ विकल्प का भी उपयोग कर सकते हैं। स्टोर खरीद रिकॉर्ड Apple या Google द्वारा प्रबंधित किए जाते हैं। बहाल की जा सकने वाली पात्रताओं की स्टोर के नियमों के तहत फिर से पुष्टि की जाती है। सहायता ईमेल अनुरोध को संभालने और आवश्यक रिकॉर्ड-रखरखाव आवश्यकताओं को पूरा करने के लिए जितने समय आवश्यक हों, उतने समय रखे जाते हैं। हमारे पास अब भी मौजूद सहायता पत्राचार को हटाने का अनुरोध आप ईमेल से कर सकते हैं।"}],"officialHelpTitle":"त्वरित सहायता"}},"hr":{"linkLabels":{"appleEula":"Appleovu standardnom licencnom ugovoru za krajnjeg korisnika (EULA)","appleCancel":"Upute za otkazivanje Apple pretplate","googleManage":"Upute za otkazivanje na Google Playu","appleRefund":"Zahtjev za povrat novca od Applea","googleRefund":"Informacije o povratu novca na Google Playu"},"nav":{"privacy":"Pravila o privatnosti","terms":"Uvjeti korištenja","support":"Podrška","language":"Jezik","chooseLanguage":"Odaberite jezik prikaza","navigationLabel":"Primarna navigacija"},"home":{"eyebrow":"{appName} · Privacy first","title":"Vaše se slike ne prenose na naše poslužitelje.","lead":"Odabir slike, OCR, otkrivanje osjetljivog sadržaja, uređivanje i izvoz odvijaju se na uređaju. Aplikacija ne nudi prepoznavanje slika u oblaku, sinkronizaciju u oblaku ni račune. Pri izvozu stvara se nova slika i uklanjaju se privatni metapodaci koji se mogu izbrisati. Privremene radne datoteke brišu se nakon uspješnog spremanja, odustajanja od uređivanja ili završetka sesije; ako spremanje ne uspije, stanje potrebno za ponovni pokušaj može se zadržati.","points":["Podaci aplikacije","Plaćeni proizvodi i cijene","Podrška"],"cards":[{"title":"Pravila o privatnosti","description":"Vaše se slike ne prenose na naše poslužitelje.","action":"Pravila o privatnosti"},{"title":"Uvjeti korištenja","description":"Prepoznavanje i uređivanje nemaju ograničenje upotrebe. Samo izvoz obrađene slike zahtijeva važeći Premium pristup. Aplikacija nudi automatski obnovljive tjedne i mjesečne pretplate te jednokratnu doživotnu kupnju, bez besplatnog probnog razdoblja. Kupnje u App Storeu i Google Playu odvojene su i ne mogu se prenositi između platformi.","action":"Uvjeti korištenja"},{"title":"Trebate pomoć?","description":"Najprije pogledajte česta pitanja u nastavku. Ako se problem nastavi, obratite nam se putem adrese e-pošte za podršku.","action":"Podrška"}]},"footer":{"privacy":"Pravila o privatnosti","terms":"Uvjeti korištenja","support":"Podrška"},"privacy":{"title":"Pravila o privatnosti","lead":"Ova Pravila o privatnosti objašnjavaju kako {appName} postupa s podacima na uređaju, informacijama o kupnji iz trgovine aplikacija i porukama e-pošte za podršku.","sections":[{"title":"1. Opseg i kontakt","paragraphs":["Ova Pravila primjenjuju se na aplikaciju {appName} za iOS, iPadOS i Android te na ovo web-mjesto za privatnost, uvjete i podršku.","Za pitanja o privatnosti, pošaljite e-poštu {email}"]},{"title":"2. Podaci aplikacije","callout":{"title":"Vaše se slike ne prenose na naše poslužitelje.","body":"Odabir slike, OCR, otkrivanje osjetljivog sadržaja, uređivanje i izvoz odvijaju se na uređaju. Aplikacija ne nudi prepoznavanje slika u oblaku, sinkronizaciju u oblaku ni račune. Pri izvozu stvara se nova slika i uklanjaju se privatni metapodaci koji se mogu izbrisati. Privremene radne datoteke brišu se nakon uspješnog spremanja, odustajanja od uređivanja ili završetka sesije; ako spremanje ne uspije, stanje potrebno za ponovni pokušaj može se zadržati."},"paragraphs":[]},{"title":"3. Dopuštenja, oglašavanje i praćenje","paragraphs":["Pristup fotografijama koristi se samo za prikaz i obradu slika koje dopustite. Kamera se koristi samo kada odaberete snimanje fotografije u aplikaciji. Dopuštenje za spremanje u fototeku traži se samo kada potvrdite izvoz s važećim Premium pristupom. Aplikacija ne traži lokaciju, kontakte, mikrofon, Bluetooth ni obavijesti.","Ne upotrebljava identifikator za oglašavanje niti integrira SDK-ove trećih strana za oglašavanje, analitiku, atribuciju ili prijavu rušenja.","Aplikacija ne integrira alat treće strane za prijavu rušenja. Ovisno o postavkama vašeg uređaja i trgovine, Apple ili Google može obrađivati dijagnostičke podatke sustava prema vlastitim pravilima o privatnosti i pružati tehničke informacije koje se koriste za istraživanje rušenja ili problema s radom."]},{"title":"4. Usluge trgovine aplikacija i mrežni pristup","paragraphs":["Aplikacija upotrebljava Apple StoreKit ili Google Play Billing za učitavanje proizvoda, prikaz lokaliziranih cijena koje vraća trgovina, dovršavanje kupnji, vraćanje kupnji, upravljanje pretplatama i potvrdu prava. Mrežni pristup upotrebljava se samo za te službene funkcije trgovine Apple ili Google.","Apple ili Google odgovoran je za račune trgovine, plaćanja, naplatu, transakcije, povrate novca i usluge pretplate. Aplikacija obrađuje samo informacije trgovine potrebne za potvrdu proizvoda i prava te ne prima niti pohranjuje potpune podatke za plaćanje."]},{"title":"5. Poruke e-pošte za podršku i web-mjesto","paragraphs":["Aplikacija ne čita automatski podatke vaše e-pošte. Samo kada odlučite poslati poruku e-pošte za podršku, kanal podrške prima vašu adresu e-pošte, poruku i svaku snimku zaslona, snimku rada zaslona, broj narudžbe ili drugi privitak koji dobrovoljno dostavite. Te se informacije upotrebljavaju samo za rješavanje vašeg zahtjeva, a ne za oglašavanje ili marketing. Nemojte slati lozinke računa, lozinke za plaćanje ni pune brojeve kartica.","Ovo web-mjesto ne postavlja kolačiće za oglašavanje ili analitiku i ne uključuje analitiku prometa ni skripte za praćenje."]},{"title":"6. Čuvanje i brisanje","paragraphs":["Podatke na uređaju izbrišite deinstaliranjem aplikacije. Na Androidu možete upotrijebiti i mogućnost sustava Izbriši podatke.","Evidenciju kupnji u trgovini vodi Apple ili Google. Prava koja se mogu vratiti ponovno se potvrđuju prema pravilima trgovine.","Poruke e-pošte za podršku čuvaju se onoliko dugo koliko je potrebno za rješavanje zahtjeva i ispunjavanje nužnih zahtjeva za vođenje evidencije. Možete nam poslati poruku e-pošte i zatražiti brisanje korespondencije s podrškom koju još čuvamo."]},{"title":"7. Sigurnost podataka","paragraphs":["Aplikacija upotrebljava obradu na uređaju, minimalna dopuštenja i službene postupke kupnje u trgovini aplikacija kako bi smanjila nepotrebne prijenose podataka. Poruke e-pošte za podršku upotrebljavaju se samo za rješavanje pristiglih zahtjeva, uz razumne zaštitne mjere primjerene prirodi informacija.","Ni za jedan uređaj, mrežu ili način elektroničke pohrane ne može se jamčiti potpuna sigurnost. U poruku e-pošte za podršku nemojte uključivati nepovezane osjetljive informacije."]},{"title":"8. Djeca i tinejdžeri","paragraphs":["Aplikacija ne zahtijeva račun i ne izrađuje profile djece ili drugih korisnika putem oglašavanja ili analitike ponašanja. Roditelj ili skrbnik koji vjeruje da je dijete putem poruke e-pošte za podršku dostavilo osobne podatke može nam se obratiti radi rješavanja tog pitanja."]},{"title":"9. Vaši izbori i prava","paragraphs":["Podacima na uređaju upravljate putem svojeg uređaja. Apple ili Google upravlja računima trgovine i evidencijom kupnji. Aplikacija ne može u vaše ime izmijeniti ili izbrisati evidenciju transakcija koju čuva trgovina aplikacija.","Ako se promijene prakse aplikacije u vezi s podacima, pravila platforme ili način smještaja web-mjesta, ažurirat ćemo ova Pravila i datum prikazan na stranici te pružiti dodatnu obavijest kada to zahtijevaju primjenjiva pravila.","Za pitanja o privatnosti, pošaljite e-poštu {email}"]}]},"terms":{"title":"Uvjeti korištenja","lead":"{appName} Uvjeti korištenja.","sections":[{"title":"1. Prihvaćanje ovih Uvjeta i pravila platforme","paragraphs":["Preuzimanjem, kupnjom ili korištenjem {appName} prihvaćate ove Uvjete i pravila koja se primjenjuju na vas u trgovini aplikacija u kojoj obavljate kupnju. Ako se ne slažete, nemojte nastaviti koristiti aplikaciju ili obavljati kupnju.","Ovi Uvjeti primjenjuju se na vaše preuzimanje, kupnju i upotrebu aplikacije. Verzije za iOS i iPadOS također podliježu"],"links":["appleEula"]},{"title":"2. Plaćeni proizvodi i cijene","paragraphs":["Prepoznavanje i uređivanje nemaju ograničenje upotrebe. Samo izvoz obrađene slike zahtijeva važeći Premium pristup. Aplikacija nudi automatski obnovljive tjedne i mjesečne pretplate te jednokratnu doživotnu kupnju, bez besplatnog probnog razdoblja. Kupnje u App Storeu i Google Playu odvojene su i ne mogu se prenositi između platformi.","Stvarna cijena, valuta, porezi, obračunsko razdoblje i mogućnost kupnje određeni su informacijama koje se prikazuju i potvrđuju na zaslonu sustava za kupnju u trgovini App Store ili Google Play. Platforma za kupnju naplaćuje i upravlja plaćanjem putem vašeg računa trgovine. Aplikacija ne nudi besplatno probno razdoblje pretplate ni druge plaćene planove."]},{"title":"3. Automatsko obnavljanje i otkazivanje","paragraphs":["Tjedne i mjesečne pretplate automatski se obnavljaju i naplaćuju za obračunsko razdoblje prikazano na zaslonu sustava za kupnju sve dok ih ne otkažete putem platforme kupnje. Brisanjem aplikacije {appName} pretplata se ne otkazuje automatski. Osim ako platforma kupnje odobri povrat novca ili drugi način postupanja, nakon isključivanja automatskog obnavljanja možete nastaviti upotrebljavati pretplatu do kraja trenutačnog plaćenog razdoblja."],"links":["appleCancel","googleManage"]},{"title":"4. Kupnje, vraćanje kupnji i povrati novca","paragraphs":["Kupnje i vraćanje kupnji obavljaju se putem službene trgovine Apple ili Google. Pravo se dodjeljuje tek nakon što trgovina potvrdi valjanu transakciju. Otkazane, neuspjele ili transakcije na čekanju ne daju pravo prije uspješne potvrde. Vraćanjem kupnji mogu se vratiti doživotni pristup i trenutačno aktivna pretplata. Kupnje u trgovinama App Store i Google Play odvojene su i ne mogu se vratiti ni prenijeti između platformi.","Povrate novca obrađuje trgovina aplikacija koja je dovršila transakciju, u skladu sa svojim pravilima, regijom kupnje i mjerodavnim pravom. Odgovarajuće pravo uklanja se nakon što trgovina potvrdi povrat novca, opoziv, istek pretplate ili nevaljanu transakciju."],"links":["appleRefund","googleRefund"]},{"title":"5. Izvanmrežna upotreba i dostupnost","paragraphs":["Odabir slike, OCR, otkrivanje osjetljivog sadržaja, uređivanje i izvoz odvijaju se na uređaju. Aplikacija ne nudi prepoznavanje slika u oblaku, sinkronizaciju u oblaku ni račune. Pri izvozu stvara se nova slika i uklanjaju se privatni metapodaci koji se mogu izbrisati. Privremene radne datoteke brišu se nakon uspješnog spremanja, odustajanja od uređivanja ili završetka sesije; ako spremanje ne uspije, stanje potrebno za ponovni pokušaj može se zadržati."]},{"title":"6. Prihvatljiva upotreba i intelektualno vlasništvo","paragraphs":["Ne smijete upotrebljavati aplikaciju za nezakonite aktivnosti; zaobilaziti provjeru kupnje; oštetiti aplikaciju; distribuirati zlonamjerni kôd; kopirati ili distribuirati aplikaciju bez dopuštenja; niti kršiti prava na sadržaj aplikacije ili intelektualno vlasništvo druge osobe.","Aplikaciju u bilo kojem trenutku možete prestati upotrebljavati i deinstalirati. Možemo objaviti ažuriranja radi otklanjanja problema, podrške operacijskim sustavima, poboljšanja stabilnosti ili ispunjavanja zahtjeva platforme. Problemi s uređajem, sustavom, mrežom ili uslugom trgovine mogu privremeno onemogućiti neke značajke.","U mjeri dopuštenoj mjerodavnim pravom, aplikacija se pruža prema dostupnosti. Ovi Uvjeti ne isključuju odgovornost koja se zakonski ne može isključiti niti ograničavaju obvezna prava potrošača koja vam pripadaju.","Ako se promijene značajke proizvoda, načini plaćanja, pravila platforme ili mjerodavno pravo, možemo ažurirati ove Uvjete i datum prikazan na stranici. Ako promjena znatno utječe na prava korisnika, pružit ćemo dodatnu obavijest kako je propisano.","Za pitanja o ovim Uvjetima, kupnjama ili korištenju aplikacije, pošaljite e-poštu {email}"]}]},"support":{"title":"Podrška","lead":"Najprije pogledajte česta pitanja u nastavku. Ako se problem nastavi, obratite nam se putem adrese e-pošte za podršku.","emailTitle":"{appName} e-pošta za podršku","emailLead":"Najprije pogledajte česta pitanja u nastavku. Ako se problem nastavi, obratite nam se putem adrese e-pošte za podršku.","beforeEmail":{"title":"Što uključiti u poruku e-pošte","paragraphs":["Za problem s kupnjom možete navesti broj narudžbe iz trgovine aplikacija, ali nemojte slati lozinku računa, lozinku za plaćanje ni potpune podatke kartice."],"bullets":["vašu platformu, model uređaja, verziju operacijskog sustava i verziju aplikacije;","što ste radili prije problema, što ste očekivali i što se zapravo dogodilo; i","ako je potrebno, snimka zaslona ili snimka zaslona sa skrivenim privatnim podacima."]},"faqs":[{"question":"Prenose li se slike na poslužitelj?","answer":"Odabir slike, OCR, otkrivanje osjetljivog sadržaja, uređivanje i izvoz odvijaju se na uređaju. Aplikacija ne nudi prepoznavanje slika u oblaku, sinkronizaciju u oblaku ni račune. Pri izvozu stvara se nova slika i uklanjaju se privatni metapodaci koji se mogu izbrisati. Privremene radne datoteke brišu se nakon uspješnog spremanja, odustajanja od uređivanja ili završetka sesije; ako spremanje ne uspije, stanje potrebno za ponovni pokušaj može se zadržati."},{"question":"Dopuštenja, oglašavanje i praćenje","answer":"Pristup fotografijama koristi se samo za prikaz i obradu slika koje dopustite. Kamera se koristi samo kada odaberete snimanje fotografije u aplikaciji. Dopuštenje za spremanje u fototeku traži se samo kada potvrdite izvoz s važećim Premium pristupom. Aplikacija ne traži lokaciju, kontakte, mikrofon, Bluetooth ni obavijesti."},{"question":"Plaćeni proizvodi i cijene","answer":"Prepoznavanje i uređivanje nemaju ograničenje upotrebe. Samo izvoz obrađene slike zahtijeva važeći Premium pristup. Aplikacija nudi automatski obnovljive tjedne i mjesečne pretplate te jednokratnu doživotnu kupnju, bez besplatnog probnog razdoblja. Kupnje u App Storeu i Google Playu odvojene su i ne mogu se prenositi između platformi."},{"question":"Spremanje i formati slika","answer":"Ako spremanje ne uspije, provjerite slobodan prostor, dopuštenje za spremanje u fototeku i može li se izvorna slika još pročitati, pa pokušajte ponovno. Aplikacija obrađuje jednu statičnu sliku odjednom i podržava većinu uobičajenih formata; neki ovise o uređaju i verziji sustava. Video, PDF, RAW/DNG i skupna obrada trenutačno nisu podržani."},{"question":"Kako promijeniti jezik?","answer":"Aplikacija podržava 40 jezika, a jezik se može promijeniti u postavkama aplikacije. Ako prikaz nije ispravan, pošaljite poruku e-pošte s jezikom uređaja i jezikom odabranim u aplikaciji."},{"question":"Vraćanje kupnji, otkazivanje i povrati novca","answer":"Kupnje i vraćanje kupnji obavljaju se putem službene trgovine Apple ili Google. Pravo se dodjeljuje tek nakon što trgovina potvrdi valjanu transakciju. Otkazane, neuspjele ili transakcije na čekanju ne daju pravo prije uspješne potvrde. Vraćanjem kupnji mogu se vratiti doživotni pristup i trenutačno aktivna pretplata. Kupnje u trgovinama App Store i Google Play odvojene su i ne mogu se vratiti ni prenijeti između platformi."},{"question":"Privatnost i brisanje podataka","answer":"Podatke na uređaju izbrišite deinstaliranjem aplikacije. Na Androidu možete upotrijebiti i mogućnost sustava Izbriši podatke. Evidenciju kupnji u trgovini vodi Apple ili Google. Prava koja se mogu vratiti ponovno se potvrđuju prema pravilima trgovine. Poruke e-pošte za podršku čuvaju se onoliko dugo koliko je potrebno za rješavanje zahtjeva i ispunjavanje nužnih zahtjeva za vođenje evidencije. Možete nam poslati poruku e-pošte i zatražiti brisanje korespondencije s podrškom koju još čuvamo."}],"officialHelpTitle":"Brza pomoć"}},"hu":{"linkLabels":{"appleEula":"Apple szabványos végfelhasználói licencszerződése (EULA)","appleCancel":"Apple-előfizetés lemondási útmutató","googleManage":"Google Play lemondási útmutató","appleRefund":"Visszatérítés kérése az Apple-től","googleRefund":"Google Play visszatérítési információk"},"nav":{"privacy":"Adatvédelmi irányelvek","terms":"Felhasználási feltételek","support":"Támogatás","language":"Nyelv","chooseLanguage":"Kijelzőnyelv kiválasztása","navigationLabel":"Elsődleges navigáció"},"home":{"eyebrow":"{appName} · Privacy first","title":"A képei nem kerülnek feltöltésre a szervereinkre.","lead":"A képkiválasztás, az OCR, az érzékeny tartalom felismerése, a szerkesztés és az exportálás az eszközön történik. Az alkalmazás nem kínál felhőalapú képfelismerést, felhőszinkronizálást vagy fiókokat. Exportáláskor új kép készül, és a törölhető privát metaadatok eltávolításra kerülnek. Az ideiglenes munkafájlok sikeres mentés, a szerkesztés elvetése vagy a munkamenet vége után törlődnek; sikertelen mentéskor az újrapróbáláshoz szükséges állapot megmaradhat.","points":["Alkalmazásadatok","Fizetős termékek és árak","Támogatás"],"cards":[{"title":"Adatvédelmi irányelvek","description":"A képei nem kerülnek feltöltésre a szervereinkre.","action":"Adatvédelmi irányelvek"},{"title":"Felhasználási feltételek","description":"A felismerés és a szerkesztés használata nincs korlátozva. Csak a feldolgozott kép exportálásához kell érvényes Premium-hozzáférés. Automatikusan megújuló heti és havi előfizetés, valamint egyszeri, élethosszig tartó vásárlás érhető el, ingyenes próba nélkül. Az App Store- és Google Play-vásárlások különállók, és nem vihetők át a platformok között.","action":"Felhasználási feltételek"},{"title":"Segítségre van szüksége?","description":"Először nézd meg az alábbi gyakori kérdéseket. Ha a probléma megmarad, írj a támogatási e-mail-címre.","action":"Támogatás"}]},"footer":{"privacy":"Adatvédelmi irányelvek","terms":"Felhasználási feltételek","support":"Támogatás"},"privacy":{"title":"Adatvédelmi irányelvek","lead":"Ez a Szabályzat ismerteti, hogyan kezeli a {appName} az eszközön tárolt adatokat, az áruházi vásárlási információkat és a támogatási e-maileket.","sections":[{"title":"1. Hatály és elérhetőség","paragraphs":["Ez a Szabályzat a {appName} iOS-, iPadOS- és Android-alkalmazásra, valamint erre az adatvédelmi, feltétel- és támogatási webhelyre vonatkozik.","Adatvédelmi kérdésekkel kapcsolatban írjon e-mailt {email}"]},{"title":"2. Alkalmazásadatok","callout":{"title":"A képei nem kerülnek feltöltésre a szervereinkre.","body":"A képkiválasztás, az OCR, az érzékeny tartalom felismerése, a szerkesztés és az exportálás az eszközön történik. Az alkalmazás nem kínál felhőalapú képfelismerést, felhőszinkronizálást vagy fiókokat. Exportáláskor új kép készül, és a törölhető privát metaadatok eltávolításra kerülnek. Az ideiglenes munkafájlok sikeres mentés, a szerkesztés elvetése vagy a munkamenet vége után törlődnek; sikertelen mentéskor az újrapróbáláshoz szükséges állapot megmaradhat."},"paragraphs":[]},{"title":"3. Engedélyek, reklám és követés","paragraphs":["A fotóhozzáférés csak az Ön által engedélyezett képek megjelenítésére és feldolgozására szolgál. A kamera csak akkor használatos, ha az alkalmazásban fényképet készít. A fotókönyvtárba mentési engedélyt csak érvényes Premium-hozzáféréssel jóváhagyott exportáláskor kérjük. Az alkalmazás nem kér hely-, névjegy-, mikrofon-, Bluetooth- vagy értesítési engedélyt.","Nem használ reklámazonosítót, és nem épít be külső reklám-, analitikai, attribúciós vagy hibajelentő SDK-t.","Az alkalmazás nem épít be külső hibajelentő eszközt. Az eszköz- és áruházbeállításoktól függően az Apple vagy a Google saját adatvédelmi szabályai szerint feldolgozhat rendszerdiagnosztikai adatokat, és műszaki információkat adhat hibák vagy teljesítményproblémák vizsgálatához."]},{"title":"4. Alkalmazásbolti szolgáltatások és hálózati hozzáférés","paragraphs":["Az alkalmazás az Apple StoreKit vagy a Google Play Billing használatával tölti be a termékeket, jeleníti meg az áruház lokalizált árait, végzi és állítja vissza a vásárlásokat, kezeli az előfizetéseket és erősíti meg a jogosultságokat. A hálózatot csak ezekhez a hivatalos Apple- vagy Google-áruházi funkciókhoz használja.","Az áruházi fiókokért, fizetésekért, számlázásért, tranzakciókért, visszatérítésekért és előfizetési szolgáltatásokért az Apple vagy a Google felel. Az alkalmazás csak a termékek és jogosultságok megerősítéséhez szükséges áruházi információkat dolgozza fel, teljes fizetési adatokat nem kap és nem tárol."]},{"title":"5. Támogatási e-mailek és webhely","paragraphs":["Az alkalmazás nem olvassa automatikusan az e-mail-adataidat. A támogatási csatorna csak támogatási e-mail küldésekor kapja meg az e-mail-címedet, üzenetedet, valamint az önként csatolt képernyőképeket, képernyőfelvételeket, rendelési számot vagy más mellékleteket. Ezeket kizárólag a kérés kezelésére használjuk, reklámra vagy marketingre nem. Ne küldj fiók- vagy fizetési jelszót, illetve teljes kártyaszámot.","Ez a webhely nem helyez el reklám- vagy analitikai cookie-kat, és nem tartalmaz forgalomelemző vagy követő szkriptet."]},{"title":"6. Megőrzés és törlés","paragraphs":["Az eszközön tárolt adatok törléséhez távolítsd el az alkalmazást. Androidon a rendszer „Adatok törlése” lehetőségét is használhatod.","A vásárlási nyilvántartást az Apple vagy a Google kezeli. A visszaállítható jogosultságokat az áruház szabályai szerint újra meg kell erősíteni.","A támogatási e-maileket a kérés kezeléséhez és a szükséges nyilvántartási kötelezettségek teljesítéséhez szükséges ideig őrizzük. E-mailben kérheted a még tárolt támogatási levelezés törlését."]},{"title":"7. Adatbiztonság","paragraphs":["Az alkalmazás eszközön történő feldolgozást, minimális engedélyeket és hivatalos áruházi vásárlási folyamatokat használ a szükségtelen adatátvitel csökkentésére. A támogatási e-maileket csak a beérkező kérések kezelésére használjuk, az információ jellegének megfelelő észszerű védelemmel.","Egyetlen eszköz, hálózat vagy elektronikus tárolási módszer teljes biztonsága sem garantálható. Ne adj meg a kérdéshez nem kapcsolódó érzékeny információt támogatási e-mailben."]},{"title":"8. Gyermekek és fiatalok","paragraphs":["Az alkalmazás nem igényel fiókot, és reklám vagy viselkedéselemzés útján nem készít profilt gyermekekről vagy más felhasználókról. Ha egy szülő vagy gondviselő úgy véli, hogy egy gyermek támogatási e-mailben személyes adatot küldött, kapcsolatba léphet velünk az ügy rendezéséhez."]},{"title":"9. Választási lehetőségeid és jogaid","paragraphs":["A helyi adatokat az eszközön kezeled. Az áruházi fiókokat és vásárlási nyilvántartást az Apple vagy a Google kezeli. Az alkalmazás nem módosíthatja vagy törölheti helyetted az áruház által tárolt tranzakciós adatokat.","Ha az alkalmazás adatkezelése, a platformszabályok vagy a webhely tárhelye megváltozik, frissítjük ezt a Szabályzatot és az oldalon szereplő dátumot, és további értesítést adunk, ha ezt az alkalmazandó szabályok előírják.","Adatvédelmi kérdésekkel kapcsolatban írjon e-mailt {email}"]}]},"terms":{"title":"Felhasználási feltételek","lead":"{appName} Felhasználási feltételek.","sections":[{"title":"1. A Felhasználási Feltételek és a platformszabályok elfogadása","paragraphs":["A {appName} letöltésével, megvásárlásával vagy használatával Ön elfogadja ezeket a Felhasználási Feltételeket és az alkalmazásboltban érvényes szabályokat, ahol a vásárlást végzi. Ha nem ért egyet, ne folytassa az alkalmazás használatát, és ne vásároljon.","Ezek a Feltételek az alkalmazás letöltésére, megvásárlására és használatára vonatkoznak. Az iOS- és iPadOS-verziókra az"],"links":["appleEula"]},{"title":"2. Fizetős termékek és árak","paragraphs":["A felismerés és a szerkesztés használata nincs korlátozva. Csak a feldolgozott kép exportálásához kell érvényes Premium-hozzáférés. Automatikusan megújuló heti és havi előfizetés, valamint egyszeri, élethosszig tartó vásárlás érhető el, ingyenes próba nélkül. Az App Store- és Google Play-vásárlások különállók, és nem vihetők át a platformok között.","A tényleges ár, pénznem, adók, számlázási időszak és vásárlási jogosultság az App Store vagy Google Play rendszer-vásárlási képernyőjén megjelenő és általad jóváhagyott információ. A platform az áruházi fiókodon keresztül számítja fel és kezeli a fizetést. Az alkalmazás nem kínál ingyenes előfizetési próbaidőt vagy más fizetős csomagot."]},{"title":"3. Automatikus megújítás és lemondás","paragraphs":["A heti és havi előfizetések automatikusan megújulnak, és a vásárlási képernyőn jelzett időszakra terhelik őket, amíg a vásárlási platformon le nem mondod. A {appName} törlése nem mondja le automatikusan az előfizetést. Ha a platform nem ad visszatérítést vagy más elbírálást, a megújítás kikapcsolása után a már kifizetett időszak végéig használhatod az előfizetést."],"links":["appleCancel","googleManage"]},{"title":"4. Vásárlások, visszaállítás és visszatérítések","paragraphs":["A vásárlások és visszaállításuk a hivatalos Apple- vagy Google-áruházon keresztül történnek. Jogosultság csak az érvényes tranzakció áruházi megerősítése után jár. A megszakított, sikertelen vagy függő tranzakciók a megerősítésig nem adnak jogosultságot. A visszaállítás helyreállíthatja az élethosszig tartó hozzáférést és az aktív előfizetést. Az App Store- és Google Play-vásárlások különállók, és nem állíthatók vissza vagy vihetők át platformok között.","A visszatérítést a tranzakciót teljesítő áruház kezeli saját szabályai, a vásárlási régió és az alkalmazandó jog alapján. A jogosultság megszűnik, miután az áruház visszatérítést, visszavonást, előfizetés-lejáratot vagy érvénytelen tranzakciót erősít meg."],"links":["appleRefund","googleRefund"]},{"title":"5. Offline használat és elérhetőség","paragraphs":["A képkiválasztás, az OCR, az érzékeny tartalom felismerése, a szerkesztés és az exportálás az eszközön történik. Az alkalmazás nem kínál felhőalapú képfelismerést, felhőszinkronizálást vagy fiókokat. Exportáláskor új kép készül, és a törölhető privát metaadatok eltávolításra kerülnek. Az ideiglenes munkafájlok sikeres mentés, a szerkesztés elvetése vagy a munkamenet vége után törlődnek; sikertelen mentéskor az újrapróbáláshoz szükséges állapot megmaradhat."]},{"title":"6. Elfogadható használat és szellemi tulajdon","paragraphs":["Tilos az alkalmazást jogellenes tevékenységre használni, a vásárlás ellenőrzését megkerülni, az alkalmazást károsítani, rosszindulatú kódot terjeszteni, engedély nélkül másolni vagy terjeszteni, illetve az alkalmazás tartalmához vagy mások szellemi tulajdonához fűződő jogokat megsérteni.","Bármikor abbahagyhatod a használatot és eltávolíthatod az alkalmazást. Frissítéseket adhatunk ki problémák javítására, rendszerek támogatására, a stabilitás növelésére vagy platformkövetelmények teljesítésére. Eszköz-, rendszer-, hálózati vagy áruházi problémák átmenetileg elérhetetlenné tehetnek egyes funkciókat.","Az alkalmazandó jog által megengedett mértékben az alkalmazás a rendelkezésre álló állapotában érhető el. E Feltételek nem zárnak ki jogszerűen ki nem zárható felelősséget, és nem korlátozzák a kötelező fogyasztói jogokat.","Ha a funkciók, fizetési módok, platformszabályok vagy jogszabályok változnak, frissíthetjük e Feltételeket és az oldal dátumát. Ha egy változás lényegesen érinti a felhasználói jogokat, megadjuk a szükséges további értesítést.","A jelen Feltételekkel, vásárlásokkal vagy az alkalmazás használatával kapcsolatos kérdéseivel írjon e-mailt a következő címre: {email}"]}]},"support":{"title":"Támogatás","lead":"Először nézd meg az alábbi gyakori kérdéseket. Ha a probléma megmarad, írj a támogatási e-mail-címre.","emailTitle":"{appName} támogatási e-mail cím","emailLead":"Először nézd meg az alábbi gyakori kérdéseket. Ha a probléma megmarad, írj a támogatási e-mail-címre.","beforeEmail":{"title":"Mit adj meg az e-mailben","paragraphs":["Vásárlási problémánál megadhatod az áruházi rendelési számot, de ne küldd el a fiók- vagy fizetési jelszavadat, illetve teljes kártyaadataidat."],"bullets":["a platformot, eszközmodellt, rendszerverziót és alkalmazásverziót;","a probléma előtti lépéseket, a várt és tényleges eredményt; és","szükség esetén képernyőkép vagy képernyőfelvétel, amelyen személyes adatok vannak elrejtve."]},"faqs":[{"question":"Feltöltődnek a képek egy szerverre?","answer":"A képkiválasztás, az OCR, az érzékeny tartalom felismerése, a szerkesztés és az exportálás az eszközön történik. Az alkalmazás nem kínál felhőalapú képfelismerést, felhőszinkronizálást vagy fiókokat. Exportáláskor új kép készül, és a törölhető privát metaadatok eltávolításra kerülnek. Az ideiglenes munkafájlok sikeres mentés, a szerkesztés elvetése vagy a munkamenet vége után törlődnek; sikertelen mentéskor az újrapróbáláshoz szükséges állapot megmaradhat."},{"question":"Engedélyek, reklám és követés","answer":"A fotóhozzáférés csak az Ön által engedélyezett képek megjelenítésére és feldolgozására szolgál. A kamera csak akkor használatos, ha az alkalmazásban fényképet készít. A fotókönyvtárba mentési engedélyt csak érvényes Premium-hozzáféréssel jóváhagyott exportáláskor kérjük. Az alkalmazás nem kér hely-, névjegy-, mikrofon-, Bluetooth- vagy értesítési engedélyt."},{"question":"Fizetős termékek és árak","answer":"A felismerés és a szerkesztés használata nincs korlátozva. Csak a feldolgozott kép exportálásához kell érvényes Premium-hozzáférés. Automatikusan megújuló heti és havi előfizetés, valamint egyszeri, élethosszig tartó vásárlás érhető el, ingyenes próba nélkül. Az App Store- és Google Play-vásárlások különállók, és nem vihetők át a platformok között."},{"question":"Mentés és képformátumok","answer":"Sikertelen mentés esetén ellenőrizze a szabad tárhelyet, a fotókönyvtárba mentési engedélyt és az eredeti kép olvashatóságát, majd próbálja újra. Az alkalmazás egyszerre egy állóképet dolgoz fel, és a legtöbb gyakori formátumot támogatja; egyes formátumok az eszköztől és a rendszerverziótól függenek. Videó, PDF, RAW/DNG és kötegelt feldolgozás jelenleg nem támogatott."},{"question":"Hogyan változtathatom meg a nyelvet?","answer":"Az alkalmazás 40 nyelvet támogat, amelyek a beállításokban válthatók. Hibás megjelenítés esetén e-mailben add meg az eszköz nyelvét és az alkalmazásban kiválasztott nyelvet."},{"question":"Visszaállítás, lemondás és visszatérítések","answer":"A vásárlások és visszaállításuk a hivatalos Apple- vagy Google-áruházon keresztül történnek. Jogosultság csak az érvényes tranzakció áruházi megerősítése után jár. A megszakított, sikertelen vagy függő tranzakciók a megerősítésig nem adnak jogosultságot. A visszaállítás helyreállíthatja az élethosszig tartó hozzáférést és az aktív előfizetést. Az App Store- és Google Play-vásárlások különállók, és nem állíthatók vissza vagy vihetők át platformok között."},{"question":"Adatvédelem és adattörlés","answer":"Az eszközön tárolt adatok törléséhez távolítsd el az alkalmazást. Androidon a rendszer „Adatok törlése” lehetőségét is használhatod. A vásárlási nyilvántartást az Apple vagy a Google kezeli. A visszaállítható jogosultságokat az áruház szabályai szerint újra meg kell erősíteni. A támogatási e-maileket a kérés kezeléséhez és a szükséges nyilvántartási kötelezettségek teljesítéséhez szükséges ideig őrizzük. E-mailben kérheted a még tárolt támogatási levelezés törlését."}],"officialHelpTitle":"Gyors segítség"}},"id":{"linkLabels":{"appleEula":"Perjanjian Lisensi Pengguna Akhir Standar (EULA) Apple","appleCancel":"Petunjuk pembatalan langganan Apple","googleManage":"Petunjuk pembatalan Google Play","appleRefund":"Ajukan pengembalian dana dari Apple","googleRefund":"Informasi pengembalian dana Google Play"},"nav":{"privacy":"Kebijakan Privasi","terms":"Syarat Penggunaan","support":"Dukungan","language":"Bahasa","chooseLanguage":"Pilih bahasa tampilan","navigationLabel":"Navigasi utama"},"home":{"eyebrow":"{appName} · Privacy first","title":"Gambar Anda tidak diunggah ke server kami.","lead":"Pemilihan gambar, OCR, deteksi konten sensitif, pengeditan, dan ekspor dilakukan di perangkat. Aplikasi tidak menyediakan pengenalan gambar cloud, sinkronisasi cloud, atau akun. Saat mengekspor, gambar baru dibuat dan metadata privasi yang dapat dihapus dibersihkan. File kerja sementara dihapus setelah penyimpanan berhasil, saat pengeditan dibatalkan, atau ketika sesi berakhir; jika penyimpanan gagal, status yang diperlukan dapat disimpan untuk mencoba lagi.","points":["Data aplikasi","Produk berbayar dan harga","Dukungan"],"cards":[{"title":"Kebijakan Privasi","description":"Gambar Anda tidak diunggah ke server kami.","action":"Kebijakan Privasi"},{"title":"Syarat Penggunaan","description":"Pengenalan dan pengeditan tidak memiliki batas penggunaan. Hanya ekspor gambar yang telah diproses yang memerlukan akses Premium valid. Aplikasi menawarkan langganan mingguan dan bulanan yang diperpanjang otomatis serta pembelian seumur hidup satu kali, tanpa uji coba gratis. Pembelian App Store dan Google Play terpisah dan tidak dapat dipindahkan antarplatform.","action":"Syarat Penggunaan"},{"title":"Butuh bantuan?","description":"Mulailah dengan pertanyaan umum di bawah ini. Jika masalah tetap terjadi, hubungi kami melalui alamat email dukungan.","action":"Dukungan"}]},"footer":{"privacy":"Kebijakan Privasi","terms":"Syarat Penggunaan","support":"Dukungan"},"privacy":{"title":"Kebijakan Privasi","lead":"Kebijakan ini menjelaskan cara {appName} menangani data di perangkat, informasi pembelian toko aplikasi, dan email dukungan.","sections":[{"title":"1. Lingkup dan kontak","paragraphs":["Kebijakan ini berlaku untuk aplikasi {appName} di iOS, iPadOS, dan Android, serta situs web privasi, ketentuan, dan dukungan ini.","Untuk pertanyaan terkait privasi, kirim email. {email}"]},{"title":"2. Data aplikasi","callout":{"title":"Gambar Anda tidak diunggah ke server kami.","body":"Pemilihan gambar, OCR, deteksi konten sensitif, pengeditan, dan ekspor dilakukan di perangkat. Aplikasi tidak menyediakan pengenalan gambar cloud, sinkronisasi cloud, atau akun. Saat mengekspor, gambar baru dibuat dan metadata privasi yang dapat dihapus dibersihkan. File kerja sementara dihapus setelah penyimpanan berhasil, saat pengeditan dibatalkan, atau ketika sesi berakhir; jika penyimpanan gagal, status yang diperlukan dapat disimpan untuk mencoba lagi."},"paragraphs":[]},{"title":"3. Izin, iklan, dan pelacakan","paragraphs":["Akses foto hanya digunakan untuk menampilkan dan memproses gambar yang Anda izinkan. Kamera hanya digunakan saat Anda memilih mengambil foto di aplikasi. Izin menyimpan ke galeri hanya diminta saat Anda mengonfirmasi ekspor dengan akses Premium yang valid. Aplikasi tidak meminta lokasi, kontak, mikrofon, Bluetooth, atau notifikasi.","Aplikasi tidak menggunakan ID iklan atau mengintegrasikan SDK pihak ketiga untuk iklan, analitik, atribusi, atau pelaporan kerusakan.","Aplikasi tidak mengintegrasikan alat pelaporan kerusakan pihak ketiga. Bergantung pada pengaturan perangkat dan toko Anda, Apple atau Google dapat memproses informasi diagnostik sistem berdasarkan aturan privasi masing-masing dan menyediakan informasi teknis yang digunakan untuk menyelidiki kerusakan atau masalah performa."]},{"title":"4. Layanan toko aplikasi dan akses jaringan","paragraphs":["Aplikasi menggunakan Apple StoreKit atau Google Play Billing untuk memuat produk, menampilkan harga lokal yang diberikan toko, menyelesaikan pembelian, memulihkan pembelian, mengelola langganan, dan mengonfirmasi hak akses. Akses jaringan hanya digunakan untuk fitur resmi toko Apple atau Google ini.","Apple atau Google bertanggung jawab atas akun toko, pembayaran, penagihan, transaksi, pengembalian dana, dan layanan langganan. Aplikasi hanya memproses informasi toko yang diperlukan untuk mengonfirmasi produk dan hak akses serta tidak menerima atau menyimpan kredensial pembayaran lengkap."]},{"title":"5. Email dukungan dan situs web","paragraphs":["Aplikasi tidak secara otomatis membaca informasi email Anda. Hanya jika Anda memilih untuk mengirim email dukungan, saluran dukungan akan menerima alamat email, pesan, dan tangkapan layar, rekaman layar, nomor pesanan, atau lampiran lain yang Anda berikan secara sukarela. Informasi ini hanya digunakan untuk menangani permintaan Anda dan tidak digunakan untuk iklan atau pemasaran. Jangan kirimkan kata sandi akun, kata sandi pembayaran, atau nomor kartu lengkap.","Situs web ini tidak memasang cookie iklan atau analitik dan tidak menyertakan analitik lalu lintas atau skrip pelacakan."]},{"title":"6. Penyimpanan dan penghapusan","paragraphs":["Hapus data di perangkat dengan mencopot pemasangan aplikasi. Di Android, Anda juga dapat menggunakan opsi Hapus data pada sistem.","Catatan pembelian toko dikelola oleh Apple atau Google. Hak akses yang dapat dipulihkan akan dikonfirmasi kembali berdasarkan aturan toko.","Email dukungan disimpan selama diperlukan untuk menangani permintaan dan memenuhi persyaratan pencatatan yang diperlukan. Anda dapat mengirim email kepada kami untuk meminta penghapusan korespondensi dukungan yang masih kami simpan."]},{"title":"7. Keamanan data","paragraphs":["Aplikasi menggunakan pemrosesan di perangkat, izin minimum, dan alur pembelian resmi toko aplikasi untuk mengurangi transfer data yang tidak perlu. Email dukungan hanya digunakan untuk menangani permintaan masuk, dengan perlindungan wajar yang sesuai dengan sifat informasinya.","Tidak ada perangkat, jaringan, atau metode penyimpanan elektronik yang dapat dijamin sepenuhnya aman. Jangan sertakan informasi sensitif yang tidak terkait dalam email dukungan."]},{"title":"8. Anak-anak dan remaja","paragraphs":["Aplikasi tidak mewajibkan akun dan tidak membuat profil anak-anak atau pengguna lain melalui iklan atau analitik perilaku. Orang tua atau wali yang meyakini bahwa seorang anak memberikan informasi pribadi melalui email dukungan dapat menghubungi kami agar masalah tersebut ditangani."]},{"title":"9. Pilihan dan hak Anda","paragraphs":["Anda mengelola data di perangkat melalui perangkat Anda. Apple atau Google mengelola akun toko dan catatan pembelian. Aplikasi tidak dapat mengubah atau menghapus catatan transaksi yang disimpan toko aplikasi atas nama Anda.","Jika praktik data aplikasi, aturan platform, atau pengaturan hosting situs web berubah, kami akan memperbarui Kebijakan ini dan tanggal yang ditampilkan di halaman ini serta memberikan pemberitahuan tambahan jika diwajibkan oleh aturan yang berlaku.","Untuk pertanyaan terkait privasi, kirim email. {email}"]}]},"terms":{"title":"Syarat Penggunaan","lead":"{appName} Ketentuan Penggunaan.","sections":[{"title":"1. Menerima Syarat dan ketentuan serta peraturan platform ini","paragraphs":["Dengan mengunduh, membeli, atau menggunakan {appName}, Anda menyetujui Syarat dan Ketentuan ini serta peraturan yang berlaku bagi Anda di toko aplikasi tempat Anda melakukan pembelian. Jika Anda tidak setuju, jangan lanjutkan menggunakan aplikasi atau melakukan pembelian.","Ketentuan ini berlaku atas pengunduhan, pembelian, dan penggunaan aplikasi oleh Anda. Versi iOS dan iPadOS juga tunduk pada"],"links":["appleEula"]},{"title":"2. Produk berbayar dan harga","paragraphs":["Pengenalan dan pengeditan tidak memiliki batas penggunaan. Hanya ekspor gambar yang telah diproses yang memerlukan akses Premium valid. Aplikasi menawarkan langganan mingguan dan bulanan yang diperpanjang otomatis serta pembelian seumur hidup satu kali, tanpa uji coba gratis. Pembelian App Store dan Google Play terpisah dan tidak dapat dipindahkan antarplatform.","Harga, mata uang, pajak, periode penagihan, dan kelayakan pembelian yang sebenarnya adalah informasi yang ditampilkan dan dikonfirmasi pada layar pembelian sistem App Store atau Google Play. Platform pembelian menagih dan mengelola pembayaran melalui akun toko Anda. Aplikasi tidak menawarkan uji coba gratis langganan atau paket berbayar lainnya."]},{"title":"3. Perpanjangan otomatis dan pembatalan","paragraphs":["Langganan mingguan dan bulanan diperpanjang otomatis serta ditagih untuk periode penagihan yang ditampilkan pada layar pembelian sistem sampai Anda membatalkannya melalui platform pembelian. Menghapus {appName} tidak membatalkan langganan secara otomatis. Kecuali platform pembelian memberikan pengembalian dana atau penanganan lain, Anda dapat terus menggunakan langganan hingga akhir periode berbayar saat ini setelah menonaktifkan perpanjangan otomatis."],"links":["appleCancel","googleManage"]},{"title":"4. Pembelian, pemulihan, dan pengembalian dana","paragraphs":["Pembelian dan pemulihan pembelian diselesaikan melalui toko resmi Apple atau Google. Hak akses hanya diberikan setelah toko mengonfirmasi transaksi yang valid. Transaksi yang dibatalkan, gagal, atau tertunda tidak memberikan hak akses sebelum berhasil dikonfirmasi. Pemulihan pembelian dapat memulihkan akses seumur hidup dan langganan yang saat ini aktif. Pembelian App Store dan Google Play terpisah serta tidak dapat dipulihkan atau dipindahkan lintas platform.","Pengembalian dana ditangani oleh toko aplikasi yang menyelesaikan transaksi berdasarkan aturannya, wilayah pembelian, dan hukum yang berlaku. Hak akses terkait akan dihapus setelah toko mengonfirmasi pengembalian dana, pencabutan, berakhirnya langganan, atau transaksi yang tidak valid."],"links":["appleRefund","googleRefund"]},{"title":"5. Penggunaan offline dan ketersediaan","paragraphs":["Pemilihan gambar, OCR, deteksi konten sensitif, pengeditan, dan ekspor dilakukan di perangkat. Aplikasi tidak menyediakan pengenalan gambar cloud, sinkronisasi cloud, atau akun. Saat mengekspor, gambar baru dibuat dan metadata privasi yang dapat dihapus dibersihkan. File kerja sementara dihapus setelah penyimpanan berhasil, saat pengeditan dibatalkan, atau ketika sesi berakhir; jika penyimpanan gagal, status yang diperlukan dapat disimpan untuk mencoba lagi."]},{"title":"6. Penggunaan yang diperbolehkan dan kekayaan intelektual","paragraphs":["Anda tidak boleh menggunakan aplikasi untuk aktivitas yang melanggar hukum; menghindari verifikasi pembelian; merusak aplikasi; menyebarkan kode berbahaya; menyalin atau menyebarkan aplikasi tanpa izin; atau melanggar hak atas konten aplikasi atau kekayaan intelektual orang lain.","Anda dapat berhenti menggunakan dan mencopot pemasangan aplikasi kapan saja. Kami dapat merilis pembaruan untuk memperbaiki masalah, mendukung sistem operasi, meningkatkan stabilitas, atau memenuhi persyaratan platform. Masalah perangkat, sistem, jaringan, atau layanan toko dapat membuat beberapa fitur tidak tersedia untuk sementara.","Sejauh diizinkan oleh hukum yang berlaku, aplikasi disediakan sesuai ketersediaan. Ketentuan ini tidak mengecualikan tanggung jawab yang secara hukum tidak dapat dikecualikan atau membatasi hak wajib konsumen yang Anda miliki.","Jika fitur produk, metode pembayaran, aturan platform, atau hukum yang berlaku berubah, kami dapat memperbarui Ketentuan ini dan tanggal yang ditampilkan di halaman. Jika perubahan berdampak besar pada hak pengguna, kami akan memberikan pemberitahuan tambahan sebagaimana diwajibkan.","Untuk pertanyaan mengenai Syarat dan Ketentuan ini, pembelian, atau penggunaan aplikasi, silakan kirim email. {email}"]}]},"support":{"title":"Dukungan","lead":"Mulailah dengan pertanyaan umum di bawah ini. Jika masalah tetap terjadi, hubungi kami melalui alamat email dukungan.","emailTitle":"email dukungan {appName}","emailLead":"Mulailah dengan pertanyaan umum di bawah ini. Jika masalah tetap terjadi, hubungi kami melalui alamat email dukungan.","beforeEmail":{"title":"Hal yang perlu disertakan dalam email","paragraphs":["Untuk masalah pembelian, Anda dapat menyertakan nomor pesanan toko aplikasi, tetapi jangan kirimkan kata sandi akun, kata sandi pembayaran, atau informasi kartu lengkap."],"bullets":["platform, model perangkat, versi sistem operasi, dan versi aplikasi Anda;","tindakan Anda sebelum masalah terjadi, hasil yang Anda harapkan, dan hal yang sebenarnya terjadi; serta","Jika diperlukan, tangkapan layar atau rekaman layar dengan informasi pribadi yang disembunyikan."]},"faqs":[{"question":"Apakah gambar diunggah ke server?","answer":"Pemilihan gambar, OCR, deteksi konten sensitif, pengeditan, dan ekspor dilakukan di perangkat. Aplikasi tidak menyediakan pengenalan gambar cloud, sinkronisasi cloud, atau akun. Saat mengekspor, gambar baru dibuat dan metadata privasi yang dapat dihapus dibersihkan. File kerja sementara dihapus setelah penyimpanan berhasil, saat pengeditan dibatalkan, atau ketika sesi berakhir; jika penyimpanan gagal, status yang diperlukan dapat disimpan untuk mencoba lagi."},{"question":"Izin, iklan, dan pelacakan","answer":"Akses foto hanya digunakan untuk menampilkan dan memproses gambar yang Anda izinkan. Kamera hanya digunakan saat Anda memilih mengambil foto di aplikasi. Izin menyimpan ke galeri hanya diminta saat Anda mengonfirmasi ekspor dengan akses Premium yang valid. Aplikasi tidak meminta lokasi, kontak, mikrofon, Bluetooth, atau notifikasi."},{"question":"Produk berbayar dan harga","answer":"Pengenalan dan pengeditan tidak memiliki batas penggunaan. Hanya ekspor gambar yang telah diproses yang memerlukan akses Premium valid. Aplikasi menawarkan langganan mingguan dan bulanan yang diperpanjang otomatis serta pembelian seumur hidup satu kali, tanpa uji coba gratis. Pembelian App Store dan Google Play terpisah dan tidak dapat dipindahkan antarplatform."},{"question":"Penyimpanan dan format gambar","answer":"Jika penyimpanan gagal, periksa ruang kosong, izin menyimpan ke galeri, dan apakah gambar asli masih dapat dibaca, lalu coba lagi. Aplikasi memproses satu gambar diam pada satu waktu dan mendukung sebagian besar format umum; beberapa bergantung pada perangkat dan versi sistem. Video, PDF, RAW/DNG, dan pemrosesan batch belum didukung."},{"question":"Bagaimana cara mengubah bahasa?","answer":"Aplikasi mendukung 40 bahasa dan bahasa dapat diubah di pengaturan aplikasi. Jika tampilan tidak benar, kirimkan bahasa perangkat dan bahasa yang dipilih di aplikasi melalui email."},{"question":"Pemulihan, pembatalan, dan pengembalian dana","answer":"Pembelian dan pemulihan pembelian diselesaikan melalui toko resmi Apple atau Google. Hak akses hanya diberikan setelah toko mengonfirmasi transaksi yang valid. Transaksi yang dibatalkan, gagal, atau tertunda tidak memberikan hak akses sebelum berhasil dikonfirmasi. Pemulihan pembelian dapat memulihkan akses seumur hidup dan langganan yang saat ini aktif. Pembelian App Store dan Google Play terpisah serta tidak dapat dipulihkan atau dipindahkan lintas platform."},{"question":"Privasi dan penghapusan data","answer":"Hapus data di perangkat dengan mencopot pemasangan aplikasi. Di Android, Anda juga dapat menggunakan opsi Hapus data pada sistem. Catatan pembelian toko dikelola oleh Apple atau Google. Hak akses yang dapat dipulihkan akan dikonfirmasi kembali berdasarkan aturan toko. Email dukungan disimpan selama diperlukan untuk menangani permintaan dan memenuhi persyaratan pencatatan yang diperlukan. Anda dapat mengirim email kepada kami untuk meminta penghapusan korespondensi dukungan yang masih kami simpan."}],"officialHelpTitle":"Bantuan cepat"}},"it":{"linkLabels":{"appleEula":"Contratto di licenza standard con l’utente finale di Apple (EULA)","appleCancel":"Istruzioni per la cancellazione dell'abbonamento Apple","googleManage":"Istruzioni per annullare su Google Play","appleRefund":"Richiedi un rimborso ad Apple","googleRefund":"Informazioni sui rimborsi Google Play"},"nav":{"privacy":"politica sulla riservatezza","terms":"Termini di utilizzo","support":"Assistenza","language":"Lingua","chooseLanguage":"Seleziona la lingua di visualizzazione","navigationLabel":"Navigazione principale"},"home":{"eyebrow":"{appName} · Privacy first","title":"Le tue immagini non vengono caricate sui nostri server.","lead":"La selezione delle immagini, l’OCR, il rilevamento dei contenuti sensibili, la modifica e l’esportazione avvengono sul dispositivo. L’app non offre riconoscimento immagini nel cloud, sincronizzazione cloud o account. Durante l’esportazione viene creata una nuova immagine e vengono rimossi i metadati privati eliminabili. I file di lavoro temporanei vengono cancellati dopo un salvataggio riuscito, quando abbandoni la modifica o al termine della sessione; dopo un errore di salvataggio può essere mantenuto lo stato necessario per riprovare.","points":["Dati dell’app","Prodotti a pagamento e prezzi","Assistenza"],"cards":[{"title":"politica sulla riservatezza","description":"Le tue immagini non vengono caricate sui nostri server.","action":"politica sulla riservatezza"},{"title":"Termini di utilizzo","description":"Il riconoscimento e la modifica non hanno limiti di utilizzo. Solo l’esportazione dell’immagine elaborata richiede un accesso Premium valido. L’app offre abbonamenti settimanali e mensili con rinnovo automatico e un acquisto una tantum a vita, senza prova gratuita. Gli acquisti su App Store e Google Play sono separati e non possono essere trasferiti tra piattaforme.","action":"Termini di utilizzo"},{"title":"Hai bisogno di aiuto?","description":"Consulta prima le domande frequenti riportate di seguito. Se il problema persiste, contattaci tramite l’indirizzo e-mail di assistenza.","action":"Assistenza"}]},"footer":{"privacy":"politica sulla riservatezza","terms":"Termini di utilizzo","support":"Assistenza"},"privacy":{"title":"politica sulla riservatezza","lead":"La presente Informativa spiega come {appName} gestisce i dati presenti sul dispositivo, le informazioni sugli acquisti dello store e le e-mail di assistenza.","sections":[{"title":"1. Ambito di applicazione e contatti","paragraphs":["La presente Informativa si applica all’app {appName} per iOS, iPadOS e Android e a questo sito dedicato a privacy, condizioni e assistenza.","Per domande sulla privacy, inviare un'e-mail {email}"]},{"title":"2. Dati dell’app","callout":{"title":"Le tue immagini non vengono caricate sui nostri server.","body":"La selezione delle immagini, l’OCR, il rilevamento dei contenuti sensibili, la modifica e l’esportazione avvengono sul dispositivo. L’app non offre riconoscimento immagini nel cloud, sincronizzazione cloud o account. Durante l’esportazione viene creata una nuova immagine e vengono rimossi i metadati privati eliminabili. I file di lavoro temporanei vengono cancellati dopo un salvataggio riuscito, quando abbandoni la modifica o al termine della sessione; dopo un errore di salvataggio può essere mantenuto lo stato necessario per riprovare."},"paragraphs":[]},{"title":"3. Autorizzazioni, pubblicità e tracciamento","paragraphs":["L’accesso alle foto serve solo a mostrare e trattare le immagini autorizzate. La fotocamera viene usata solo quando scegli di scattare una foto nell’app. Il permesso di salvare nella libreria foto viene richiesto solo quando confermi l’esportazione con un accesso Premium valido. L’app non richiede posizione, contatti, microfono, Bluetooth o notifiche.","Non usa identificatori pubblicitari né integra SDK di terze parti per pubblicità, analisi, attribuzione o segnalazione degli arresti anomali.","L’app non integra strumenti di terze parti per la segnalazione degli arresti anomali. In base alle impostazioni del dispositivo e dello store, Apple o Google può trattare informazioni diagnostiche di sistema secondo le proprie regole sulla privacy e fornire dati tecnici usati per esaminare arresti anomali o problemi di prestazioni."]},{"title":"4. Servizi dello store e accesso alla rete","paragraphs":["L’app usa Apple StoreKit o Google Play Billing per caricare i prodotti, mostrare i prezzi localizzati restituiti dallo store, completare e ripristinare gli acquisti, gestire gli abbonamenti e confermare i diritti. L’accesso alla rete viene usato esclusivamente per queste funzioni ufficiali Apple o Google.","Apple o Google è responsabile degli account dello store, dei pagamenti, della fatturazione, delle transazioni, dei rimborsi e dei servizi di abbonamento. L’app tratta solo le informazioni dello store necessarie a confermare prodotti e diritti e non riceve né conserva credenziali di pagamento complete."]},{"title":"5. E-mail di assistenza e sito","paragraphs":["L’app non legge automaticamente i dati della tua e-mail. Il canale di assistenza riceve indirizzo e-mail, messaggio ed eventuali schermate, registrazioni dello schermo, numeri d’ordine o altri allegati forniti volontariamente solo quando scegli di inviare un’e-mail di assistenza. Queste informazioni vengono usate esclusivamente per gestire la richiesta e non per pubblicità o marketing. Non inviare password di account o pagamento né numeri di carta completi.","Questo sito non imposta cookie pubblicitari o analitici e non include script di analisi del traffico o tracciamento."]},{"title":"6. Conservazione ed eliminazione","paragraphs":["Disinstalla l’app per eliminare i dati presenti sul dispositivo. Su Android puoi anche usare l’opzione di sistema «Cancella dati».","I registri degli acquisti sono gestiti da Apple o Google. I diritti ripristinabili vengono confermati nuovamente secondo le regole dello store.","Le e-mail di assistenza vengono conservate per il tempo necessario a gestire la richiesta e soddisfare gli indispensabili obblighi di registrazione. Puoi scriverci per chiedere l’eliminazione della corrispondenza di assistenza che conserviamo ancora."]},{"title":"7. Sicurezza dei dati","paragraphs":["L’app usa l’elaborazione sul dispositivo, autorizzazioni minime e procedure di acquisto ufficiali degli store per ridurre trasferimenti di dati non necessari. Le e-mail di assistenza servono solo a gestire le richieste ricevute, con misure ragionevoli adeguate alla natura delle informazioni.","Nessun dispositivo, rete o metodo di archiviazione elettronica può essere garantito come completamente sicuro. Non includere in un’e-mail di assistenza informazioni sensibili non pertinenti."]},{"title":"8. Bambini e adolescenti","paragraphs":["L’app non richiede un account e non crea profili di bambini o altri utenti mediante pubblicità o analisi comportamentale. Un genitore o tutore che ritenga che un minore abbia fornito informazioni personali in un’e-mail di assistenza può contattarci affinché la questione venga gestita."]},{"title":"9. Le tue scelte e i tuoi diritti","paragraphs":["Gestisci i dati locali tramite il dispositivo. Apple o Google gestisce gli account dello store e i registri degli acquisti. L’app non può modificare o eliminare per tuo conto i registri delle transazioni conservati da uno store.","Se cambiano le pratiche dell’app relative ai dati, le regole delle piattaforme o le modalità di hosting del sito, aggiorneremo la presente Informativa e la data indicata sulla pagina e forniremo ulteriori avvisi quando richiesto dalle norme applicabili.","Per domande sulla privacy, inviare un'e-mail {email}"]}]},"terms":{"title":"Termini di utilizzo","lead":"Termini di utilizzo di {appName}.","sections":[{"title":"1. Accettazione dei presenti Termini e delle regole della piattaforma","paragraphs":["Scaricando, acquistando o utilizzando {appName}, accetti i presenti Termini e le regole applicabili nell'app store in cui effettui l'acquisto. Se non accetti, non continuare a utilizzare l'app né effettuare acquisti.","Le presenti Condizioni si applicano al download, all’acquisto e all’uso dell’app. Le versioni iOS e iPadOS sono inoltre soggette al"],"links":["appleEula"]},{"title":"2. Prodotti a pagamento e prezzi","paragraphs":["Il riconoscimento e la modifica non hanno limiti di utilizzo. Solo l’esportazione dell’immagine elaborata richiede un accesso Premium valido. L’app offre abbonamenti settimanali e mensili con rinnovo automatico e un acquisto una tantum a vita, senza prova gratuita. Gli acquisti su App Store e Google Play sono separati e non possono essere trasferiti tra piattaforme.","Il prezzo effettivo, la valuta, le imposte, il periodo di fatturazione e l’idoneità all’acquisto sono quelli mostrati e confermati nella schermata di acquisto di sistema dell’App Store o di Google Play. La piattaforma addebita e gestisce il pagamento tramite il tuo account dello store. L’app non offre una prova gratuita dell’abbonamento o altri piani a pagamento."]},{"title":"3. Rinnovo automatico e annullamento","paragraphs":["Gli abbonamenti settimanali e mensili si rinnovano automaticamente e vengono addebitati per il periodo mostrato nella schermata di acquisto fino all’annullamento tramite la piattaforma. Eliminare {appName} non annulla automaticamente un abbonamento. Salvo rimborso o altra gestione da parte della piattaforma, dopo aver disattivato il rinnovo automatico puoi continuare a usare l’abbonamento fino al termine del periodo già pagato."],"links":["appleCancel","googleManage"]},{"title":"4. Acquisti, ripristino e rimborsi","paragraphs":["Gli acquisti e il relativo ripristino avvengono tramite lo store ufficiale Apple o Google. Un diritto viene concesso solo dopo che lo store conferma una transazione valida. Le transazioni annullate, non riuscite o in sospeso non concedono diritti prima della conferma. Il ripristino può recuperare l’accesso a vita e un abbonamento attualmente attivo. Gli acquisti dell’App Store e di Google Play sono distinti e non possono essere ripristinati o trasferiti tra piattaforme.","I rimborsi sono gestiti dallo store che ha completato la transazione secondo le proprie regole, la regione di acquisto e la legge applicabile. Il diritto corrispondente viene rimosso dopo la conferma di un rimborso, una revoca, la scadenza dell’abbonamento o una transazione non valida."],"links":["appleRefund","googleRefund"]},{"title":"5. Uso offline e disponibilità","paragraphs":["La selezione delle immagini, l’OCR, il rilevamento dei contenuti sensibili, la modifica e l’esportazione avvengono sul dispositivo. L’app non offre riconoscimento immagini nel cloud, sincronizzazione cloud o account. Durante l’esportazione viene creata una nuova immagine e vengono rimossi i metadati privati eliminabili. I file di lavoro temporanei vengono cancellati dopo un salvataggio riuscito, quando abbandoni la modifica o al termine della sessione; dopo un errore di salvataggio può essere mantenuto lo stato necessario per riprovare."]},{"title":"6. Uso consentito e proprietà intellettuale","paragraphs":["Non devi usare l’app per attività illecite, aggirare la verifica degli acquisti, danneggiare l’app, distribuire codice dannoso, copiare o distribuire l’app senza autorizzazione né violare i diritti sui contenuti dell’app o la proprietà intellettuale altrui.","Puoi smettere di usare e disinstallare l’app in qualsiasi momento. Potremmo pubblicare aggiornamenti per correggere problemi, supportare sistemi operativi, migliorare la stabilità o rispettare i requisiti delle piattaforme. Problemi del dispositivo, sistema, rete o servizio dello store possono rendere temporaneamente indisponibili alcune funzioni.","Nella misura consentita dalla legge applicabile, l’app viene fornita secondo disponibilità. Le presenti Condizioni non escludono responsabilità che non possono essere escluse per legge e non limitano i diritti inderogabili dei consumatori.","Se cambiano le funzioni del prodotto, i metodi di pagamento, le regole delle piattaforme o la legge applicabile, potremmo aggiornare le presenti Condizioni e la data della pagina. Se una modifica incide sostanzialmente sui diritti degli utenti, forniremo l’ulteriore avviso richiesto.","Per domande relative a questi Termini, agli acquisti o all'utilizzo dell'app, inviare un'e-mail {email}"]}]},"support":{"title":"Assistenza","lead":"Consulta prima le domande frequenti riportate di seguito. Se il problema persiste, contattaci tramite l’indirizzo e-mail di assistenza.","emailTitle":"e-mail di supporto {appName}","emailLead":"Consulta prima le domande frequenti riportate di seguito. Se il problema persiste, contattaci tramite l’indirizzo e-mail di assistenza.","beforeEmail":{"title":"Informazioni da includere nell’e-mail","paragraphs":["Per un problema di acquisto puoi includere il numero d’ordine dello store, ma non inviare la password dell’account o di pagamento né i dati completi della carta."],"bullets":["piattaforma, modello del dispositivo, versione del sistema operativo e versione dell’app;","operazioni eseguite prima del problema, risultato previsto e risultato effettivo; e","Se necessario, è possibile fornire uno screenshot o una registrazione dello schermo con le informazioni private oscurate."]},"faqs":[{"question":"Le immagini vengono caricate su un server?","answer":"La selezione delle immagini, l’OCR, il rilevamento dei contenuti sensibili, la modifica e l’esportazione avvengono sul dispositivo. L’app non offre riconoscimento immagini nel cloud, sincronizzazione cloud o account. Durante l’esportazione viene creata una nuova immagine e vengono rimossi i metadati privati eliminabili. I file di lavoro temporanei vengono cancellati dopo un salvataggio riuscito, quando abbandoni la modifica o al termine della sessione; dopo un errore di salvataggio può essere mantenuto lo stato necessario per riprovare."},{"question":"Autorizzazioni, pubblicità e tracciamento","answer":"L’accesso alle foto serve solo a mostrare e trattare le immagini autorizzate. La fotocamera viene usata solo quando scegli di scattare una foto nell’app. Il permesso di salvare nella libreria foto viene richiesto solo quando confermi l’esportazione con un accesso Premium valido. L’app non richiede posizione, contatti, microfono, Bluetooth o notifiche."},{"question":"Prodotti a pagamento e prezzi","answer":"Il riconoscimento e la modifica non hanno limiti di utilizzo. Solo l’esportazione dell’immagine elaborata richiede un accesso Premium valido. L’app offre abbonamenti settimanali e mensili con rinnovo automatico e un acquisto una tantum a vita, senza prova gratuita. Gli acquisti su App Store e Google Play sono separati e non possono essere trasferiti tra piattaforme."},{"question":"Salvataggio e formati immagine","answer":"Se il salvataggio non riesce, controlla lo spazio disponibile, il permesso di salvare nella libreria foto e la leggibilità dell’immagine originale, quindi riprova. L’app elabora un’immagine statica alla volta e supporta la maggior parte dei formati comuni; alcuni dipendono dal dispositivo e dalla versione del sistema. Video, PDF, RAW/DNG ed elaborazione in batch non sono attualmente supportati."},{"question":"Come si cambia la lingua?","answer":"L’app supporta 40 lingue, selezionabili nelle impostazioni. Se la visualizzazione non è corretta, indica via e-mail la lingua del dispositivo e quella scelta nell’app."},{"question":"Ripristino, annullamento e rimborsi","answer":"Gli acquisti e il relativo ripristino avvengono tramite lo store ufficiale Apple o Google. Un diritto viene concesso solo dopo che lo store conferma una transazione valida. Le transazioni annullate, non riuscite o in sospeso non concedono diritti prima della conferma. Il ripristino può recuperare l’accesso a vita e un abbonamento attualmente attivo. Gli acquisti dell’App Store e di Google Play sono distinti e non possono essere ripristinati o trasferiti tra piattaforme."},{"question":"Privacy ed eliminazione dei dati","answer":"Disinstalla l’app per eliminare i dati presenti sul dispositivo. Su Android puoi anche usare l’opzione di sistema «Cancella dati». I registri degli acquisti sono gestiti da Apple o Google. I diritti ripristinabili vengono confermati nuovamente secondo le regole dello store. Le e-mail di assistenza vengono conservate per il tempo necessario a gestire la richiesta e soddisfare gli indispensabili obblighi di registrazione. Puoi scriverci per chiedere l’eliminazione della corrispondenza di assistenza che conserviamo ancora."}],"officialHelpTitle":"Aiuto rapido"}},"ja":{"linkLabels":{"appleEula":"Apple 標準エンドユーザ使用許諾契約（EULA）","appleCancel":"Appleのサブスクリプションの解約手順","googleManage":"Google Play の解約手順","appleRefund":"Appleに返金を依頼する","googleRefund":"Google Play の返金情報"},"nav":{"privacy":"プライバシーポリシー","terms":"利用規約","support":"サポート","language":"言語","chooseLanguage":"表示言語を選択してください","navigationLabel":"メインナビゲーション"},"home":{"eyebrow":"{appName} · Privacy first","title":"画像がサーバーにアップロードされることはありません。","lead":"画像の選択、OCR、機密情報の検出、編集、書き出しは端末上で行われます。本アプリはクラウド画像認識、クラウド同期、アカウント機能を提供しません。書き出し時には新しい画像を作成し、削除可能なプライバシー関連メタデータを除去します。一時作業ファイルは、保存成功時、編集の破棄時、またはセッション終了時に削除されます。保存に失敗した場合は、再試行に必要な状態を保持することがあります。","points":["アプリのデータ","有料商品と価格","サポート"],"cards":[{"title":"プライバシーポリシー","description":"画像がサーバーにアップロードされることはありません。","action":"プライバシーポリシー"},{"title":"利用規約","description":"認識と編集には利用回数の制限がありません。処理済み画像の書き出しにのみ有効な Premium が必要です。自動更新の週額・月額サブスクリプションと、一回払いの永久アクセスを提供し、無料トライアルはありません。App Store と Google Play の購入は別々で、プラットフォーム間で移行できません。","action":"利用規約"},{"title":"お困りですか？","description":"まず、以下のよくある質問をご確認ください。問題が解決しない場合は、サポートメールアドレスからお問い合わせください。","action":"サポート"}]},"footer":{"privacy":"プライバシーポリシー","terms":"利用規約","support":"サポート"},"privacy":{"title":"プライバシーポリシー","lead":"本ポリシーでは、{appName} における端末内データ、アプリストアの購入情報、サポートメールの取り扱いについて説明します。","sections":[{"title":"1. 適用範囲と連絡先","paragraphs":["本ポリシーは、iOS、iPadOS、Android 向けの {appName} アプリ、および本プライバシー・利用規約・サポートウェブサイトに適用されます。","プライバシーに関するご質問は、メールでお問い合わせください。 {email}"]},{"title":"2. アプリのデータ","callout":{"title":"画像がサーバーにアップロードされることはありません。","body":"画像の選択、OCR、機密情報の検出、編集、書き出しは端末上で行われます。本アプリはクラウド画像認識、クラウド同期、アカウント機能を提供しません。書き出し時には新しい画像を作成し、削除可能なプライバシー関連メタデータを除去します。一時作業ファイルは、保存成功時、編集の破棄時、またはセッション終了時に削除されます。保存に失敗した場合は、再試行に必要な状態を保持することがあります。"},"paragraphs":[]},{"title":"3. 権限、広告、トラッキング","paragraphs":["写真へのアクセスは、許可した画像の表示と処理にのみ使用します。カメラはアプリ内で撮影を選んだ場合にのみ使用します。写真ライブラリへの保存権限は、有効な Premium を持つ状態で書き出しを確定した場合にのみ求めます。位置情報、連絡先、マイク、Bluetooth、通知の権限は求めません。","広告識別子を使用せず、広告、分析、アトリビューション、クラッシュ報告のための第三者 SDK を組み込みません。","本アプリは、第三者のクラッシュ報告ツールを組み込みません。端末とストアの設定によっては、Apple または Google がそれぞれのプライバシールールに基づいてシステム診断情報を処理し、クラッシュやパフォーマンス上の問題の調査に使用される技術情報を提供する場合があります。"]},{"title":"4. アプリストアのサービスとネットワークアクセス","paragraphs":["本アプリは、商品の読み込み、ストアから返される現地価格の表示、購入の完了、購入の復元、サブスクリプションの管理、利用権の確認に Apple StoreKit または Google Play Billing を使用します。ネットワークアクセスは、Apple または Google のこれらの公式ストア機能にのみ使用されます。","ストアアカウント、支払い、請求、取引、返金、サブスクリプションサービスについては、Apple または Google が管理します。本アプリが処理するのは、商品と利用権の確認に必要なストア情報のみであり、完全な支払い認証情報を受け取ったり保存したりすることはありません。"]},{"title":"5. サポートメールとウェブサイト","paragraphs":["本アプリがメール情報を自動的に読み取ることはありません。利用者がサポートメールの送信を選択した場合に限り、サポート窓口は、メールアドレス、メッセージ、および利用者が任意で添付したスクリーンショット、画面収録、注文番号、その他の添付ファイルを受け取ります。これらの情報はお問い合わせへの対応にのみ使用し、広告やマーケティングには使用しません。アカウントや支払いのパスワード、カード番号全桁は送信しないでください。","本ウェブサイトは、広告または分析用の Cookie を設定せず、アクセス解析やトラッキングスクリプトを含みません。"]},{"title":"6. 保存期間と削除","paragraphs":["アプリをアンインストールすると、端末内データを削除できます。Android では、システムの「データを消去」も使用できます。","ストアの購入記録は Apple または Google が管理します。復元可能な利用権は、ストアのルールに従って再確認されます。","サポートメールは、お問い合わせへの対応および必要な記録保持要件を満たすために必要な期間、保存されます。当方が引き続き保有しているサポート対応メールの削除を希望する場合は、メールでご連絡ください。"]},{"title":"7. データセキュリティ","paragraphs":["本アプリは、端末内処理、最小限の権限、アプリストアの公式購入フローを使用し、不要なデータ転送を減らしています。サポートメールは受信したお問い合わせへの対応にのみ使用し、情報の性質に応じた合理的な保護措置を講じます。","いかなる端末、ネットワーク、電子的保存方法についても、完全な安全性を保証することはできません。サポートメールには、お問い合わせと関係のない機密情報を記載しないでください。"]},{"title":"8. 子どもと未成年者","paragraphs":["本アプリはアカウントを必要とせず、広告や行動分析によって子どもやその他の利用者のプロフィールを作成しません。子どもがサポートメールを通じて個人情報を提供したと考える保護者は、対応を求めて当方に連絡できます。"]},{"title":"9. 利用者の選択と権利","paragraphs":["端末内データは端末上で管理します。ストアアカウントと購入記録は Apple または Google が管理します。本アプリが利用者に代わって、アプリストアが保有する取引記録を変更または削除することはできません。","本アプリのデータ取り扱い、プラットフォームのルール、またはウェブサイトのホスティング方法が変更された場合、本ポリシーと本ページに表示される日付を更新し、適用されるルールで求められる場合は追加でお知らせします。","プライバシーに関するご質問は、メールでお問い合わせください。 {email}"]}]},"terms":{"title":"利用規約","lead":"{appName} 利用規約","sections":[{"title":"1. 本規約およびプラットフォーム規則への同意","paragraphs":["{appName}をダウンロード、購入、または使用することにより、お客様は本規約および購入先のアプリストアで適用される規則に同意したものとみなされます。同意されない場合は、アプリの使用または購入を中止してください。","本規約は、本アプリのダウンロード、購入、利用に適用されます。iOS 版と iPadOS 版には、以下も適用されます。"],"links":["appleEula"]},{"title":"2. 有料商品と価格","paragraphs":["認識と編集には利用回数の制限がありません。処理済み画像の書き出しにのみ有効な Premium が必要です。自動更新の週額・月額サブスクリプションと、一回払いの永久アクセスを提供し、無料トライアルはありません。App Store と Google Play の購入は別々で、プラットフォーム間で移行できません。","実際の価格、通貨、税金、請求期間、購入資格は、App Store または Google Play のシステム購入画面に表示され、確認される情報に従います。購入プラットフォームがストアアカウントを通じて請求と支払いを管理します。本アプリには、サブスクリプションの無料トライアルやその他の有料プランはありません。"]},{"title":"3. 自動更新と解約","paragraphs":["週間および月間サブスクリプションは、購入プラットフォームで解約するまで自動更新され、システム購入画面に表示される請求期間ごとに課金されます。{appName} を削除しても、サブスクリプションは自動的に解約されません。購入プラットフォームが返金などの対応を行わない限り、自動更新をオフにした後も、現在の支払済み期間が終了するまでサブスクリプションを利用できます。"],"links":["appleCancel","googleManage"]},{"title":"4. 購入、復元、返金","paragraphs":["購入および購入の復元は、Apple または Google の公式ストアを通じて行われます。ストアが有効な取引を確認した後にのみ利用権が付与されます。キャンセル、失敗、保留中の取引については、正常に確認されるまで利用権は付与されません。購入の復元では、ライフタイムアクセスと現在有効なサブスクリプションを復元できます。App Store と Google Play の購入は別々であり、プラットフォームをまたいで復元または移行することはできません。","返金は、取引を処理したアプリストアが、そのルール、購入地域、適用法に基づいて対応します。ストアが返金、取消し、サブスクリプションの失効、または無効な取引を確認した後、対応する利用権は削除されます。"],"links":["appleRefund","googleRefund"]},{"title":"5. オフライン利用と提供状況","paragraphs":["画像の選択、OCR、機密情報の検出、編集、書き出しは端末上で行われます。本アプリはクラウド画像認識、クラウド同期、アカウント機能を提供しません。書き出し時には新しい画像を作成し、削除可能なプライバシー関連メタデータを除去します。一時作業ファイルは、保存成功時、編集の破棄時、またはセッション終了時に削除されます。保存に失敗した場合は、再試行に必要な状態を保持することがあります。"]},{"title":"6. 適切な利用と知的財産","paragraphs":["本アプリを違法行為に使用すること、購入確認を回避すること、本アプリを破損させること、悪意のあるコードを配布すること、許可なく本アプリを複製または配布すること、本アプリのコンテンツに関する権利または他者の知的財産権を侵害することは禁止されています。","利用者はいつでも本アプリの利用をやめ、アンインストールできます。当方は、問題の修正、オペレーティングシステムへの対応、安定性の向上、プラットフォーム要件への適合のためにアップデートを提供する場合があります。端末、システム、ネットワーク、またはストアサービスの問題により、一部の機能が一時的に利用できなくなる場合があります。","適用法で認められる範囲で、本アプリは提供可能な状態で提供されます。本規約は、法律上除外できない責任を除外するものではなく、利用者に認められる強行的な消費者の権利を制限するものでもありません。","商品の機能、支払い方法、プラットフォームのルール、または適用法が変更された場合、本規約と本ページに表示される日付を更新することがあります。変更が利用者の権利に重大な影響を与える場合は、必要に応じて追加でお知らせします。","本規約、購入、またはアプリの使用に関するご質問は、メールでお問い合わせください。 {email}"]}]},"support":{"title":"サポート","lead":"まず、以下のよくある質問をご確認ください。問題が解決しない場合は、サポートメールアドレスからお問い合わせください。","emailTitle":"{appName} サポートメール","emailLead":"まず、以下のよくある質問をご確認ください。問題が解決しない場合は、サポートメールアドレスからお問い合わせください。","beforeEmail":{"title":"メールに記載する内容","paragraphs":["購入に関する問題の場合は、アプリストアの注文番号を記載できますが、アカウントや支払いのパスワード、カード情報全桁は送信しないでください。"],"bullets":["プラットフォーム、端末モデル、オペレーティングシステムのバージョン、アプリのバージョン","問題が起きる前に行った操作、期待していた動作、実際に起きたこと","必要に応じて、個人情報を隠したスクリーンショットまたは画面録画。"]},"faqs":[{"question":"画像はサーバーにアップロードされますか？","answer":"画像の選択、OCR、機密情報の検出、編集、書き出しは端末上で行われます。本アプリはクラウド画像認識、クラウド同期、アカウント機能を提供しません。書き出し時には新しい画像を作成し、削除可能なプライバシー関連メタデータを除去します。一時作業ファイルは、保存成功時、編集の破棄時、またはセッション終了時に削除されます。保存に失敗した場合は、再試行に必要な状態を保持することがあります。"},{"question":"権限、広告、トラッキング","answer":"写真へのアクセスは、許可した画像の表示と処理にのみ使用します。カメラはアプリ内で撮影を選んだ場合にのみ使用します。写真ライブラリへの保存権限は、有効な Premium を持つ状態で書き出しを確定した場合にのみ求めます。位置情報、連絡先、マイク、Bluetooth、通知の権限は求めません。"},{"question":"有料商品と価格","answer":"認識と編集には利用回数の制限がありません。処理済み画像の書き出しにのみ有効な Premium が必要です。自動更新の週額・月額サブスクリプションと、一回払いの永久アクセスを提供し、無料トライアルはありません。App Store と Google Play の購入は別々で、プラットフォーム間で移行できません。"},{"question":"保存と画像形式","answer":"保存に失敗した場合は、端末の空き容量、写真ライブラリへの保存権限、元画像を読み取れるかを確認して再試行してください。本アプリは一度に1枚の静止画像を処理し、一般的な画像形式の多くに対応します。一部の形式は端末やOSのバージョンに依存します。動画、PDF、RAW／DNG、バッチ処理には現在対応していません。"},{"question":"言語を変更するには？","answer":"本アプリは40言語に対応しており、アプリの設定で変更できます。表示が正しくない場合は、端末の言語とアプリで選択した言語をメールでお知らせください。"},{"question":"復元、解約、返金","answer":"購入および購入の復元は、Apple または Google の公式ストアを通じて行われます。ストアが有効な取引を確認した後にのみ利用権が付与されます。キャンセル、失敗、保留中の取引については、正常に確認されるまで利用権は付与されません。購入の復元では、ライフタイムアクセスと現在有効なサブスクリプションを復元できます。App Store と Google Play の購入は別々であり、プラットフォームをまたいで復元または移行することはできません。"},{"question":"プライバシーとデータの削除","answer":"アプリをアンインストールすると、端末内データを削除できます。Android では、システムの「データを消去」も使用できます。 ストアの購入記録は Apple または Google が管理します。復元可能な利用権は、ストアのルールに従って再確認されます。 サポートメールは、お問い合わせへの対応および必要な記録保持要件を満たすために必要な期間、保存されます。当方が引き続き保有しているサポート対応メールの削除を希望する場合は、メールでご連絡ください。"}],"officialHelpTitle":"クイックヘルプ"}},"ko":{"linkLabels":{"appleEula":"Apple 표준 최종 사용자 사용권 계약(EULA)","appleCancel":"애플 구독 취소 안내","googleManage":"Google Play 해지 안내","appleRefund":"애플에 환불을 요청하세요","googleRefund":"Google Play 환불 정보"},"nav":{"privacy":"개인정보 보호정책","terms":"이용약관","support":"지원","language":"언어","chooseLanguage":"표시 언어를 선택하세요","navigationLabel":"기본 탐색"},"home":{"eyebrow":"{appName} · Privacy first","title":"이미지는 당사 서버에 업로드되지 않습니다.","lead":"이미지 선택, OCR, 민감한 내용 감지, 편집 및 내보내기는 기기에서 처리됩니다. 앱은 클라우드 이미지 인식, 클라우드 동기화 또는 계정 기능을 제공하지 않습니다. 내보낼 때 새 이미지를 만들고 삭제 가능한 개인정보 메타데이터를 제거합니다. 임시 작업 파일은 저장 성공, 편집 취소 또는 세션 종료 후 삭제되며, 저장에 실패하면 재시도에 필요한 상태가 남을 수 있습니다.","points":["앱 데이터","유료 상품 및 가격","지원"],"cards":[{"title":"개인정보 보호정책","description":"이미지는 당사 서버에 업로드되지 않습니다.","action":"개인정보 보호정책"},{"title":"이용약관","description":"인식과 편집에는 사용 횟수 제한이 없습니다. 처리된 이미지를 내보낼 때만 유효한 Premium이 필요합니다. 무료 체험 없이 자동 갱신 주간·월간 구독과 일회성 평생 이용권을 제공합니다. App Store와 Google Play 구매는 서로 별개이며 플랫폼 간 이전이 불가능합니다.","action":"이용약관"},{"title":"도움이 필요하세요?","description":"먼저 아래의 자주 묻는 질문을 확인하세요. 문제가 계속되면 지원 이메일 주소로 문의해 주세요.","action":"지원"}]},"footer":{"privacy":"개인정보 보호정책","terms":"이용약관","support":"지원"},"privacy":{"title":"개인정보 보호정책","lead":"본 정책은 {appName}에서 기기 내 데이터, 앱 스토어 구매 정보 및 지원 이메일을 처리하는 방식을 설명합니다.","sections":[{"title":"1. 범위 및 연락처","paragraphs":["본 정책은 iOS, iPadOS 및 Android용 {appName} 앱과 본 개인정보 처리방침, 이용 약관 및 지원 웹사이트에 적용됩니다.","개인정보 보호 관련 문의는 이메일로 보내주세요. {email}"]},{"title":"2. 앱 데이터","callout":{"title":"이미지는 당사 서버에 업로드되지 않습니다.","body":"이미지 선택, OCR, 민감한 내용 감지, 편집 및 내보내기는 기기에서 처리됩니다. 앱은 클라우드 이미지 인식, 클라우드 동기화 또는 계정 기능을 제공하지 않습니다. 내보낼 때 새 이미지를 만들고 삭제 가능한 개인정보 메타데이터를 제거합니다. 임시 작업 파일은 저장 성공, 편집 취소 또는 세션 종료 후 삭제되며, 저장에 실패하면 재시도에 필요한 상태가 남을 수 있습니다."},"paragraphs":[]},{"title":"3. 권한, 광고 및 추적","paragraphs":["사진 접근 권한은 사용자가 허용한 이미지를 표시하고 처리하는 데만 사용됩니다. 카메라는 앱에서 직접 촬영을 선택한 경우에만 사용됩니다. 사진 보관함 저장 권한은 유효한 Premium 상태에서 내보내기를 확인할 때만 요청됩니다. 앱은 위치, 연락처, 마이크, Bluetooth 또는 알림 권한을 요청하지 않습니다.","광고 식별자를 사용하지 않으며 광고, 분석, 기여도 측정 또는 충돌 보고를 위한 제3자 SDK를 통합하지 않습니다.","앱은 제3자 충돌 보고 도구를 통합하지 않습니다. 기기 및 스토어 설정에 따라 Apple 또는 Google은 각자의 개인정보 보호 규칙에 따라 시스템 진단 정보를 처리하고 충돌 또는 성능 문제를 조사하는 데 사용되는 기술 정보를 제공할 수 있습니다."]},{"title":"4. 앱 스토어 서비스 및 네트워크 접속","paragraphs":["앱은 Apple StoreKit 또는 Google Play Billing을 사용하여 상품을 불러오고, 스토어에서 반환한 현지화된 가격을 표시하고, 구매를 완료하고, 구매를 복원하고, 구독을 관리하고, 이용 권한을 확인합니다. 네트워크 접속은 이러한 Apple 또는 Google의 공식 스토어 기능에만 사용됩니다.","스토어 계정, 결제, 청구, 거래, 환불 및 구독 서비스는 Apple 또는 Google이 담당합니다. 앱은 상품 및 이용 권한을 확인하는 데 필요한 스토어 정보만 처리하며 전체 결제 인증 정보를 받거나 저장하지 않습니다."]},{"title":"5. 지원 이메일 및 웹사이트","paragraphs":["앱은 사용자의 이메일 정보를 자동으로 읽지 않습니다. 사용자가 지원 이메일을 보내기로 선택한 경우에만 지원 채널에서 이메일 주소, 메시지 및 사용자가 자발적으로 제공한 스크린샷, 화면 녹화, 주문 번호 또는 기타 첨부 파일을 받습니다. 이 정보는 요청 처리에만 사용되며 광고나 마케팅에는 사용되지 않습니다. 계정 비밀번호, 결제 비밀번호 또는 전체 카드 번호를 보내지 마세요.","본 웹사이트는 광고 또는 분석 쿠키를 설정하지 않으며 트래픽 분석이나 추적 스크립트를 포함하지 않습니다."]},{"title":"6. 보관 및 삭제","paragraphs":["앱을 제거하면 기기 내 데이터가 삭제됩니다. Android에서는 시스템의 데이터 삭제 옵션도 사용할 수 있습니다.","스토어 구매 기록은 Apple 또는 Google이 관리합니다. 복원 가능한 이용 권한은 스토어 규칙에 따라 다시 확인됩니다.","지원 이메일은 요청을 처리하고 필요한 기록 보관 요건을 충족하는 데 필요한 기간 동안 보관됩니다. 당사가 아직 보관 중인 지원 서신의 삭제를 요청하려면 이메일로 문의할 수 있습니다."]},{"title":"7. 데이터 보안","paragraphs":["앱은 불필요한 데이터 전송을 줄이기 위해 기기 내 처리, 최소한의 권한 및 앱 스토어의 공식 구매 절차를 사용합니다. 지원 이메일은 접수된 요청을 처리하는 데만 사용되며 정보의 성격에 적합한 합리적인 보호 조치를 적용합니다.","어떠한 기기, 네트워크 또는 전자적 저장 방식도 완전히 안전하다고 보장할 수 없습니다. 지원 이메일에 요청과 관련 없는 민감한 정보를 포함하지 마세요."]},{"title":"8. 아동 및 청소년","paragraphs":["앱은 계정을 요구하지 않으며 광고 또는 행동 분석을 통해 아동이나 다른 사용자의 프로필을 만들지 않습니다. 아동이 지원 이메일을 통해 개인정보를 제공했다고 생각하는 부모 또는 보호자는 해당 문제를 처리할 수 있도록 당사에 연락할 수 있습니다."]},{"title":"9. 사용자의 선택과 권리","paragraphs":["기기 내 데이터는 사용자의 기기에서 관리합니다. 스토어 계정과 구매 기록은 Apple 또는 Google이 관리합니다. 앱은 앱 스토어에서 보관하는 거래 기록을 사용자를 대신하여 변경하거나 삭제할 수 없습니다.","앱의 데이터 처리 방식, 플랫폼 규칙 또는 웹사이트 호스팅 방식이 변경되는 경우 본 정책과 이 페이지에 표시된 날짜를 업데이트하고, 적용되는 규칙에서 요구하는 경우 추가로 안내합니다.","개인정보 보호 관련 문의는 이메일로 보내주세요. {email}"]}]},"terms":{"title":"이용약관","lead":"{appName} 이용 약관.","sections":[{"title":"1. 약관 및 플랫폼 규칙에 대한 동의","paragraphs":["{appName}을 다운로드, 구매 또는 사용함으로써 귀하는 본 약관 및 구매가 이루어진 앱 스토어에 적용되는 규칙에 동의하는 것입니다. 동의하지 않는 경우 앱 사용을 중단하거나 구매를 하지 마십시오.","본 약관은 사용자의 앱 다운로드, 구매 및 이용에 적용됩니다. iOS 및 iPadOS 버전에는 다음도 적용됩니다."],"links":["appleEula"]},{"title":"2. 유료 상품 및 가격","paragraphs":["인식과 편집에는 사용 횟수 제한이 없습니다. 처리된 이미지를 내보낼 때만 유효한 Premium이 필요합니다. 무료 체험 없이 자동 갱신 주간·월간 구독과 일회성 평생 이용권을 제공합니다. App Store와 Google Play 구매는 서로 별개이며 플랫폼 간 이전이 불가능합니다.","실제 가격, 통화, 세금, 청구 기간 및 구매 자격은 App Store 또는 Google Play 시스템 구매 화면에 표시되고 확인되는 정보를 따릅니다. 구매 플랫폼은 사용자의 스토어 계정을 통해 요금을 청구하고 결제를 관리합니다. 앱은 구독 무료 체험 또는 다른 유료 요금제를 제공하지 않습니다."]},{"title":"3. 자동 갱신 및 해지","paragraphs":["주간 및 월간 구독은 구매 플랫폼에서 해지할 때까지 자동으로 갱신되며 시스템 구매 화면에 표시된 청구 기간마다 요금이 청구됩니다. {appName}을 삭제해도 구독은 자동으로 해지되지 않습니다. 구매 플랫폼에서 환불 또는 다른 처리를 제공하지 않는 한, 자동 갱신을 끈 후에도 현재 결제 기간이 끝날 때까지 구독을 계속 이용할 수 있습니다."],"links":["appleCancel","googleManage"]},{"title":"4. 구매, 복원 및 환불","paragraphs":["구매 및 구매 복원은 Apple 또는 Google 공식 스토어를 통해 이루어집니다. 스토어에서 유효한 거래를 확인한 후에만 이용 권한이 부여됩니다. 취소, 실패 또는 대기 중인 거래는 정상 확인 전까지 이용 권한을 부여하지 않습니다. 구매 복원을 통해 평생 이용 권한과 현재 활성 상태인 구독을 복원할 수 있습니다. App Store와 Google Play 구매는 서로 별개이며 플랫폼 간에 복원하거나 이전할 수 없습니다.","환불은 거래를 처리한 앱 스토어에서 해당 규칙, 구매 지역 및 관련 법률에 따라 처리합니다. 스토어에서 환불, 취소, 구독 만료 또는 무효 거래를 확인하면 해당 이용 권한이 삭제됩니다."],"links":["appleRefund","googleRefund"]},{"title":"5. 오프라인 이용 및 사용 가능 여부","paragraphs":["이미지 선택, OCR, 민감한 내용 감지, 편집 및 내보내기는 기기에서 처리됩니다. 앱은 클라우드 이미지 인식, 클라우드 동기화 또는 계정 기능을 제공하지 않습니다. 내보낼 때 새 이미지를 만들고 삭제 가능한 개인정보 메타데이터를 제거합니다. 임시 작업 파일은 저장 성공, 편집 취소 또는 세션 종료 후 삭제되며, 저장에 실패하면 재시도에 필요한 상태가 남을 수 있습니다."]},{"title":"6. 허용되는 이용 및 지식재산권","paragraphs":["앱을 불법 활동에 사용하거나, 구매 확인을 우회하거나, 앱을 손상시키거나, 악성 코드를 배포하거나, 허가 없이 앱을 복제 또는 배포하거나, 앱 콘텐츠에 관한 권리 또는 타인의 지식재산권을 침해해서는 안 됩니다.","사용자는 언제든지 앱 이용을 중단하고 제거할 수 있습니다. 당사는 문제 해결, 운영체제 지원, 안정성 향상 또는 플랫폼 요건 충족을 위해 업데이트를 출시할 수 있습니다. 기기, 시스템, 네트워크 또는 스토어 서비스 문제로 일부 기능을 일시적으로 사용하지 못할 수 있습니다.","관련 법률에서 허용하는 범위 내에서 앱은 사용 가능한 상태로 제공됩니다. 본 약관은 법적으로 제외할 수 없는 책임을 제외하거나 사용자에게 보장되는 강행적 소비자 권리를 제한하지 않습니다.","상품 기능, 결제 방식, 플랫폼 규칙 또는 관련 법률이 변경되는 경우 본 약관과 이 페이지에 표시된 날짜를 업데이트할 수 있습니다. 변경으로 사용자의 권리에 중대한 영향이 발생하는 경우 요구되는 바에 따라 추가로 안내합니다.","본 약관, 구매 또는 앱 사용과 관련하여 궁금한 사항이 있으면 이메일을 보내주세요. {email}"]}]},"support":{"title":"지원","lead":"먼저 아래의 자주 묻는 질문을 확인하세요. 문제가 계속되면 지원 이메일 주소로 문의해 주세요.","emailTitle":"{appName} 지원 이메일","emailLead":"먼저 아래의 자주 묻는 질문을 확인하세요. 문제가 계속되면 지원 이메일 주소로 문의해 주세요.","beforeEmail":{"title":"이메일에 포함할 내용","paragraphs":["구매 문제의 경우 앱 스토어 주문 번호를 포함할 수 있지만 계정 비밀번호, 결제 비밀번호 또는 전체 카드 정보를 보내지 마세요."],"bullets":["플랫폼, 기기 모델, 운영체제 버전 및 앱 버전","문제 발생 전에 한 작업, 예상한 결과 및 실제로 발생한 상황","필요한 경우 개인 정보가 가려진 스크린샷 또는 화면 녹화본을 제공할 수 있습니다."]},"faqs":[{"question":"이미지가 서버에 업로드되나요?","answer":"이미지 선택, OCR, 민감한 내용 감지, 편집 및 내보내기는 기기에서 처리됩니다. 앱은 클라우드 이미지 인식, 클라우드 동기화 또는 계정 기능을 제공하지 않습니다. 내보낼 때 새 이미지를 만들고 삭제 가능한 개인정보 메타데이터를 제거합니다. 임시 작업 파일은 저장 성공, 편집 취소 또는 세션 종료 후 삭제되며, 저장에 실패하면 재시도에 필요한 상태가 남을 수 있습니다."},{"question":"권한, 광고 및 추적","answer":"사진 접근 권한은 사용자가 허용한 이미지를 표시하고 처리하는 데만 사용됩니다. 카메라는 앱에서 직접 촬영을 선택한 경우에만 사용됩니다. 사진 보관함 저장 권한은 유효한 Premium 상태에서 내보내기를 확인할 때만 요청됩니다. 앱은 위치, 연락처, 마이크, Bluetooth 또는 알림 권한을 요청하지 않습니다."},{"question":"유료 상품 및 가격","answer":"인식과 편집에는 사용 횟수 제한이 없습니다. 처리된 이미지를 내보낼 때만 유효한 Premium이 필요합니다. 무료 체험 없이 자동 갱신 주간·월간 구독과 일회성 평생 이용권을 제공합니다. App Store와 Google Play 구매는 서로 별개이며 플랫폼 간 이전이 불가능합니다."},{"question":"저장 및 이미지 형식","answer":"저장에 실패하면 기기 여유 공간, 사진 보관함 저장 권한, 원본 이미지의 읽기 가능 여부를 확인한 후 다시 시도하세요. 앱은 한 번에 정지 이미지 한 장을 처리하며 대부분의 일반적인 이미지 형식을 지원합니다. 일부 형식은 기기와 시스템 버전에 따라 달라질 수 있습니다. 동영상, PDF, RAW/DNG 및 일괄 처리는 현재 지원되지 않습니다."},{"question":"언어를 변경하려면 어떻게 하나요?","answer":"앱은 40개 언어를 지원하며 앱 설정에서 언어를 변경할 수 있습니다. 표시가 올바르지 않으면 기기 언어와 앱에서 선택한 언어를 이메일로 보내 주세요."},{"question":"복원, 해지 및 환불","answer":"구매 및 구매 복원은 Apple 또는 Google 공식 스토어를 통해 이루어집니다. 스토어에서 유효한 거래를 확인한 후에만 이용 권한이 부여됩니다. 취소, 실패 또는 대기 중인 거래는 정상 확인 전까지 이용 권한을 부여하지 않습니다. 구매 복원을 통해 평생 이용 권한과 현재 활성 상태인 구독을 복원할 수 있습니다. App Store와 Google Play 구매는 서로 별개이며 플랫폼 간에 복원하거나 이전할 수 없습니다."},{"question":"개인정보 보호 및 데이터 삭제","answer":"앱을 제거하면 기기 내 데이터가 삭제됩니다. Android에서는 시스템의 데이터 삭제 옵션도 사용할 수 있습니다. 스토어 구매 기록은 Apple 또는 Google이 관리합니다. 복원 가능한 이용 권한은 스토어 규칙에 따라 다시 확인됩니다. 지원 이메일은 요청을 처리하고 필요한 기록 보관 요건을 충족하는 데 필요한 기간 동안 보관됩니다. 당사가 아직 보관 중인 지원 서신의 삭제를 요청하려면 이메일로 문의할 수 있습니다."}],"officialHelpTitle":"빠른 도움"}},"mr":{"linkLabels":{"appleEula":"Apple चा मानक अंतिम वापरकर्ता परवाना करार (EULA)","appleCancel":"ॲपल सबस्क्रिप्शन रद्द करण्याच्या सूचना","googleManage":"Google Play रद्द करण्याच्या सूचना","appleRefund":"ॲपलकडून परताव्याची विनंती करा","googleRefund":"Google Play परतावा माहिती"},"nav":{"privacy":"गोपनीयता धोरण","terms":"वापराच्या अटी","support":"सहाय्य","language":"भाषा","chooseLanguage":"डिस्प्ले भाषा निवडा","navigationLabel":"प्राथमिक नेव्हिगेशन"},"home":{"eyebrow":"{appName} · Privacy first","title":"तुमच्या प्रतिमा आमच्या सर्व्हरवर अपलोड केल्या जात नाहीत.","lead":"प्रतिमा निवड, OCR, संवेदनशील मजकूर ओळख, संपादन आणि निर्यात डिव्हाइसवरच होते. ॲप क्लाउड प्रतिमा ओळख, क्लाउड सिंक किंवा खाते देत नाही. निर्यात करताना नवीन प्रतिमा तयार केली जाते आणि काढता येणारा खाजगी मेटाडेटा हटवला जातो. यशस्वी जतन, संपादन रद्द करणे किंवा सत्र संपल्यानंतर तात्पुरत्या फाइल्स हटवल्या जातात; जतन अयशस्वी झाल्यास पुन्हा प्रयत्नासाठी आवश्यक स्थिती ठेवली जाऊ शकते.","points":["ॲप डेटा","सशुल्क उत्पादने आणि किमती","सहाय्य"],"cards":[{"title":"गोपनीयता धोरण","description":"तुमच्या प्रतिमा आमच्या सर्व्हरवर अपलोड केल्या जात नाहीत.","action":"गोपनीयता धोरण"},{"title":"वापराच्या अटी","description":"ओळख आणि संपादनाला वापर मर्यादा नाही. प्रक्रिया केलेली प्रतिमा निर्यात करण्यासाठीच वैध Premium आवश्यक आहे. विनामूल्य चाचणीशिवाय स्वयं-नूतनीकरण होणाऱ्या साप्ताहिक व मासिक सदस्यता आणि एकदाच खरेदी करता येणारा आजीवन प्रवेश उपलब्ध आहे. App Store आणि Google Play खरेदी स्वतंत्र आहेत व प्लॅटफॉर्मदरम्यान हस्तांतरित करता येत नाहीत.","action":"वापराच्या अटी"},{"title":"मदत हवी आहे का?","description":"सर्वप्रथम खालील नेहमीचे प्रश्न पाहा. समस्या कायम राहिल्यास सहाय्य ईमेल पत्त्याद्वारे आमच्याशी संपर्क साधा.","action":"सहाय्य"}]},"footer":{"privacy":"गोपनीयता धोरण","terms":"वापराच्या अटी","support":"सहाय्य"},"privacy":{"title":"गोपनीयता धोरण","lead":"हे धोरण {appName} डिव्हाइसवरील डेटा, ॲप स्टोअर खरेदी माहिती आणि सहाय्य ईमेल कसे हाताळतो ते स्पष्ट करते.","sections":[{"title":"1. व्याप्ती आणि संपर्क","paragraphs":["हे धोरण iOS, iPadOS आणि Android साठीच्या {appName} ॲपवर आणि या गोपनीयता, अटी व सहाय्य वेबसाइटवर लागू होते.","गोपनीयतेच्या प्रश्नांसाठी, ईमेल करा {email}"]},{"title":"2. ॲप डेटा","callout":{"title":"तुमच्या प्रतिमा आमच्या सर्व्हरवर अपलोड केल्या जात नाहीत.","body":"प्रतिमा निवड, OCR, संवेदनशील मजकूर ओळख, संपादन आणि निर्यात डिव्हाइसवरच होते. ॲप क्लाउड प्रतिमा ओळख, क्लाउड सिंक किंवा खाते देत नाही. निर्यात करताना नवीन प्रतिमा तयार केली जाते आणि काढता येणारा खाजगी मेटाडेटा हटवला जातो. यशस्वी जतन, संपादन रद्द करणे किंवा सत्र संपल्यानंतर तात्पुरत्या फाइल्स हटवल्या जातात; जतन अयशस्वी झाल्यास पुन्हा प्रयत्नासाठी आवश्यक स्थिती ठेवली जाऊ शकते."},"paragraphs":[]},{"title":"3. परवानग्या, जाहिरात आणि ट्रॅकिंग","paragraphs":["तुम्ही परवानगी दिलेल्या प्रतिमा दाखवण्यासाठी आणि प्रक्रिया करण्यासाठीच फोटो प्रवेश वापरला जातो. ॲपमध्ये फोटो काढणे निवडल्यावरच कॅमेरा वापरला जातो. वैध Premium सह निर्यात निश्चित करताना फोटो लायब्ररीत जतन करण्याची परवानगी मागितली जाते. ॲप स्थान, संपर्क, मायक्रोफोन, Bluetooth किंवा सूचनांची परवानगी मागत नाही.","तो जाहिरात ओळखकर्ता वापरत नाही आणि जाहिरात, विश्लेषण, ॲट्रिब्युशन किंवा क्रॅश रिपोर्टिंगसाठी तृतीय-पक्ष SDK समाविष्ट करत नाही.","ॲप तृतीय-पक्ष क्रॅश रिपोर्टिंग साधन समाविष्ट करत नाही. तुमच्या डिव्हाइस आणि स्टोअर सेटिंग्जनुसार Apple किंवा Google त्यांच्या संबंधित गोपनीयता नियमांनुसार सिस्टम निदान माहितीवर प्रक्रिया करू शकते आणि क्रॅश किंवा कार्यप्रदर्शन समस्या तपासण्यासाठी तांत्रिक माहिती देऊ शकते."]},{"title":"4. ॲप स्टोअर सेवा आणि नेटवर्क प्रवेश","paragraphs":["ॲप उत्पादने लोड करण्यासाठी, स्टोअरने दिलेल्या स्थानिक किमती दाखवण्यासाठी, खरेदी पूर्ण करण्यासाठी, खरेदी पुनर्स्थापित करण्यासाठी, सदस्यता व्यवस्थापित करण्यासाठी आणि हक्कांची पुष्टी करण्यासाठी Apple StoreKit किंवा Google Play Billing वापरतो. नेटवर्क प्रवेश केवळ Apple किंवा Google च्या या अधिकृत स्टोअर सुविधांसाठी वापरला जातो.","स्टोअर खाती, पेमेंट, बिलिंग, व्यवहार, परतावे आणि सदस्यता सेवांसाठी Apple किंवा Google जबाबदार आहे. ॲप केवळ उत्पादने आणि हक्कांची पुष्टी करण्यासाठी आवश्यक स्टोअर माहितीवर प्रक्रिया करतो आणि संपूर्ण पेमेंट क्रेडेन्शियल्स प्राप्त किंवा साठवत नाही."]},{"title":"5. सहाय्य ईमेल आणि वेबसाइट","paragraphs":["ॲप तुमची ईमेल माहिती आपोआप वाचत नाही. तुम्ही सहाय्य ईमेल पाठवण्याचे निवडल्यावरच सहाय्य माध्यमाला तुमचा ईमेल पत्ता, संदेश आणि तुम्ही स्वेच्छेने दिलेला स्क्रीनशॉट, स्क्रीन रेकॉर्डिंग, ऑर्डर नंबर किंवा इतर संलग्नक मिळते. ही माहिती केवळ तुमची विनंती हाताळण्यासाठी वापरली जाते, जाहिरात किंवा विपणनासाठी नाही. खाते किंवा पेमेंट पासवर्ड अथवा संपूर्ण कार्ड नंबर पाठवू नका.","ही वेबसाइट जाहिरात किंवा विश्लेषण कुकीज सेट करत नाही आणि रहदारी विश्लेषण किंवा ट्रॅकिंग स्क्रिप्ट समाविष्ट करत नाही."]},{"title":"6. धारणा आणि हटवणे","paragraphs":["ॲप अनइंस्टॉल करून डिव्हाइसवरील डेटा हटवा. Android वर तुम्ही सिस्टमचा डेटा साफ करा पर्यायही वापरू शकता.","स्टोअर खरेदी नोंदी Apple किंवा Google व्यवस्थापित करते. पुनर्स्थापित करता येणाऱ्या हक्कांची स्टोअरच्या नियमांनुसार पुन्हा पुष्टी केली जाते.","सहाय्य ईमेल विनंती हाताळण्यासाठी आणि आवश्यक नोंद-ठेव आवश्यकता पूर्ण करण्यासाठी आवश्यक असेपर्यंत ठेवले जातात. आमच्याकडे अजूनही असलेला सहाय्य पत्रव्यवहार हटवण्याची विनंती तुम्ही ईमेलद्वारे करू शकता."]},{"title":"7. डेटा सुरक्षा","paragraphs":["अनावश्यक डेटा हस्तांतरण कमी करण्यासाठी ॲप डिव्हाइसवरील प्रक्रिया, किमान परवानग्या आणि ॲप स्टोअरच्या अधिकृत खरेदी प्रक्रिया वापरतो. सहाय्य ईमेल केवळ येणाऱ्या विनंत्या हाताळण्यासाठी वापरले जातात आणि माहितीच्या स्वरूपानुसार वाजवी सुरक्षा उपाय केले जातात.","कोणतेही डिव्हाइस, नेटवर्क किंवा इलेक्ट्रॉनिक स्टोरेज पद्धत पूर्णपणे सुरक्षित असल्याची हमी देता येत नाही. सहाय्य ईमेलमध्ये असंबंधित संवेदनशील माहिती समाविष्ट करू नका."]},{"title":"8. मुले आणि किशोरवयीन","paragraphs":["ॲपला खाते आवश्यक नाही आणि तो जाहिरात किंवा वर्तन विश्लेषणाद्वारे मुले किंवा इतर वापरकर्त्यांची प्रोफाइल तयार करत नाही. मुलाने सहाय्य ईमेलद्वारे वैयक्तिक माहिती दिली आहे असे वाटणारे पालक किंवा संरक्षक विषय हाताळण्यासाठी आमच्याशी संपर्क साधू शकतात."]},{"title":"9. तुमचे पर्याय आणि हक्क","paragraphs":["तुम्ही तुमच्या डिव्हाइसद्वारे डिव्हाइसवरील डेटा व्यवस्थापित करता. Apple किंवा Google स्टोअर खाती आणि खरेदी नोंदी व्यवस्थापित करते. ॲप तुमच्या वतीने ॲप स्टोअरकडे असलेल्या व्यवहार नोंदी बदलू किंवा हटवू शकत नाही.","ॲपच्या डेटा पद्धती, प्लॅटफॉर्म नियम किंवा वेबसाइट होस्टिंग व्यवस्था बदलल्यास, आम्ही हे धोरण आणि या पृष्ठावर दाखवलेली तारीख अपडेट करू आणि लागू नियमांनुसार आवश्यक असल्यास अतिरिक्त सूचना देऊ.","गोपनीयतेच्या प्रश्नांसाठी, ईमेल करा {email}"]}]},"terms":{"title":"वापराच्या अटी","lead":"{appName} वापराच्या अटी.","sections":[{"title":"1. या अटी आणि प्लॅटफॉर्मचे नियम स्वीकारणे","paragraphs":["{appName} डाउनलोड करून, खरेदी करून किंवा वापरून, तुम्ही या अटी व शर्तींना आणि तुम्ही खरेदी करत असलेल्या ॲप स्टोअरमधील तुम्हाला लागू होणाऱ्या नियमांना सहमती देत आहात. तुम्ही सहमत नसल्यास, ॲपचा वापर सुरू ठेवू नका किंवा खरेदी करू नका.","या अटी तुम्ही ॲप डाउनलोड करणे, खरेदी करणे आणि वापरणे यावर लागू होतात. iOS आणि iPadOS आवृत्त्यांवर हेही लागू होते:"],"links":["appleEula"]},{"title":"2. सशुल्क उत्पादने आणि किमती","paragraphs":["ओळख आणि संपादनाला वापर मर्यादा नाही. प्रक्रिया केलेली प्रतिमा निर्यात करण्यासाठीच वैध Premium आवश्यक आहे. विनामूल्य चाचणीशिवाय स्वयं-नूतनीकरण होणाऱ्या साप्ताहिक व मासिक सदस्यता आणि एकदाच खरेदी करता येणारा आजीवन प्रवेश उपलब्ध आहे. App Store आणि Google Play खरेदी स्वतंत्र आहेत व प्लॅटफॉर्मदरम्यान हस्तांतरित करता येत नाहीत.","प्रत्यक्ष किंमत, चलन, कर, बिलिंग कालावधी आणि खरेदी पात्रता ही App Store किंवा Google Play च्या सिस्टम खरेदी स्क्रीनवर दाखवलेली आणि पुष्टी केलेली माहिती असते. खरेदी प्लॅटफॉर्म तुमच्या स्टोअर खात्याद्वारे शुल्क आकारतो आणि पेमेंट व्यवस्थापित करतो. ॲप सदस्यतेची विनामूल्य चाचणी किंवा इतर सशुल्क योजना देत नाही."]},{"title":"3. स्वयं-नूतनीकरण आणि रद्द करणे","paragraphs":["साप्ताहिक आणि मासिक सदस्यता स्वयं-नूतनीकरण होतात आणि तुम्ही खरेदी प्लॅटफॉर्मवरून रद्द करेपर्यंत सिस्टम खरेदी स्क्रीनवर दाखवलेल्या बिलिंग कालावधीसाठी शुल्क आकारले जाते. {appName} हटवल्याने सदस्यता आपोआप रद्द होत नाही. खरेदी प्लॅटफॉर्मने परतावा किंवा अन्य व्यवस्था दिली नाही तर, स्वयं-नूतनीकरण बंद केल्यानंतर सध्याचा सशुल्क कालावधी संपेपर्यंत तुम्ही सदस्यता वापरू शकता."],"links":["appleCancel","googleManage"]},{"title":"4. खरेदी, पुनर्स्थापना आणि परतावे","paragraphs":["खरेदी आणि खरेदी पुनर्स्थापना Apple किंवा Google च्या अधिकृत स्टोअरद्वारे पूर्ण केली जाते. स्टोअरने वैध व्यवहाराची पुष्टी केल्यानंतरच हक्क दिला जातो. रद्द, अयशस्वी किंवा प्रलंबित व्यवहार यशस्वी पुष्टीपूर्वी हक्क देत नाहीत. खरेदी पुनर्स्थापना आजीवन प्रवेश आणि सध्या सक्रिय सदस्यता पुनर्स्थापित करू शकते. App Store आणि Google Play खरेदी स्वतंत्र आहेत आणि प्लॅटफॉर्मदरम्यान पुनर्स्थापित किंवा हस्तांतरित करता येत नाहीत.","परतावे व्यवहार पूर्ण करणारे ॲप स्टोअर त्याच्या नियमांनुसार, खरेदी प्रदेश आणि लागू कायद्यानुसार हाताळते. स्टोअरने परतावा, रद्द करणे, सदस्यता समाप्ती किंवा अवैध व्यवहाराची पुष्टी केल्यानंतर संबंधित हक्क काढून टाकला जातो."],"links":["appleRefund","googleRefund"]},{"title":"5. ऑफलाइन वापर आणि उपलब्धता","paragraphs":["प्रतिमा निवड, OCR, संवेदनशील मजकूर ओळख, संपादन आणि निर्यात डिव्हाइसवरच होते. ॲप क्लाउड प्रतिमा ओळख, क्लाउड सिंक किंवा खाते देत नाही. निर्यात करताना नवीन प्रतिमा तयार केली जाते आणि काढता येणारा खाजगी मेटाडेटा हटवला जातो. यशस्वी जतन, संपादन रद्द करणे किंवा सत्र संपल्यानंतर तात्पुरत्या फाइल्स हटवल्या जातात; जतन अयशस्वी झाल्यास पुन्हा प्रयत्नासाठी आवश्यक स्थिती ठेवली जाऊ शकते."]},{"title":"6. स्वीकार्य वापर आणि बौद्धिक संपदा","paragraphs":["तुम्ही बेकायदेशीर कृतीसाठी ॲप वापरू नये; खरेदी पडताळणी टाळू नये; ॲपचे नुकसान करू नये; दुर्भावनापूर्ण कोड वितरित करू नये; परवानगीशिवाय ॲपची प्रत किंवा वितरण करू नये; किंवा ॲप सामग्रीवरील हक्क अथवा दुसऱ्या व्यक्तीच्या बौद्धिक संपदेचे उल्लंघन करू नये.","तुम्ही कधीही ॲपचा वापर थांबवून तो अनइंस्टॉल करू शकता. समस्या दुरुस्त करण्यासाठी, ऑपरेटिंग सिस्टमचे समर्थन करण्यासाठी, स्थिरता सुधारण्यासाठी किंवा प्लॅटफॉर्म आवश्यकता पूर्ण करण्यासाठी आम्ही अपडेट जारी करू शकतो. डिव्हाइस, सिस्टम, नेटवर्क किंवा स्टोअर सेवा समस्यांमुळे काही सुविधा तात्पुरत्या अनुपलब्ध होऊ शकतात.","लागू कायद्याने परवानगी दिलेल्या मर्यादेत ॲप उपलब्धतेनुसार दिला जातो. या अटी कायदेशीररीत्या वगळता न येणारी जबाबदारी वगळत नाहीत किंवा तुम्हाला उपलब्ध अनिवार्य ग्राहक हक्क मर्यादित करत नाहीत.","उत्पादन सुविधा, पेमेंट पद्धती, प्लॅटफॉर्म नियम किंवा लागू कायदा बदलल्यास, आम्ही या अटी आणि पृष्ठावर दाखवलेली तारीख अपडेट करू शकतो. बदलामुळे वापरकर्त्यांच्या हक्कांवर महत्त्वपूर्ण परिणाम होत असल्यास, आवश्यकतेनुसार अतिरिक्त सूचना देऊ.","या अटी, खरेदी किंवा ॲपच्या वापरासंबंधी प्रश्नांसाठी, ईमेल करा. {email}"]}]},"support":{"title":"सहाय्य","lead":"सर्वप्रथम खालील नेहमीचे प्रश्न पाहा. समस्या कायम राहिल्यास सहाय्य ईमेल पत्त्याद्वारे आमच्याशी संपर्क साधा.","emailTitle":"{appName} सपोर्ट ईमेल","emailLead":"सर्वप्रथम खालील नेहमीचे प्रश्न पाहा. समस्या कायम राहिल्यास सहाय्य ईमेल पत्त्याद्वारे आमच्याशी संपर्क साधा.","beforeEmail":{"title":"तुमच्या ईमेलमध्ये काय समाविष्ट करावे","paragraphs":["खरेदीच्या समस्येसाठी तुम्ही ॲप स्टोअर ऑर्डर नंबर समाविष्ट करू शकता, पण खाते किंवा पेमेंट पासवर्ड अथवा संपूर्ण कार्ड माहिती पाठवू नका."],"bullets":["तुमचे प्लॅटफॉर्म, डिव्हाइस मॉडेल, ऑपरेटिंग सिस्टम आवृत्ती आणि ॲप आवृत्ती;","समस्येपूर्वी तुम्ही काय केले, तुम्हाला काय अपेक्षित होते आणि प्रत्यक्षात काय झाले; आणि","गरज भासल्यास, खाजगी माहिती लपवलेला स्क्रीनशॉट किंवा स्क्रीन रेकॉर्डिंग."]},"faqs":[{"question":"प्रतिमा सर्व्हरवर अपलोड केल्या जातात का?","answer":"प्रतिमा निवड, OCR, संवेदनशील मजकूर ओळख, संपादन आणि निर्यात डिव्हाइसवरच होते. ॲप क्लाउड प्रतिमा ओळख, क्लाउड सिंक किंवा खाते देत नाही. निर्यात करताना नवीन प्रतिमा तयार केली जाते आणि काढता येणारा खाजगी मेटाडेटा हटवला जातो. यशस्वी जतन, संपादन रद्द करणे किंवा सत्र संपल्यानंतर तात्पुरत्या फाइल्स हटवल्या जातात; जतन अयशस्वी झाल्यास पुन्हा प्रयत्नासाठी आवश्यक स्थिती ठेवली जाऊ शकते."},{"question":"परवानग्या, जाहिरात आणि ट्रॅकिंग","answer":"तुम्ही परवानगी दिलेल्या प्रतिमा दाखवण्यासाठी आणि प्रक्रिया करण्यासाठीच फोटो प्रवेश वापरला जातो. ॲपमध्ये फोटो काढणे निवडल्यावरच कॅमेरा वापरला जातो. वैध Premium सह निर्यात निश्चित करताना फोटो लायब्ररीत जतन करण्याची परवानगी मागितली जाते. ॲप स्थान, संपर्क, मायक्रोफोन, Bluetooth किंवा सूचनांची परवानगी मागत नाही."},{"question":"सशुल्क उत्पादने आणि किमती","answer":"ओळख आणि संपादनाला वापर मर्यादा नाही. प्रक्रिया केलेली प्रतिमा निर्यात करण्यासाठीच वैध Premium आवश्यक आहे. विनामूल्य चाचणीशिवाय स्वयं-नूतनीकरण होणाऱ्या साप्ताहिक व मासिक सदस्यता आणि एकदाच खरेदी करता येणारा आजीवन प्रवेश उपलब्ध आहे. App Store आणि Google Play खरेदी स्वतंत्र आहेत व प्लॅटफॉर्मदरम्यान हस्तांतरित करता येत नाहीत."},{"question":"जतन आणि प्रतिमा स्वरूप","answer":"जतन अयशस्वी झाल्यास मोकळी जागा, फोटो लायब्ररीत जतन करण्याची परवानगी आणि मूळ प्रतिमा वाचता येते का ते तपासून पुन्हा प्रयत्न करा. ॲप एका वेळी एक स्थिर प्रतिमा प्रक्रिया करते आणि बहुतेक सामान्य फॉरमॅट समर्थित आहेत; काही डिव्हाइस व सिस्टीम आवृत्तीवर अवलंबून असतात. व्हिडिओ, PDF, RAW/DNG आणि बॅच प्रक्रिया सध्या समर्थित नाही."},{"question":"भाषा कशी बदलावी?","answer":"ॲप 40 भाषांना समर्थन देतो आणि ॲपच्या सेटिंग्जमध्ये भाषा बदलता येते. प्रदर्शन चुकीचे असल्यास डिव्हाइसची भाषा आणि ॲपमध्ये निवडलेली भाषा ईमेल करा."},{"question":"पुनर्स्थापना, रद्द करणे आणि परतावे","answer":"खरेदी आणि खरेदी पुनर्स्थापना Apple किंवा Google च्या अधिकृत स्टोअरद्वारे पूर्ण केली जाते. स्टोअरने वैध व्यवहाराची पुष्टी केल्यानंतरच हक्क दिला जातो. रद्द, अयशस्वी किंवा प्रलंबित व्यवहार यशस्वी पुष्टीपूर्वी हक्क देत नाहीत. खरेदी पुनर्स्थापना आजीवन प्रवेश आणि सध्या सक्रिय सदस्यता पुनर्स्थापित करू शकते. App Store आणि Google Play खरेदी स्वतंत्र आहेत आणि प्लॅटफॉर्मदरम्यान पुनर्स्थापित किंवा हस्तांतरित करता येत नाहीत."},{"question":"गोपनीयता आणि डेटा हटवणे","answer":"ॲप अनइंस्टॉल करून डिव्हाइसवरील डेटा हटवा. Android वर तुम्ही सिस्टमचा डेटा साफ करा पर्यायही वापरू शकता. स्टोअर खरेदी नोंदी Apple किंवा Google व्यवस्थापित करते. पुनर्स्थापित करता येणाऱ्या हक्कांची स्टोअरच्या नियमांनुसार पुन्हा पुष्टी केली जाते. सहाय्य ईमेल विनंती हाताळण्यासाठी आणि आवश्यक नोंद-ठेव आवश्यकता पूर्ण करण्यासाठी आवश्यक असेपर्यंत ठेवले जातात. आमच्याकडे अजूनही असलेला सहाय्य पत्रव्यवहार हटवण्याची विनंती तुम्ही ईमेलद्वारे करू शकता."}],"officialHelpTitle":"त्वरित मदत"}},"ms":{"linkLabels":{"appleEula":"Perjanjian Lesen Pengguna Akhir Standard (EULA) Apple","appleCancel":"Arahan pembatalan langganan Apple","googleManage":"Arahan pembatalan Google Play","appleRefund":"Minta bayaran balik daripada Apple","googleRefund":"Maklumat bayaran balik Google Play"},"nav":{"privacy":"Dasar Privasi","terms":"Syarat Penggunaan","support":"Sokongan","language":"Bahasa","chooseLanguage":"Pilih bahasa paparan","navigationLabel":"Navigasi utama"},"home":{"eyebrow":"{appName} · Privacy first","title":"Imej anda tidak dimuat naik ke pelayan kami.","lead":"Pemilihan imej, OCR, pengesanan kandungan sensitif, pengeditan dan eksport dilakukan pada peranti. App tidak menyediakan pengecaman imej awan, penyegerakan awan atau akaun. Semasa eksport, imej baharu dicipta dan metadata privasi yang boleh dibuang dipadam. Fail kerja sementara dibersihkan selepas simpanan berjaya, apabila pengeditan ditinggalkan atau sesi tamat; jika simpanan gagal, keadaan yang diperlukan boleh disimpan untuk mencuba semula.","points":["Data aplikasi","Produk berbayar dan harga","Sokongan"],"cards":[{"title":"Dasar Privasi","description":"Imej anda tidak dimuat naik ke pelayan kami.","action":"Dasar Privasi"},{"title":"Syarat Penggunaan","description":"Pengecaman dan pengeditan tidak mempunyai had penggunaan. Hanya eksport imej yang diproses memerlukan akses Premium yang sah. App menawarkan langganan mingguan dan bulanan yang diperbaharui secara automatik serta pembelian seumur hidup sekali sahaja, tanpa percubaan percuma. Pembelian App Store dan Google Play adalah berasingan dan tidak boleh dipindahkan antara platform.","action":"Syarat Penggunaan"},{"title":"Perlukan bantuan?","description":"Mulakan dengan soalan lazim di bawah. Jika masalah berterusan, hubungi kami melalui alamat e-mel sokongan.","action":"Sokongan"}]},"footer":{"privacy":"Dasar Privasi","terms":"Syarat Penggunaan","support":"Sokongan"},"privacy":{"title":"Dasar Privasi","lead":"Dasar ini menerangkan cara {appName} mengendalikan data pada peranti, maklumat pembelian gedung aplikasi dan e-mel sokongan.","sections":[{"title":"1. Skop dan hubungan","paragraphs":["Dasar ini terpakai pada aplikasi {appName} untuk iOS, iPadOS dan Android, serta laman web privasi, terma dan sokongan ini.","Untuk soalan privasi, emel {email}"]},{"title":"2. Data aplikasi","callout":{"title":"Imej anda tidak dimuat naik ke pelayan kami.","body":"Pemilihan imej, OCR, pengesanan kandungan sensitif, pengeditan dan eksport dilakukan pada peranti. App tidak menyediakan pengecaman imej awan, penyegerakan awan atau akaun. Semasa eksport, imej baharu dicipta dan metadata privasi yang boleh dibuang dipadam. Fail kerja sementara dibersihkan selepas simpanan berjaya, apabila pengeditan ditinggalkan atau sesi tamat; jika simpanan gagal, keadaan yang diperlukan boleh disimpan untuk mencuba semula."},"paragraphs":[]},{"title":"3. Kebenaran, pengiklanan dan penjejakan","paragraphs":["Akses foto hanya digunakan untuk memaparkan dan memproses imej yang anda benarkan. Kamera hanya digunakan apabila anda memilih untuk mengambil foto dalam app. Kebenaran menyimpan ke pustaka foto hanya diminta apabila anda mengesahkan eksport dengan akses Premium yang sah. App tidak meminta lokasi, kenalan, mikrofon, Bluetooth atau pemberitahuan.","Aplikasi tidak menggunakan pengecam pengiklanan atau menyepadukan SDK pihak ketiga untuk pengiklanan, analitis, atribusi atau pelaporan ranap.","Aplikasi tidak menyepadukan alat pelaporan ranap pihak ketiga. Bergantung pada tetapan peranti dan gedung anda, Apple atau Google mungkin memproses maklumat diagnostik sistem di bawah peraturan privasi masing-masing dan menyediakan maklumat teknikal yang digunakan untuk menyiasat ranap atau masalah prestasi."]},{"title":"4. Perkhidmatan gedung aplikasi dan akses rangkaian","paragraphs":["Aplikasi menggunakan Apple StoreKit atau Google Play Billing untuk memuatkan produk, memaparkan harga setempat yang dikembalikan oleh gedung, melengkapkan pembelian, memulihkan pembelian, mengurus langganan dan mengesahkan kelayakan. Akses rangkaian hanya digunakan untuk fungsi rasmi gedung Apple atau Google ini.","Apple atau Google bertanggungjawab terhadap akaun gedung, pembayaran, pengebilan, transaksi, bayaran balik dan perkhidmatan langganan. Aplikasi hanya memproses maklumat gedung yang diperlukan untuk mengesahkan produk dan kelayakan serta tidak menerima atau menyimpan bukti kelayakan pembayaran penuh."]},{"title":"5. E-mel sokongan dan laman web","paragraphs":["Aplikasi tidak membaca maklumat e-mel anda secara automatik. Hanya apabila anda memilih untuk menghantar e-mel sokongan, saluran sokongan akan menerima alamat e-mel, mesej dan sebarang tangkap layar, rakaman skrin, nombor pesanan atau lampiran lain yang anda berikan secara sukarela. Maklumat ini hanya digunakan untuk mengendalikan permintaan anda dan tidak digunakan untuk pengiklanan atau pemasaran. Jangan hantar kata laluan akaun, kata laluan pembayaran atau nombor kad penuh.","Laman web ini tidak menetapkan kuki pengiklanan atau analitis dan tidak menyertakan analitis trafik atau skrip penjejakan."]},{"title":"6. Penyimpanan dan pemadaman","paragraphs":["Padam data pada peranti dengan menyahpasang aplikasi. Pada Android, anda juga boleh menggunakan pilihan Kosongkan data pada sistem.","Rekod pembelian gedung diurus oleh Apple atau Google. Kelayakan yang boleh dipulihkan akan disahkan semula di bawah peraturan gedung.","E-mel sokongan disimpan selama yang diperlukan untuk mengendalikan permintaan dan memenuhi keperluan penyimpanan rekod yang perlu. Anda boleh menghantar e-mel kepada kami untuk meminta pemadaman surat-menyurat sokongan yang masih kami simpan."]},{"title":"7. Keselamatan data","paragraphs":["Aplikasi menggunakan pemprosesan pada peranti, kebenaran minimum dan aliran pembelian rasmi gedung aplikasi untuk mengurangkan pemindahan data yang tidak perlu. E-mel sokongan hanya digunakan untuk mengendalikan permintaan masuk, dengan perlindungan munasabah yang sesuai dengan sifat maklumat.","Tiada peranti, rangkaian atau kaedah storan elektronik yang boleh dijamin selamat sepenuhnya. Jangan sertakan maklumat sensitif yang tidak berkaitan dalam e-mel sokongan."]},{"title":"8. Kanak-kanak dan remaja","paragraphs":["Aplikasi tidak memerlukan akaun dan tidak membina profil kanak-kanak atau pengguna lain melalui pengiklanan atau analitis tingkah laku. Ibu bapa atau penjaga yang percaya bahawa seorang kanak-kanak memberikan maklumat peribadi melalui e-mel sokongan boleh menghubungi kami supaya perkara tersebut dapat ditangani."]},{"title":"9. Pilihan dan hak anda","paragraphs":["Anda mengurus data pada peranti melalui peranti anda. Apple atau Google mengurus akaun gedung dan rekod pembelian. Aplikasi tidak boleh mengubah atau memadam rekod transaksi yang disimpan oleh gedung aplikasi bagi pihak anda.","Jika amalan data aplikasi, peraturan platform atau aturan pengehosan laman web berubah, kami akan mengemas kini Dasar ini dan tarikh yang dipaparkan pada halaman ini serta memberikan notis tambahan apabila diperlukan oleh peraturan yang terpakai.","Untuk soalan privasi, emel {email}"]}]},"terms":{"title":"Syarat Penggunaan","lead":"{appName} Syarat Penggunaan.","sections":[{"title":"1. Menerima Terma dan peraturan platform ini","paragraphs":["Dengan memuat turun, membeli atau menggunakan {appName}, anda bersetuju dengan Terma ini dan peraturan yang terpakai kepada anda di gedung aplikasi tempat anda membuat pembelian. Jika anda tidak bersetuju, jangan terus menggunakan aplikasi atau membuat pembelian.","Terma ini terpakai pada muat turun, pembelian dan penggunaan aplikasi oleh anda. Versi iOS dan iPadOS juga tertakluk pada"],"links":["appleEula"]},{"title":"2. Produk berbayar dan harga","paragraphs":["Pengecaman dan pengeditan tidak mempunyai had penggunaan. Hanya eksport imej yang diproses memerlukan akses Premium yang sah. App menawarkan langganan mingguan dan bulanan yang diperbaharui secara automatik serta pembelian seumur hidup sekali sahaja, tanpa percubaan percuma. Pembelian App Store dan Google Play adalah berasingan dan tidak boleh dipindahkan antara platform.","Harga, mata wang, cukai, tempoh pengebilan dan kelayakan pembelian sebenar ialah maklumat yang dipaparkan dan disahkan pada skrin pembelian sistem App Store atau Google Play. Platform pembelian mengenakan caj dan mengurus pembayaran melalui akaun gedung anda. Aplikasi tidak menawarkan percubaan percuma langganan atau pelan berbayar lain."]},{"title":"3. Pembaharuan automatik dan pembatalan","paragraphs":["Langganan mingguan dan bulanan diperbaharui secara automatik dan dikenakan caj untuk tempoh pengebilan yang ditunjukkan pada skrin pembelian sistem sehingga anda membatalkannya melalui platform pembelian. Memadam {appName} tidak membatalkan langganan secara automatik. Melainkan platform pembelian memberikan bayaran balik atau layanan lain, anda boleh terus menggunakan langganan sehingga akhir tempoh berbayar semasa selepas mematikan pembaharuan automatik."],"links":["appleCancel","googleManage"]},{"title":"4. Pembelian, pemulihan dan bayaran balik","paragraphs":["Pembelian dan pemulihan pembelian diselesaikan melalui gedung rasmi Apple atau Google. Kelayakan hanya diberikan selepas gedung mengesahkan transaksi yang sah. Transaksi yang dibatalkan, gagal atau belum selesai tidak memberikan kelayakan sebelum pengesahan berjaya. Pemulihan pembelian boleh memulihkan akses seumur hidup dan langganan yang sedang aktif. Pembelian App Store dan Google Play adalah berasingan dan tidak boleh dipulihkan atau dipindahkan merentas platform.","Bayaran balik dikendalikan oleh gedung aplikasi yang melengkapkan transaksi mengikut peraturannya, rantau pembelian dan undang-undang yang terpakai. Kelayakan berkaitan akan dialih keluar selepas gedung mengesahkan bayaran balik, penarikan balik, tamat tempoh langganan atau transaksi yang tidak sah."],"links":["appleRefund","googleRefund"]},{"title":"5. Penggunaan luar talian dan ketersediaan","paragraphs":["Pemilihan imej, OCR, pengesanan kandungan sensitif, pengeditan dan eksport dilakukan pada peranti. App tidak menyediakan pengecaman imej awan, penyegerakan awan atau akaun. Semasa eksport, imej baharu dicipta dan metadata privasi yang boleh dibuang dipadam. Fail kerja sementara dibersihkan selepas simpanan berjaya, apabila pengeditan ditinggalkan atau sesi tamat; jika simpanan gagal, keadaan yang diperlukan boleh disimpan untuk mencuba semula."]},{"title":"6. Penggunaan yang boleh diterima dan harta intelek","paragraphs":["Anda tidak boleh menggunakan aplikasi untuk aktiviti yang menyalahi undang-undang; memintas pengesahan pembelian; merosakkan aplikasi; mengedarkan kod hasad; menyalin atau mengedarkan aplikasi tanpa kebenaran; atau melanggar hak dalam kandungan aplikasi atau harta intelek orang lain.","Anda boleh berhenti menggunakan dan menyahpasang aplikasi pada bila-bila masa. Kami mungkin mengeluarkan kemas kini untuk membetulkan masalah, menyokong sistem pengendalian, meningkatkan kestabilan atau memenuhi keperluan platform. Masalah peranti, sistem, rangkaian atau perkhidmatan gedung mungkin menyebabkan sesetengah ciri tidak tersedia buat sementara waktu.","Setakat yang dibenarkan oleh undang-undang yang terpakai, aplikasi disediakan mengikut ketersediaan. Terma ini tidak mengecualikan liabiliti yang tidak boleh dikecualikan secara sah atau mengehadkan hak mandatori pengguna yang tersedia kepada anda.","Jika ciri produk, kaedah pembayaran, peraturan platform atau undang-undang yang terpakai berubah, kami mungkin mengemas kini Terma ini dan tarikh yang dipaparkan pada halaman. Jika perubahan memberi kesan ketara kepada hak pengguna, kami akan memberikan notis tambahan seperti yang diperlukan.","Untuk pertanyaan tentang Terma, pembelian atau penggunaan aplikasi ini, emel {email}"]}]},"support":{"title":"Sokongan","lead":"Mulakan dengan soalan lazim di bawah. Jika masalah berterusan, hubungi kami melalui alamat e-mel sokongan.","emailTitle":"E-mel sokongan {appName}","emailLead":"Mulakan dengan soalan lazim di bawah. Jika masalah berterusan, hubungi kami melalui alamat e-mel sokongan.","beforeEmail":{"title":"Perkara yang perlu disertakan dalam e-mel anda","paragraphs":["Untuk masalah pembelian, anda boleh menyertakan nombor pesanan gedung aplikasi, tetapi jangan hantar kata laluan akaun, kata laluan pembayaran atau maklumat kad penuh."],"bullets":["platform, model peranti, versi sistem pengendalian dan versi aplikasi anda;","perkara yang anda lakukan sebelum masalah, perkara yang anda jangkakan dan perkara yang sebenarnya berlaku; dan","jika perlu, tangkapan skrin atau rakaman skrin dengan maklumat peribadi disembunyikan."]},"faqs":[{"question":"Adakah imej dimuat naik ke pelayan?","answer":"Pemilihan imej, OCR, pengesanan kandungan sensitif, pengeditan dan eksport dilakukan pada peranti. App tidak menyediakan pengecaman imej awan, penyegerakan awan atau akaun. Semasa eksport, imej baharu dicipta dan metadata privasi yang boleh dibuang dipadam. Fail kerja sementara dibersihkan selepas simpanan berjaya, apabila pengeditan ditinggalkan atau sesi tamat; jika simpanan gagal, keadaan yang diperlukan boleh disimpan untuk mencuba semula."},{"question":"Kebenaran, pengiklanan dan penjejakan","answer":"Akses foto hanya digunakan untuk memaparkan dan memproses imej yang anda benarkan. Kamera hanya digunakan apabila anda memilih untuk mengambil foto dalam app. Kebenaran menyimpan ke pustaka foto hanya diminta apabila anda mengesahkan eksport dengan akses Premium yang sah. App tidak meminta lokasi, kenalan, mikrofon, Bluetooth atau pemberitahuan."},{"question":"Produk berbayar dan harga","answer":"Pengecaman dan pengeditan tidak mempunyai had penggunaan. Hanya eksport imej yang diproses memerlukan akses Premium yang sah. App menawarkan langganan mingguan dan bulanan yang diperbaharui secara automatik serta pembelian seumur hidup sekali sahaja, tanpa percubaan percuma. Pembelian App Store dan Google Play adalah berasingan dan tidak boleh dipindahkan antara platform."},{"question":"Penyimpanan dan format imej","answer":"Jika simpanan gagal, semak ruang kosong, kebenaran menyimpan ke pustaka foto dan sama ada imej asal masih boleh dibaca, kemudian cuba lagi. App memproses satu imej pegun pada satu masa dan menyokong kebanyakan format biasa; sesetengah format bergantung pada peranti dan versi sistem. Video, PDF, RAW/DNG dan pemprosesan kelompok tidak disokong buat masa ini."},{"question":"Bagaimanakah cara menukar bahasa?","answer":"Aplikasi menyokong 40 bahasa dan bahasa boleh ditukar dalam tetapan aplikasi. Jika paparan tidak betul, e-melkan bahasa peranti dan bahasa yang dipilih dalam aplikasi."},{"question":"Pemulihan, pembatalan dan bayaran balik","answer":"Pembelian dan pemulihan pembelian diselesaikan melalui gedung rasmi Apple atau Google. Kelayakan hanya diberikan selepas gedung mengesahkan transaksi yang sah. Transaksi yang dibatalkan, gagal atau belum selesai tidak memberikan kelayakan sebelum pengesahan berjaya. Pemulihan pembelian boleh memulihkan akses seumur hidup dan langganan yang sedang aktif. Pembelian App Store dan Google Play adalah berasingan dan tidak boleh dipulihkan atau dipindahkan merentas platform."},{"question":"Privasi dan pemadaman data","answer":"Padam data pada peranti dengan menyahpasang aplikasi. Pada Android, anda juga boleh menggunakan pilihan Kosongkan data pada sistem. Rekod pembelian gedung diurus oleh Apple atau Google. Kelayakan yang boleh dipulihkan akan disahkan semula di bawah peraturan gedung. E-mel sokongan disimpan selama yang diperlukan untuk mengendalikan permintaan dan memenuhi keperluan penyimpanan rekod yang perlu. Anda boleh menghantar e-mel kepada kami untuk meminta pemadaman surat-menyurat sokongan yang masih kami simpan."}],"officialHelpTitle":"Bantuan pantas"}},"nb":{"linkLabels":{"appleEula":"Apples standard lisensavtale for sluttbrukere (EULA)","appleCancel":"Instruksjoner for oppsigelse av Apple-abonnement","googleManage":"Veiledning for oppsigelse i Google Play","appleRefund":"Be om refusjon fra Apple","googleRefund":"Informasjon om refusjon i Google Play"},"nav":{"privacy":"Personvernerklæring","terms":"Bruksvilkår","support":"Støtte","language":"Språk","chooseLanguage":"Velg visningsspråk","navigationLabel":"Primærnavigasjon"},"home":{"eyebrow":"{appName} · Privacy first","title":"Bildene dine lastes ikke opp til serverne våre.","lead":"Bildevalg, OCR, oppdagelse av sensitivt innhold, redigering og eksport skjer på enheten. Appen tilbyr ikke bildegjenkjenning eller synkronisering i skyen og har ingen kontoer. Ved eksport opprettes et nytt bilde, og flyttbare private metadata slettes. Midlertidige arbeidsfiler fjernes etter vellykket lagring, når redigeringen forkastes eller økten avsluttes; hvis lagring mislykkes, kan nødvendig tilstand beholdes for å prøve på nytt.","points":["Appdata","Betalte produkter og priser","Støtte"],"cards":[{"title":"Personvernerklæring","description":"Bildene dine lastes ikke opp til serverne våre.","action":"Personvernerklæring"},{"title":"Bruksvilkår","description":"Gjenkjenning og redigering har ingen bruksgrenser. Bare eksport av det behandlede bildet krever gyldig Premium-tilgang. Appen tilbyr automatisk fornybare uke- og månedsabonnementer og et engangskjøp med livstidstilgang, uten gratis prøveperiode. Kjøp i App Store og Google Play er separate og kan ikke overføres mellom plattformene.","action":"Bruksvilkår"},{"title":"Trenger du hjelp?","description":"Start med de vanlige spørsmålene nedenfor. Hvis problemet fortsetter, kan du kontakte oss via e-postadressen til brukerstøtten.","action":"Støtte"}]},"footer":{"privacy":"Personvernerklæring","terms":"Bruksvilkår","support":"Støtte"},"privacy":{"title":"Personvernerklæring","lead":"Disse personvernreglene forklarer hvordan {appName} håndterer data på enheten, kjøpsinformasjon fra appbutikken og e-post til brukerstøtten.","sections":[{"title":"1. Omfang og kontakt","paragraphs":["Disse personvernreglene gjelder {appName}-appen for iOS, iPadOS og Android samt dette nettstedet for personvern, vilkår og brukerstøtte.","For spørsmål om personvern, send e-post {email}"]},{"title":"2. Appdata","callout":{"title":"Bildene dine lastes ikke opp til serverne våre.","body":"Bildevalg, OCR, oppdagelse av sensitivt innhold, redigering og eksport skjer på enheten. Appen tilbyr ikke bildegjenkjenning eller synkronisering i skyen og har ingen kontoer. Ved eksport opprettes et nytt bilde, og flyttbare private metadata slettes. Midlertidige arbeidsfiler fjernes etter vellykket lagring, når redigeringen forkastes eller økten avsluttes; hvis lagring mislykkes, kan nødvendig tilstand beholdes for å prøve på nytt."},"paragraphs":[]},{"title":"3. Tillatelser, annonsering og sporing","paragraphs":["Fototilgang brukes bare til å vise og behandle bilder du godkjenner. Kameraet brukes bare når du velger å ta et bilde i appen. Tillatelse til å lagre i bildebiblioteket blir bare bedt om når du bekrefter eksport med gyldig Premium-tilgang. Appen ber ikke om posisjon, kontakter, mikrofon, Bluetooth eller varsler.","Den bruker ikke en annonseidentifikator og integrerer ikke SDK-er fra tredjeparter for annonsering, analyse, attribusjon eller krasjrapportering.","Appen integrerer ikke et tredjepartsverktøy for krasjrapportering. Avhengig av innstillingene på enheten og i butikken kan Apple eller Google behandle systemdiagnostikk etter sine respektive personvernregler og levere teknisk informasjon som brukes til å undersøke krasj eller ytelsesproblemer."]},{"title":"4. Appbutikktjenester og nettverkstilgang","paragraphs":["Appen bruker Apple StoreKit eller Google Play Billing til å laste inn produkter, vise lokaliserte priser fra butikken, fullføre kjøp, gjenopprette kjøp, administrere abonnementer og bekrefte tilganger. Nettverkstilgang brukes bare til disse offisielle butikktjenestene fra Apple eller Google.","Apple eller Google er ansvarlig for butikkontoer, betalinger, fakturering, transaksjoner, refusjoner og abonnementstjenester. Appen behandler bare butikkinformasjonen som er nødvendig for å bekrefte produkter og tilganger, og mottar eller lagrer ikke fullstendige betalingsopplysninger."]},{"title":"5. E-post til brukerstøtten og nettstedet","paragraphs":["Appen leser ikke e-postinformasjonen din automatisk. Bare når du selv velger å sende en e-post til brukerstøtten, mottar støttekanalen e-postadressen din, meldingen din og eventuelle skjermbilder, skjermopptak, ordrenumre eller andre vedlegg du frivillig sender. Informasjonen brukes bare til å behandle henvendelsen din og ikke til annonsering eller markedsføring. Ikke send passord til kontoer eller betaling eller fullstendige kortnumre.","Dette nettstedet bruker ikke informasjonskapsler for annonsering eller analyse og inneholder ikke trafikkanalyse eller sporingsskript."]},{"title":"6. Lagring og sletting","paragraphs":["Slett data på enheten ved å avinstallere appen. På Android kan du også bruke systemets funksjon Tøm data.","Kjøpsoppføringer administreres av Apple eller Google. Tilganger som kan gjenopprettes, bekreftes på nytt etter butikkens regler.","E-post til brukerstøtten lagres så lenge det er nødvendig for å behandle henvendelsen og oppfylle nødvendige krav til dokumentasjon. Du kan sende oss en e-post for å be om sletting av støttekommunikasjon vi fortsatt oppbevarer."]},{"title":"7. Datasikkerhet","paragraphs":["Appen bruker behandling på enheten, færrest mulig tillatelser og offisielle kjøpsprosesser i appbutikken for å redusere unødvendige dataoverføringer. E-post til brukerstøtten brukes bare til å behandle innkommende henvendelser, med rimelige sikkerhetstiltak tilpasset informasjonens art.","Ingen enhet, nettverk eller elektronisk lagringsmetode kan garanteres å være helt sikker. Ikke ta med uvedkommende sensitiv informasjon i en e-post til brukerstøtten."]},{"title":"8. Barn og unge","paragraphs":["Appen krever ikke en konto og oppretter ikke profiler av barn eller andre brukere gjennom annonsering eller atferdsanalyse. En forelder eller verge som mener at et barn har gitt personopplysninger i en e-post til brukerstøtten, kan kontakte oss for å få saken behandlet."]},{"title":"9. Valgene og rettighetene dine","paragraphs":["Du administrerer data på enheten via enheten din. Apple eller Google administrerer butikkontoer og kjøpsoppføringer. Appen kan ikke endre eller slette transaksjonsoppføringer som en appbutikk oppbevarer på dine vegne.","Hvis appens datapraksis, plattformreglene eller nettstedets hosting endres, oppdaterer vi disse personvernreglene og datoen på siden og gir ytterligere varsel der gjeldende regler krever det.","For spørsmål om personvern, send e-post {email}"]}]},"terms":{"title":"Bruksvilkår","lead":"{appName} Bruksvilkår.","sections":[{"title":"1. Godta disse vilkårene og plattformreglene","paragraphs":["Ved å laste ned, kjøpe eller bruke {appName}, godtar du disse vilkårene og reglene som gjelder for deg i appbutikken der du foretar et kjøp. Hvis du ikke godtar, må du ikke fortsette å bruke appen eller foreta et kjøp.","Disse vilkårene gjelder når du laster ned, kjøper og bruker appen. iOS- og iPadOS-versjonene er også underlagt"],"links":["appleEula"]},{"title":"2. Betalte produkter og priser","paragraphs":["Gjenkjenning og redigering har ingen bruksgrenser. Bare eksport av det behandlede bildet krever gyldig Premium-tilgang. Appen tilbyr automatisk fornybare uke- og månedsabonnementer og et engangskjøp med livstidstilgang, uten gratis prøveperiode. Kjøp i App Store og Google Play er separate og kan ikke overføres mellom plattformene.","Faktisk pris, valuta, avgifter, faktureringsperiode og kjøpsmulighet er informasjonen som vises og bekreftes på systemets kjøpsskjerm i App Store eller Google Play. Kjøpsplattformen belaster og administrerer betalingen via butikkontoen din. Appen tilbyr ikke en gratis prøveperiode for abonnement eller andre betalingsplaner."]},{"title":"3. Automatisk fornyelse og oppsigelse","paragraphs":["Ukentlige og månedlige abonnementer fornyes automatisk og belastes for faktureringsperioden som vises på systemets kjøpsskjerm, til du sier opp via kjøpsplattformen. Et abonnement sies ikke opp automatisk når {appName} slettes. Med mindre kjøpsplattformen gir refusjon eller annen behandling, kan du fortsette å bruke abonnementet til slutten av den gjeldende betalte perioden etter at automatisk fornyelse er slått av."],"links":["appleCancel","googleManage"]},{"title":"4. Kjøp, gjenoppretting og refusjon","paragraphs":["Kjøp og gjenoppretting av kjøp gjennomføres via den offisielle Apple- eller Google-butikken. Tilgang gis først etter at butikken har bekreftet en gyldig transaksjon. Avbrutte, mislykkede eller ventende transaksjoner gir ikke tilgang før vellykket bekreftelse. Gjenoppretting av kjøp kan gjenopprette livstidstilgang og et aktivt abonnement. Kjøp i App Store og Google Play er separate og kan ikke gjenopprettes eller overføres på tvers av plattformer.","Refusjoner håndteres av appbutikken som gjennomførte transaksjonen, etter butikkens regler, kjøpsregionen og gjeldende lov. Den tilhørende tilgangen fjernes når butikken bekrefter refusjon, tilbakekalling, utløpt abonnement eller ugyldig transaksjon."],"links":["appleRefund","googleRefund"]},{"title":"5. Bruk uten nett og tilgjengelighet","paragraphs":["Bildevalg, OCR, oppdagelse av sensitivt innhold, redigering og eksport skjer på enheten. Appen tilbyr ikke bildegjenkjenning eller synkronisering i skyen og har ingen kontoer. Ved eksport opprettes et nytt bilde, og flyttbare private metadata slettes. Midlertidige arbeidsfiler fjernes etter vellykket lagring, når redigeringen forkastes eller økten avsluttes; hvis lagring mislykkes, kan nødvendig tilstand beholdes for å prøve på nytt."]},{"title":"6. Akseptabel bruk og immaterielle rettigheter","paragraphs":["Du må ikke bruke appen til ulovlig aktivitet, omgå kjøpsbekreftelse, skade appen, distribuere skadelig kode, kopiere eller distribuere appen uten tillatelse eller krenke rettigheter til appinnhold eller en annen persons immaterielle rettigheter.","Du kan når som helst slutte å bruke og avinstallere appen. Vi kan utgi oppdateringer for å rette problemer, støtte operativsystemer, forbedre stabiliteten eller oppfylle plattformkrav. Problemer med enheten, systemet, nettverket eller butikktjenesten kan gjøre enkelte funksjoner midlertidig utilgjengelige.","I den grad gjeldende lov tillater det, leveres appen slik den er tilgjengelig. Disse vilkårene utelukker ikke ansvar som ikke lovlig kan utelukkes, og begrenser ikke ufravikelige forbrukerrettigheter du har.","Hvis produktfunksjoner, betalingsmetoder, plattformregler eller gjeldende lov endres, kan vi oppdatere disse vilkårene og datoen på siden. Hvis en endring påvirker brukernes rettigheter vesentlig, gir vi ytterligere varsel som påkrevd.","For spørsmål om disse vilkårene, kjøp eller bruk av appen, send e-post {email}"]}]},"support":{"title":"Støtte","lead":"Start med de vanlige spørsmålene nedenfor. Hvis problemet fortsetter, kan du kontakte oss via e-postadressen til brukerstøtten.","emailTitle":"{appName} brukerstøtte-e-post","emailLead":"Start med de vanlige spørsmålene nedenfor. Hvis problemet fortsetter, kan du kontakte oss via e-postadressen til brukerstøtten.","beforeEmail":{"title":"Dette bør du ta med i e-posten","paragraphs":["Ved et kjøpsproblem kan du ta med ordrenummeret fra appbutikken, men ikke send passordet til kontoen eller betalingen eller fullstendige kortopplysninger."],"bullets":["plattform, enhetsmodell, operativsystemversjon og appversjon;","hva du gjorde før problemet, hva du forventet og hva som faktisk skjedde; og","om nødvendig, et skjermbilde eller skjermopptak med skjult privat informasjon."]},"faqs":[{"question":"Lastes bilder opp til en server?","answer":"Bildevalg, OCR, oppdagelse av sensitivt innhold, redigering og eksport skjer på enheten. Appen tilbyr ikke bildegjenkjenning eller synkronisering i skyen og har ingen kontoer. Ved eksport opprettes et nytt bilde, og flyttbare private metadata slettes. Midlertidige arbeidsfiler fjernes etter vellykket lagring, når redigeringen forkastes eller økten avsluttes; hvis lagring mislykkes, kan nødvendig tilstand beholdes for å prøve på nytt."},{"question":"Tillatelser, annonsering og sporing","answer":"Fototilgang brukes bare til å vise og behandle bilder du godkjenner. Kameraet brukes bare når du velger å ta et bilde i appen. Tillatelse til å lagre i bildebiblioteket blir bare bedt om når du bekrefter eksport med gyldig Premium-tilgang. Appen ber ikke om posisjon, kontakter, mikrofon, Bluetooth eller varsler."},{"question":"Betalte produkter og priser","answer":"Gjenkjenning og redigering har ingen bruksgrenser. Bare eksport av det behandlede bildet krever gyldig Premium-tilgang. Appen tilbyr automatisk fornybare uke- og månedsabonnementer og et engangskjøp med livstidstilgang, uten gratis prøveperiode. Kjøp i App Store og Google Play er separate og kan ikke overføres mellom plattformene."},{"question":"Lagring og bildeformater","answer":"Hvis lagring mislykkes, kontroller ledig plass, tillatelsen til å lagre i bildebiblioteket og at originalbildet fortsatt kan leses, og prøv på nytt. Appen behandler ett stillbilde om gangen og støtter de fleste vanlige formater; enkelte avhenger av enhet og systemversjon. Video, PDF, RAW/DNG og gruppebehandling støttes ikke nå."},{"question":"Hvordan endrer jeg språk?","answer":"Appen støtter 40 språk, og språket kan endres i appens innstillinger. Hvis visningen er feil, sender du en e-post med enhetens språk og språket som er valgt i appen."},{"question":"Gjenoppretting, oppsigelse og refusjon","answer":"Kjøp og gjenoppretting av kjøp gjennomføres via den offisielle Apple- eller Google-butikken. Tilgang gis først etter at butikken har bekreftet en gyldig transaksjon. Avbrutte, mislykkede eller ventende transaksjoner gir ikke tilgang før vellykket bekreftelse. Gjenoppretting av kjøp kan gjenopprette livstidstilgang og et aktivt abonnement. Kjøp i App Store og Google Play er separate og kan ikke gjenopprettes eller overføres på tvers av plattformer."},{"question":"Personvern og sletting av data","answer":"Slett data på enheten ved å avinstallere appen. På Android kan du også bruke systemets funksjon Tøm data. Kjøpsoppføringer administreres av Apple eller Google. Tilganger som kan gjenopprettes, bekreftes på nytt etter butikkens regler. E-post til brukerstøtten lagres så lenge det er nødvendig for å behandle henvendelsen og oppfylle nødvendige krav til dokumentasjon. Du kan sende oss en e-post for å be om sletting av støttekommunikasjon vi fortsatt oppbevarer."}],"officialHelpTitle":"Rask hjelp"}},"nl":{"linkLabels":{"appleEula":"Standaardlicentieovereenkomst voor eindgebruikers van Apple (EULA)","appleCancel":"Instructies voor het annuleren van een Apple-abonnement","googleManage":"Instructies voor opzegging via Google Play","appleRefund":"Vraag een terugbetaling aan bij Apple.","googleRefund":"Informatie over terugbetalingen van Google Play"},"nav":{"privacy":"Privacybeleid","terms":"Gebruiksvoorwaarden","support":"Ondersteuning","language":"Taal","chooseLanguage":"Selecteer de weergavetaal","navigationLabel":"Hoofdnavigatie"},"home":{"eyebrow":"{appName} · Privacy first","title":"Je afbeeldingen worden niet naar onze servers geüpload.","lead":"Afbeeldingen kiezen, OCR, detectie van gevoelige inhoud, bewerken en exporteren gebeurt op je apparaat. De app biedt geen beeldherkenning of synchronisatie in de cloud en heeft geen accounts. Bij export wordt een nieuwe afbeelding gemaakt en worden verwijderbare privacygevoelige metadata gewist. Tijdelijke werkbestanden worden verwijderd na een geslaagde opslag, wanneer je de bewerking verlaat of wanneer de sessie eindigt; na een opslagfout kan de benodigde status blijven staan om opnieuw te proberen.","points":["Appgegevens","Betaalde producten en prijzen","Ondersteuning"],"cards":[{"title":"Privacybeleid","description":"Je afbeeldingen worden niet naar onze servers geüpload.","action":"Privacybeleid"},{"title":"Gebruiksvoorwaarden","description":"Herkenning en bewerking hebben geen gebruikslimiet. Alleen voor het exporteren van de verwerkte afbeelding is geldige Premium-toegang nodig. Er zijn automatisch verlengende week- en maandabonnementen en een eenmalige levenslange aankoop, zonder gratis proefperiode. Aankopen in de App Store en Google Play zijn gescheiden en kunnen niet tussen platforms worden overgedragen.","action":"Gebruiksvoorwaarden"},{"title":"Hulp nodig?","description":"Bekijk eerst de veelgestelde vragen hieronder. Als het probleem blijft bestaan, neem dan contact op via het e-mailadres voor ondersteuning.","action":"Ondersteuning"}]},"footer":{"privacy":"Privacybeleid","terms":"Gebruiksvoorwaarden","support":"Ondersteuning"},"privacy":{"title":"Privacybeleid","lead":"Dit Beleid legt uit hoe {appName} gegevens op het apparaat, aankoopgegevens van de appwinkel en ondersteuningsmails verwerkt.","sections":[{"title":"1. Omvang en contactgegevens","paragraphs":["Dit Beleid geldt voor de app {appName} op iOS, iPadOS en Android en voor deze website over privacy, voorwaarden en ondersteuning.","Voor vragen over privacy kunt u een e-mail sturen. {email}"]},{"title":"2. Appgegevens","callout":{"title":"Je afbeeldingen worden niet naar onze servers geüpload.","body":"Afbeeldingen kiezen, OCR, detectie van gevoelige inhoud, bewerken en exporteren gebeurt op je apparaat. De app biedt geen beeldherkenning of synchronisatie in de cloud en heeft geen accounts. Bij export wordt een nieuwe afbeelding gemaakt en worden verwijderbare privacygevoelige metadata gewist. Tijdelijke werkbestanden worden verwijderd na een geslaagde opslag, wanneer je de bewerking verlaat of wanneer de sessie eindigt; na een opslagfout kan de benodigde status blijven staan om opnieuw te proberen."},"paragraphs":[]},{"title":"3. Machtigingen, reclame en tracking","paragraphs":["Fototoegang wordt alleen gebruikt om afbeeldingen te tonen en te verwerken waarvoor je toestemming geeft. De camera wordt alleen gebruikt wanneer je in de app een foto maakt. Toestemming om in de fotobibliotheek op te slaan wordt alleen gevraagd wanneer je export bevestigt met geldige Premium-toegang. De app vraagt niet om locatie, contacten, microfoon, Bluetooth of meldingen.","De app gebruikt geen reclame-id en integreert geen SDK’s van derden voor reclame, analyse, attributie of crashrapportage.","De app integreert geen crashrapportagetool van derden. Afhankelijk van je apparaat- en winkelinstellingen kunnen Apple of Google systeemdiagnosegegevens volgens hun eigen privacyregels verwerken en technische informatie verstrekken om crashes of prestatieproblemen te onderzoeken."]},{"title":"4. Appwinkeldiensten en netwerktoegang","paragraphs":["De app gebruikt Apple StoreKit of Google Play Billing om producten te laden, door de winkel geleverde lokale prijzen te tonen, aankopen te voltooien en te herstellen, abonnementen te beheren en toegang te bevestigen. Netwerktoegang wordt alleen voor deze officiële winkelmogelijkheden van Apple of Google gebruikt.","Apple of Google is verantwoordelijk voor winkelaccounts, betalingen, facturering, transacties, terugbetalingen en abonnementsdiensten. De app verwerkt alleen winkelgegevens die nodig zijn om producten en toegang te bevestigen en ontvangt of bewaart geen volledige betaalgegevens."]},{"title":"5. Ondersteuningsmails en website","paragraphs":["De app leest je e-mailgegevens niet automatisch. Alleen wanneer je een ondersteuningsmail verzendt, ontvangt het ondersteuningskanaal je e-mailadres, bericht en vrijwillig meegestuurde schermafbeeldingen, schermopnamen, bestelnummers of andere bijlagen. Deze informatie wordt uitsluitend gebruikt om je verzoek te behandelen en niet voor reclame of marketing. Stuur geen account- of betaalwachtwoorden en geen volledige kaartnummers.","Deze website plaatst geen reclame- of analysecookies en bevat geen scripts voor bezoekersanalyse of tracking."]},{"title":"6. Bewaring en verwijdering","paragraphs":["Verwijder gegevens op het apparaat door de app te verwijderen. Op Android kun je ook de systeemoptie ‘Gegevens wissen’ gebruiken.","Aankoopgegevens worden beheerd door Apple of Google. Herstelbare toegang wordt opnieuw bevestigd volgens de regels van de winkel.","Ondersteuningsmails worden bewaard zolang dat nodig is om het verzoek te behandelen en aan noodzakelijke bewaarplichten te voldoen. Je kunt ons mailen om verwijdering te vragen van ondersteuningscorrespondentie die we nog bewaren."]},{"title":"7. Gegevensbeveiliging","paragraphs":["De app gebruikt verwerking op het apparaat, minimale machtigingen en officiële aankoopprocessen van appwinkels om onnodige gegevensoverdracht te beperken. Ondersteuningsmails worden alleen gebruikt om binnenkomende verzoeken te behandelen, met redelijke beveiligingsmaatregelen die passen bij de aard van de informatie.","Geen enkel apparaat, netwerk of elektronisch opslagmiddel kan volledig veilig worden gegarandeerd. Neem geen niet-relevante gevoelige informatie op in een ondersteuningsmail."]},{"title":"8. Kinderen en jongeren","paragraphs":["De app vereist geen account en maakt via reclame of gedragsanalyse geen profielen van kinderen of andere gebruikers. Een ouder of voogd die denkt dat een kind persoonsgegevens via een ondersteuningsmail heeft verstrekt, kan contact opnemen om dit te laten behandelen."]},{"title":"9. Je keuzes en rechten","paragraphs":["Je beheert lokale gegevens via je apparaat. Apple of Google beheert winkelaccounts en aankoopgegevens. De app kan transactiegegevens die een appwinkel bewaart niet namens jou wijzigen of verwijderen.","Als de gegevenspraktijken van de app, platformregels of hosting van de website veranderen, werken we dit Beleid en de datum op deze pagina bij en geven we extra kennisgeving wanneer toepasselijke regels dat vereisen.","Voor vragen over privacy kunt u een e-mail sturen. {email}"]}]},"terms":{"title":"Gebruiksvoorwaarden","lead":"{appName} Gebruiksvoorwaarden.","sections":[{"title":"1. Acceptatie van deze voorwaarden en platformregels","paragraphs":["Door {appName} te downloaden, te kopen of te gebruiken, gaat u akkoord met deze voorwaarden en met de regels die op u van toepassing zijn in de app store waar u de aankoop doet. Als u niet akkoord gaat, dient u de app niet verder te gebruiken of een aankoop te doen.","Deze Voorwaarden gelden voor het downloaden, kopen en gebruiken van de app. Op de iOS- en iPadOS-versies is ook de volgende overeenkomst van toepassing:"],"links":["appleEula"]},{"title":"2. Betaalde producten en prijzen","paragraphs":["Herkenning en bewerking hebben geen gebruikslimiet. Alleen voor het exporteren van de verwerkte afbeelding is geldige Premium-toegang nodig. Er zijn automatisch verlengende week- en maandabonnementen en een eenmalige levenslange aankoop, zonder gratis proefperiode. Aankopen in de App Store en Google Play zijn gescheiden en kunnen niet tussen platforms worden overgedragen.","De werkelijke prijs, valuta, belastingen, factureringsperiode en koopmogelijkheid zijn de gegevens die in het systeemaankoopscherm van de App Store of Google Play worden getoond en door jou worden bevestigd. Het aankoopplatform brengt de betaling via je winkelaccount in rekening en beheert deze. De app biedt geen gratis proefabonnement of andere betaalde abonnementen."]},{"title":"3. Automatische verlenging en opzegging","paragraphs":["Week- en maandabonnementen worden automatisch verlengd en in rekening gebracht voor de periode die op het systeemaankoopscherm staat, totdat je via het aankoopplatform opzegt. Het verwijderen van {appName} zegt een abonnement niet automatisch op. Tenzij het aankoopplatform een terugbetaling of andere afhandeling biedt, kun je het abonnement na het uitschakelen van automatische verlenging blijven gebruiken tot het einde van de reeds betaalde periode."],"links":["appleCancel","googleManage"]},{"title":"4. Aankopen, herstel en terugbetalingen","paragraphs":["Aankopen en aankoopherstel verlopen via de officiële winkel van Apple of Google. Toegang wordt pas verleend nadat de winkel een geldige transactie heeft bevestigd. Geannuleerde, mislukte of openstaande transacties geven vóór succesvolle bevestiging geen toegang. Met aankoopherstel kunnen levenslange toegang en een momenteel actief abonnement worden hersteld. Aankopen in de App Store en Google Play zijn afzonderlijk en kunnen niet tussen platforms worden hersteld of overgedragen.","Terugbetalingen worden door de appwinkel die de transactie voltooide behandeld volgens diens regels, de aankoopregio en de toepasselijke wet. De bijbehorende toegang wordt verwijderd nadat de winkel een terugbetaling, intrekking, afloop van het abonnement of ongeldige transactie bevestigt."],"links":["appleRefund","googleRefund"]},{"title":"5. Offlinegebruik en beschikbaarheid","paragraphs":["Afbeeldingen kiezen, OCR, detectie van gevoelige inhoud, bewerken en exporteren gebeurt op je apparaat. De app biedt geen beeldherkenning of synchronisatie in de cloud en heeft geen accounts. Bij export wordt een nieuwe afbeelding gemaakt en worden verwijderbare privacygevoelige metadata gewist. Tijdelijke werkbestanden worden verwijderd na een geslaagde opslag, wanneer je de bewerking verlaat of wanneer de sessie eindigt; na een opslagfout kan de benodigde status blijven staan om opnieuw te proberen."]},{"title":"6. Aanvaardbaar gebruik en intellectueel eigendom","paragraphs":["Je mag de app niet gebruiken voor onwettige activiteiten, aankoopverificatie omzeilen, de app beschadigen, schadelijke code verspreiden, de app zonder toestemming kopiëren of verspreiden of rechten op appinhoud of intellectueel eigendom van anderen schenden.","Je kunt de app op elk moment niet meer gebruiken en verwijderen. We kunnen updates uitbrengen om problemen op te lossen, besturingssystemen te ondersteunen, stabiliteit te verbeteren of aan platformvereisten te voldoen. Problemen met apparaat, systeem, netwerk of winkeldienst kunnen sommige functies tijdelijk onbeschikbaar maken.","Voor zover toegestaan door de toepasselijke wet wordt de app naar beschikbaarheid geleverd. Deze Voorwaarden sluiten geen aansprakelijkheid uit die wettelijk niet kan worden uitgesloten en beperken geen dwingende consumentenrechten.","Als productfuncties, betaalmethoden, platformregels of de toepasselijke wet veranderen, kunnen we deze Voorwaarden en de datum op deze pagina bijwerken. Als een wijziging de rechten van gebruikers wezenlijk raakt, geven we de vereiste extra kennisgeving.","Voor vragen over deze voorwaarden, aankopen of het gebruik van de app kunt u een e-mail sturen naar [e-mailadres]. {email}"]}]},"support":{"title":"Ondersteuning","lead":"Bekijk eerst de veelgestelde vragen hieronder. Als het probleem blijft bestaan, neem dan contact op via het e-mailadres voor ondersteuning.","emailTitle":"{appName} support e-mailadres","emailLead":"Bekijk eerst de veelgestelde vragen hieronder. Als het probleem blijft bestaan, neem dan contact op via het e-mailadres voor ondersteuning.","beforeEmail":{"title":"Wat je in je e-mail moet vermelden","paragraphs":["Bij een aankoopprobleem kun je het bestelnummer van de appwinkel vermelden, maar stuur niet je account- of betaalwachtwoord of volledige kaartgegevens."],"bullets":["je platform, apparaatmodel, besturingssysteemversie en appversie;","wat je vóór het probleem deed, wat je verwachtte en wat er werkelijk gebeurde; en","Indien nodig, een screenshot of schermopname waarbij privégegevens zijn afgeschermd."]},"faqs":[{"question":"Worden afbeeldingen naar een server geüpload?","answer":"Afbeeldingen kiezen, OCR, detectie van gevoelige inhoud, bewerken en exporteren gebeurt op je apparaat. De app biedt geen beeldherkenning of synchronisatie in de cloud en heeft geen accounts. Bij export wordt een nieuwe afbeelding gemaakt en worden verwijderbare privacygevoelige metadata gewist. Tijdelijke werkbestanden worden verwijderd na een geslaagde opslag, wanneer je de bewerking verlaat of wanneer de sessie eindigt; na een opslagfout kan de benodigde status blijven staan om opnieuw te proberen."},{"question":"Machtigingen, reclame en tracking","answer":"Fototoegang wordt alleen gebruikt om afbeeldingen te tonen en te verwerken waarvoor je toestemming geeft. De camera wordt alleen gebruikt wanneer je in de app een foto maakt. Toestemming om in de fotobibliotheek op te slaan wordt alleen gevraagd wanneer je export bevestigt met geldige Premium-toegang. De app vraagt niet om locatie, contacten, microfoon, Bluetooth of meldingen."},{"question":"Betaalde producten en prijzen","answer":"Herkenning en bewerking hebben geen gebruikslimiet. Alleen voor het exporteren van de verwerkte afbeelding is geldige Premium-toegang nodig. Er zijn automatisch verlengende week- en maandabonnementen en een eenmalige levenslange aankoop, zonder gratis proefperiode. Aankopen in de App Store en Google Play zijn gescheiden en kunnen niet tussen platforms worden overgedragen."},{"question":"Opslaan en afbeeldingsindelingen","answer":"Controleer bij een opslagfout de vrije ruimte, toestemming om in de fotobibliotheek op te slaan en of de originele afbeelding nog leesbaar is, en probeer opnieuw. De app verwerkt één stilstaand beeld tegelijk en ondersteunt de meeste gangbare formaten; sommige zijn afhankelijk van apparaat en systeemversie. Video, PDF, RAW/DNG en batchverwerking worden momenteel niet ondersteund."},{"question":"Hoe wijzig ik de taal?","answer":"De app ondersteunt 40 talen, die je in de appinstellingen kunt wijzigen. Als de weergave niet klopt, mail dan de apparaattaal en de in de app gekozen taal."},{"question":"Herstel, opzegging en terugbetalingen","answer":"Aankopen en aankoopherstel verlopen via de officiële winkel van Apple of Google. Toegang wordt pas verleend nadat de winkel een geldige transactie heeft bevestigd. Geannuleerde, mislukte of openstaande transacties geven vóór succesvolle bevestiging geen toegang. Met aankoopherstel kunnen levenslange toegang en een momenteel actief abonnement worden hersteld. Aankopen in de App Store en Google Play zijn afzonderlijk en kunnen niet tussen platforms worden hersteld of overgedragen."},{"question":"Privacy en gegevensverwijdering","answer":"Verwijder gegevens op het apparaat door de app te verwijderen. Op Android kun je ook de systeemoptie ‘Gegevens wissen’ gebruiken. Aankoopgegevens worden beheerd door Apple of Google. Herstelbare toegang wordt opnieuw bevestigd volgens de regels van de winkel. Ondersteuningsmails worden bewaard zolang dat nodig is om het verzoek te behandelen en aan noodzakelijke bewaarplichten te voldoen. Je kunt ons mailen om verwijdering te vragen van ondersteuningscorrespondentie die we nog bewaren."}],"officialHelpTitle":"Snelle hulp"}},"pl":{"linkLabels":{"appleEula":"Standardowej umowie licencyjnej użytkownika końcowego Apple (EULA)","appleCancel":"Instrukcje anulowania subskrypcji Apple","googleManage":"Instrukcje anulowania w Google Play","appleRefund":"Poproś Apple o zwrot pieniędzy","googleRefund":"Informacje o zwrotach Google Play"},"nav":{"privacy":"Polityka prywatności","terms":"Warunki korzystania","support":"Wsparcie","language":"Język","chooseLanguage":"Wybierz język wyświetlania","navigationLabel":"Nawigacja główna"},"home":{"eyebrow":"{appName} · Privacy first","title":"Twoje obrazy nie są przesyłane na nasze serwery.","lead":"Wybór obrazu, OCR, wykrywanie treści wrażliwych, edycja i eksport odbywają się na urządzeniu. Aplikacja nie oferuje rozpoznawania obrazów ani synchronizacji w chmurze i nie ma kont. Podczas eksportu tworzony jest nowy obraz, a możliwe do usunięcia prywatne metadane są kasowane. Tymczasowe pliki robocze są usuwane po udanym zapisie, porzuceniu edycji lub zakończeniu sesji; po błędzie zapisu stan potrzebny do ponowienia próby może zostać zachowany.","points":["Dane aplikacji","Płatne produkty i ceny","Wsparcie"],"cards":[{"title":"Polityka prywatności","description":"Twoje obrazy nie są przesyłane na nasze serwery.","action":"Polityka prywatności"},{"title":"Warunki korzystania","description":"Rozpoznawanie i edycja nie mają limitów użycia. Tylko eksport przetworzonego obrazu wymaga ważnego dostępu Premium. Dostępne są automatycznie odnawiane subskrypcje tygodniowe i miesięczne oraz jednorazowy zakup dożywotni, bez bezpłatnego okresu próbnego. Zakupy w App Store i Google Play są niezależne i nie można ich przenosić między platformami.","action":"Warunki korzystania"},{"title":"Potrzebujesz pomocy?","description":"Najpierw sprawdź poniższe częste pytania. Jeśli problem nadal występuje, skontaktuj się przez adres e-mail pomocy.","action":"Wsparcie"}]},"footer":{"privacy":"Polityka prywatności","terms":"Warunki korzystania","support":"Wsparcie"},"privacy":{"title":"Polityka prywatności","lead":"Niniejsza Polityka wyjaśnia, jak {appName} obsługuje dane na urządzeniu, informacje o zakupach ze sklepu i wiadomości do pomocy.","sections":[{"title":"1. Zakres i kontakt","paragraphs":["Niniejsza Polityka dotyczy aplikacji {appName} na iOS, iPadOS i Androida oraz tej witryny dotyczącej prywatności, warunków i pomocy.","W przypadku pytań dotyczących prywatności prosimy o kontakt mailowy {email}"]},{"title":"2. Dane aplikacji","callout":{"title":"Twoje obrazy nie są przesyłane na nasze serwery.","body":"Wybór obrazu, OCR, wykrywanie treści wrażliwych, edycja i eksport odbywają się na urządzeniu. Aplikacja nie oferuje rozpoznawania obrazów ani synchronizacji w chmurze i nie ma kont. Podczas eksportu tworzony jest nowy obraz, a możliwe do usunięcia prywatne metadane są kasowane. Tymczasowe pliki robocze są usuwane po udanym zapisie, porzuceniu edycji lub zakończeniu sesji; po błędzie zapisu stan potrzebny do ponowienia próby może zostać zachowany."},"paragraphs":[]},{"title":"3. Uprawnienia, reklamy i śledzenie","paragraphs":["Dostęp do zdjęć służy wyłącznie do wyświetlania i przetwarzania obrazów, na które zezwolisz. Aparat jest używany tylko wtedy, gdy wybierzesz wykonanie zdjęcia w aplikacji. Zgoda na zapis w bibliotece zdjęć jest wymagana tylko po potwierdzeniu eksportu z ważnym dostępem Premium. Aplikacja nie prosi o lokalizację, kontakty, mikrofon, Bluetooth ani powiadomienia.","Nie używa identyfikatora reklamowego i nie integruje zewnętrznych zestawów SDK do reklam, analityki, atrybucji lub raportowania awarii.","Aplikacja nie integruje zewnętrznego narzędzia do raportowania awarii. Zależnie od ustawień urządzenia i sklepu Apple lub Google może przetwarzać systemowe informacje diagnostyczne według własnych zasad prywatności i przekazywać dane techniczne używane do badania awarii lub problemów z wydajnością."]},{"title":"4. Usługi sklepu i dostęp do sieci","paragraphs":["Aplikacja korzysta z Apple StoreKit lub Google Play Billing, aby wczytywać produkty, wyświetlać lokalne ceny zwrócone przez sklep, realizować i przywracać zakupy, zarządzać subskrypcjami oraz potwierdzać uprawnienia. Dostęp do sieci jest używany tylko do tych oficjalnych funkcji sklepu Apple lub Google.","Apple lub Google odpowiada za konta sklepu, płatności, rozliczenia, transakcje, zwroty i usługi subskrypcji. Aplikacja przetwarza tylko informacje ze sklepu potrzebne do potwierdzenia produktów i uprawnień oraz nie otrzymuje ani nie zapisuje pełnych danych płatniczych."]},{"title":"5. Wiadomości do pomocy i witryna","paragraphs":["Aplikacja nie odczytuje automatycznie danych e-mail. Dopiero po wysłaniu wiadomości do pomocy kanał pomocy otrzyma adres e-mail, treść oraz dobrowolnie dołączone zrzuty lub nagrania ekranu, numer zamówienia albo inne załączniki. Dane te służą wyłącznie do obsługi zgłoszenia, a nie reklamie lub marketingowi. Nie wysyłaj haseł do konta lub płatności ani pełnych numerów kart.","Ta witryna nie ustawia reklamowych ani analitycznych plików cookie i nie zawiera skryptów analizy ruchu ani śledzenia."]},{"title":"6. Przechowywanie i usuwanie","paragraphs":["Odinstaluj aplikację, aby usunąć dane z urządzenia. W systemie Android możesz też użyć opcji „Wyczyść dane”.","Rejestry zakupów są zarządzane przez Apple lub Google. Uprawnienia możliwe do przywrócenia są ponownie potwierdzane zgodnie z zasadami sklepu.","Wiadomości do pomocy są przechowywane przez czas potrzebny do obsługi zgłoszenia i spełnienia niezbędnych wymogów ewidencyjnych. Możesz poprosić e-mailem o usunięcie korespondencji, którą nadal przechowujemy."]},{"title":"7. Bezpieczeństwo danych","paragraphs":["Aplikacja wykorzystuje przetwarzanie na urządzeniu, minimalne uprawnienia i oficjalne procesy zakupowe sklepów, aby ograniczyć zbędne przesyłanie danych. Wiadomości do pomocy służą tylko do obsługi zgłoszeń i są chronione rozsądnymi środkami odpowiednimi do charakteru informacji.","Nie można zagwarantować pełnego bezpieczeństwa urządzenia, sieci ani elektronicznego sposobu przechowywania. Nie umieszczaj w wiadomości do pomocy niezwiązanych ze sprawą danych wrażliwych."]},{"title":"8. Dzieci i młodzież","paragraphs":["Aplikacja nie wymaga konta i nie tworzy profili dzieci ani innych użytkowników za pomocą reklam lub analizy zachowań. Rodzic albo opiekun, który uważa, że dziecko podało dane osobowe w wiadomości do pomocy, może skontaktować się z nami w celu rozwiązania sprawy."]},{"title":"9. Twoje wybory i prawa","paragraphs":["Danymi lokalnymi zarządzasz na urządzeniu. Apple lub Google zarządza kontami sklepu i rejestrami zakupów. Aplikacja nie może w twoim imieniu zmieniać ani usuwać zapisów transakcji przechowywanych przez sklep.","Jeżeli zmienią się praktyki aplikacji dotyczące danych, zasady platform lub hosting witryny, zaktualizujemy niniejszą Politykę i datę na stronie oraz przekażemy dodatkowe powiadomienie, gdy wymagają tego właściwe zasady.","W przypadku pytań dotyczących prywatności prosimy o kontakt mailowy {email}"]}]},"terms":{"title":"Warunki korzystania","lead":"{appName} Warunki korzystania.","sections":[{"title":"1. Akceptacja niniejszego Regulaminu i zasad platformy","paragraphs":["Pobierając, kupując lub korzystając z aplikacji {appName}, akceptujesz niniejszy Regulamin oraz zasady obowiązujące w sklepie z aplikacjami, w którym dokonujesz zakupu. Jeśli nie wyrażasz zgody, nie kontynuuj korzystania z aplikacji ani dokonywania zakupu.","Niniejsze Warunki dotyczą pobierania, zakupu i używania aplikacji. Wersje na iOS i iPadOS podlegają również"],"links":["appleEula"]},{"title":"2. Płatne produkty i ceny","paragraphs":["Rozpoznawanie i edycja nie mają limitów użycia. Tylko eksport przetworzonego obrazu wymaga ważnego dostępu Premium. Dostępne są automatycznie odnawiane subskrypcje tygodniowe i miesięczne oraz jednorazowy zakup dożywotni, bez bezpłatnego okresu próbnego. Zakupy w App Store i Google Play są niezależne i nie można ich przenosić między platformami.","Rzeczywista cena, waluta, podatki, okres rozliczeniowy i możliwość zakupu odpowiadają informacjom wyświetlonym i potwierdzonym na systemowym ekranie zakupu App Store lub Google Play. Platforma zakupowa pobiera i obsługuje płatność za pośrednictwem konta sklepu. Aplikacja nie oferuje bezpłatnego okresu próbnego subskrypcji ani innych płatnych planów."]},{"title":"3. Automatyczne odnawianie i anulowanie","paragraphs":["Subskrypcje tygodniowe i miesięczne odnawiają się automatycznie i są rozliczane za okres wskazany na systemowym ekranie zakupu, dopóki nie anulujesz ich na platformie zakupowej. Usunięcie {appName} nie anuluje automatycznie subskrypcji. Jeżeli platforma nie przyzna zwrotu ani nie zastosuje innego rozwiązania, po wyłączeniu automatycznego odnawiania możesz korzystać z subskrypcji do końca opłaconego okresu."],"links":["appleCancel","googleManage"]},{"title":"4. Zakupy, przywracanie i zwroty","paragraphs":["Zakupy i ich przywracanie odbywają się za pośrednictwem oficjalnego sklepu Apple lub Google. Uprawnienie jest przyznawane dopiero po potwierdzeniu ważnej transakcji przez sklep. Transakcje anulowane, nieudane lub oczekujące nie przyznają uprawnienia przed potwierdzeniem. Przywracanie może odzyskać dostęp dożywotni i aktualnie aktywną subskrypcję. Zakupy w App Store i Google Play są niezależne i nie można ich przywracać ani przenosić między platformami.","Zwroty są obsługiwane przez sklep, który zrealizował transakcję, zgodnie z jego zasadami, regionem zakupu i właściwym prawem. Odpowiednie uprawnienie jest usuwane po potwierdzeniu zwrotu, cofnięcia, wygaśnięcia subskrypcji lub nieważnej transakcji."],"links":["appleRefund","googleRefund"]},{"title":"5. Używanie offline i dostępność","paragraphs":["Wybór obrazu, OCR, wykrywanie treści wrażliwych, edycja i eksport odbywają się na urządzeniu. Aplikacja nie oferuje rozpoznawania obrazów ani synchronizacji w chmurze i nie ma kont. Podczas eksportu tworzony jest nowy obraz, a możliwe do usunięcia prywatne metadane są kasowane. Tymczasowe pliki robocze są usuwane po udanym zapisie, porzuceniu edycji lub zakończeniu sesji; po błędzie zapisu stan potrzebny do ponowienia próby może zostać zachowany."]},{"title":"6. Dozwolone używanie i własność intelektualna","paragraphs":["Nie wolno używać aplikacji do działań niezgodnych z prawem, omijać weryfikacji zakupów, uszkadzać aplikacji, rozpowszechniać złośliwego kodu, kopiować lub rozpowszechniać aplikacji bez zgody ani naruszać praw do treści aplikacji lub własności intelektualnej innych osób.","Możesz w każdej chwili przestać używać aplikacji i ją odinstalować. Możemy wydawać aktualizacje, aby usuwać problemy, obsługiwać systemy, poprawiać stabilność lub spełniać wymagania platform. Problemy z urządzeniem, systemem, siecią lub usługą sklepu mogą tymczasowo uniemożliwić korzystanie z niektórych funkcji.","W zakresie dozwolonym przez właściwe prawo aplikacja jest udostępniana w aktualnie dostępnej postaci. Niniejsze Warunki nie wyłączają odpowiedzialności, której nie można prawnie wyłączyć, ani nie ograniczają bezwzględnie obowiązujących praw konsumenta.","Jeżeli zmienią się funkcje produktu, metody płatności, zasady platform lub właściwe prawo, możemy zaktualizować Warunki i datę na stronie. Gdy zmiana istotnie wpływa na prawa użytkowników, przekażemy wymagane dodatkowe powiadomienie.","W przypadku pytań dotyczących niniejszych Warunków, zakupów lub korzystania z aplikacji prosimy o kontakt mailowy {email}"]}]},"support":{"title":"Wsparcie","lead":"Najpierw sprawdź poniższe częste pytania. Jeśli problem nadal występuje, skontaktuj się przez adres e-mail pomocy.","emailTitle":"Adres e-mail pomocy technicznej {appName}","emailLead":"Najpierw sprawdź poniższe częste pytania. Jeśli problem nadal występuje, skontaktuj się przez adres e-mail pomocy.","beforeEmail":{"title":"Co podać w wiadomości","paragraphs":["W sprawie zakupu możesz podać numer zamówienia ze sklepu, ale nie wysyłaj hasła konta lub płatności ani pełnych danych karty."],"bullets":["platformę, model urządzenia, wersję systemu i wersję aplikacji;","czynności przed wystąpieniem problemu, oczekiwany i rzeczywisty wynik; oraz","w razie potrzeby zrzut ekranu lub nagranie ekranu z ukrytymi prywatnymi informacjami."]},"faqs":[{"question":"Czy obrazy są przesyłane na serwer?","answer":"Wybór obrazu, OCR, wykrywanie treści wrażliwych, edycja i eksport odbywają się na urządzeniu. Aplikacja nie oferuje rozpoznawania obrazów ani synchronizacji w chmurze i nie ma kont. Podczas eksportu tworzony jest nowy obraz, a możliwe do usunięcia prywatne metadane są kasowane. Tymczasowe pliki robocze są usuwane po udanym zapisie, porzuceniu edycji lub zakończeniu sesji; po błędzie zapisu stan potrzebny do ponowienia próby może zostać zachowany."},{"question":"Uprawnienia, reklamy i śledzenie","answer":"Dostęp do zdjęć służy wyłącznie do wyświetlania i przetwarzania obrazów, na które zezwolisz. Aparat jest używany tylko wtedy, gdy wybierzesz wykonanie zdjęcia w aplikacji. Zgoda na zapis w bibliotece zdjęć jest wymagana tylko po potwierdzeniu eksportu z ważnym dostępem Premium. Aplikacja nie prosi o lokalizację, kontakty, mikrofon, Bluetooth ani powiadomienia."},{"question":"Płatne produkty i ceny","answer":"Rozpoznawanie i edycja nie mają limitów użycia. Tylko eksport przetworzonego obrazu wymaga ważnego dostępu Premium. Dostępne są automatycznie odnawiane subskrypcje tygodniowe i miesięczne oraz jednorazowy zakup dożywotni, bez bezpłatnego okresu próbnego. Zakupy w App Store i Google Play są niezależne i nie można ich przenosić między platformami."},{"question":"Zapisywanie i formaty obrazów","answer":"Jeśli zapis się nie powiedzie, sprawdź wolne miejsce, zgodę na zapis w bibliotece zdjęć oraz możliwość odczytu oryginalnego obrazu, a następnie spróbuj ponownie. Aplikacja przetwarza jeden obraz statyczny naraz i obsługuje większość popularnych formatów; niektóre zależą od urządzenia i wersji systemu. Wideo, PDF, RAW/DNG i przetwarzanie wsadowe nie są obecnie obsługiwane."},{"question":"Jak zmienić język?","answer":"Aplikacja obsługuje 40 języków, które można zmienić w jej ustawieniach. Jeśli wyświetlanie jest nieprawidłowe, podaj e-mailem język urządzenia i język wybrany w aplikacji."},{"question":"Przywracanie, anulowanie i zwroty","answer":"Zakupy i ich przywracanie odbywają się za pośrednictwem oficjalnego sklepu Apple lub Google. Uprawnienie jest przyznawane dopiero po potwierdzeniu ważnej transakcji przez sklep. Transakcje anulowane, nieudane lub oczekujące nie przyznają uprawnienia przed potwierdzeniem. Przywracanie może odzyskać dostęp dożywotni i aktualnie aktywną subskrypcję. Zakupy w App Store i Google Play są niezależne i nie można ich przywracać ani przenosić między platformami."},{"question":"Prywatność i usuwanie danych","answer":"Odinstaluj aplikację, aby usunąć dane z urządzenia. W systemie Android możesz też użyć opcji „Wyczyść dane”. Rejestry zakupów są zarządzane przez Apple lub Google. Uprawnienia możliwe do przywrócenia są ponownie potwierdzane zgodnie z zasadami sklepu. Wiadomości do pomocy są przechowywane przez czas potrzebny do obsługi zgłoszenia i spełnienia niezbędnych wymogów ewidencyjnych. Możesz poprosić e-mailem o usunięcie korespondencji, którą nadal przechowujemy."}],"officialHelpTitle":"Szybka pomoc"}},"pt-BR":{"linkLabels":{"appleEula":"Contrato de Licença de Usuário Final Padrão da Apple (EULA)","appleCancel":"Instruções para cancelamento de assinatura da Apple","googleManage":"Instruções de cancelamento do Google Play","appleRefund":"Solicite um reembolso à Apple.","googleRefund":"Informações sobre reembolso do Google Play"},"nav":{"privacy":"política de Privacidade","terms":"Termos de Uso","support":"Suporte","language":"Linguagem","chooseLanguage":"Selecione o idioma de exibição","navigationLabel":"Navegação principal"},"home":{"eyebrow":"{appName} · Privacy first","title":"Suas imagens não são enviadas aos nossos servidores.","lead":"A seleção de imagens, o OCR, a detecção de conteúdo sensível, a edição e a exportação são realizados no dispositivo. O app não oferece reconhecimento de imagens na nuvem, sincronização na nuvem nem conta. Ao exportar, uma nova imagem é criada e os metadados privados removíveis são apagados. Os arquivos temporários de trabalho são excluídos após um salvamento bem-sucedido, ao abandonar a edição ou no fim da sessão; se o salvamento falhar, o estado necessário pode ser mantido para tentar novamente.","points":["Dados do app","Produtos pagos e preços","Suporte"],"cards":[{"title":"política de Privacidade","description":"Suas imagens não são enviadas aos nossos servidores.","action":"política de Privacidade"},{"title":"Termos de Uso","description":"O reconhecimento e a edição não têm limite de uso. Apenas a exportação da imagem processada exige acesso Premium válido. O app oferece assinaturas semanais e mensais com renovação automática e uma compra vitalícia única, sem teste grátis. As compras da App Store e do Google Play são independentes e não podem ser transferidas entre plataformas.","action":"Termos de Uso"},{"title":"Precisar de ajuda?","description":"Comece pelas perguntas frequentes abaixo. Se o problema continuar, entre em contato pelo e-mail de suporte.","action":"Suporte"}]},"footer":{"privacy":"política de Privacidade","terms":"Termos de Uso","support":"Suporte"},"privacy":{"title":"política de Privacidade","lead":"Esta Política explica como {appName} trata dados no dispositivo, informações de compra da loja e e-mails de suporte.","sections":[{"title":"1. Âmbito de aplicação e contacto","paragraphs":["Esta Política se aplica ao app {appName} para iOS, iPadOS e Android e a este site de privacidade, termos e suporte.","Para questões de privacidade, envie um e-mail. {email}"]},{"title":"2. Dados do app","callout":{"title":"Suas imagens não são enviadas aos nossos servidores.","body":"A seleção de imagens, o OCR, a detecção de conteúdo sensível, a edição e a exportação são realizados no dispositivo. O app não oferece reconhecimento de imagens na nuvem, sincronização na nuvem nem conta. Ao exportar, uma nova imagem é criada e os metadados privados removíveis são apagados. Os arquivos temporários de trabalho são excluídos após um salvamento bem-sucedido, ao abandonar a edição ou no fim da sessão; se o salvamento falhar, o estado necessário pode ser mantido para tentar novamente."},"paragraphs":[]},{"title":"3. Permissões, publicidade e rastreamento","paragraphs":["O acesso às fotos é usado apenas para exibir e processar as imagens autorizadas por você. A câmera só é usada quando você escolhe tirar uma foto no app. A permissão para salvar na biblioteca é solicitada apenas quando você confirma a exportação com acesso Premium válido. O app não solicita localização, contatos, microfone, Bluetooth nem notificações.","Ele não usa identificador de publicidade nem integra SDKs de terceiros para publicidade, análise, atribuição ou relatório de falhas.","O app não integra ferramentas de terceiros para relatório de falhas. Conforme as configurações do dispositivo e da loja, a Apple ou o Google pode tratar informações de diagnóstico do sistema segundo suas regras de privacidade e fornecer dados técnicos para investigar falhas ou problemas de desempenho."]},{"title":"4. Serviços da loja e acesso à rede","paragraphs":["O app usa Apple StoreKit ou Google Play Billing para carregar produtos, exibir preços localizados fornecidos pela loja, concluir e restaurar compras, gerenciar assinaturas e confirmar direitos. O acesso à rede é usado somente para essas funções oficiais da Apple ou do Google.","A Apple ou o Google é responsável por contas da loja, pagamentos, cobranças, transações, reembolsos e serviços de assinatura. O app trata apenas as informações da loja necessárias para confirmar produtos e direitos e não recebe nem armazena credenciais completas de pagamento."]},{"title":"5. E-mails de suporte e site","paragraphs":["O app não lê automaticamente as informações do seu e-mail. O canal de suporte só recebe seu endereço, mensagem e capturas de tela, gravações, números de pedido ou outros anexos fornecidos voluntariamente quando você envia um e-mail de suporte. Essas informações são usadas somente para atender à solicitação e não para publicidade ou marketing. Não envie senhas de conta ou pagamento nem números completos de cartão.","Este site não define cookies de publicidade ou análise e não inclui scripts de análise de tráfego ou rastreamento."]},{"title":"6. Retenção e exclusão","paragraphs":["Desinstale o app para excluir os dados do dispositivo. No Android, você também pode usar a opção do sistema “Limpar dados”.","Os registros de compra são gerenciados pela Apple ou pelo Google. Os direitos restauráveis são confirmados novamente segundo as regras da loja.","Os e-mails de suporte são mantidos pelo tempo necessário para atender à solicitação e cumprir requisitos essenciais de registro. Você pode nos enviar um e-mail para solicitar a exclusão das mensagens de suporte que ainda mantemos."]},{"title":"7. Segurança dos dados","paragraphs":["O app usa processamento no dispositivo, permissões mínimas e fluxos oficiais de compra para reduzir transferências desnecessárias de dados. Os e-mails de suporte são usados somente para atender às solicitações recebidas, com medidas razoáveis adequadas à natureza das informações.","Nenhum dispositivo, rede ou método de armazenamento eletrônico pode ter segurança absoluta garantida. Não inclua informações confidenciais sem relação com o problema em um e-mail de suporte."]},{"title":"8. Crianças e adolescentes","paragraphs":["O app não exige conta nem cria perfis de crianças ou outros usuários por meio de publicidade ou análise comportamental. Se um responsável acreditar que uma criança forneceu informações pessoais em um e-mail de suporte, poderá entrar em contato para que a questão seja tratada."]},{"title":"9. Suas escolhas e seus direitos","paragraphs":["Você gerencia os dados locais pelo dispositivo. A Apple ou o Google gerencia as contas da loja e os registros de compra. O app não pode modificar nem excluir em seu nome os registros de transações mantidos por uma loja.","Se as práticas de dados do app, as regras das plataformas ou a hospedagem do site mudarem, atualizaremos esta Política e a data da página e forneceremos aviso adicional quando exigido pelas regras aplicáveis.","Para questões de privacidade, envie um e-mail. {email}"]}]},"terms":{"title":"Termos de Uso","lead":"Termos de Uso do {appName}.","sections":[{"title":"1. Aceitação destes Termos e das regras da plataforma","paragraphs":["Ao baixar, comprar ou usar o {appName}, você concorda com estes Termos e com as regras aplicáveis na loja de aplicativos onde você efetuar a compra. Caso não concorde, não continue a usar o aplicativo nem faça a compra.","Estes Termos se aplicam ao download, à compra e ao uso do app. As versões para iOS e iPadOS também estão sujeitas ao"],"links":["appleEula"]},{"title":"2. Produtos pagos e preços","paragraphs":["O reconhecimento e a edição não têm limite de uso. Apenas a exportação da imagem processada exige acesso Premium válido. O app oferece assinaturas semanais e mensais com renovação automática e uma compra vitalícia única, sem teste grátis. As compras da App Store e do Google Play são independentes e não podem ser transferidas entre plataformas.","O preço real, a moeda, os impostos, o período de cobrança e a qualificação para compra são as informações exibidas e confirmadas na tela de compra do sistema da App Store ou do Google Play. A plataforma cobra e gerencia o pagamento pela sua conta da loja. O app não oferece teste gratuito de assinatura nem outros planos pagos."]},{"title":"3. Renovação automática e cancelamento","paragraphs":["As assinaturas semanais e mensais são renovadas automaticamente e cobradas pelo período indicado na tela de compra até que você as cancele na plataforma. Excluir {appName} não cancela automaticamente uma assinatura. A menos que a plataforma conceda reembolso ou outro tratamento, você poderá continuar usando a assinatura até o fim do período já pago após desativar a renovação automática."],"links":["appleCancel","googleManage"]},{"title":"4. Compras, restauração e reembolsos","paragraphs":["As compras e a restauração são realizadas pela loja oficial da Apple ou do Google. Um direito é concedido somente depois que a loja confirma uma transação válida. Transações canceladas, com falha ou pendentes não concedem direitos antes da confirmação. A restauração pode recuperar o acesso vitalício e uma assinatura atualmente ativa. As compras da App Store e do Google Play são independentes e não podem ser restauradas ou transferidas entre plataformas.","Os reembolsos são tratados pela loja que concluiu a transação, conforme suas regras, a região da compra e a legislação aplicável. O direito correspondente é removido quando a loja confirma reembolso, revogação, expiração da assinatura ou transação inválida."],"links":["appleRefund","googleRefund"]},{"title":"5. Uso off-line e disponibilidade","paragraphs":["A seleção de imagens, o OCR, a detecção de conteúdo sensível, a edição e a exportação são realizados no dispositivo. O app não oferece reconhecimento de imagens na nuvem, sincronização na nuvem nem conta. Ao exportar, uma nova imagem é criada e os metadados privados removíveis são apagados. Os arquivos temporários de trabalho são excluídos após um salvamento bem-sucedido, ao abandonar a edição ou no fim da sessão; se o salvamento falhar, o estado necessário pode ser mantido para tentar novamente."]},{"title":"6. Uso aceitável e propriedade intelectual","paragraphs":["Você não deve usar o app para atividades ilegais; contornar a verificação de compras; danificar o app; distribuir código malicioso; copiar ou distribuir o app sem permissão; nem violar direitos sobre o conteúdo do app ou a propriedade intelectual de terceiros.","Você pode parar de usar e desinstalar o app a qualquer momento. Podemos lançar atualizações para corrigir problemas, oferecer suporte a sistemas operacionais, melhorar a estabilidade ou atender a requisitos das plataformas. Problemas no dispositivo, sistema, rede ou serviço da loja podem tornar alguns recursos temporariamente indisponíveis.","Na medida permitida pela legislação aplicável, o app é fornecido conforme disponível. Estes Termos não excluem responsabilidades que não possam ser legalmente excluídas nem limitam direitos obrigatórios do consumidor.","Se os recursos, os métodos de pagamento, as regras das plataformas ou a legislação aplicável mudarem, poderemos atualizar estes Termos e a data da página. Se uma mudança afetar significativamente os direitos dos usuários, forneceremos o aviso adicional exigido.","Para dúvidas sobre estes Termos, compras ou uso do aplicativo, envie um e-mail. {email}"]}]},"support":{"title":"Suporte","lead":"Comece pelas perguntas frequentes abaixo. Se o problema continuar, entre em contato pelo e-mail de suporte.","emailTitle":"E-mail de suporte {appName}","emailLead":"Comece pelas perguntas frequentes abaixo. Se o problema continuar, entre em contato pelo e-mail de suporte.","beforeEmail":{"title":"O que incluir no e-mail","paragraphs":["Em caso de problema com uma compra, você pode informar o número do pedido da loja, mas não envie a senha da conta ou do pagamento nem os dados completos do cartão."],"bullets":["sua plataforma, modelo do dispositivo, versão do sistema operacional e versão do app;","o que você fez antes do problema, o que esperava e o que realmente aconteceu; e","Se necessário, uma captura de tela ou gravação da tela com informações privadas ocultas."]},"faqs":[{"question":"As imagens são enviadas para algum servidor?","answer":"A seleção de imagens, o OCR, a detecção de conteúdo sensível, a edição e a exportação são realizados no dispositivo. O app não oferece reconhecimento de imagens na nuvem, sincronização na nuvem nem conta. Ao exportar, uma nova imagem é criada e os metadados privados removíveis são apagados. Os arquivos temporários de trabalho são excluídos após um salvamento bem-sucedido, ao abandonar a edição ou no fim da sessão; se o salvamento falhar, o estado necessário pode ser mantido para tentar novamente."},{"question":"Permissões, publicidade e rastreamento","answer":"O acesso às fotos é usado apenas para exibir e processar as imagens autorizadas por você. A câmera só é usada quando você escolhe tirar uma foto no app. A permissão para salvar na biblioteca é solicitada apenas quando você confirma a exportação com acesso Premium válido. O app não solicita localização, contatos, microfone, Bluetooth nem notificações."},{"question":"Produtos pagos e preços","answer":"O reconhecimento e a edição não têm limite de uso. Apenas a exportação da imagem processada exige acesso Premium válido. O app oferece assinaturas semanais e mensais com renovação automática e uma compra vitalícia única, sem teste grátis. As compras da App Store e do Google Play são independentes e não podem ser transferidas entre plataformas."},{"question":"Salvamento e formatos de imagem","answer":"Se o salvamento falhar, verifique o espaço disponível, a permissão para salvar na biblioteca e se a imagem original ainda pode ser lida; depois tente novamente. O app processa uma imagem estática por vez e aceita a maioria dos formatos comuns; alguns dependem do dispositivo e da versão do sistema. Vídeos, PDF, RAW/DNG e processamento em lote não são compatíveis no momento."},{"question":"Como alterar o idioma?","answer":"O app oferece suporte a 40 idiomas, que podem ser alterados nas configurações. Se a exibição estiver incorreta, informe por e-mail o idioma do dispositivo e o idioma escolhido no app."},{"question":"Restauração, cancelamento e reembolsos","answer":"As compras e a restauração são realizadas pela loja oficial da Apple ou do Google. Um direito é concedido somente depois que a loja confirma uma transação válida. Transações canceladas, com falha ou pendentes não concedem direitos antes da confirmação. A restauração pode recuperar o acesso vitalício e uma assinatura atualmente ativa. As compras da App Store e do Google Play são independentes e não podem ser restauradas ou transferidas entre plataformas."},{"question":"Privacidade e exclusão de dados","answer":"Desinstale o app para excluir os dados do dispositivo. No Android, você também pode usar a opção do sistema “Limpar dados”. Os registros de compra são gerenciados pela Apple ou pelo Google. Os direitos restauráveis são confirmados novamente segundo as regras da loja. Os e-mails de suporte são mantidos pelo tempo necessário para atender à solicitação e cumprir requisitos essenciais de registro. Você pode nos enviar um e-mail para solicitar a exclusão das mensagens de suporte que ainda mantemos."}],"officialHelpTitle":"Ajuda rápida"}},"pt-PT":{"linkLabels":{"appleEula":"Contrato de Licença de Utilizador Final Padrão da Apple (EULA)","appleCancel":"Instruções para cancelamento de assinatura da Apple","googleManage":"Instruções de cancelamento do Google Play","appleRefund":"Solicite um reembolso à Apple.","googleRefund":"Informações sobre reembolso do Google Play"},"nav":{"privacy":"política de Privacidade","terms":"Termos de Uso","support":"Suporte","language":"Linguagem","chooseLanguage":"Selecione o idioma de exibição","navigationLabel":"Navegação principal"},"home":{"eyebrow":"{appName} · Privacy first","title":"As suas imagens não são enviadas para os nossos servidores.","lead":"A seleção de imagens, o OCR, a deteção de conteúdo sensível, a edição e a exportação são efetuados no dispositivo. A app não oferece reconhecimento de imagens na nuvem, sincronização na nuvem nem conta. Ao exportar, é criada uma nova imagem e são removidos os metadados privados que podem ser eliminados. Os ficheiros temporários de trabalho são apagados após uma gravação bem-sucedida, ao abandonar a edição ou no fim da sessão; se a gravação falhar, o estado necessário pode ser mantido para tentar novamente.","points":["Dados da aplicação","Produtos pagos e preços","Suporte"],"cards":[{"title":"política de Privacidade","description":"As suas imagens não são enviadas para os nossos servidores.","action":"política de Privacidade"},{"title":"Termos de Uso","description":"O reconhecimento e a edição não têm limites de utilização. Apenas a exportação da imagem processada exige acesso Premium válido. A app oferece assinaturas semanais e mensais com renovação automática e uma compra vitalícia única, sem avaliação gratuita. As compras na App Store e no Google Play são independentes e não podem ser transferidas entre plataformas.","action":"Termos de Uso"},{"title":"Precisar de ajuda?","description":"Comece pelas perguntas frequentes abaixo. Se o problema continuar, entre em contato pelo e-mail de assistência.","action":"Suporte"}]},"footer":{"privacy":"política de Privacidade","terms":"Termos de Uso","support":"Suporte"},"privacy":{"title":"política de Privacidade","lead":"Esta Política explica como {appName} trata dados no dispositivo, informações de compra da loja e e-mails de assistência.","sections":[{"title":"1. Âmbito de aplicação e contacto","paragraphs":["Esta Política se aplica à aplicação {appName} para iOS, iPadOS e Android e a este site de privacidade, termos e assistência.","Para questões de privacidade, envie um e-mail. {email}"]},{"title":"2. Dados da aplicação","callout":{"title":"As suas imagens não são enviadas para os nossos servidores.","body":"A seleção de imagens, o OCR, a deteção de conteúdo sensível, a edição e a exportação são efetuados no dispositivo. A app não oferece reconhecimento de imagens na nuvem, sincronização na nuvem nem conta. Ao exportar, é criada uma nova imagem e são removidos os metadados privados que podem ser eliminados. Os ficheiros temporários de trabalho são apagados após uma gravação bem-sucedida, ao abandonar a edição ou no fim da sessão; se a gravação falhar, o estado necessário pode ser mantido para tentar novamente."},"paragraphs":[]},{"title":"3. Permissões, publicidade e rastreamento","paragraphs":["O acesso às fotografias serve apenas para apresentar e processar as imagens que autorizar. A câmara só é utilizada quando escolher tirar uma fotografia na app. A permissão para guardar na fototeca só é pedida quando confirmar a exportação com acesso Premium válido. A app não solicita localização, contactos, microfone, Bluetooth nem notificações.","Ela não usa identificador de publicidade nem integra SDKs de terceiros para publicidade, análise, atribuição ou relatório de falhas.","A aplicação não integra ferramentas de terceiros para relatório de falhas. Conforme as configurações do dispositivo e da loja, a Apple ou o Google pode tratar informações de diagnóstico do sistema segundo suas regras de privacidade e fornecer dados técnicos para investigar falhas ou problemas de desempenho."]},{"title":"4. Serviços da loja e acesso à rede","paragraphs":["A aplicação usa Apple StoreKit ou Google Play Billing para carregar produtos, exibir preços localizados fornecidos pela loja, concluir e restaurar compras, gerir subscrições e confirmar direitos. O acesso à rede é usado somente para essas funções oficiais da Apple ou do Google.","A Apple ou o Google é responsável por contas da loja, pagamentos, faturações, transações, reembolsos e serviços de subscrição. A aplicação trata apenas as informações da loja necessárias para confirmar produtos e direitos e não recebe nem armazena credenciais completas de pagamento."]},{"title":"5. E-mails de assistência e site","paragraphs":["A aplicação não lê automaticamente as informações do seu e-mail. O canal de assistência só recebe seu endereço, mensagem e capturas de ecrã, gravações, números de pedido ou outros anexos fornecidos voluntariamente quando envia um e-mail de assistência. Essas informações são usadas somente para atender à solicitação e não para publicidade ou marketing. Não envie senhas de conta ou pagamento nem números completos de cartão.","Este site não define cookies de publicidade ou análise e não inclui scripts de análise de tráfego ou rastreamento."]},{"title":"6. Retenção e eliminação","paragraphs":["Desinstale a aplicação para eliminar os dados do dispositivo. No Android, também pode usar a opção do sistema “Limpar dados”.","Os registos de compra são geridos pela Apple ou pelo Google. Os direitos restauráveis são confirmados novamente segundo as regras da loja.","Os e-mails de assistência são mantidos pelo tempo necessário para atender à solicitação e cumprir requisitos essenciais de registo. Pode nos enviar um e-mail para solicitar a eliminação das mensagens de assistência que ainda mantemos."]},{"title":"7. Segurança dos dados","paragraphs":["A aplicação usa processamento no dispositivo, permissões mínimas e fluxos oficiais de compra para reduzir transferências desnecessárias de dados. Os e-mails de assistência são usados somente para atender às solicitações recebidas, com medidas razoáveis adequadas à natureza das informações.","Nenhum dispositivo, rede ou método de armazenamento eletrônico pode ter segurança absoluta garantida. Não inclua informações confidenciais sem relação com o problema em um e-mail de assistência."]},{"title":"8. Crianças e adolescentes","paragraphs":["A aplicação não exige conta nem cria perfis de crianças ou outros utilizadores por meio de publicidade ou análise comportamental. Se um responsável acreditar que uma criança forneceu informações pessoais em um e-mail de assistência, poderá entrar em contato para que a questão seja tratada."]},{"title":"9. Suas escolhas e seus direitos","paragraphs":["O utilizador gere os dados locais pelo dispositivo. A Apple ou o Google gere as contas da loja e os registos de compra. A aplicação não pode modificar nem eliminar em seu nome os registos de transações mantidos por uma loja.","Se as práticas de dados da aplicação, as regras das plataformas ou a hospedagem do site mudarem, atualizaremos esta Política e a data da página e forneceremos aviso adicional quando exigido pelas regras aplicáveis.","Para questões de privacidade, envie um e-mail. {email}"]}]},"terms":{"title":"Termos de Uso","lead":"Termos de Uso do {appName}.","sections":[{"title":"1. Aceitação destes Termos e das regras da plataforma","paragraphs":["Ao baixar, comprar ou usar o {appName}, você concorda com estes Termos e com as regras aplicáveis na loja de aplicativos onde você efetuar a compra. Caso não concorde, não continue a usar o aplicativo nem faça a compra.","Estes Termos se aplicam ao download, à compra e ao uso da aplicação. As versões para iOS e iPadOS também estão sujeitas ao"],"links":["appleEula"]},{"title":"2. Produtos pagos e preços","paragraphs":["O reconhecimento e a edição não têm limites de utilização. Apenas a exportação da imagem processada exige acesso Premium válido. A app oferece assinaturas semanais e mensais com renovação automática e uma compra vitalícia única, sem avaliação gratuita. As compras na App Store e no Google Play são independentes e não podem ser transferidas entre plataformas.","O preço real, a moeda, os impostos, o período de faturação e a elegibilidade para compra são as informações exibidas e confirmadas no ecrã de compra do sistema da App Store ou do Google Play. A plataforma cobra e gere o pagamento pela sua conta da loja. A aplicação não oferece teste gratuito de subscrição nem outros planos pagos."]},{"title":"3. Renovação automática e cancelamento","paragraphs":["As subscrições semanais e mensais são renovadas automaticamente e faturadas pelo período indicado no ecrã de compra até que as cancele na plataforma. Eliminar {appName} não cancela automaticamente uma subscrição. A menos que a plataforma conceda reembolso ou outro tratamento, poderá continuar usando a subscrição até o fim do período já pago após desativar a renovação automática."],"links":["appleCancel","googleManage"]},{"title":"4. Compras, restauração e reembolsos","paragraphs":["As compras e a restauração são realizadas pela loja oficial da Apple ou do Google. Um direito é concedido somente depois que a loja confirma uma transação válida. Transações canceladas, com falha ou pendentes não concedem direitos antes da confirmação. A restauração pode recuperar o acesso vitalício e uma subscrição atualmente ativa. As compras da App Store e do Google Play são independentes e não podem ser restauradas ou transferidas entre plataformas.","Os reembolsos são tratados pela loja que concluiu a transação, conforme suas regras, a região da compra e a legislação aplicável. O direito correspondente é removido quando a loja confirma reembolso, revogação, expiração da subscrição ou transação inválida."],"links":["appleRefund","googleRefund"]},{"title":"5. Uso offline e disponibilidade","paragraphs":["A seleção de imagens, o OCR, a deteção de conteúdo sensível, a edição e a exportação são efetuados no dispositivo. A app não oferece reconhecimento de imagens na nuvem, sincronização na nuvem nem conta. Ao exportar, é criada uma nova imagem e são removidos os metadados privados que podem ser eliminados. Os ficheiros temporários de trabalho são apagados após uma gravação bem-sucedida, ao abandonar a edição ou no fim da sessão; se a gravação falhar, o estado necessário pode ser mantido para tentar novamente."]},{"title":"6. Uso aceitável e propriedade intelectual","paragraphs":["Não deve usar a aplicação para atividades ilegais; contornar a verificação de compras; danificar a aplicação; distribuir código malicioso; copiar ou distribuir a aplicação sem permissão; nem violar direitos sobre o conteúdo da aplicação ou a propriedade intelectual de terceiros.","Pode parar de usar e desinstalar a aplicação a qualquer momento. Podemos lançar atualizações para corrigir problemas, assegurar compatibilidade com sistemas operativos, melhorar a estabilidade ou atender a requisitos das plataformas. Problemas no dispositivo, sistema, rede ou serviço da loja podem tornar alguns recursos temporariamente indisponíveis.","Na medida permitida pela legislação aplicável, a aplicação é fornecida conforme disponível. Estes Termos não excluem responsabilidades que não possam ser legalmente excluídas nem limitam direitos obrigatórios do consumidor.","Se os recursos, os métodos de pagamento, as regras das plataformas ou a legislação aplicável mudarem, poderemos atualizar estes Termos e a data da página. Se uma mudança afetar significativamente os direitos dos utilizadores, forneceremos o aviso adicional exigido.","Para dúvidas sobre estes Termos, compras ou uso do aplicativo, envie um e-mail. {email}"]}]},"support":{"title":"Suporte","lead":"Comece pelas perguntas frequentes abaixo. Se o problema continuar, entre em contato pelo e-mail de assistência.","emailTitle":"E-mail de suporte {appName}","emailLead":"Comece pelas perguntas frequentes abaixo. Se o problema continuar, entre em contato pelo e-mail de assistência.","beforeEmail":{"title":"O que incluir no e-mail","paragraphs":["Em caso de problema com uma compra, pode informar o número do pedido da loja, mas não envie a senha da conta ou do pagamento nem os dados completos do cartão."],"bullets":["sua plataforma, modelo do dispositivo, versão do sistema operativo e versão da aplicação;","o que fez antes do problema, o que esperava e o que realmente aconteceu; e","Se necessário, uma captura de tela ou gravação da tela com informações privadas ocultas."]},"faqs":[{"question":"As imagens são enviadas para algum servidor?","answer":"A seleção de imagens, o OCR, a deteção de conteúdo sensível, a edição e a exportação são efetuados no dispositivo. A app não oferece reconhecimento de imagens na nuvem, sincronização na nuvem nem conta. Ao exportar, é criada uma nova imagem e são removidos os metadados privados que podem ser eliminados. Os ficheiros temporários de trabalho são apagados após uma gravação bem-sucedida, ao abandonar a edição ou no fim da sessão; se a gravação falhar, o estado necessário pode ser mantido para tentar novamente."},{"question":"Permissões, publicidade e rastreamento","answer":"O acesso às fotografias serve apenas para apresentar e processar as imagens que autorizar. A câmara só é utilizada quando escolher tirar uma fotografia na app. A permissão para guardar na fototeca só é pedida quando confirmar a exportação com acesso Premium válido. A app não solicita localização, contactos, microfone, Bluetooth nem notificações."},{"question":"Produtos pagos e preços","answer":"O reconhecimento e a edição não têm limites de utilização. Apenas a exportação da imagem processada exige acesso Premium válido. A app oferece assinaturas semanais e mensais com renovação automática e uma compra vitalícia única, sem avaliação gratuita. As compras na App Store e no Google Play são independentes e não podem ser transferidas entre plataformas."},{"question":"Gravação e formatos de imagem","answer":"Se a gravação falhar, verifique o espaço disponível, a permissão para guardar na fototeca e se a imagem original continua legível; depois tente novamente. A app processa uma imagem estática de cada vez e suporta a maioria dos formatos comuns; alguns dependem do dispositivo e da versão do sistema. Vídeo, PDF, RAW/DNG e processamento em lote não são atualmente suportados."},{"question":"Como alterar o idioma?","answer":"A aplicação é compatível com 40 idiomas, que podem ser alterados nas configurações. Se a exibição estiver incorreta, informe por e-mail o idioma do dispositivo e o idioma escolhido na aplicação."},{"question":"Restauração, cancelamento e reembolsos","answer":"As compras e a restauração são realizadas pela loja oficial da Apple ou do Google. Um direito é concedido somente depois que a loja confirma uma transação válida. Transações canceladas, com falha ou pendentes não concedem direitos antes da confirmação. A restauração pode recuperar o acesso vitalício e uma subscrição atualmente ativa. As compras da App Store e do Google Play são independentes e não podem ser restauradas ou transferidas entre plataformas."},{"question":"Privacidade e eliminação de dados","answer":"Desinstale a aplicação para eliminar os dados do dispositivo. No Android, também pode usar a opção do sistema “Limpar dados”. Os registos de compra são geridos pela Apple ou pelo Google. Os direitos restauráveis são confirmados novamente segundo as regras da loja. Os e-mails de assistência são mantidos pelo tempo necessário para atender à solicitação e cumprir requisitos essenciais de registo. Pode nos enviar um e-mail para solicitar a eliminação das mensagens de assistência que ainda mantemos."}],"officialHelpTitle":"Ajuda rápida"}},"ro":{"linkLabels":{"appleEula":"Acordului standard de licență Apple pentru utilizatorul final (EULA)","appleCancel":"Instrucțiuni de anulare a abonamentului Apple","googleManage":"Instrucțiuni de anulare Google Play","appleRefund":"Solicitați o rambursare de la Apple","googleRefund":"Informații privind rambursările Google Play"},"nav":{"privacy":"Politica de confidențialitate","terms":"Termeni de utilizare","support":"Asistență","language":"Limbă","chooseLanguage":"Selectați limba de afișare","navigationLabel":"Navigare principală"},"home":{"eyebrow":"{appName} · Privacy first","title":"Imaginile tale nu sunt încărcate pe serverele noastre.","lead":"Selectarea imaginilor, OCR, detectarea conținutului sensibil, editarea și exportul au loc pe dispozitiv. Aplicația nu oferă recunoaștere de imagini în cloud, sincronizare în cloud sau conturi. La export se creează o imagine nouă și se elimină metadatele private care pot fi șterse. Fișierele temporare de lucru sunt șterse după salvarea reușită, renunțarea la editare sau încheierea sesiunii; dacă salvarea eșuează, starea necesară poate fi păstrată pentru reîncercare.","points":["Datele aplicației","Produse plătite și prețuri","Asistență"],"cards":[{"title":"Politica de confidențialitate","description":"Imaginile tale nu sunt încărcate pe serverele noastre.","action":"Politica de confidențialitate"},{"title":"Termeni de utilizare","description":"Recunoașterea și editarea nu au limite de utilizare. Numai exportul imaginii procesate necesită acces Premium valabil. Aplicația oferă abonamente săptămânale și lunare cu reînnoire automată și o achiziție unică pe viață, fără perioadă de probă gratuită. Achizițiile din App Store și Google Play sunt separate și nu pot fi transferate între platforme.","action":"Termeni de utilizare"},{"title":"Ai nevoie de ajutor?","description":"Consultă mai întâi întrebările frecvente de mai jos. Dacă problema persistă, contactează-ne prin e-mailul de asistență.","action":"Asistență"}]},"footer":{"privacy":"Politica de confidențialitate","terms":"Termeni de utilizare","support":"Asistență"},"privacy":{"title":"Politica de confidențialitate","lead":"Această Politică explică modul în care {appName} gestionează datele de pe dispozitiv, informațiile despre cumpărături din magazin și e-mailurile de asistență.","sections":[{"title":"1. Domeniu de aplicare și contact","paragraphs":["Această Politică se aplică aplicației {appName} pentru iOS, iPadOS și Android și acestui site privind confidențialitatea, condițiile și asistența.","Pentru întrebări legate de confidențialitate, trimiteți un e-mail {email}"]},{"title":"2. Datele aplicației","callout":{"title":"Imaginile tale nu sunt încărcate pe serverele noastre.","body":"Selectarea imaginilor, OCR, detectarea conținutului sensibil, editarea și exportul au loc pe dispozitiv. Aplicația nu oferă recunoaștere de imagini în cloud, sincronizare în cloud sau conturi. La export se creează o imagine nouă și se elimină metadatele private care pot fi șterse. Fișierele temporare de lucru sunt șterse după salvarea reușită, renunțarea la editare sau încheierea sesiunii; dacă salvarea eșuează, starea necesară poate fi păstrată pentru reîncercare."},"paragraphs":[]},{"title":"3. Permisiuni, publicitate și urmărire","paragraphs":["Accesul la fotografii este folosit doar pentru afișarea și procesarea imaginilor pe care le autorizezi. Camera este folosită numai când alegi să faci o fotografie în aplicație. Permisiunea de salvare în biblioteca foto este solicitată numai când confirmi exportul cu acces Premium valabil. Aplicația nu solicită locația, contactele, microfonul, Bluetooth sau notificările.","Nu folosește un identificator publicitar și nu integrează SDK-uri terțe pentru publicitate, analiză, atribuire sau raportarea blocărilor.","Aplicația nu integrează un instrument terț de raportare a blocărilor. În funcție de setările dispozitivului și magazinului, Apple sau Google poate prelucra informații de diagnostic ale sistemului conform propriilor reguli de confidențialitate și poate furniza date tehnice pentru investigarea blocărilor sau problemelor de performanță."]},{"title":"4. Serviciile magazinului și accesul la rețea","paragraphs":["Aplicația folosește Apple StoreKit sau Google Play Billing pentru a încărca produsele, a afișa prețurile locale returnate de magazin, a finaliza și restaura cumpărăturile, a gestiona abonamentele și a confirma drepturile. Accesul la rețea este folosit numai pentru aceste funcții oficiale Apple sau Google.","Apple sau Google răspunde pentru conturile magazinului, plăți, facturare, tranzacții, rambursări și servicii de abonament. Aplicația prelucrează numai informațiile necesare pentru confirmarea produselor și drepturilor și nu primește ori stochează date complete de plată."]},{"title":"5. E-mailuri de asistență și site","paragraphs":["Aplicația nu citește automat datele tale de e-mail. Canalul de asistență primește adresa, mesajul și capturile, înregistrările de ecran, numerele de comandă sau alte atașamente oferite voluntar numai când trimiți un e-mail de asistență. Informațiile sunt folosite exclusiv pentru solicitare, nu pentru publicitate sau marketing. Nu trimite parole de cont ori de plată sau numere complete de card.","Acest site nu setează module cookie de publicitate sau analiză și nu include scripturi de analiză a traficului ori urmărire."]},{"title":"6. Păstrare și ștergere","paragraphs":["Dezinstalează aplicația pentru a șterge datele de pe dispozitiv. Pe Android poți folosi și opțiunea de sistem „Șterge datele”.","Evidențele cumpărăturilor sunt gestionate de Apple sau Google. Drepturile restaurabile sunt confirmate din nou conform regulilor magazinului.","E-mailurile de asistență sunt păstrate cât este necesar pentru soluționarea solicitării și respectarea cerințelor necesare de evidență. Ne poți scrie pentru a cere ștergerea corespondenței de asistență pe care încă o păstrăm."]},{"title":"7. Securitatea datelor","paragraphs":["Aplicația folosește prelucrarea pe dispozitiv, permisiuni minime și fluxurile oficiale de cumpărare pentru a reduce transferurile inutile de date. E-mailurile de asistență sunt folosite doar pentru solicitările primite, cu măsuri rezonabile potrivite naturii informațiilor.","Niciun dispozitiv, nicio rețea și nicio metodă de stocare electronică nu pot fi garantate ca fiind complet sigure. Nu include informații sensibile fără legătură cu problema într-un e-mail de asistență."]},{"title":"8. Copii și adolescenți","paragraphs":["Aplicația nu necesită cont și nu creează profiluri ale copiilor sau altor utilizatori prin publicitate ori analiză comportamentală. Un părinte sau tutore care crede că un copil a transmis informații personale într-un e-mail de asistență ne poate contacta pentru soluționarea situației."]},{"title":"9. Opțiunile și drepturile tale","paragraphs":["Gestionezi datele locale prin dispozitiv. Apple sau Google gestionează conturile magazinului și evidențele cumpărăturilor. Aplicația nu poate modifica sau șterge în numele tău înregistrările tranzacțiilor păstrate de un magazin.","Dacă se schimbă practicile de date ale aplicației, regulile platformelor sau găzduirea site-ului, vom actualiza această Politică și data paginii și vom furniza o notificare suplimentară când regulile aplicabile o cer.","Pentru întrebări legate de confidențialitate, trimiteți un e-mail {email}"]}]},"terms":{"title":"Termeni de utilizare","lead":"Termeni de utilizare {appName}.","sections":[{"title":"1. Acceptarea acestor Termeni și a regulilor platformei","paragraphs":["Prin descărcarea, achiziționarea sau utilizarea aplicației {appName}, sunteți de acord cu acești Termeni și cu regulile care vi se aplică în magazinul de aplicații de unde efectuați o achiziție. Dacă nu sunteți de acord, nu continuați să utilizați aplicația sau să faceți o achiziție.","Acești Termeni se aplică descărcării, cumpărării și utilizării aplicației. Versiunile iOS și iPadOS sunt supuse și"],"links":["appleEula"]},{"title":"2. Produse plătite și prețuri","paragraphs":["Recunoașterea și editarea nu au limite de utilizare. Numai exportul imaginii procesate necesită acces Premium valabil. Aplicația oferă abonamente săptămânale și lunare cu reînnoire automată și o achiziție unică pe viață, fără perioadă de probă gratuită. Achizițiile din App Store și Google Play sunt separate și nu pot fi transferate între platforme.","Prețul real, moneda, taxele, perioada de facturare și eligibilitatea pentru cumpărare sunt informațiile afișate și confirmate în ecranul de cumpărare al App Store sau Google Play. Platforma taxează și gestionează plata prin contul magazinului. Aplicația nu oferă o perioadă gratuită de probă pentru abonament sau alte planuri plătite."]},{"title":"3. Reînnoire automată și anulare","paragraphs":["Abonamentele săptămânale și lunare se reînnoiesc automat și sunt taxate pentru perioada afișată în ecranul de cumpărare până când le anulezi prin platformă. Ștergerea {appName} nu anulează automat abonamentul. Dacă platforma nu acordă rambursare sau altă soluție, poți folosi abonamentul până la sfârșitul perioadei deja plătite după dezactivarea reînnoirii."],"links":["appleCancel","googleManage"]},{"title":"4. Cumpărături, restaurare și rambursări","paragraphs":["Cumpărăturile și restaurarea se realizează prin magazinul oficial Apple sau Google. Un drept este acordat numai după confirmarea unei tranzacții valabile de către magazin. Tranzacțiile anulate, nereușite sau în așteptare nu acordă drepturi înainte de confirmare. Restaurarea poate recupera accesul pe viață și un abonament activ. Cumpărăturile App Store și Google Play sunt independente și nu pot fi restaurate sau transferate între platforme.","Rambursările sunt gestionate de magazinul care a finalizat tranzacția, conform regulilor sale, regiunii cumpărării și legislației aplicabile. Dreptul este eliminat după confirmarea unei rambursări, revocări, expirări a abonamentului sau tranzacții nevalide."],"links":["appleRefund","googleRefund"]},{"title":"5. Utilizare offline și disponibilitate","paragraphs":["Selectarea imaginilor, OCR, detectarea conținutului sensibil, editarea și exportul au loc pe dispozitiv. Aplicația nu oferă recunoaștere de imagini în cloud, sincronizare în cloud sau conturi. La export se creează o imagine nouă și se elimină metadatele private care pot fi șterse. Fișierele temporare de lucru sunt șterse după salvarea reușită, renunțarea la editare sau încheierea sesiunii; dacă salvarea eșuează, starea necesară poate fi păstrată pentru reîncercare."]},{"title":"6. Utilizare acceptabilă și proprietate intelectuală","paragraphs":["Nu poți folosi aplicația pentru activități ilegale, evita verificarea cumpărăturilor, deteriora aplicația, distribui cod rău intenționat, copia sau distribui aplicația fără permisiune ori încălca drepturile asupra conținutului aplicației sau proprietatea intelectuală a altora.","Poți înceta utilizarea și dezinstala aplicația oricând. Putem publica actualizări pentru remedierea problemelor, acceptarea sistemelor, îmbunătățirea stabilității sau respectarea cerințelor platformelor. Problemele dispozitivului, sistemului, rețelei sau magazinului pot face unele funcții temporar indisponibile.","În măsura permisă de lege, aplicația este oferită în forma disponibilă. Acești Termeni nu exclud răspunderea care nu poate fi exclusă legal și nu limitează drepturile obligatorii ale consumatorilor.","Dacă se schimbă funcțiile, metodele de plată, regulile platformelor sau legislația, putem actualiza Termenii și data paginii. Dacă o schimbare afectează substanțial drepturile utilizatorilor, vom furniza notificarea suplimentară necesară.","Pentru întrebări despre acești Termeni, achiziții sau utilizarea aplicației, trimiteți un e-mail {email}"]}]},"support":{"title":"Asistență","lead":"Consultă mai întâi întrebările frecvente de mai jos. Dacă problema persistă, contactează-ne prin e-mailul de asistență.","emailTitle":"Adresă de e-mail de asistență {appName}","emailLead":"Consultă mai întâi întrebările frecvente de mai jos. Dacă problema persistă, contactează-ne prin e-mailul de asistență.","beforeEmail":{"title":"Ce să incluzi în e-mail","paragraphs":["Pentru o problemă de cumpărare poți include numărul comenzii din magazin, dar nu trimite parola contului sau plății ori datele complete ale cardului."],"bullets":["platforma, modelul dispozitivului, versiunea sistemului și versiunea aplicației;","acțiunile anterioare problemei, rezultatul așteptat și cel real; și","dacă este necesar, o captură de ecran sau o înregistrare a ecranului cu informații private ascunse."]},"faqs":[{"question":"Imaginile sunt încărcate pe un server?","answer":"Selectarea imaginilor, OCR, detectarea conținutului sensibil, editarea și exportul au loc pe dispozitiv. Aplicația nu oferă recunoaștere de imagini în cloud, sincronizare în cloud sau conturi. La export se creează o imagine nouă și se elimină metadatele private care pot fi șterse. Fișierele temporare de lucru sunt șterse după salvarea reușită, renunțarea la editare sau încheierea sesiunii; dacă salvarea eșuează, starea necesară poate fi păstrată pentru reîncercare."},{"question":"Permisiuni, publicitate și urmărire","answer":"Accesul la fotografii este folosit doar pentru afișarea și procesarea imaginilor pe care le autorizezi. Camera este folosită numai când alegi să faci o fotografie în aplicație. Permisiunea de salvare în biblioteca foto este solicitată numai când confirmi exportul cu acces Premium valabil. Aplicația nu solicită locația, contactele, microfonul, Bluetooth sau notificările."},{"question":"Produse plătite și prețuri","answer":"Recunoașterea și editarea nu au limite de utilizare. Numai exportul imaginii procesate necesită acces Premium valabil. Aplicația oferă abonamente săptămânale și lunare cu reînnoire automată și o achiziție unică pe viață, fără perioadă de probă gratuită. Achizițiile din App Store și Google Play sunt separate și nu pot fi transferate între platforme."},{"question":"Salvare și formate de imagine","answer":"Dacă salvarea eșuează, verifică spațiul disponibil, permisiunea de salvare în biblioteca foto și dacă imaginea originală mai poate fi citită, apoi încearcă din nou. Aplicația procesează câte o imagine statică și acceptă majoritatea formatelor obișnuite; unele depind de dispozitiv și versiunea sistemului. Video, PDF, RAW/DNG și procesarea în lot nu sunt acceptate momentan."},{"question":"Cum schimb limba?","answer":"Aplicația acceptă 40 de limbi, care pot fi schimbate din setări. Dacă afișarea este incorectă, trimite prin e-mail limba dispozitivului și limba selectată în aplicație."},{"question":"Restaurare, anulare și rambursări","answer":"Cumpărăturile și restaurarea se realizează prin magazinul oficial Apple sau Google. Un drept este acordat numai după confirmarea unei tranzacții valabile de către magazin. Tranzacțiile anulate, nereușite sau în așteptare nu acordă drepturi înainte de confirmare. Restaurarea poate recupera accesul pe viață și un abonament activ. Cumpărăturile App Store și Google Play sunt independente și nu pot fi restaurate sau transferate între platforme."},{"question":"Confidențialitate și ștergerea datelor","answer":"Dezinstalează aplicația pentru a șterge datele de pe dispozitiv. Pe Android poți folosi și opțiunea de sistem „Șterge datele”. Evidențele cumpărăturilor sunt gestionate de Apple sau Google. Drepturile restaurabile sunt confirmate din nou conform regulilor magazinului. E-mailurile de asistență sunt păstrate cât este necesar pentru soluționarea solicitării și respectarea cerințelor necesare de evidență. Ne poți scrie pentru a cere ștergerea corespondenței de asistență pe care încă o păstrăm."}],"officialHelpTitle":"Ajutor rapid"}},"ru":{"linkLabels":{"appleEula":"Стандартное лицензионное соглашение Apple с конечным пользователем (EULA)","appleCancel":"Инструкции по отмене подписки Apple","googleManage":"Инструкции по отмене в Google Play","appleRefund":"Запросить возврат средств у Apple","googleRefund":"Информация о возврате средств Google Play"},"nav":{"privacy":"политика конфиденциальности","terms":"Условия эксплуатации","support":"Поддержка","language":"Язык","chooseLanguage":"Выберите язык отображения","navigationLabel":"Основная навигация"},"home":{"eyebrow":"{appName} · Privacy first","title":"Ваши изображения не загружаются на наши серверы.","lead":"Выбор изображений, OCR, обнаружение конфиденциального содержимого, редактирование и экспорт выполняются на устройстве. В приложении нет облачного распознавания изображений, облачной синхронизации и учётных записей. При экспорте создаётся новое изображение и удаляются доступные для удаления конфиденциальные метаданные. Временные рабочие файлы удаляются после успешного сохранения, отмены редактирования или завершения сеанса; при ошибке сохранения необходимое состояние может быть оставлено для повторной попытки.","points":["Данные приложения","Платные продукты и цены","Поддержка"],"cards":[{"title":"политика конфиденциальности","description":"Ваши изображения не загружаются на наши серверы.","action":"политика конфиденциальности"},{"title":"Условия эксплуатации","description":"Распознавание и редактирование не имеют лимитов использования. Действующий Premium требуется только для экспорта обработанного изображения. Доступны автоматически продлеваемые недельная и месячная подписки и разовая пожизненная покупка, без бесплатного пробного периода. Покупки в App Store и Google Play независимы и не переносятся между платформами.","action":"Условия эксплуатации"},{"title":"Нужна помощь?","description":"Сначала ознакомьтесь с частыми вопросами ниже. Если проблема остается, напишите на адрес поддержки.","action":"Поддержка"}]},"footer":{"privacy":"политика конфиденциальности","terms":"Условия эксплуатации","support":"Поддержка"},"privacy":{"title":"политика конфиденциальности","lead":"В этой Политике объясняется, как {appName} обрабатывает данные на устройстве, сведения о покупках магазина и письма в поддержку.","sections":[{"title":"1. Сфера деятельности и контакты","paragraphs":["Эта Политика относится к приложению {appName} для iOS, iPadOS и Android, а также к этому сайту о конфиденциальности, условиях и поддержке.","По вопросам конфиденциальности пишите на электронную почту. {email}"]},{"title":"2. Данные приложения","callout":{"title":"Ваши изображения не загружаются на наши серверы.","body":"Выбор изображений, OCR, обнаружение конфиденциального содержимого, редактирование и экспорт выполняются на устройстве. В приложении нет облачного распознавания изображений, облачной синхронизации и учётных записей. При экспорте создаётся новое изображение и удаляются доступные для удаления конфиденциальные метаданные. Временные рабочие файлы удаляются после успешного сохранения, отмены редактирования или завершения сеанса; при ошибке сохранения необходимое состояние может быть оставлено для повторной попытки."},"paragraphs":[]},{"title":"3. Разрешения, реклама и отслеживание","paragraphs":["Доступ к фото используется только для показа и обработки разрешённых вами изображений. Камера используется только когда вы выбираете съёмку в приложении. Разрешение на сохранение в медиатеку запрашивается только при подтверждении экспорта с действующим доступом Premium. Приложение не запрашивает геопозицию, контакты, микрофон, Bluetooth или уведомления.","Оно не использует рекламный идентификатор и не подключает сторонние SDK для рекламы, аналитики, атрибуции или отчетов о сбоях.","Приложение не подключает сторонний инструмент отчетов о сбоях. В зависимости от настроек устройства и магазина Apple или Google может обрабатывать системные диагностические сведения согласно своим правилам конфиденциальности и предоставлять технические данные для изучения сбоев или проблем производительности."]},{"title":"4. Сервисы магазина и доступ к сети","paragraphs":["Приложение использует Apple StoreKit или Google Play Billing для загрузки товаров, отображения локальных цен от магазина, совершения и восстановления покупок, управления подписками и подтверждения прав. Доступ к сети используется только для этих официальных функций магазинов Apple или Google.","Apple или Google отвечает за учетные записи магазина, платежи, выставление счетов, транзакции, возврат средств и подписки. Приложение обрабатывает только сведения магазина, необходимые для подтверждения товаров и прав, и не получает и не хранит полные платежные данные."]},{"title":"5. Письма в поддержку и сайт","paragraphs":["Приложение не читает данные вашей электронной почты автоматически. Только когда вы отправляете письмо в поддержку, канал поддержки получает ваш адрес, сообщение и добровольно приложенные снимки или записи экрана, номер заказа либо другие вложения. Эти сведения используются только для обработки запроса, а не для рекламы или маркетинга. Не отправляйте пароли учетной записи или платежа и полные номера карт.","Этот сайт не устанавливает рекламные или аналитические файлы cookie и не содержит скрипты анализа посещений или отслеживания."]},{"title":"6. Хранение и удаление","paragraphs":["Чтобы удалить данные с устройства, удалите приложение. На Android также можно использовать системную функцию «Очистить данные».","Записи о покупках управляются Apple или Google. Восстанавливаемые права повторно подтверждаются по правилам магазина.","Письма в поддержку хранятся столько, сколько необходимо для обработки запроса и выполнения обязательных требований к учету. Вы можете попросить по электронной почте удалить переписку с поддержкой, которую мы еще храним."]},{"title":"7. Безопасность данных","paragraphs":["Приложение использует обработку на устройстве, минимальные разрешения и официальные процессы покупки в магазинах, чтобы сократить ненужную передачу данных. Письма в поддержку используются только для обработки обращений и защищаются разумными мерами, соответствующими характеру сведений.","Нельзя гарантировать абсолютную безопасность устройства, сети или электронного способа хранения. Не указывайте в письме в поддержку не относящиеся к вопросу конфиденциальные сведения."]},{"title":"8. Дети и подростки","paragraphs":["Приложение не требует учетной записи и не создает профили детей или других пользователей с помощью рекламы или поведенческой аналитики. Родитель или опекун, считающий, что ребенок отправил персональные данные в письме в поддержку, может связаться с нами для решения вопроса."]},{"title":"9. Ваш выбор и права","paragraphs":["Вы управляете локальными данными через устройство. Apple или Google управляет учетными записями магазина и записями покупок. Приложение не может от вашего имени изменить или удалить записи транзакций, хранящиеся в магазине.","Если изменятся способы обработки данных приложением, правила платформ или размещение сайта, мы обновим эту Политику и дату на странице и предоставим дополнительное уведомление, если этого требуют применимые правила.","По вопросам конфиденциальности пишите на электронную почту. {email}"]}]},"terms":{"title":"Условия эксплуатации","lead":"Условия использования {appName}.","sections":[{"title":"1. Принятие настоящих Условий и правил платформы.","paragraphs":["Загружая, приобретая или используя {appName}, вы соглашаетесь с настоящими Условиями и правилами, действующими в магазине приложений, где вы совершаете покупку. Если вы не согласны, не продолжайте использовать приложение и не совершайте покупку.","Эти Условия относятся к загрузке, покупке и использованию приложения. К версиям для iOS и iPadOS также применяется"],"links":["appleEula"]},{"title":"2. Платные продукты и цены","paragraphs":["Распознавание и редактирование не имеют лимитов использования. Действующий Premium требуется только для экспорта обработанного изображения. Доступны автоматически продлеваемые недельная и месячная подписки и разовая пожизненная покупка, без бесплатного пробного периода. Покупки в App Store и Google Play независимы и не переносятся между платформами.","Фактическая цена, валюта, налоги, расчетный период и возможность покупки соответствуют сведениям, показанным и подтвержденным на системном экране покупки App Store или Google Play. Платформа списывает платеж через вашу учетную запись магазина и управляет им. Приложение не предлагает бесплатный пробный период подписки или другие платные планы."]},{"title":"3. Автоматическое продление и отмена","paragraphs":["Недельная и месячная подписки продлеваются автоматически и оплачиваются за период, указанный на системном экране покупки, пока вы не отмените их через платформу покупки. Удаление {appName} не отменяет подписку автоматически. Если платформа не оформит возврат или иное решение, после отключения автоматического продления подпиской можно пользоваться до конца уже оплаченного периода."],"links":["appleCancel","googleManage"]},{"title":"4. Покупки, восстановление и возврат средств","paragraphs":["Покупки и их восстановление выполняются через официальный магазин Apple или Google. Право предоставляется только после подтверждения действительной транзакции магазином. Отмененные, неудачные или ожидающие транзакции не дают право до успешного подтверждения. Восстановление покупок может вернуть бессрочный доступ и действующую подписку. Покупки в App Store и Google Play независимы, и их нельзя восстанавливать или переносить между платформами.","Возврат средств обрабатывает магазин, завершивший транзакцию, согласно своим правилам, региону покупки и применимому законодательству. Соответствующее право удаляется после подтверждения магазином возврата, отзыва, окончания подписки или недействительной транзакции."],"links":["appleRefund","googleRefund"]},{"title":"5. Использование офлайн и доступность","paragraphs":["Выбор изображений, OCR, обнаружение конфиденциального содержимого, редактирование и экспорт выполняются на устройстве. В приложении нет облачного распознавания изображений, облачной синхронизации и учётных записей. При экспорте создаётся новое изображение и удаляются доступные для удаления конфиденциальные метаданные. Временные рабочие файлы удаляются после успешного сохранения, отмены редактирования или завершения сеанса; при ошибке сохранения необходимое состояние может быть оставлено для повторной попытки."]},{"title":"6. Допустимое использование и интеллектуальная собственность","paragraphs":["Запрещено использовать приложение для незаконной деятельности, обходить проверку покупок, повреждать приложение, распространять вредоносный код, копировать или распространять приложение без разрешения либо нарушать права на материалы приложения или интеллектуальную собственность других лиц.","Вы можете прекратить использование и удалить приложение в любое время. Мы можем выпускать обновления для исправления проблем, поддержки систем, повышения стабильности или соблюдения требований платформ. Проблемы устройства, системы, сети или сервиса магазина могут временно сделать отдельные функции недоступными.","В пределах, разрешенных применимым законодательством, приложение предоставляется по мере доступности. Эти Условия не исключают ответственность, которую нельзя законно исключить, и не ограничивают обязательные права потребителей.","Если изменятся функции, способы оплаты, правила платформ или применимое законодательство, мы можем обновить эти Условия и дату на странице. Если изменение существенно затрагивает права пользователей, мы предоставим требуемое дополнительное уведомление.","По вопросам, касающимся данных Условий, покупок или использования приложения, обращайтесь по электронной почте. {email}"]}]},"support":{"title":"Поддержка","lead":"Сначала ознакомьтесь с частыми вопросами ниже. Если проблема остается, напишите на адрес поддержки.","emailTitle":"Адрес электронной почты службы поддержки {appName}","emailLead":"Сначала ознакомьтесь с частыми вопросами ниже. Если проблема остается, напишите на адрес поддержки.","beforeEmail":{"title":"Что указать в письме","paragraphs":["По вопросу покупки можно указать номер заказа магазина, но не отправляйте пароль учетной записи или платежа и полные данные карты."],"bullets":["платформу, модель устройства, версию системы и версию приложения;","действия перед возникновением проблемы, ожидаемый и фактический результат; и","При необходимости — снимок экрана или запись экрана, на которой не указана конфиденциальная информация."]},"faqs":[{"question":"Загружаются ли изображения на сервер?","answer":"Выбор изображений, OCR, обнаружение конфиденциального содержимого, редактирование и экспорт выполняются на устройстве. В приложении нет облачного распознавания изображений, облачной синхронизации и учётных записей. При экспорте создаётся новое изображение и удаляются доступные для удаления конфиденциальные метаданные. Временные рабочие файлы удаляются после успешного сохранения, отмены редактирования или завершения сеанса; при ошибке сохранения необходимое состояние может быть оставлено для повторной попытки."},{"question":"Разрешения, реклама и отслеживание","answer":"Доступ к фото используется только для показа и обработки разрешённых вами изображений. Камера используется только когда вы выбираете съёмку в приложении. Разрешение на сохранение в медиатеку запрашивается только при подтверждении экспорта с действующим доступом Premium. Приложение не запрашивает геопозицию, контакты, микрофон, Bluetooth или уведомления."},{"question":"Платные продукты и цены","answer":"Распознавание и редактирование не имеют лимитов использования. Действующий Premium требуется только для экспорта обработанного изображения. Доступны автоматически продлеваемые недельная и месячная подписки и разовая пожизненная покупка, без бесплатного пробного периода. Покупки в App Store и Google Play независимы и не переносятся между платформами."},{"question":"Сохранение и форматы изображений","answer":"Если сохранение не удалось, проверьте свободное место, разрешение на сохранение в медиатеку и доступность исходного изображения, затем повторите попытку. Приложение обрабатывает по одному статическому изображению и поддерживает большинство распространённых форматов; некоторые зависят от устройства и версии системы. Видео, PDF, RAW/DNG и пакетная обработка пока не поддерживаются."},{"question":"Как изменить язык?","answer":"Приложение поддерживает 40 языков, которые можно выбрать в настройках. Если язык отображается неверно, укажите в письме язык устройства и язык, выбранный в приложении."},{"question":"Восстановление, отмена и возврат средств","answer":"Покупки и их восстановление выполняются через официальный магазин Apple или Google. Право предоставляется только после подтверждения действительной транзакции магазином. Отмененные, неудачные или ожидающие транзакции не дают право до успешного подтверждения. Восстановление покупок может вернуть бессрочный доступ и действующую подписку. Покупки в App Store и Google Play независимы, и их нельзя восстанавливать или переносить между платформами."},{"question":"Конфиденциальность и удаление данных","answer":"Чтобы удалить данные с устройства, удалите приложение. На Android также можно использовать системную функцию «Очистить данные». Записи о покупках управляются Apple или Google. Восстанавливаемые права повторно подтверждаются по правилам магазина. Письма в поддержку хранятся столько, сколько необходимо для обработки запроса и выполнения обязательных требований к учету. Вы можете попросить по электронной почте удалить переписку с поддержкой, которую мы еще храним."}],"officialHelpTitle":"Быстрая помощь"}},"sk":{"linkLabels":{"appleEula":"Štandardnou licenčnou zmluvou spoločnosti Apple s koncovým používateľom (EULA)","appleCancel":"Pokyny na zrušenie predplatného Apple","googleManage":"Pokyny na zrušenie v Google Play","appleRefund":"Žiadosť o vrátenie peňazí od spoločnosti Apple","googleRefund":"Informácie o vrátení peňazí v Google Play"},"nav":{"privacy":"Zásady ochrany osobných údajov","terms":"Podmienky používania","support":"Podpora","language":"Jazyk","chooseLanguage":"Vyberte jazyk zobrazenia","navigationLabel":"Hlavná navigácia"},"home":{"eyebrow":"{appName} · Privacy first","title":"Vaše obrázky sa neodosielajú na naše servery.","lead":"Výber obrázkov, OCR, zisťovanie citlivého obsahu, úpravy a export prebiehajú v zariadení. Aplikácia neposkytuje cloudové rozpoznávanie obrázkov, synchronizáciu s cloudom ani účty. Pri exporte sa vytvorí nový obrázok a odstránia sa odstrániteľné súkromné metadáta. Dočasné pracovné súbory sa vymažú po úspešnom uložení, zrušení úprav alebo ukončení relácie; pri zlyhaní uloženia sa môže zachovať stav potrebný na opakovanie.","points":["Údaje aplikácie","Platené produkty a ceny","Podpora"],"cards":[{"title":"Zásady ochrany osobných údajov","description":"Vaše obrázky sa neodosielajú na naše servery.","action":"Zásady ochrany osobných údajov"},{"title":"Podmienky používania","description":"Rozpoznávanie a úpravy nemajú limit použitia. Platný prístup Premium je potrebný iba na export spracovaného obrázka. Aplikácia ponúka automaticky obnovované týždenné a mesačné predplatné a jednorazový doživotný nákup bez bezplatnej skúšobnej verzie. Nákupy v App Store a Google Play sú oddelené a nemožno ich prenášať medzi platformami.","action":"Podmienky používania"},{"title":"Potrebujete pomoc?","description":"Začnite častými otázkami nižšie. Ak problém pretrváva, kontaktujte nás prostredníctvom e-mailovej adresy podpory.","action":"Podpora"}]},"footer":{"privacy":"Zásady ochrany osobných údajov","terms":"Podmienky používania","support":"Podpora"},"privacy":{"title":"Zásady ochrany osobných údajov","lead":"Tieto zásady vysvetľujú, ako {appName} spracúva údaje v zariadení, informácie o nákupoch z obchodu s aplikáciami a e-maily podpory.","sections":[{"title":"1. Rozsah a kontakt","paragraphs":["Tieto zásady sa vzťahujú na aplikáciu {appName} pre iOS, iPadOS a Android a na túto webovú lokalitu s informáciami o ochrane súkromia, podmienkach a podpore.","V prípade otázok týkajúcich sa ochrany osobných údajov nám pošlite e-mail {email}"]},{"title":"2. Údaje aplikácie","callout":{"title":"Vaše obrázky sa neodosielajú na naše servery.","body":"Výber obrázkov, OCR, zisťovanie citlivého obsahu, úpravy a export prebiehajú v zariadení. Aplikácia neposkytuje cloudové rozpoznávanie obrázkov, synchronizáciu s cloudom ani účty. Pri exporte sa vytvorí nový obrázok a odstránia sa odstrániteľné súkromné metadáta. Dočasné pracovné súbory sa vymažú po úspešnom uložení, zrušení úprav alebo ukončení relácie; pri zlyhaní uloženia sa môže zachovať stav potrebný na opakovanie."},"paragraphs":[]},{"title":"3. Povolenia, reklama a sledovanie","paragraphs":["Prístup k fotografiám sa používa len na zobrazenie a spracovanie obrázkov, ktoré povolíte. Fotoaparát sa použije iba vtedy, keď sa rozhodnete odfotiť obrázok v aplikácii. Povolenie ukladať do fotoknižnice sa vyžiada iba pri potvrdení exportu s platným prístupom Premium. Aplikácia nežiada polohu, kontakty, mikrofón, Bluetooth ani oznámenia.","Nepoužíva reklamný identifikátor ani neintegruje SDK tretích strán na reklamu, analytiku, atribúciu alebo hlásenie zlyhaní.","Aplikácia neintegruje nástroj tretej strany na hlásenie zlyhaní. V závislosti od nastavení zariadenia a obchodu môže Apple alebo Google spracúvať systémové diagnostické údaje podľa svojich pravidiel ochrany súkromia a poskytovať technické informácie používané na vyšetrovanie zlyhaní alebo problémov s výkonom."]},{"title":"4. Služby obchodu s aplikáciami a prístup k sieti","paragraphs":["Aplikácia používa Apple StoreKit alebo Google Play Billing na načítanie produktov, zobrazenie lokalizovaných cien vrátených obchodom, dokončenie nákupov, obnovenie nákupov, správu predplatných a potvrdenie oprávnení. Prístup k sieti sa používa iba na tieto oficiálne funkcie obchodu Apple alebo Google.","Apple alebo Google zodpovedá za účty v obchode, platby, fakturáciu, transakcie, vrátenia peňazí a služby predplatného. Aplikácia spracúva iba informácie z obchodu potrebné na potvrdenie produktov a oprávnení a neprijíma ani neukladá úplné platobné údaje."]},{"title":"5. E-maily podpory a webová lokalita","paragraphs":["Aplikácia automaticky nečíta vaše e-mailové údaje. Iba keď sa rozhodnete odoslať e-mail podpore, kanál podpory prijme vašu e-mailovú adresu, správu a všetky snímky obrazovky, záznamy obrazovky, čísla objednávok alebo iné prílohy, ktoré dobrovoľne poskytnete. Tieto informácie sa používajú iba na vybavenie vašej žiadosti a nie na reklamu alebo marketing. Neposielajte heslá účtu, platobné heslá ani úplné čísla kariet.","Táto webová lokalita nenastavuje reklamné ani analytické súbory cookie a neobsahuje analýzu návštevnosti ani sledovacie skripty."]},{"title":"6. Uchovávanie a vymazanie","paragraphs":["Údaje v zariadení vymažete odinštalovaním aplikácie. V systéme Android môžete použiť aj systémovú možnosť Vymazať údaje.","Záznamy o nákupoch v obchode spravuje Apple alebo Google. Obnoviteľné oprávnenia sa opätovne potvrdzujú podľa pravidiel obchodu.","E-maily podpory sa uchovávajú tak dlho, ako je potrebné na vybavenie žiadosti a splnenie nevyhnutných požiadaviek na vedenie záznamov. Môžete nám poslať e-mail so žiadosťou o vymazanie korešpondencie s podporou, ktorú stále uchovávame."]},{"title":"7. Bezpečnosť údajov","paragraphs":["Aplikácia používa spracovanie v zariadení, minimálne povolenia a oficiálne postupy nákupu v obchode s aplikáciami, aby obmedzila zbytočné prenosy údajov. E-maily podpory sa používajú iba na vybavenie prichádzajúcich žiadostí s primeranými ochrannými opatreniami zodpovedajúcimi povahe informácií.","Pri žiadnom zariadení, sieti ani spôsobe elektronického ukladania nemožno zaručiť úplnú bezpečnosť. Do e-mailu podpore nezahŕňajte nesúvisiace citlivé informácie."]},{"title":"8. Deti a dospievajúci","paragraphs":["Aplikácia nevyžaduje účet a nevytvára profily detí ani iných používateľov prostredníctvom reklamy alebo analýzy správania. Rodič alebo zákonný zástupca, ktorý sa domnieva, že dieťa poskytlo osobné údaje prostredníctvom e-mailu podpore, nás môže kontaktovať, aby sme záležitosť vyriešili."]},{"title":"9. Vaše možnosti a práva","paragraphs":["Údaje v zariadení spravujete prostredníctvom svojho zariadenia. Apple alebo Google spravuje účty v obchode a záznamy o nákupoch. Aplikácia nemôže vo vašom mene meniť ani odstraňovať záznamy transakcií uchovávané obchodom s aplikáciami.","Ak sa zmenia postupy aplikácie pri práci s údajmi, pravidlá platformy alebo spôsob hosťovania webovej lokality, aktualizujeme tieto zásady a dátum uvedený na stránke a poskytneme ďalšie oznámenie, ak to vyžadujú platné pravidlá.","V prípade otázok týkajúcich sa ochrany osobných údajov nám pošlite e-mail {email}"]}]},"terms":{"title":"Podmienky používania","lead":"{appName} Podmienky používania.","sections":[{"title":"1. Súhlas s týmito Podmienkami a pravidlami platformy","paragraphs":["Stiahnutím, zakúpením alebo používaním aplikácie {appName} súhlasíte s týmito Podmienkami a s pravidlami, ktoré sa na vás vzťahujú v obchode s aplikáciami, kde ju nakupujete. Ak s tým nesúhlasíte, aplikáciu ďalej nepoužívajte ani ju nenakupujte.","Tieto podmienky sa vzťahujú na vaše stiahnutie, nákup a používanie aplikácie. Verzie pre iOS a iPadOS sa tiež riadia"],"links":["appleEula"]},{"title":"2. Platené produkty a ceny","paragraphs":["Rozpoznávanie a úpravy nemajú limit použitia. Platný prístup Premium je potrebný iba na export spracovaného obrázka. Aplikácia ponúka automaticky obnovované týždenné a mesačné predplatné a jednorazový doživotný nákup bez bezplatnej skúšobnej verzie. Nákupy v App Store a Google Play sú oddelené a nemožno ich prenášať medzi platformami.","Skutočná cena, mena, dane, fakturačné obdobie a spôsobilosť na nákup sú informácie zobrazené a potvrdené na systémovej obrazovke nákupu v App Store alebo Google Play. Nákupná platforma účtuje a spravuje platbu prostredníctvom vášho účtu v obchode. Aplikácia neponúka bezplatné skúšobné obdobie predplatného ani iné platené plány."]},{"title":"3. Automatické obnovenie a zrušenie","paragraphs":["Týždenné a mesačné predplatné sa automaticky obnovuje a účtuje za fakturačné obdobie uvedené na systémovej obrazovke nákupu, kým ho nezrušíte prostredníctvom nákupnej platformy. Odstránením aplikácie {appName} sa predplatné automaticky nezruší. Ak nákupná platforma neposkytne vrátenie peňazí alebo iný postup, po vypnutí automatického obnovovania môžete predplatné naďalej používať až do konca aktuálneho zaplateného obdobia."],"links":["appleCancel","googleManage"]},{"title":"4. Nákupy, obnovenie a vrátenie peňazí","paragraphs":["Nákupy a obnovenie nákupov sa vykonávajú prostredníctvom oficiálneho obchodu Apple alebo Google. Oprávnenie sa udelí až po potvrdení platnej transakcie obchodom. Zrušené, neúspešné alebo čakajúce transakcie neposkytujú oprávnenie pred úspešným potvrdením. Obnovenie nákupov môže obnoviť doživotný prístup a aktuálne aktívne predplatné. Nákupy v App Store a Google Play sú oddelené a nemožno ich obnoviť ani preniesť medzi platformami.","Vrátenie peňazí vybavuje obchod s aplikáciami, ktorý dokončil transakciu, podľa svojich pravidiel, regiónu nákupu a platných právnych predpisov. Príslušné oprávnenie sa odstráni po tom, čo obchod potvrdí vrátenie peňazí, odvolanie, uplynutie predplatného alebo neplatnú transakciu."],"links":["appleRefund","googleRefund"]},{"title":"5. Používanie offline a dostupnosť","paragraphs":["Výber obrázkov, OCR, zisťovanie citlivého obsahu, úpravy a export prebiehajú v zariadení. Aplikácia neposkytuje cloudové rozpoznávanie obrázkov, synchronizáciu s cloudom ani účty. Pri exporte sa vytvorí nový obrázok a odstránia sa odstrániteľné súkromné metadáta. Dočasné pracovné súbory sa vymažú po úspešnom uložení, zrušení úprav alebo ukončení relácie; pri zlyhaní uloženia sa môže zachovať stav potrebný na opakovanie."]},{"title":"6. Prijateľné používanie a duševné vlastníctvo","paragraphs":["Aplikáciu nesmiete používať na nezákonnú činnosť, obchádzať overenie nákupu, poškodzovať aplikáciu, šíriť škodlivý kód, kopírovať alebo distribuovať aplikáciu bez povolenia ani porušovať práva na obsah aplikácie alebo duševné vlastníctvo inej osoby.","Aplikáciu môžete kedykoľvek prestať používať a odinštalovať. Môžeme vydávať aktualizácie na opravu problémov, podporu operačných systémov, zlepšenie stability alebo splnenie požiadaviek platformy. Problémy so zariadením, systémom, sieťou alebo službou obchodu môžu dočasne zneprístupniť niektoré funkcie.","V rozsahu povolenom platnými právnymi predpismi sa aplikácia poskytuje podľa dostupnosti. Tieto podmienky nevylučujú zodpovednosť, ktorú nemožno zákonne vylúčiť, ani neobmedzujú záväzné spotrebiteľské práva, ktoré máte.","Ak sa zmenia funkcie produktu, spôsoby platby, pravidlá platformy alebo platné právne predpisy, môžeme aktualizovať tieto podmienky a dátum uvedený na stránke. Ak zmena podstatne ovplyvní práva používateľov, poskytneme ďalšie oznámenie podľa požiadaviek.","V prípade otázok týkajúcich sa týchto Podmienok, nákupov alebo používania aplikácie pošlite e-mail na adresu {email}"]}]},"support":{"title":"Podpora","lead":"Začnite častými otázkami nižšie. Ak problém pretrváva, kontaktujte nás prostredníctvom e-mailovej adresy podpory.","emailTitle":"E-mail podpory pre {appName}","emailLead":"Začnite častými otázkami nižšie. Ak problém pretrváva, kontaktujte nás prostredníctvom e-mailovej adresy podpory.","beforeEmail":{"title":"Čo uviesť v e-maile","paragraphs":["Pri probléme s nákupom môžete uviesť číslo objednávky z obchodu s aplikáciami, neposielajte však heslo účtu, platobné heslo ani úplné údaje karty."],"bullets":["vašu platformu, model zariadenia, verziu operačného systému a verziu aplikácie;","čo ste robili pred problémom, čo ste očakávali a čo sa skutočne stalo; a","v prípade potreby snímku obrazovky alebo záznam obrazovky so skrytými súkromnými informáciami."]},"faqs":[{"question":"Nahrávajú sa obrázky na server?","answer":"Výber obrázkov, OCR, zisťovanie citlivého obsahu, úpravy a export prebiehajú v zariadení. Aplikácia neposkytuje cloudové rozpoznávanie obrázkov, synchronizáciu s cloudom ani účty. Pri exporte sa vytvorí nový obrázok a odstránia sa odstrániteľné súkromné metadáta. Dočasné pracovné súbory sa vymažú po úspešnom uložení, zrušení úprav alebo ukončení relácie; pri zlyhaní uloženia sa môže zachovať stav potrebný na opakovanie."},{"question":"Povolenia, reklama a sledovanie","answer":"Prístup k fotografiám sa používa len na zobrazenie a spracovanie obrázkov, ktoré povolíte. Fotoaparát sa použije iba vtedy, keď sa rozhodnete odfotiť obrázok v aplikácii. Povolenie ukladať do fotoknižnice sa vyžiada iba pri potvrdení exportu s platným prístupom Premium. Aplikácia nežiada polohu, kontakty, mikrofón, Bluetooth ani oznámenia."},{"question":"Platené produkty a ceny","answer":"Rozpoznávanie a úpravy nemajú limit použitia. Platný prístup Premium je potrebný iba na export spracovaného obrázka. Aplikácia ponúka automaticky obnovované týždenné a mesačné predplatné a jednorazový doživotný nákup bez bezplatnej skúšobnej verzie. Nákupy v App Store a Google Play sú oddelené a nemožno ich prenášať medzi platformami."},{"question":"Ukladanie a formáty obrázkov","answer":"Ak sa uloženie nepodarí, skontrolujte voľné miesto, povolenie ukladať do fotoknižnice a čitateľnosť pôvodného obrázka a skúste to znova. Aplikácia spracúva vždy jeden statický obrázok a podporuje väčšinu bežných formátov; niektoré závisia od zariadenia a verzie systému. Video, PDF, RAW/DNG a dávkové spracovanie momentálne nie sú podporované."},{"question":"Ako zmením jazyk?","answer":"Aplikácia podporuje 40 jazykov a jazyk možno zmeniť v nastaveniach aplikácie. Ak je zobrazenie nesprávne, pošlite e-mail s jazykom zariadenia a jazykom vybratým v aplikácii."},{"question":"Obnovenie, zrušenie a vrátenie peňazí","answer":"Nákupy a obnovenie nákupov sa vykonávajú prostredníctvom oficiálneho obchodu Apple alebo Google. Oprávnenie sa udelí až po potvrdení platnej transakcie obchodom. Zrušené, neúspešné alebo čakajúce transakcie neposkytujú oprávnenie pred úspešným potvrdením. Obnovenie nákupov môže obnoviť doživotný prístup a aktuálne aktívne predplatné. Nákupy v App Store a Google Play sú oddelené a nemožno ich obnoviť ani preniesť medzi platformami."},{"question":"Ochrana súkromia a vymazanie údajov","answer":"Údaje v zariadení vymažete odinštalovaním aplikácie. V systéme Android môžete použiť aj systémovú možnosť Vymazať údaje. Záznamy o nákupoch v obchode spravuje Apple alebo Google. Obnoviteľné oprávnenia sa opätovne potvrdzujú podľa pravidiel obchodu. E-maily podpory sa uchovávajú tak dlho, ako je potrebné na vybavenie žiadosti a splnenie nevyhnutných požiadaviek na vedenie záznamov. Môžete nám poslať e-mail so žiadosťou o vymazanie korešpondencie s podporou, ktorú stále uchovávame."}],"officialHelpTitle":"Rýchla pomoc"}},"sl":{"linkLabels":{"appleEula":"Applova standardna licenčna pogodba za končnega uporabnika (EULA)","appleCancel":"Navodila za preklic naročnine na Apple","googleManage":"Navodila za preklic v storitvi Google Play","appleRefund":"Zahtevajte vračilo denarja od Appla","googleRefund":"Informacije o vračilih kupnine v storitvi Google Play"},"nav":{"privacy":"Pravilnik o zasebnosti","terms":"Pogoji uporabe","support":"Podpora","language":"Jezik","chooseLanguage":"Izberite jezik prikaza","navigationLabel":"Primarna navigacija"},"home":{"eyebrow":"{appName} · Privacy first","title":"Vaše slike se ne nalagajo na naše strežnike.","lead":"Izbira slik, OCR, zaznavanje občutljive vsebine, urejanje in izvoz potekajo v napravi. Aplikacija ne ponuja prepoznavanja slik ali sinhronizacije v oblaku in nima računov. Pri izvozu se ustvari nova slika in odstranijo se zasebni metapodatki, ki jih je mogoče izbrisati. Začasne delovne datoteke se izbrišejo po uspešnem shranjevanju, opustitvi urejanja ali koncu seje; če shranjevanje ne uspe, se lahko ohrani stanje za ponovni poskus.","points":["Podatki aplikacije","Plačljivi izdelki in cene","Podpora"],"cards":[{"title":"Pravilnik o zasebnosti","description":"Vaše slike se ne nalagajo na naše strežnike.","action":"Pravilnik o zasebnosti"},{"title":"Pogoji uporabe","description":"Prepoznavanje in urejanje nimata omejitev uporabe. Veljaven dostop Premium je potreben samo za izvoz obdelane slike. Aplikacija ponuja samodejno obnovljive tedenske in mesečne naročnine ter enkratni doživljenjski nakup brez brezplačnega preskusa. Nakupi v App Store in Google Play so ločeni in jih ni mogoče prenesti med platformama.","action":"Pogoji uporabe"},{"title":"Potrebujete pomoč?","description":"Najprej preglejte spodnja pogosta vprašanja. Če težava ni odpravljena, se obrnite na nas prek e-poštnega naslova za podporo.","action":"Podpora"}]},"footer":{"privacy":"Pravilnik o zasebnosti","terms":"Pogoji uporabe","support":"Podpora"},"privacy":{"title":"Pravilnik o zasebnosti","lead":"Ta pravilnik pojasnjuje, kako {appName} obravnava podatke v napravi, podatke o nakupih iz trgovine z aplikacijami in e-pošto za podporo.","sections":[{"title":"1. Obseg in stik","paragraphs":["Ta pravilnik velja za aplikacijo {appName} za iOS, iPadOS in Android ter za to spletno mesto o zasebnosti, pogojih in podpori.","Za vprašanja o zasebnosti pišite na {email}"]},{"title":"2. Podatki aplikacije","callout":{"title":"Vaše slike se ne nalagajo na naše strežnike.","body":"Izbira slik, OCR, zaznavanje občutljive vsebine, urejanje in izvoz potekajo v napravi. Aplikacija ne ponuja prepoznavanja slik ali sinhronizacije v oblaku in nima računov. Pri izvozu se ustvari nova slika in odstranijo se zasebni metapodatki, ki jih je mogoče izbrisati. Začasne delovne datoteke se izbrišejo po uspešnem shranjevanju, opustitvi urejanja ali koncu seje; če shranjevanje ne uspe, se lahko ohrani stanje za ponovni poskus."},"paragraphs":[]},{"title":"3. Dovoljenja, oglaševanje in sledenje","paragraphs":["Dostop do fotografij se uporablja samo za prikaz in obdelavo slik, ki jih dovolite. Kamera se uporabi le, ko v aplikaciji izberete fotografiranje. Dovoljenje za shranjevanje v knjižnico fotografij se zahteva samo, ko potrdite izvoz z veljavnim dostopom Premium. Aplikacija ne zahteva lokacije, stikov, mikrofona, Bluetootha ali obvestil.","Ne uporablja oglaševalskega identifikatorja in ne vključuje kompletov SDK tretjih oseb za oglaševanje, analitiko, atribucijo ali poročanje o zrušitvah.","Aplikacija ne vključuje orodja tretje osebe za poročanje o zrušitvah. Glede na nastavitve naprave in trgovine lahko Apple ali Google obdeluje sistemske diagnostične podatke v skladu s svojimi pravili o zasebnosti ter zagotovi tehnične podatke za preiskovanje zrušitev ali težav z delovanjem."]},{"title":"4. Storitve trgovine z aplikacijami in dostop do omrežja","paragraphs":["Aplikacija uporablja Apple StoreKit ali Google Play Billing za nalaganje izdelkov, prikaz lokaliziranih cen, ki jih vrne trgovina, dokončanje nakupov, obnovitev nakupov, upravljanje naročnin in potrjevanje pravic. Dostop do omrežja se uporablja samo za te uradne funkcije trgovine Apple ali Google.","Apple ali Google je odgovoren za račune trgovine, plačila, obračunavanje, transakcije, vračila kupnine in naročniške storitve. Aplikacija obdeluje samo podatke trgovine, ki so potrebni za potrditev izdelkov in pravic, ter ne prejema ali shranjuje popolnih plačilnih podatkov."]},{"title":"5. E-pošta za podporo in spletno mesto","paragraphs":["Aplikacija ne bere samodejno vaših e-poštnih podatkov. Samo ko se odločite poslati e-pošto za podporo, kanal za podporo prejme vaš e-poštni naslov, sporočilo ter vsak posnetek zaslona, videoposnetek zaslona, številko naročila ali drugo prilogo, ki jo prostovoljno posredujete. Ti podatki se uporabljajo samo za obravnavo vaše zahteve in ne za oglaševanje ali trženje. Ne pošiljajte gesel računa, gesel za plačilo ali celotnih številk kartic.","To spletno mesto ne namešča oglaševalskih ali analitičnih piškotkov in ne vsebuje analitike obiska ali skriptov za sledenje."]},{"title":"6. Hramba in izbris","paragraphs":["Podatke v napravi izbrišete tako, da odstranite aplikacijo. V sistemu Android lahko uporabite tudi sistemsko možnost Izbriši podatke.","Evidence nakupov v trgovini upravlja Apple ali Google. Pravice, ki jih je mogoče obnoviti, se znova potrdijo v skladu s pravili trgovine.","E-pošta za podporo se hrani toliko časa, kot je potrebno za obravnavo zahteve in izpolnjevanje nujnih zahtev glede vodenja evidenc. Po e-pošti lahko zahtevate izbris korespondence s podporo, ki jo še vedno hranimo."]},{"title":"7. Varnost podatkov","paragraphs":["Aplikacija uporablja obdelavo v napravi, najmanjša potrebna dovoljenja in uradne postopke nakupa v trgovini z aplikacijami, da zmanjša nepotrebne prenose podatkov. E-pošta za podporo se uporablja samo za obravnavo prejetih zahtev, pri čemer se uporabljajo razumni zaščitni ukrepi, primerni naravi podatkov.","Za nobeno napravo, omrežje ali način elektronskega shranjevanja ni mogoče zagotoviti popolne varnosti. V e-pošto za podporo ne vključujte nepovezanih občutljivih podatkov."]},{"title":"8. Otroci in najstniki","paragraphs":["Aplikacija ne zahteva računa in z oglaševanjem ali vedenjsko analitiko ne ustvarja profilov otrok ali drugih uporabnikov. Starš ali skrbnik, ki meni, da je otrok posredoval osebne podatke po e-pošti za podporo, se lahko obrne na nas, da zadevo obravnavamo."]},{"title":"9. Vaše izbire in pravice","paragraphs":["Podatke v napravi upravljate prek svoje naprave. Apple ali Google upravlja račune trgovine in evidence nakupov. Aplikacija v vašem imenu ne more spreminjati ali izbrisati evidenc transakcij, ki jih hrani trgovina z aplikacijami.","Če se spremenijo prakse aplikacije glede podatkov, pravila platforme ali način gostovanja spletnega mesta, bomo posodobili ta pravilnik in datum na strani ter zagotovili dodatno obvestilo, kadar to zahtevajo veljavna pravila.","Za vprašanja o zasebnosti pišite na {email}"]}]},"terms":{"title":"Pogoji uporabe","lead":"{appName} Pogoji uporabe.","sections":[{"title":"1. Sprejemanje teh pogojev in pravil platforme","paragraphs":["S prenosom, nakupom ali uporabo aplikacije {appName} se strinjate s temi pogoji in pravili, ki veljajo za vas v trgovini z aplikacijami, kjer opravite nakup. Če se ne strinjate, ne nadaljujte z uporabo aplikacije ali ne opravite nakupa.","Ti pogoji veljajo za vaš prenos, nakup in uporabo aplikacije. Za različici iOS in iPadOS velja tudi"],"links":["appleEula"]},{"title":"2. Plačljivi izdelki in cene","paragraphs":["Prepoznavanje in urejanje nimata omejitev uporabe. Veljaven dostop Premium je potreben samo za izvoz obdelane slike. Aplikacija ponuja samodejno obnovljive tedenske in mesečne naročnine ter enkratni doživljenjski nakup brez brezplačnega preskusa. Nakupi v App Store in Google Play so ločeni in jih ni mogoče prenesti med platformama.","Dejanska cena, valuta, davki, obračunsko obdobje in upravičenost do nakupa so podatki, prikazani in potrjeni na sistemskem zaslonu za nakup v trgovini App Store ali Google Play. Nakupna platforma zaračuna in upravlja plačilo prek vašega računa trgovine. Aplikacija ne ponuja brezplačnega preskusnega obdobja naročnine ali drugih plačljivih paketov."]},{"title":"3. Samodejno podaljšanje in preklic","paragraphs":["Tedenske in mesečne naročnine se samodejno podaljšujejo in zaračunavajo za obračunsko obdobje, prikazano na sistemskem zaslonu za nakup, dokler jih ne prekličete prek nakupne platforme. Če izbrišete {appName}, se naročnina ne prekliče samodejno. Če nakupna platforma ne zagotovi vračila kupnine ali drugačne obravnave, lahko po izklopu samodejnega podaljšanja naročnino uporabljate do konca trenutnega plačanega obdobja."],"links":["appleCancel","googleManage"]},{"title":"4. Nakupi, obnovitev in vračila kupnine","paragraphs":["Nakupi in obnovitev nakupov se izvedejo prek uradne trgovine Apple ali Google. Pravica je podeljena šele, ko trgovina potrdi veljavno transakcijo. Preklicane, neuspešne ali čakajoče transakcije ne podelijo pravice pred uspešno potrditvijo. Z obnovitvijo nakupov je mogoče obnoviti doživljenjski dostop in trenutno aktivno naročnino. Nakupi v trgovinah App Store in Google Play so ločeni ter jih ni mogoče obnoviti ali prenesti med platformama.","Vračila kupnine obravnava trgovina z aplikacijami, ki je izvedla transakcijo, v skladu s svojimi pravili, regijo nakupa in veljavno zakonodajo. Ustrezna pravica se odstrani, ko trgovina potrdi vračilo kupnine, preklic, potek naročnine ali neveljavno transakcijo."],"links":["appleRefund","googleRefund"]},{"title":"5. Uporaba brez povezave in razpoložljivost","paragraphs":["Izbira slik, OCR, zaznavanje občutljive vsebine, urejanje in izvoz potekajo v napravi. Aplikacija ne ponuja prepoznavanja slik ali sinhronizacije v oblaku in nima računov. Pri izvozu se ustvari nova slika in odstranijo se zasebni metapodatki, ki jih je mogoče izbrisati. Začasne delovne datoteke se izbrišejo po uspešnem shranjevanju, opustitvi urejanja ali koncu seje; če shranjevanje ne uspe, se lahko ohrani stanje za ponovni poskus."]},{"title":"6. Sprejemljiva uporaba in intelektualna lastnina","paragraphs":["Aplikacije ne smete uporabljati za nezakonite dejavnosti; zaobiti preverjanja nakupa; poškodovati aplikacije; širiti zlonamerne kode; kopirati ali distribuirati aplikacije brez dovoljenja; ali kršiti pravic do vsebine aplikacije ali intelektualne lastnine druge osebe.","Aplikacijo lahko kadar koli prenehate uporabljati in jo odstranite. Objavimo lahko posodobitve za odpravo težav, podporo operacijskim sistemom, izboljšanje stabilnosti ali izpolnjevanje zahtev platforme. Zaradi težav z napravo, sistemom, omrežjem ali storitvijo trgovine so lahko nekatere funkcije začasno nedostopne.","V obsegu, ki ga dovoljuje veljavna zakonodaja, je aplikacija na voljo glede na razpoložljivost. Ti pogoji ne izključujejo odgovornosti, ki je ni mogoče zakonito izključiti, in ne omejujejo obveznih pravic potrošnikov, ki vam pripadajo.","Če se spremenijo funkcije izdelka, načini plačila, pravila platforme ali veljavna zakonodaja, lahko posodobimo te pogoje in datum na strani. Če sprememba bistveno vpliva na pravice uporabnikov, bomo zagotovili dodatno obvestilo, kot je zahtevano.","Za vprašanja o teh pogojih, nakupih ali uporabi aplikacije pišite na {email}"]}]},"support":{"title":"Podpora","lead":"Najprej preglejte spodnja pogosta vprašanja. Če težava ni odpravljena, se obrnite na nas prek e-poštnega naslova za podporo.","emailTitle":"{appName} e-poštni naslov za podporo","emailLead":"Najprej preglejte spodnja pogosta vprašanja. Če težava ni odpravljena, se obrnite na nas prek e-poštnega naslova za podporo.","beforeEmail":{"title":"Kaj vključiti v e-pošto","paragraphs":["Pri težavi z nakupom lahko navedete številko naročila iz trgovine z aplikacijami, vendar ne pošiljajte gesla računa, gesla za plačilo ali popolnih podatkov kartice."],"bullets":["svojo platformo, model naprave, različico operacijskega sistema in različico aplikacije;","kaj ste storili pred težavo, kaj ste pričakovali in kaj se je dejansko zgodilo; in","po potrebi posnetek zaslona ali zaslonski posnetek s skritimi zasebnimi podatki."]},"faqs":[{"question":"Ali se slike naložijo na strežnik?","answer":"Izbira slik, OCR, zaznavanje občutljive vsebine, urejanje in izvoz potekajo v napravi. Aplikacija ne ponuja prepoznavanja slik ali sinhronizacije v oblaku in nima računov. Pri izvozu se ustvari nova slika in odstranijo se zasebni metapodatki, ki jih je mogoče izbrisati. Začasne delovne datoteke se izbrišejo po uspešnem shranjevanju, opustitvi urejanja ali koncu seje; če shranjevanje ne uspe, se lahko ohrani stanje za ponovni poskus."},{"question":"Dovoljenja, oglaševanje in sledenje","answer":"Dostop do fotografij se uporablja samo za prikaz in obdelavo slik, ki jih dovolite. Kamera se uporabi le, ko v aplikaciji izberete fotografiranje. Dovoljenje za shranjevanje v knjižnico fotografij se zahteva samo, ko potrdite izvoz z veljavnim dostopom Premium. Aplikacija ne zahteva lokacije, stikov, mikrofona, Bluetootha ali obvestil."},{"question":"Plačljivi izdelki in cene","answer":"Prepoznavanje in urejanje nimata omejitev uporabe. Veljaven dostop Premium je potreben samo za izvoz obdelane slike. Aplikacija ponuja samodejno obnovljive tedenske in mesečne naročnine ter enkratni doživljenjski nakup brez brezplačnega preskusa. Nakupi v App Store in Google Play so ločeni in jih ni mogoče prenesti med platformama."},{"question":"Shranjevanje in oblike slik","answer":"Če shranjevanje ne uspe, preverite prosti prostor, dovoljenje za shranjevanje v knjižnico fotografij in berljivost izvirne slike ter poskusite znova. Aplikacija obdeluje po eno statično sliko in podpira večino običajnih oblik; nekatere so odvisne od naprave in različice sistema. Video, PDF, RAW/DNG in paketna obdelava trenutno niso podprti."},{"question":"Kako spremenim jezik?","answer":"Aplikacija podpira 40 jezikov, jezik pa je mogoče spremeniti v nastavitvah aplikacije. Če prikaz ni pravilen, pošljite e-pošto z jezikom naprave in jezikom, izbranim v aplikaciji."},{"question":"Obnovitev, preklic in vračila kupnine","answer":"Nakupi in obnovitev nakupov se izvedejo prek uradne trgovine Apple ali Google. Pravica je podeljena šele, ko trgovina potrdi veljavno transakcijo. Preklicane, neuspešne ali čakajoče transakcije ne podelijo pravice pred uspešno potrditvijo. Z obnovitvijo nakupov je mogoče obnoviti doživljenjski dostop in trenutno aktivno naročnino. Nakupi v trgovinah App Store in Google Play so ločeni ter jih ni mogoče obnoviti ali prenesti med platformama."},{"question":"Zasebnost in izbris podatkov","answer":"Podatke v napravi izbrišete tako, da odstranite aplikacijo. V sistemu Android lahko uporabite tudi sistemsko možnost Izbriši podatke. Evidence nakupov v trgovini upravlja Apple ali Google. Pravice, ki jih je mogoče obnoviti, se znova potrdijo v skladu s pravili trgovine. E-pošta za podporo se hrani toliko časa, kot je potrebno za obravnavo zahteve in izpolnjevanje nujnih zahtev glede vodenja evidenc. Po e-pošti lahko zahtevate izbris korespondence s podporo, ki jo še vedno hranimo."}],"officialHelpTitle":"Hitra pomoč"}},"sv":{"linkLabels":{"appleEula":"Apples standardlicensavtal för slutanvändare (EULA)","appleCancel":"Instruktioner för att avsluta Apple-prenumerationen","googleManage":"Anvisningar för uppsägning i Google Play","appleRefund":"Begär återbetalning från Apple","googleRefund":"Information om återbetalning i Google Play"},"nav":{"privacy":"Integritetspolicy","terms":"Användarvillkor","support":"Support","language":"Språk","chooseLanguage":"Välj visningsspråk","navigationLabel":"Primär navigering"},"home":{"eyebrow":"{appName} · Privacy first","title":"Dina bilder laddas inte upp till våra servrar.","lead":"Bildval, OCR, identifiering av känsligt innehåll, redigering och export sker på enheten. Appen erbjuder inte bildigenkänning eller synkronisering i molnet och har inga konton. Vid export skapas en ny bild och borttagbara privata metadata rensas. Tillfälliga arbetsfiler tas bort efter lyckad lagring, när redigeringen överges eller sessionen avslutas; om lagringen misslyckas kan nödvändigt tillstånd sparas för ett nytt försök.","points":["Appdata","Betalda produkter och priser","Support"],"cards":[{"title":"Integritetspolicy","description":"Dina bilder laddas inte upp till våra servrar.","action":"Integritetspolicy"},{"title":"Användarvillkor","description":"Igenkänning och redigering har inga användningsgränser. Endast export av den behandlade bilden kräver giltig Premium-åtkomst. Appen erbjuder automatiskt förnyade vecko- och månadsabonnemang samt ett engångsköp för livstidsåtkomst, utan kostnadsfri provperiod. Köp i App Store och Google Play är separata och kan inte överföras mellan plattformarna.","action":"Användarvillkor"},{"title":"Behöver du hjälp?","description":"Börja med de vanliga frågorna nedan. Om problemet kvarstår kontaktar du oss via supportens e-postadress.","action":"Support"}]},"footer":{"privacy":"Integritetspolicy","terms":"Användarvillkor","support":"Support"},"privacy":{"title":"Integritetspolicy","lead":"Denna integritetspolicy förklarar hur {appName} hanterar data på enheten, köpinformation från appbutiken och supportmejl.","sections":[{"title":"1. Omfattning och kontakt","paragraphs":["Denna policy gäller appen {appName} för iOS, iPadOS och Android samt denna webbplats för integritet, villkor och support.","För frågor om integritet, skicka e-post {email}"]},{"title":"2. Appdata","callout":{"title":"Dina bilder laddas inte upp till våra servrar.","body":"Bildval, OCR, identifiering av känsligt innehåll, redigering och export sker på enheten. Appen erbjuder inte bildigenkänning eller synkronisering i molnet och har inga konton. Vid export skapas en ny bild och borttagbara privata metadata rensas. Tillfälliga arbetsfiler tas bort efter lyckad lagring, när redigeringen överges eller sessionen avslutas; om lagringen misslyckas kan nödvändigt tillstånd sparas för ett nytt försök."},"paragraphs":[]},{"title":"3. Behörigheter, annonsering och spårning","paragraphs":["Fotoåtkomst används endast för att visa och behandla bilder som du godkänner. Kameran används endast när du väljer att ta ett foto i appen. Behörighet att spara i fotobiblioteket begärs endast när du bekräftar export med giltig Premium-åtkomst. Appen begär inte plats, kontakter, mikrofon, Bluetooth eller notiser.","Den använder inte något annons-id och integrerar inte SDK:er från tredje part för annonsering, analys, attribuering eller kraschrapportering.","Appen integrerar inte något kraschrapporteringsverktyg från tredje part. Beroende på inställningarna på din enhet och i butiken kan Apple eller Google behandla systemdiagnostik enligt sina respektive integritetsregler och tillhandahålla teknisk information som används för att undersöka krascher eller prestandaproblem."]},{"title":"4. Appbutikstjänster och nätverksåtkomst","paragraphs":["Appen använder Apple StoreKit eller Google Play Billing för att läsa in produkter, visa lokaliserade priser från butiken, slutföra köp, återställa köp, hantera abonnemang och bekräfta åtkomster. Nätverksåtkomst används endast för dessa officiella butikstjänster från Apple eller Google.","Apple eller Google ansvarar för butikskonton, betalningar, fakturering, transaktioner, återbetalningar och abonnemangstjänster. Appen behandlar endast den butiksinformation som behövs för att bekräfta produkter och åtkomster och tar inte emot eller lagrar fullständiga betalningsuppgifter."]},{"title":"5. Supportmejl och webbplats","paragraphs":["Appen läser inte automatiskt dina e-postuppgifter. Endast när du själv väljer att skicka ett supportmejl tar supportkanalen emot din e-postadress, ditt meddelande och eventuella skärmbilder, skärminspelningar, ordernummer eller andra bilagor som du frivilligt skickar. Informationen används endast för att hantera din förfrågan och inte för annonsering eller marknadsföring. Skicka inte lösenord till konton eller betalningar eller fullständiga kortnummer.","Denna webbplats använder inte cookies för annonsering eller analys och innehåller inte trafikanalys eller spårningsskript."]},{"title":"6. Lagring och radering","paragraphs":["Radera data på enheten genom att avinstallera appen. På Android kan du även använda systemets funktion Rensa data.","Köpuppgifter hanteras av Apple eller Google. Återställningsbara åtkomster bekräftas på nytt enligt butikens regler.","Supportmejl sparas så länge det behövs för att hantera förfrågan och uppfylla nödvändiga dokumentationskrav. Du kan mejla oss för att begära radering av supportkorrespondens som vi fortfarande har kvar."]},{"title":"7. Datasäkerhet","paragraphs":["Appen använder behandling på enheten, minsta möjliga behörigheter och appbutikens officiella köpflöden för att minska onödiga dataöverföringar. Supportmejl används endast för att hantera inkommande förfrågningar och skyddas med rimliga åtgärder anpassade till informationens art.","Ingen enhet, inget nätverk och ingen elektronisk lagringsmetod kan garanteras vara helt säker. Ta inte med ovidkommande känslig information i ett supportmejl."]},{"title":"8. Barn och ungdomar","paragraphs":["Appen kräver inget konto och skapar inte profiler av barn eller andra användare genom annonsering eller beteendeanalys. En förälder eller vårdnadshavare som anser att ett barn har lämnat personuppgifter i ett supportmejl kan kontakta oss för att få ärendet hanterat."]},{"title":"9. Dina val och rättigheter","paragraphs":["Du hanterar data på enheten via din enhet. Apple eller Google hanterar butikskonton och köpuppgifter. Appen kan inte ändra eller radera transaktionsuppgifter som en appbutik lagrar åt dig.","Om appens datapraxis, plattformsregler eller webbplatsens hosting ändras uppdaterar vi denna policy och datumet på sidan samt lämnar ytterligare information när tillämpliga regler kräver det.","För frågor om integritet, skicka e-post {email}"]}]},"terms":{"title":"Användarvillkor","lead":"{appName} Användarvillkor.","sections":[{"title":"1. Godkännande av dessa villkor och plattformsregler","paragraphs":["Genom att ladda ner, köpa eller använda {appName} godkänner du dessa villkor och de regler som gäller för dig i appbutiken där du gör ett köp. Om du inte godkänner villkoren ska du inte fortsätta använda appen eller göra ett köp.","Dessa villkor gäller när du hämtar, köper och använder appen. iOS- och iPadOS-versionerna omfattas även av"],"links":["appleEula"]},{"title":"2. Betalda produkter och priser","paragraphs":["Igenkänning och redigering har inga användningsgränser. Endast export av den behandlade bilden kräver giltig Premium-åtkomst. Appen erbjuder automatiskt förnyade vecko- och månadsabonnemang samt ett engångsköp för livstidsåtkomst, utan kostnadsfri provperiod. Köp i App Store och Google Play är separata och kan inte överföras mellan plattformarna.","Det faktiska priset, valutan, skatterna, faktureringsperioden och möjligheten att köpa är den information som visas och bekräftas på systemets köpskärm i App Store eller Google Play. Köpplattformen debiterar och hanterar betalningen via ditt butikskonto. Appen erbjuder ingen kostnadsfri provperiod för abonnemang eller andra betalplaner."]},{"title":"3. Automatisk förnyelse och uppsägning","paragraphs":["Vecko- och månadsabonnemang förnyas automatiskt och debiteras för den faktureringsperiod som visas på systemets köpskärm tills du säger upp via köpplattformen. Ett abonnemang sägs inte upp automatiskt när {appName} raderas. Om köpplattformen inte ger en återbetalning eller annan hantering kan du fortsätta använda abonnemanget till slutet av den aktuella betalade perioden efter att automatisk förnyelse har stängts av."],"links":["appleCancel","googleManage"]},{"title":"4. Köp, återställning och återbetalning","paragraphs":["Köp och återställning av köp genomförs via den officiella Apple- eller Google-butiken. Åtkomst beviljas först efter att butiken har bekräftat en giltig transaktion. Avbrutna, misslyckade eller väntande transaktioner ger inte åtkomst före en lyckad bekräftelse. Återställning av köp kan återställa livstidsåtkomst och ett för närvarande aktivt abonnemang. Köp i App Store och Google Play är separata och kan inte återställas eller överföras mellan plattformar.","Återbetalningar hanteras av den appbutik som genomförde transaktionen enligt butikens regler, köpregionen och tillämplig lag. Den tillhörande åtkomsten tas bort när butiken bekräftar en återbetalning, återkallelse, ett utgånget abonnemang eller en ogiltig transaktion."],"links":["appleRefund","googleRefund"]},{"title":"5. Offlineanvändning och tillgänglighet","paragraphs":["Bildval, OCR, identifiering av känsligt innehåll, redigering och export sker på enheten. Appen erbjuder inte bildigenkänning eller synkronisering i molnet och har inga konton. Vid export skapas en ny bild och borttagbara privata metadata rensas. Tillfälliga arbetsfiler tas bort efter lyckad lagring, när redigeringen överges eller sessionen avslutas; om lagringen misslyckas kan nödvändigt tillstånd sparas för ett nytt försök."]},{"title":"6. Tillåten användning och immateriella rättigheter","paragraphs":["Du får inte använda appen för olaglig verksamhet, kringgå köpverifiering, skada appen, sprida skadlig kod, kopiera eller distribuera appen utan tillstånd eller göra intrång i rättigheter till appinnehåll eller någon annans immateriella rättigheter.","Du kan när som helst sluta använda och avinstallera appen. Vi kan ge ut uppdateringar för att åtgärda problem, stödja operativsystem, förbättra stabiliteten eller uppfylla plattformskraven. Problem med enheten, systemet, nätverket eller butikstjänsten kan göra vissa funktioner tillfälligt otillgängliga.","I den utsträckning tillämplig lag medger tillhandahålls appen i befintligt tillgängligt skick. Dessa villkor utesluter inte ansvar som enligt lag inte får uteslutas och begränsar inte tvingande konsumenträttigheter som du har.","Om produktfunktioner, betalningsmetoder, plattformsregler eller tillämplig lag ändras kan vi uppdatera dessa villkor och datumet på sidan. Om en ändring väsentligt påverkar användarnas rättigheter lämnar vi ytterligare information enligt gällande krav.","För frågor om dessa villkor, köp eller användning av appen, skicka e-post till {email}"]}]},"support":{"title":"Support","lead":"Börja med de vanliga frågorna nedan. Om problemet kvarstår kontaktar du oss via supportens e-postadress.","emailTitle":"{appName} supportmejladress","emailLead":"Börja med de vanliga frågorna nedan. Om problemet kvarstår kontaktar du oss via supportens e-postadress.","beforeEmail":{"title":"Det här bör du ta med i mejlet","paragraphs":["Vid ett köpproblem kan du ange ordernumret från appbutiken, men skicka inte lösenordet till ditt konto eller betalning eller fullständiga kortuppgifter."],"bullets":["din plattform, enhetsmodell, operativsystemversion och appversion;","vad du gjorde före problemet, vad du förväntade dig och vad som faktiskt hände; samt","om det behövs, en skärmdump eller skärminspelning med dold privat information."]},"faqs":[{"question":"Laddas bilder upp till en server?","answer":"Bildval, OCR, identifiering av känsligt innehåll, redigering och export sker på enheten. Appen erbjuder inte bildigenkänning eller synkronisering i molnet och har inga konton. Vid export skapas en ny bild och borttagbara privata metadata rensas. Tillfälliga arbetsfiler tas bort efter lyckad lagring, när redigeringen överges eller sessionen avslutas; om lagringen misslyckas kan nödvändigt tillstånd sparas för ett nytt försök."},{"question":"Behörigheter, annonsering och spårning","answer":"Fotoåtkomst används endast för att visa och behandla bilder som du godkänner. Kameran används endast när du väljer att ta ett foto i appen. Behörighet att spara i fotobiblioteket begärs endast när du bekräftar export med giltig Premium-åtkomst. Appen begär inte plats, kontakter, mikrofon, Bluetooth eller notiser."},{"question":"Betalda produkter och priser","answer":"Igenkänning och redigering har inga användningsgränser. Endast export av den behandlade bilden kräver giltig Premium-åtkomst. Appen erbjuder automatiskt förnyade vecko- och månadsabonnemang samt ett engångsköp för livstidsåtkomst, utan kostnadsfri provperiod. Köp i App Store och Google Play är separata och kan inte överföras mellan plattformarna."},{"question":"Sparande och bildformat","answer":"Om lagringen misslyckas kontrollerar du ledigt utrymme, behörigheten att spara i fotobiblioteket och att originalbilden fortfarande kan läsas och försöker igen. Appen behandlar en stillbild åt gången och stöder de flesta vanliga format; vissa beror på enhet och systemversion. Video, PDF, RAW/DNG och batchbearbetning stöds inte för närvarande."},{"question":"Hur byter jag språk?","answer":"Appen stöder 40 språk och språket kan ändras i appens inställningar. Om visningen är felaktig mejlar du enhetens språk och det språk som valts i appen."},{"question":"Återställning, uppsägning och återbetalning","answer":"Köp och återställning av köp genomförs via den officiella Apple- eller Google-butiken. Åtkomst beviljas först efter att butiken har bekräftat en giltig transaktion. Avbrutna, misslyckade eller väntande transaktioner ger inte åtkomst före en lyckad bekräftelse. Återställning av köp kan återställa livstidsåtkomst och ett för närvarande aktivt abonnemang. Köp i App Store och Google Play är separata och kan inte återställas eller överföras mellan plattformar."},{"question":"Integritet och radering av data","answer":"Radera data på enheten genom att avinstallera appen. På Android kan du även använda systemets funktion Rensa data. Köpuppgifter hanteras av Apple eller Google. Återställningsbara åtkomster bekräftas på nytt enligt butikens regler. Supportmejl sparas så länge det behövs för att hantera förfrågan och uppfylla nödvändiga dokumentationskrav. Du kan mejla oss för att begära radering av supportkorrespondens som vi fortfarande har kvar."}],"officialHelpTitle":"Snabb hjälp"}},"ta":{"linkLabels":{"appleEula":"Apple-ன் நிலையான இறுதிப் பயனர் உரிம ஒப்பந்தம் (EULA)","appleCancel":"ஆப்பிள் சந்தாவை ரத்து செய்வதற்கான வழிமுறைகள்","googleManage":"Google Play ரத்துசெய்தல் வழிமுறைகள்","appleRefund":"ஆப்பிளிடமிருந்து பணத்தைத் திரும்பக் கோருங்கள்","googleRefund":"Google Play பணத்தைத் திரும்பப் பெறுதல் தகவல்"},"nav":{"privacy":"தனியுரிமைக் கொள்கை","terms":"பயன்பாட்டு விதிமுறைகள்","support":"ஆதரவு","language":"மொழி","chooseLanguage":"காட்சி மொழியைத் தேர்ந்தெடுக்கவும்","navigationLabel":"முதன்மை வழிசெலுத்தல்"},"home":{"eyebrow":"{appName} · Privacy first","title":"உங்கள் படங்கள் எங்கள் சேவையகங்களுக்கு பதிவேற்றப்படாது.","lead":"படத் தேர்வு, OCR, உணர்வுப்பூர்வ உள்ளடக்கக் கண்டறிதல், திருத்தம் மற்றும் ஏற்றுமதி அனைத்தும் சாதனத்திலேயே நடைபெறும். செயலி மேகப் பட அங்கீகாரம், மேக ஒத்திசைவு அல்லது கணக்குகளை வழங்காது. ஏற்றுமதியில் புதிய படம் உருவாக்கப்பட்டு, நீக்கக்கூடிய தனியுரிமை மெட்டாடேட்டா அகற்றப்படும். வெற்றிகரமான சேமிப்பு, திருத்தத்தை கைவிடுதல் அல்லது அமர்வு முடிந்ததும் தற்காலிகக் கோப்புகள் நீக்கப்படும்; சேமிப்பு தோல்வியுற்றால் மீண்டும் முயற்சிக்கத் தேவையான நிலை வைக்கப்படலாம்.","points":["ஆப் தரவு","கட்டணத் தயாரிப்புகள் மற்றும் விலைகள்","ஆதரவு"],"cards":[{"title":"தனியுரிமைக் கொள்கை","description":"உங்கள் படங்கள் எங்கள் சேவையகங்களுக்கு பதிவேற்றப்படாது.","action":"தனியுரிமைக் கொள்கை"},{"title":"பயன்பாட்டு விதிமுறைகள்","description":"அங்கீகாரம் மற்றும் திருத்தத்திற்கு பயன்பாட்டு வரம்பு இல்லை. செயலாக்கப்பட்ட படத்தை ஏற்றுமதி செய்ய மட்டுமே செல்லுபடியாகும் Premium தேவை. இலவச சோதனை இல்லாமல் தானாகப் புதுப்பிக்கப்படும் வார மற்றும் மாத சந்தாக்களும், ஒருமுறை வாங்கும் வாழ்நாள் அணுகலும் வழங்கப்படும். App Store மற்றும் Google Play கொள்முதல்கள் தனித்தனியானவை; தளங்களுக்கு இடையில் மாற்ற முடியாது.","action":"பயன்பாட்டு விதிமுறைகள்"},{"title":"உதவி தேவையா?","description":"முதலில் கீழே உள்ள பொதுவான கேள்விகளைப் பாருங்கள். சிக்கல் தொடர்ந்தால், ஆதரவு மின்னஞ்சல் முகவரி மூலம் எங்களைத் தொடர்புகொள்ளுங்கள்.","action":"ஆதரவு"}]},"footer":{"privacy":"தனியுரிமைக் கொள்கை","terms":"பயன்பாட்டு விதிமுறைகள்","support":"ஆதரவு"},"privacy":{"title":"தனியுரிமைக் கொள்கை","lead":"{appName} சாதனத்தில் உள்ள தரவு, ஆப் ஸ்டோர் வாங்குதல் தகவல் மற்றும் ஆதரவு மின்னஞ்சல்களை எவ்வாறு கையாள்கிறது என்பதை இந்தக் கொள்கை விளக்குகிறது.","sections":[{"title":"1. நோக்கம் மற்றும் தொடர்பு","paragraphs":["இந்தக் கொள்கை iOS, iPadOS மற்றும் Android-க்கான {appName} ஆப்ஸுக்கும் இந்தத் தனியுரிமை, விதிமுறைகள் மற்றும் ஆதரவு இணையதளத்திற்கும் பொருந்தும்.","தனியுரிமை தொடர்பான கேள்விகளுக்கு, மின்னஞ்சல் அனுப்பவும். {email}"]},{"title":"2. ஆப் தரவு","callout":{"title":"உங்கள் படங்கள் எங்கள் சேவையகங்களுக்கு பதிவேற்றப்படாது.","body":"படத் தேர்வு, OCR, உணர்வுப்பூர்வ உள்ளடக்கக் கண்டறிதல், திருத்தம் மற்றும் ஏற்றுமதி அனைத்தும் சாதனத்திலேயே நடைபெறும். செயலி மேகப் பட அங்கீகாரம், மேக ஒத்திசைவு அல்லது கணக்குகளை வழங்காது. ஏற்றுமதியில் புதிய படம் உருவாக்கப்பட்டு, நீக்கக்கூடிய தனியுரிமை மெட்டாடேட்டா அகற்றப்படும். வெற்றிகரமான சேமிப்பு, திருத்தத்தை கைவிடுதல் அல்லது அமர்வு முடிந்ததும் தற்காலிகக் கோப்புகள் நீக்கப்படும்; சேமிப்பு தோல்வியுற்றால் மீண்டும் முயற்சிக்கத் தேவையான நிலை வைக்கப்படலாம்."},"paragraphs":[]},{"title":"3. அனுமதிகள், விளம்பரம் மற்றும் கண்காணிப்பு","paragraphs":["நீங்கள் அனுமதித்த படங்களை காட்டவும் செயலாக்கவும் மட்டுமே புகைப்பட அணுகல் பயன்படுத்தப்படும். செயலியில் படம் எடுக்கத் தேர்ந்தெடுத்தால் மட்டுமே கேமரா பயன்படுத்தப்படும். செல்லுபடியாகும் Premium உடன் ஏற்றுமதியை உறுதிப்படுத்தும்போது மட்டுமே புகைப்பட நூலகத்தில் சேமிக்கும் அனுமதி கேட்கப்படும். இருப்பிடம், தொடர்புகள், மைக்ரோஃபோன், Bluetooth அல்லது அறிவிப்புகளுக்கான அனுமதியை செயலி கேட்காது.","விளம்பர அடையாளங்காட்டியைப் பயன்படுத்தாது; விளம்பரம், பகுப்பாய்வு, பண்புக்கூறு அல்லது செயலிழப்பு அறிக்கையிடலுக்கான மூன்றாம் தரப்பு SDK-களை இணைக்காது.","மூன்றாம் தரப்பு செயலிழப்பு அறிக்கையிடல் கருவியை ஆப் இணைக்காது. உங்கள் சாதனம் மற்றும் ஸ்டோர் அமைப்புகளைப் பொறுத்து Apple அல்லது Google தங்களுடைய தனியுரிமை விதிகளின்படி சிஸ்டம் கண்டறிதல் தகவலைச் செயலாக்கி, செயலிழப்புகள் அல்லது செயல்திறன் சிக்கல்களை விசாரிக்கப் பயன்படும் தொழில்நுட்பத் தகவலை வழங்கக்கூடும்."]},{"title":"4. ஆப் ஸ்டோர் சேவைகள் மற்றும் நெட்வொர்க் அணுகல்","paragraphs":["தயாரிப்புகளை ஏற்ற, ஸ்டோர் வழங்கும் உள்ளூர்மயமாக்கப்பட்ட விலைகளைக் காட்ட, வாங்குதல்களை முடிக்க, வாங்குதல்களை மீட்டெடுக்க, சந்தாக்களை நிர்வகிக்க மற்றும் உரிமைகளை உறுதிப்படுத்த ஆப் Apple StoreKit அல்லது Google Play Billing-ஐப் பயன்படுத்துகிறது. நெட்வொர்க் அணுகல் இந்த அதிகாரப்பூர்வ Apple அல்லது Google ஸ்டோர் அம்சங்களுக்கு மட்டுமே பயன்படுத்தப்படுகிறது.","ஸ்டோர் கணக்குகள், கட்டணங்கள், பில்லிங், பரிவர்த்தனைகள், பணத்தைத் திரும்பப் பெறுதல் மற்றும் சந்தா சேவைகளுக்கு Apple அல்லது Google பொறுப்பாகும். தயாரிப்புகள் மற்றும் உரிமைகளை உறுதிப்படுத்தத் தேவையான ஸ்டோர் தகவலை மட்டுமே ஆப் செயலாக்குகிறது; முழுமையான கட்டணச் சான்றுகளைப் பெறவோ சேமிக்கவோ செய்யாது."]},{"title":"5. ஆதரவு மின்னஞ்சல்கள் மற்றும் இணையதளம்","paragraphs":["உங்கள் மின்னஞ்சல் தகவலை ஆப் தானாகப் படிக்காது. நீங்கள் ஆதரவு மின்னஞ்சலை அனுப்பத் தேர்வு செய்தால் மட்டுமே, ஆதரவு வழி உங்கள் மின்னஞ்சல் முகவரி, செய்தி மற்றும் நீங்கள் விருப்பத்துடன் வழங்கும் ஸ்கிரீன்ஷாட், திரைப் பதிவு, ஆர்டர் எண் அல்லது பிற இணைப்பைப் பெறும். இந்தத் தகவல் உங்கள் கோரிக்கையைக் கையாள மட்டுமே பயன்படுத்தப்படும்; விளம்பரம் அல்லது சந்தைப்படுத்தலுக்குப் பயன்படுத்தப்படாது. கணக்கு அல்லது கட்டணக் கடவுச்சொற்கள் அல்லது முழு அட்டை எண்களை அனுப்ப வேண்டாம்.","இந்த இணையதளம் விளம்பர அல்லது பகுப்பாய்வு குக்கீகளை அமைக்காது; போக்குவரத்துப் பகுப்பாய்வு அல்லது கண்காணிப்பு ஸ்கிரிப்ட்களை உள்ளடக்காது."]},{"title":"6. தக்கவைத்தல் மற்றும் நீக்குதல்","paragraphs":["ஆப்பை நிறுவல் நீக்குவதன் மூலம் சாதனத்தில் உள்ள தரவை நீக்கலாம். Android-ல் சிஸ்டத்தின் தரவை அழி விருப்பத்தையும் பயன்படுத்தலாம்.","ஸ்டோர் வாங்குதல் பதிவுகளை Apple அல்லது Google நிர்வகிக்கிறது. மீட்டெடுக்கக்கூடிய உரிமைகள் ஸ்டோர் விதிகளின்படி மீண்டும் உறுதிப்படுத்தப்படுகின்றன.","கோரிக்கையைக் கையாளவும் தேவையான பதிவுப் பராமரிப்புத் தேவைகளை நிறைவேற்றவும் தேவையான காலம் வரை ஆதரவு மின்னஞ்சல்கள் தக்கவைக்கப்படும். நாங்கள் இன்னும் வைத்திருக்கும் ஆதரவு கடிதப் பரிமாற்றத்தை நீக்குமாறு மின்னஞ்சல் மூலம் கோரலாம்."]},{"title":"7. தரவுப் பாதுகாப்பு","paragraphs":["தேவையற்ற தரவுப் பரிமாற்றங்களைக் குறைக்க ஆப் சாதனத்திலேயே செயலாக்கம், குறைந்தபட்ச அனுமதிகள் மற்றும் ஆப் ஸ்டோரின் அதிகாரப்பூர்வ வாங்குதல் முறைகளைப் பயன்படுத்துகிறது. உள்வரும் கோரிக்கைகளைக் கையாள மட்டுமே ஆதரவு மின்னஞ்சல்கள் பயன்படுத்தப்படுகின்றன; தகவலின் தன்மைக்கு ஏற்ற நியாயமான பாதுகாப்பு நடவடிக்கைகள் மேற்கொள்ளப்படுகின்றன.","எந்தச் சாதனம், நெட்வொர்க் அல்லது மின்னணு சேமிப்பு முறையும் முற்றிலும் பாதுகாப்பானது என உத்தரவாதம் அளிக்க முடியாது. ஆதரவு மின்னஞ்சலில் தொடர்பில்லாத முக்கியத் தகவலைச் சேர்க்க வேண்டாம்."]},{"title":"8. குழந்தைகள் மற்றும் பதின்ம வயதினர்","paragraphs":["ஆப்பிற்குக் கணக்கு தேவையில்லை; விளம்பரம் அல்லது நடத்தைப் பகுப்பாய்வு மூலம் குழந்தைகள் அல்லது பிற பயனர்களின் சுயவிவரங்களை உருவாக்காது. ஒரு குழந்தை ஆதரவு மின்னஞ்சல் மூலம் தனிப்பட்ட தகவலை வழங்கியதாக நம்பும் பெற்றோர் அல்லது பாதுகாவலர் அந்த விஷயம் கையாளப்பட எங்களைத் தொடர்புகொள்ளலாம்."]},{"title":"9. உங்கள் தேர்வுகள் மற்றும் உரிமைகள்","paragraphs":["உங்கள் சாதனத்தின் மூலம் சாதனத்தில் உள்ள தரவை நிர்வகிக்கிறீர்கள். Apple அல்லது Google ஸ்டோர் கணக்குகள் மற்றும் வாங்குதல் பதிவுகளை நிர்வகிக்கிறது. ஆப் ஸ்டோர் வைத்திருக்கும் பரிவர்த்தனைப் பதிவுகளை உங்கள் சார்பாக ஆப் மாற்றவோ நீக்கவோ முடியாது.","ஆப்பின் தரவு நடைமுறைகள், தள விதிகள் அல்லது இணையதள ஹோஸ்டிங் ஏற்பாடுகள் மாறினால், இந்தக் கொள்கையையும் இந்தப் பக்கத்தில் காட்டப்படும் தேதியையும் புதுப்பித்து, பொருந்தும் விதிகள் கோரும்போது கூடுதல் அறிவிப்பை வழங்குவோம்.","தனியுரிமை தொடர்பான கேள்விகளுக்கு, மின்னஞ்சல் அனுப்பவும். {email}"]}]},"terms":{"title":"பயன்பாட்டு விதிமுறைகள்","lead":"பயன்பாட்டு விதிமுறைகள்.","sections":[{"title":"1. இந்த விதிமுறைகளையும் தள விதிகளையும் ஏற்றுக்கொள்வது","paragraphs":["{appName}-ஐப் பதிவிறக்குவதன், வாங்குவதன் அல்லது பயன்படுத்துவதன் மூலம், நீங்கள் இந்த விதிமுறைகளையும், நீங்கள் வாங்கும் ஆப் ஸ்டோரில் உங்களுக்குப் பொருந்தும் விதிகளையும் ஒப்புக்கொள்கிறீர்கள். நீங்கள் ஒப்புக்கொள்ளவில்லை என்றால், செயலியைத் தொடர்ந்து பயன்படுத்தவோ அல்லது வாங்கவோ வேண்டாம்.","நீங்கள் ஆப்பைப் பதிவிறக்குவது, வாங்குவது மற்றும் பயன்படுத்துவது ஆகியவற்றுக்கு இந்த விதிமுறைகள் பொருந்தும். iOS மற்றும் iPadOS பதிப்புகளும் இதற்குக் கட்டுப்படும்:"],"links":["appleEula"]},{"title":"2. கட்டணத் தயாரிப்புகள் மற்றும் விலைகள்","paragraphs":["அங்கீகாரம் மற்றும் திருத்தத்திற்கு பயன்பாட்டு வரம்பு இல்லை. செயலாக்கப்பட்ட படத்தை ஏற்றுமதி செய்ய மட்டுமே செல்லுபடியாகும் Premium தேவை. இலவச சோதனை இல்லாமல் தானாகப் புதுப்பிக்கப்படும் வார மற்றும் மாத சந்தாக்களும், ஒருமுறை வாங்கும் வாழ்நாள் அணுகலும் வழங்கப்படும். App Store மற்றும் Google Play கொள்முதல்கள் தனித்தனியானவை; தளங்களுக்கு இடையில் மாற்ற முடியாது.","உண்மையான விலை, நாணயம், வரிகள், பில்லிங் காலம் மற்றும் வாங்கும் தகுதி ஆகியவை App Store அல்லது Google Play சிஸ்டம் வாங்குதல் திரையில் காட்டப்பட்டு உறுதிப்படுத்தப்படும் தகவலாகும். வாங்குதல் தளம் உங்கள் ஸ்டோர் கணக்கின் மூலம் கட்டணம் வசூலித்து நிர்வகிக்கிறது. ஆப் சந்தாவுக்கான இலவசச் சோதனை அல்லது பிற கட்டணத் திட்டங்களை வழங்காது."]},{"title":"3. தானாகப் புதுப்பித்தல் மற்றும் ரத்துசெய்தல்","paragraphs":["வாராந்திர மற்றும் மாதாந்திர சந்தாக்கள் தானாகப் புதுப்பிக்கப்பட்டு, வாங்குதல் தளத்தின் மூலம் நீங்கள் ரத்துசெய்யும் வரை சிஸ்டம் வாங்குதல் திரையில் காட்டப்படும் பில்லிங் காலத்திற்கு கட்டணம் வசூலிக்கப்படும். {appName}-ஐ நீக்குவது சந்தாவைத் தானாக ரத்துசெய்யாது. வாங்குதல் தளம் பணத்தைத் திருப்பித் தரவோ வேறு தீர்வை வழங்கவோ செய்யாத வரை, தானாகப் புதுப்பித்தலை அணைத்த பிறகும் தற்போதைய கட்டணக் காலம் முடியும் வரை சந்தாவைப் பயன்படுத்தலாம்."],"links":["appleCancel","googleManage"]},{"title":"4. வாங்குதல்கள், மீட்டெடுப்பு மற்றும் பணத்தைத் திரும்பப் பெறுதல்","paragraphs":["வாங்குதல்களும் வாங்குதல் மீட்டெடுப்பும் அதிகாரப்பூர்வ Apple அல்லது Google ஸ்டோர் மூலம் நிறைவேற்றப்படும். ஸ்டோர் செல்லுபடியாகும் பரிவர்த்தனையை உறுதிப்படுத்திய பிறகே உரிமை வழங்கப்படும். ரத்துசெய்யப்பட்ட, தோல்வியடைந்த அல்லது நிலுவையில் உள்ள பரிவர்த்தனைகள் வெற்றிகரமான உறுதிப்படுத்தலுக்கு முன் உரிமை வழங்காது. வாங்குதல் மீட்டெடுப்பு வாழ்நாள் அணுகலையும் தற்போது செயலில் உள்ள சந்தாவையும் மீட்டெடுக்கலாம். App Store மற்றும் Google Play வாங்குதல்கள் தனித்தனியானவை; தளங்களுக்கு இடையே மீட்டெடுக்கவோ மாற்றவோ முடியாது.","பணத்தைத் திரும்பப் பெறுதலைப் பரிவர்த்தனையை நிறைவேற்றிய ஆப் ஸ்டோர் அதன் விதிகள், வாங்கிய பகுதி மற்றும் பொருந்தும் சட்டத்தின்படி கையாளும். ஸ்டோர் பணத்தைத் திரும்பப் பெறுதல், ரத்து, சந்தா காலாவதி அல்லது செல்லாத பரிவர்த்தனையை உறுதிப்படுத்திய பிறகு தொடர்புடைய உரிமை அகற்றப்படும்."],"links":["appleRefund","googleRefund"]},{"title":"5. ஆஃப்லைன் பயன்பாடு மற்றும் கிடைக்கும் தன்மை","paragraphs":["படத் தேர்வு, OCR, உணர்வுப்பூர்வ உள்ளடக்கக் கண்டறிதல், திருத்தம் மற்றும் ஏற்றுமதி அனைத்தும் சாதனத்திலேயே நடைபெறும். செயலி மேகப் பட அங்கீகாரம், மேக ஒத்திசைவு அல்லது கணக்குகளை வழங்காது. ஏற்றுமதியில் புதிய படம் உருவாக்கப்பட்டு, நீக்கக்கூடிய தனியுரிமை மெட்டாடேட்டா அகற்றப்படும். வெற்றிகரமான சேமிப்பு, திருத்தத்தை கைவிடுதல் அல்லது அமர்வு முடிந்ததும் தற்காலிகக் கோப்புகள் நீக்கப்படும்; சேமிப்பு தோல்வியுற்றால் மீண்டும் முயற்சிக்கத் தேவையான நிலை வைக்கப்படலாம்."]},{"title":"6. ஏற்றுக்கொள்ளக்கூடிய பயன்பாடு மற்றும் அறிவுசார் சொத்து","paragraphs":["சட்டவிரோத செயல்பாட்டிற்கு ஆப்பைப் பயன்படுத்துதல்; வாங்குதல் சரிபார்ப்பைத் தவிர்த்தல்; ஆப்பை சேதப்படுத்துதல்; தீங்கிழைக்கும் குறியீட்டை விநியோகித்தல்; அனுமதியின்றி ஆப்பை நகலெடுத்தல் அல்லது விநியோகித்தல்; அல்லது ஆப் உள்ளடக்க உரிமைகள் அல்லது மற்றொருவரின் அறிவுசார் சொத்தை மீறுதல் ஆகியவற்றைச் செய்யக்கூடாது.","எப்போது வேண்டுமானாலும் ஆப்பைப் பயன்படுத்துவதை நிறுத்தி நிறுவல் நீக்கலாம். சிக்கல்களைச் சரிசெய்ய, இயக்க முறைமைகளை ஆதரிக்க, நிலைத்தன்மையை மேம்படுத்த அல்லது தளத் தேவைகளை நிறைவேற்ற நாங்கள் புதுப்பிப்புகளை வெளியிடலாம். சாதனம், சிஸ்டம், நெட்வொர்க் அல்லது ஸ்டோர் சேவைச் சிக்கல்கள் சில அம்சங்களைத் தற்காலிகமாக கிடைக்காதவையாக மாற்றலாம்.","பொருந்தும் சட்டம் அனுமதிக்கும் அளவிற்கு, ஆப் கிடைக்கும் நிலையில் வழங்கப்படுகிறது. சட்டப்படி விலக்க முடியாத பொறுப்பை இந்த விதிமுறைகள் விலக்காது அல்லது உங்களுக்கு உள்ள கட்டாய நுகர்வோர் உரிமைகளை வரையறுக்காது.","தயாரிப்பு அம்சங்கள், கட்டண முறைகள், தள விதிகள் அல்லது பொருந்தும் சட்டம் மாறினால், இந்த விதிமுறைகளையும் பக்கத்தில் காட்டப்படும் தேதியையும் புதுப்பிக்கலாம். மாற்றம் பயனர்களின் உரிமைகளை குறிப்பிடத்தக்க வகையில் பாதித்தால், தேவைக்கேற்ப கூடுதல் அறிவிப்பை வழங்குவோம்.","இந்த விதிமுறைகள், கொள்முதல் அல்லது செயலியின் பயன்பாடு தொடர்பான கேள்விகளுக்கு, மின்னஞ்சல் அனுப்பவும். {email}"]}]},"support":{"title":"ஆதரவு","lead":"முதலில் கீழே உள்ள பொதுவான கேள்விகளைப் பாருங்கள். சிக்கல் தொடர்ந்தால், ஆதரவு மின்னஞ்சல் முகவரி மூலம் எங்களைத் தொடர்புகொள்ளுங்கள்.","emailTitle":"{appName} ஆதரவு மின்னஞ்சல்","emailLead":"முதலில் கீழே உள்ள பொதுவான கேள்விகளைப் பாருங்கள். சிக்கல் தொடர்ந்தால், ஆதரவு மின்னஞ்சல் முகவரி மூலம் எங்களைத் தொடர்புகொள்ளுங்கள்.","beforeEmail":{"title":"உங்கள் மின்னஞ்சலில் சேர்க்க வேண்டியவை","paragraphs":["வாங்குதல் சிக்கலுக்கு ஆப் ஸ்டோர் ஆர்டர் எண்ணைச் சேர்க்கலாம்; ஆனால் கணக்கு அல்லது கட்டணக் கடவுச்சொல் அல்லது முழுமையான அட்டைத் தகவலை அனுப்ப வேண்டாம்."],"bullets":["உங்கள் தளம், சாதன மாடல், இயக்க முறைமைப் பதிப்பு மற்றும் ஆப் பதிப்பு;","சிக்கலுக்கு முன் நீங்கள் செய்தது, நீங்கள் எதிர்பார்த்தது மற்றும் உண்மையில் நடந்தது; மற்றும்","தேவைப்பட்டால், தனிப்பட்ட தகவல்கள் மறைக்கப்பட்ட ஸ்கிரீன்ஷாட் அல்லது திரைப்பதிவு."]},"faqs":[{"question":"படங்கள் சேவையகத்திற்குப் பதிவேற்றப்படுமா?","answer":"படத் தேர்வு, OCR, உணர்வுப்பூர்வ உள்ளடக்கக் கண்டறிதல், திருத்தம் மற்றும் ஏற்றுமதி அனைத்தும் சாதனத்திலேயே நடைபெறும். செயலி மேகப் பட அங்கீகாரம், மேக ஒத்திசைவு அல்லது கணக்குகளை வழங்காது. ஏற்றுமதியில் புதிய படம் உருவாக்கப்பட்டு, நீக்கக்கூடிய தனியுரிமை மெட்டாடேட்டா அகற்றப்படும். வெற்றிகரமான சேமிப்பு, திருத்தத்தை கைவிடுதல் அல்லது அமர்வு முடிந்ததும் தற்காலிகக் கோப்புகள் நீக்கப்படும்; சேமிப்பு தோல்வியுற்றால் மீண்டும் முயற்சிக்கத் தேவையான நிலை வைக்கப்படலாம்."},{"question":"அனுமதிகள், விளம்பரம் மற்றும் கண்காணிப்பு","answer":"நீங்கள் அனுமதித்த படங்களை காட்டவும் செயலாக்கவும் மட்டுமே புகைப்பட அணுகல் பயன்படுத்தப்படும். செயலியில் படம் எடுக்கத் தேர்ந்தெடுத்தால் மட்டுமே கேமரா பயன்படுத்தப்படும். செல்லுபடியாகும் Premium உடன் ஏற்றுமதியை உறுதிப்படுத்தும்போது மட்டுமே புகைப்பட நூலகத்தில் சேமிக்கும் அனுமதி கேட்கப்படும். இருப்பிடம், தொடர்புகள், மைக்ரோஃபோன், Bluetooth அல்லது அறிவிப்புகளுக்கான அனுமதியை செயலி கேட்காது."},{"question":"கட்டணத் தயாரிப்புகள் மற்றும் விலைகள்","answer":"அங்கீகாரம் மற்றும் திருத்தத்திற்கு பயன்பாட்டு வரம்பு இல்லை. செயலாக்கப்பட்ட படத்தை ஏற்றுமதி செய்ய மட்டுமே செல்லுபடியாகும் Premium தேவை. இலவச சோதனை இல்லாமல் தானாகப் புதுப்பிக்கப்படும் வார மற்றும் மாத சந்தாக்களும், ஒருமுறை வாங்கும் வாழ்நாள் அணுகலும் வழங்கப்படும். App Store மற்றும் Google Play கொள்முதல்கள் தனித்தனியானவை; தளங்களுக்கு இடையில் மாற்ற முடியாது."},{"question":"சேமிப்பும் பட வடிவங்களும்","answer":"சேமிப்பு தோல்வியுற்றால் காலி இடம், புகைப்பட நூலகத்தில் சேமிக்கும் அனுமதி மற்றும் மூலப் படம் இன்னும் படிக்கப்படுகிறதா என்பதைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும். செயலி ஒரே நேரத்தில் ஒரு நிலையான படத்தைச் செயலாக்கி, பெரும்பாலான பொதுவான வடிவங்களை ஆதரிக்கிறது; சில வடிவங்கள் சாதனம் மற்றும் முறைமை பதிப்பைப் பொறுத்தவை. வீடியோ, PDF, RAW/DNG மற்றும் தொகுதி செயலாக்கம் தற்போது ஆதரிக்கப்படவில்லை."},{"question":"மொழியை எப்படி மாற்றுவது?","answer":"ஆப் 40 மொழிகளை ஆதரிக்கிறது; ஆப் அமைப்புகளில் மொழியை மாற்றலாம். காட்சி தவறாக இருந்தால், சாதன மொழியையும் ஆப்பில் தேர்ந்தெடுக்கப்பட்ட மொழியையும் மின்னஞ்சல் செய்யுங்கள்."},{"question":"மீட்டெடுப்பு, ரத்துசெய்தல் மற்றும் பணத்தைத் திரும்பப் பெறுதல்","answer":"வாங்குதல்களும் வாங்குதல் மீட்டெடுப்பும் அதிகாரப்பூர்வ Apple அல்லது Google ஸ்டோர் மூலம் நிறைவேற்றப்படும். ஸ்டோர் செல்லுபடியாகும் பரிவர்த்தனையை உறுதிப்படுத்திய பிறகே உரிமை வழங்கப்படும். ரத்துசெய்யப்பட்ட, தோல்வியடைந்த அல்லது நிலுவையில் உள்ள பரிவர்த்தனைகள் வெற்றிகரமான உறுதிப்படுத்தலுக்கு முன் உரிமை வழங்காது. வாங்குதல் மீட்டெடுப்பு வாழ்நாள் அணுகலையும் தற்போது செயலில் உள்ள சந்தாவையும் மீட்டெடுக்கலாம். App Store மற்றும் Google Play வாங்குதல்கள் தனித்தனியானவை; தளங்களுக்கு இடையே மீட்டெடுக்கவோ மாற்றவோ முடியாது."},{"question":"தனியுரிமை மற்றும் தரவு நீக்குதல்","answer":"ஆப்பை நிறுவல் நீக்குவதன் மூலம் சாதனத்தில் உள்ள தரவை நீக்கலாம். Android-ல் சிஸ்டத்தின் தரவை அழி விருப்பத்தையும் பயன்படுத்தலாம். ஸ்டோர் வாங்குதல் பதிவுகளை Apple அல்லது Google நிர்வகிக்கிறது. மீட்டெடுக்கக்கூடிய உரிமைகள் ஸ்டோர் விதிகளின்படி மீண்டும் உறுதிப்படுத்தப்படுகின்றன. கோரிக்கையைக் கையாளவும் தேவையான பதிவுப் பராமரிப்புத் தேவைகளை நிறைவேற்றவும் தேவையான காலம் வரை ஆதரவு மின்னஞ்சல்கள் தக்கவைக்கப்படும். நாங்கள் இன்னும் வைத்திருக்கும் ஆதரவு கடிதப் பரிமாற்றத்தை நீக்குமாறு மின்னஞ்சல் மூலம் கோரலாம்."}],"officialHelpTitle":"விரைவான உதவி"}},"te":{"linkLabels":{"appleEula":"Apple ప్రామాణిక తుది వినియోగదారు లైసెన్స్ ఒప్పందం (EULA)","appleCancel":"ఆపిల్ సబ్‌స్క్రిప్షన్ రద్దు సూచనలు","googleManage":"Google Play రద్దు సూచనలు","appleRefund":"ఆపిల్ నుండి వాపసు కోరండి","googleRefund":"Google Play రీఫండ్ సమాచారం"},"nav":{"privacy":"గోప్యతా విధానం","terms":"వినియోగ నిబంధనలు","support":"మద్దతు","language":"భాష","chooseLanguage":"ప్రదర్శన భాషను ఎంచుకోండి","navigationLabel":"ప్రాథమిక నావిగేషన్"},"home":{"eyebrow":"{appName} · Privacy first","title":"మీ చిత్రాలు మా సర్వర్లకు అప్‌లోడ్ చేయబడవు.","lead":"చిత్ర ఎంపిక, OCR, సున్నితమైన కంటెంట్ గుర్తింపు, ఎడిటింగ్ మరియు ఎగుమతి పరికరంలోనే జరుగుతాయి. యాప్ క్లౌడ్ చిత్ర గుర్తింపు, క్లౌడ్ సమకాలీకరణ లేదా ఖాతాలను అందించదు. ఎగుమతి సమయంలో కొత్త చిత్రం సృష్టించబడుతుంది మరియు తొలగించగల ప్రైవేట్ మెటాడేటా తొలగించబడుతుంది. విజయవంతంగా సేవ్ చేసిన తర్వాత, ఎడిటింగ్‌ను వదిలినప్పుడు లేదా సెషన్ ముగిసినప్పుడు తాత్కాలిక ఫైళ్లు తొలగించబడతాయి; సేవ్ విఫలమైతే మళ్లీ ప్రయత్నించడానికి అవసరమైన స్థితి ఉంచబడవచ్చు.","points":["యాప్ డేటా","చెల్లింపు ఉత్పత్తులు మరియు ధరలు","మద్దతు"],"cards":[{"title":"గోప్యతా విధానం","description":"మీ చిత్రాలు మా సర్వర్లకు అప్‌లోడ్ చేయబడవు.","action":"గోప్యతా విధానం"},{"title":"వినియోగ నిబంధనలు","description":"గుర్తింపు మరియు ఎడిటింగ్‌కు వినియోగ పరిమితులు లేవు. ప్రాసెస్ చేసిన చిత్రాన్ని ఎగుమతి చేయడానికి మాత్రమే చెల్లుబాటు అయ్యే Premium అవసరం. ఉచిత ట్రయల్ లేకుండా స్వయంచాలకంగా పునరుద్ధరించే వారపు మరియు నెలవారీ సభ్యత్వాలు, ఒకసారి కొనుగోలు చేసే జీవితకాల యాక్సెస్ అందుబాటులో ఉంటాయి. App Store మరియు Google Play కొనుగోళ్లు వేర్వేరు; ప్లాట్‌ఫారమ్‌ల మధ్య బదిలీ చేయలేరు.","action":"వినియోగ నిబంధనలు"},{"title":"సహాయం కావాలా?","description":"ముందుగా దిగువ సాధారణ ప్రశ్నలను చూడండి. సమస్య కొనసాగితే, సహాయ ఇమెయిల్ చిరునామా ద్వారా మమ్మల్ని సంప్రదించండి.","action":"మద్దతు"}]},"footer":{"privacy":"గోప్యతా విధానం","terms":"వినియోగ నిబంధనలు","support":"మద్దతు"},"privacy":{"title":"గోప్యతా విధానం","lead":"{appName} పరికరంలోని డేటా, యాప్ స్టోర్ కొనుగోలు సమాచారం మరియు సహాయ ఇమెయిల్‌లను ఎలా నిర్వహిస్తుందో ఈ పాలసీ వివరిస్తుంది.","sections":[{"title":"1. పరిధి మరియు సంప్రదింపు","paragraphs":["ఈ పాలసీ iOS, iPadOS మరియు Android కోసం {appName} యాప్‌కు మరియు ఈ గోప్యత, నిబంధనలు మరియు సహాయ వెబ్‌సైట్‌కు వర్తిస్తుంది.","గోప్యతా ప్రశ్నల కోసం, ఇమెయిల్ చేయండి {email}"]},{"title":"2. యాప్ డేటా","callout":{"title":"మీ చిత్రాలు మా సర్వర్లకు అప్‌లోడ్ చేయబడవు.","body":"చిత్ర ఎంపిక, OCR, సున్నితమైన కంటెంట్ గుర్తింపు, ఎడిటింగ్ మరియు ఎగుమతి పరికరంలోనే జరుగుతాయి. యాప్ క్లౌడ్ చిత్ర గుర్తింపు, క్లౌడ్ సమకాలీకరణ లేదా ఖాతాలను అందించదు. ఎగుమతి సమయంలో కొత్త చిత్రం సృష్టించబడుతుంది మరియు తొలగించగల ప్రైవేట్ మెటాడేటా తొలగించబడుతుంది. విజయవంతంగా సేవ్ చేసిన తర్వాత, ఎడిటింగ్‌ను వదిలినప్పుడు లేదా సెషన్ ముగిసినప్పుడు తాత్కాలిక ఫైళ్లు తొలగించబడతాయి; సేవ్ విఫలమైతే మళ్లీ ప్రయత్నించడానికి అవసరమైన స్థితి ఉంచబడవచ్చు."},"paragraphs":[]},{"title":"3. అనుమతులు, ప్రకటనలు మరియు ట్రాకింగ్","paragraphs":["మీరు అనుమతించిన చిత్రాలను చూపడానికి మరియు ప్రాసెస్ చేయడానికి మాత్రమే ఫోటో యాక్సెస్ ఉపయోగించబడుతుంది. యాప్‌లో ఫోటో తీయాలని ఎంచుకున్నప్పుడు మాత్రమే కెమెరా ఉపయోగించబడుతుంది. చెల్లుబాటు అయ్యే Premiumతో ఎగుమతిని నిర్ధారించినప్పుడు మాత్రమే ఫోటో లైబ్రరీలో సేవ్ చేసే అనుమతి కోరబడుతుంది. యాప్ స్థానం, పరిచయాలు, మైక్రోఫోన్, Bluetooth లేదా నోటిఫికేషన్ అనుమతులను కోరదు.","ప్రకటన గుర్తింపుదారును ఉపయోగించదు మరియు ప్రకటనలు, విశ్లేషణ, అట్రిబ్యూషన్ లేదా క్రాష్ రిపోర్టింగ్ కోసం మూడవ పక్ష SDKలను అనుసంధానించదు.","యాప్ మూడవ పక్ష క్రాష్ రిపోర్టింగ్ సాధనాన్ని అనుసంధానించదు. మీ పరికరం మరియు స్టోర్ సెట్టింగ్‌లను బట్టి Apple లేదా Google తమ గోప్యతా నియమాల ప్రకారం సిస్టమ్ డయాగ్నస్టిక్ సమాచారాన్ని ప్రాసెస్ చేసి, క్రాష్‌లు లేదా పనితీరు సమస్యలను పరిశోధించడానికి ఉపయోగించే సాంకేతిక సమాచారాన్ని అందించవచ్చు."]},{"title":"4. యాప్ స్టోర్ సేవలు మరియు నెట్‌వర్క్ యాక్సెస్","paragraphs":["ఉత్పత్తులను లోడ్ చేయడానికి, స్టోర్ అందించిన స్థానిక ధరలను చూపడానికి, కొనుగోళ్లను పూర్తి చేయడానికి, కొనుగోళ్లను పునరుద్ధరించడానికి, సబ్‌స్క్రిప్షన్‌లను నిర్వహించడానికి మరియు హక్కులను ధృవీకరించడానికి యాప్ Apple StoreKit లేదా Google Play Billingను ఉపయోగిస్తుంది. నెట్‌వర్క్ యాక్సెస్ ఈ అధికారిక Apple లేదా Google స్టోర్ ఫీచర్‌లకు మాత్రమే ఉపయోగించబడుతుంది.","స్టోర్ ఖాతాలు, చెల్లింపులు, బిల్లింగ్, లావాదేవీలు, రీఫండ్‌లు మరియు సబ్‌స్క్రిప్షన్ సేవలకు Apple లేదా Google బాధ్యత వహిస్తుంది. ఉత్పత్తులు మరియు హక్కులను ధృవీకరించడానికి అవసరమైన స్టోర్ సమాచారాన్ని మాత్రమే యాప్ ప్రాసెస్ చేస్తుంది; పూర్తి చెల్లింపు ఆధారాలను స్వీకరించదు లేదా నిల్వ చేయదు."]},{"title":"5. సహాయ ఇమెయిల్‌లు మరియు వెబ్‌సైట్","paragraphs":["యాప్ మీ ఇమెయిల్ సమాచారాన్ని ఆటోమేటిక్‌గా చదవదు. మీరు సహాయ ఇమెయిల్ పంపాలని ఎంచుకున్నప్పుడు మాత్రమే సహాయ మార్గం మీ ఇమెయిల్ చిరునామా, సందేశం మరియు మీరు స్వచ్ఛందంగా అందించే స్క్రీన్‌షాట్, స్క్రీన్ రికార్డింగ్, ఆర్డర్ నంబర్ లేదా ఇతర అటాచ్‌మెంట్‌ను స్వీకరిస్తుంది. ఈ సమాచారం మీ అభ్యర్థనను నిర్వహించడానికి మాత్రమే ఉపయోగించబడుతుంది; ప్రకటనలు లేదా మార్కెటింగ్ కోసం ఉపయోగించబడదు. ఖాతా లేదా చెల్లింపు పాస్‌వర్డ్‌లు లేదా పూర్తి కార్డ్ నంబర్‌లను పంపవద్దు.","ఈ వెబ్‌సైట్ ప్రకటన లేదా విశ్లేషణ కుకీలను సెట్ చేయదు మరియు ట్రాఫిక్ విశ్లేషణ లేదా ట్రాకింగ్ స్క్రిప్ట్‌లను కలిగి ఉండదు."]},{"title":"6. నిల్వ మరియు తొలగింపు","paragraphs":["యాప్‌ను అన్‌ఇన్‌స్టాల్ చేయడం ద్వారా పరికరంలోని డేటాను తొలగించండి. Androidలో సిస్టమ్‌లోని డేటాను క్లియర్ చేయి ఎంపికను కూడా ఉపయోగించవచ్చు.","స్టోర్ కొనుగోలు రికార్డ్‌లను Apple లేదా Google నిర్వహిస్తుంది. పునరుద్ధరించగల హక్కులు స్టోర్ నియమాల ప్రకారం మళ్లీ ధృవీకరించబడతాయి.","అభ్యర్థనను నిర్వహించడానికి మరియు అవసరమైన రికార్డ్ నిర్వహణ అవసరాలను తీర్చడానికి అవసరమైనంత కాలం సహాయ ఇమెయిల్‌లు ఉంచబడతాయి. మేము ఇప్పటికీ ఉంచుకున్న సహాయ ఉత్తరప్రత్యుత్తరాలను తొలగించమని మీరు ఇమెయిల్ ద్వారా అభ్యర్థించవచ్చు."]},{"title":"7. డేటా భద్రత","paragraphs":["అనవసరమైన డేటా బదిలీలను తగ్గించడానికి యాప్ పరికరంలోనే ప్రాసెసింగ్, కనీస అనుమతులు మరియు యాప్ స్టోర్ అధికారిక కొనుగోలు విధానాలను ఉపయోగిస్తుంది. వచ్చే అభ్యర్థనలను నిర్వహించడానికి మాత్రమే సహాయ ఇమెయిల్‌లు ఉపయోగించబడతాయి; సమాచారం స్వభావానికి తగిన సమంజసమైన రక్షణ చర్యలు అమలు చేయబడతాయి.","ఏ పరికరం, నెట్‌వర్క్ లేదా ఎలక్ట్రానిక్ నిల్వ విధానం పూర్తిగా సురక్షితమని హామీ ఇవ్వలేం. సహాయ ఇమెయిల్‌లో సంబంధం లేని సున్నితమైన సమాచారాన్ని చేర్చవద్దు."]},{"title":"8. పిల్లలు మరియు కిశోరులు","paragraphs":["యాప్‌కు ఖాతా అవసరం లేదు మరియు ప్రకటనలు లేదా ప్రవర్తన విశ్లేషణ ద్వారా పిల్లలు లేదా ఇతర వినియోగదారుల ప్రొఫైల్‌లను రూపొందించదు. పిల్లలు సహాయ ఇమెయిల్ ద్వారా వ్యక్తిగత సమాచారాన్ని అందించారని భావించే తల్లిదండ్రులు లేదా సంరక్షకులు ఆ విషయాన్ని పరిష్కరించడానికి మమ్మల్ని సంప్రదించవచ్చు."]},{"title":"9. మీ ఎంపికలు మరియు హక్కులు","paragraphs":["మీరు మీ పరికరం ద్వారా పరికరంలోని డేటాను నిర్వహిస్తారు. Apple లేదా Google స్టోర్ ఖాతాలు మరియు కొనుగోలు రికార్డ్‌లను నిర్వహిస్తుంది. యాప్ స్టోర్ ఉంచే లావాదేవీ రికార్డ్‌లను మీ తరఫున యాప్ మార్చడం లేదా తొలగించడం సాధ్యం కాదు.","యాప్ డేటా విధానాలు, ప్లాట్‌ఫారమ్ నియమాలు లేదా వెబ్‌సైట్ హోస్టింగ్ ఏర్పాట్లు మారితే, ఈ పాలసీని మరియు ఈ పేజీలో చూపిన తేదీని అప్‌డేట్ చేస్తాము; వర్తించే నియమాలు కోరినప్పుడు అదనపు నోటీసు ఇస్తాము.","గోప్యతా ప్రశ్నల కోసం, ఇమెయిల్ చేయండి {email}"]}]},"terms":{"title":"వినియోగ నిబంధనలు","lead":"{appName} వినియోగ నిబంధనలు.","sections":[{"title":"1. ఈ నిబంధనలు మరియు ప్లాట్‌ఫారమ్ నియమాలను అంగీకరించడం","paragraphs":["{appName}ను డౌన్‌లోడ్ చేయడం, కొనుగోలు చేయడం లేదా ఉపయోగించడం ద్వారా, మీరు ఈ నిబంధనలకు మరియు మీరు కొనుగోలు చేసే యాప్ స్టోర్‌లో మీకు వర్తించే నియమాలకు అంగీకరిస్తున్నారు. మీరు అంగీకరించకపోతే, యాప్‌ను ఉపయోగించడం కొనసాగించవద్దు లేదా కొనుగోలు చేయవద్దు.","మీరు యాప్‌ను డౌన్‌లోడ్ చేయడం, కొనడం మరియు ఉపయోగించడంపై ఈ నిబంధనలు వర్తిస్తాయి. iOS మరియు iPadOS వెర్షన్‌లు దీనికి కూడా లోబడి ఉంటాయి:"],"links":["appleEula"]},{"title":"2. చెల్లింపు ఉత్పత్తులు మరియు ధరలు","paragraphs":["గుర్తింపు మరియు ఎడిటింగ్‌కు వినియోగ పరిమితులు లేవు. ప్రాసెస్ చేసిన చిత్రాన్ని ఎగుమతి చేయడానికి మాత్రమే చెల్లుబాటు అయ్యే Premium అవసరం. ఉచిత ట్రయల్ లేకుండా స్వయంచాలకంగా పునరుద్ధరించే వారపు మరియు నెలవారీ సభ్యత్వాలు, ఒకసారి కొనుగోలు చేసే జీవితకాల యాక్సెస్ అందుబాటులో ఉంటాయి. App Store మరియు Google Play కొనుగోళ్లు వేర్వేరు; ప్లాట్‌ఫారమ్‌ల మధ్య బదిలీ చేయలేరు.","అసలు ధర, కరెన్సీ, పన్నులు, బిల్లింగ్ వ్యవధి మరియు కొనుగోలు అర్హత App Store లేదా Google Play సిస్టమ్ కొనుగోలు స్క్రీన్‌లో చూపబడి ధృవీకరించబడే సమాచారమే. కొనుగోలు ప్లాట్‌ఫారమ్ మీ స్టోర్ ఖాతా ద్వారా ఛార్జ్ చేసి చెల్లింపును నిర్వహిస్తుంది. యాప్ ఉచిత సబ్‌స్క్రిప్షన్ ట్రయల్ లేదా ఇతర చెల్లింపు ప్లాన్‌లను అందించదు."]},{"title":"3. ఆటోమేటిక్ పునరుద్ధరణ మరియు రద్దు","paragraphs":["వారపు మరియు నెలవారీ సబ్‌స్క్రిప్షన్‌లు ఆటోమేటిక్‌గా పునరుద్ధరించబడతాయి మరియు మీరు కొనుగోలు ప్లాట్‌ఫారమ్ ద్వారా రద్దు చేసే వరకు సిస్టమ్ కొనుగోలు స్క్రీన్‌లో చూపిన బిల్లింగ్ వ్యవధికి ఛార్జ్ చేయబడతాయి. {appName}ను తొలగించడం వల్ల సబ్‌స్క్రిప్షన్ ఆటోమేటిక్‌గా రద్దు కాదు. కొనుగోలు ప్లాట్‌ఫారమ్ రీఫండ్ లేదా ఇతర పరిష్కారం ఇవ్వకపోతే, ఆటోమేటిక్ పునరుద్ధరణను ఆఫ్ చేసిన తర్వాత కూడా ప్రస్తుత చెల్లింపు వ్యవధి ముగిసే వరకు సబ్‌స్క్రిప్షన్‌ను ఉపయోగించవచ్చు."],"links":["appleCancel","googleManage"]},{"title":"4. కొనుగోళ్లు, పునరుద్ధరణ మరియు రీఫండ్‌లు","paragraphs":["కొనుగోళ్లు మరియు కొనుగోలు పునరుద్ధరణ అధికారిక Apple లేదా Google స్టోర్ ద్వారా పూర్తవుతాయి. స్టోర్ చెల్లుబాటు అయ్యే లావాదేవీని ధృవీకరించిన తర్వాత మాత్రమే హక్కు ఇవ్వబడుతుంది. రద్దు చేయబడిన, విఫలమైన లేదా పెండింగ్ లావాదేవీలు విజయవంతమైన ధృవీకరణకు ముందు హక్కును ఇవ్వవు. కొనుగోలు పునరుద్ధరణ జీవితకాల యాక్సెస్‌ను మరియు ప్రస్తుతం యాక్టివ్‌గా ఉన్న సబ్‌స్క్రిప్షన్‌ను పునరుద్ధరించవచ్చు. App Store మరియు Google Play కొనుగోళ్లు వేర్వేరు; ప్లాట్‌ఫారమ్‌ల మధ్య పునరుద్ధరించడం లేదా బదిలీ చేయడం సాధ్యం కాదు.","రీఫండ్‌లను లావాదేవీని పూర్తి చేసిన యాప్ స్టోర్ తన నియమాలు, కొనుగోలు ప్రాంతం మరియు వర్తించే చట్టం ప్రకారం నిర్వహిస్తుంది. స్టోర్ రీఫండ్, రద్దు, సబ్‌స్క్రిప్షన్ గడువు ముగింపు లేదా చెల్లని లావాదేవీని ధృవీకరించిన తర్వాత సంబంధిత హక్కు తొలగించబడుతుంది."],"links":["appleRefund","googleRefund"]},{"title":"5. ఆఫ్‌లైన్ వినియోగం మరియు లభ్యత","paragraphs":["చిత్ర ఎంపిక, OCR, సున్నితమైన కంటెంట్ గుర్తింపు, ఎడిటింగ్ మరియు ఎగుమతి పరికరంలోనే జరుగుతాయి. యాప్ క్లౌడ్ చిత్ర గుర్తింపు, క్లౌడ్ సమకాలీకరణ లేదా ఖాతాలను అందించదు. ఎగుమతి సమయంలో కొత్త చిత్రం సృష్టించబడుతుంది మరియు తొలగించగల ప్రైవేట్ మెటాడేటా తొలగించబడుతుంది. విజయవంతంగా సేవ్ చేసిన తర్వాత, ఎడిటింగ్‌ను వదిలినప్పుడు లేదా సెషన్ ముగిసినప్పుడు తాత్కాలిక ఫైళ్లు తొలగించబడతాయి; సేవ్ విఫలమైతే మళ్లీ ప్రయత్నించడానికి అవసరమైన స్థితి ఉంచబడవచ్చు."]},{"title":"6. ఆమోదయోగ్యమైన వినియోగం మరియు మేధో సంపత్తి","paragraphs":["చట్టవిరుద్ధ కార్యకలాపాలకు యాప్‌ను ఉపయోగించడం; కొనుగోలు ధృవీకరణను తప్పించుకోవడం; యాప్‌కు హాని కలిగించడం; హానికరమైన కోడ్‌ను పంపిణీ చేయడం; అనుమతి లేకుండా యాప్‌ను కాపీ చేయడం లేదా పంపిణీ చేయడం; లేదా యాప్ కంటెంట్‌లోని హక్కులను లేదా మరొకరి మేధో సంపత్తిని ఉల్లంఘించడం చేయకూడదు.","మీరు ఎప్పుడైనా యాప్ వినియోగాన్ని ఆపి అన్‌ఇన్‌స్టాల్ చేయవచ్చు. సమస్యలను పరిష్కరించడానికి, ఆపరేటింగ్ సిస్టమ్‌లకు మద్దతు ఇవ్వడానికి, స్థిరత్వాన్ని మెరుగుపరచడానికి లేదా ప్లాట్‌ఫారమ్ అవసరాలను తీర్చడానికి మేము అప్‌డేట్‌లను విడుదల చేయవచ్చు. పరికరం, సిస్టమ్, నెట్‌వర్క్ లేదా స్టోర్ సేవ సమస్యలు కొన్ని ఫీచర్‌లను తాత్కాలికంగా అందుబాటులో లేకుండా చేయవచ్చు.","వర్తించే చట్టం అనుమతించిన మేరకు యాప్ అందుబాటులో ఉన్న స్థితిలో అందించబడుతుంది. చట్టపరంగా మినహాయించలేని బాధ్యతను ఈ నిబంధనలు మినహాయించవు లేదా మీకు అందుబాటులో ఉన్న తప్పనిసరి వినియోగదారు హక్కులను పరిమితం చేయవు.","ఉత్పత్తి ఫీచర్‌లు, చెల్లింపు పద్ధతులు, ప్లాట్‌ఫారమ్ నియమాలు లేదా వర్తించే చట్టం మారితే, ఈ నిబంధనలను మరియు పేజీలో చూపిన తేదీని అప్‌డేట్ చేయవచ్చు. మార్పు వినియోగదారుల హక్కులను గణనీయంగా ప్రభావితం చేస్తే, అవసరమైన విధంగా అదనపు నోటీసు ఇస్తాము.","ఈ నిబంధనలు, కొనుగోళ్లు లేదా యాప్ వినియోగానికి సంబంధించిన ప్రశ్నల కోసం, ఇమెయిల్ చేయండి {email}"]}]},"support":{"title":"మద్దతు","lead":"ముందుగా దిగువ సాధారణ ప్రశ్నలను చూడండి. సమస్య కొనసాగితే, సహాయ ఇమెయిల్ చిరునామా ద్వారా మమ్మల్ని సంప్రదించండి.","emailTitle":"{appName} మద్దతు ఇమెయిల్","emailLead":"ముందుగా దిగువ సాధారణ ప్రశ్నలను చూడండి. సమస్య కొనసాగితే, సహాయ ఇమెయిల్ చిరునామా ద్వారా మమ్మల్ని సంప్రదించండి.","beforeEmail":{"title":"మీ ఇమెయిల్‌లో చేర్చాల్సినవి","paragraphs":["కొనుగోలు సమస్య కోసం యాప్ స్టోర్ ఆర్డర్ నంబర్‌ను చేర్చవచ్చు; కానీ ఖాతా లేదా చెల్లింపు పాస్‌వర్డ్ లేదా పూర్తి కార్డ్ సమాచారాన్ని పంపవద్దు."],"bullets":["మీ ప్లాట్‌ఫారమ్, పరికర మోడల్, ఆపరేటింగ్ సిస్టమ్ వెర్షన్ మరియు యాప్ వెర్షన్;","సమస్యకు ముందు మీరు చేసినది, మీరు ఆశించినది మరియు వాస్తవంగా జరిగినది; మరియు","అవసరమైతే, వ్యక్తిగత సమాచారం దాచిపెట్టిన స్క్రీన్‌షాట్ లేదా స్క్రీన్ రికార్డింగ్."]},"faqs":[{"question":"చిత్రాలు సర్వర్‌కు అప్‌లోడ్ అవుతాయా?","answer":"చిత్ర ఎంపిక, OCR, సున్నితమైన కంటెంట్ గుర్తింపు, ఎడిటింగ్ మరియు ఎగుమతి పరికరంలోనే జరుగుతాయి. యాప్ క్లౌడ్ చిత్ర గుర్తింపు, క్లౌడ్ సమకాలీకరణ లేదా ఖాతాలను అందించదు. ఎగుమతి సమయంలో కొత్త చిత్రం సృష్టించబడుతుంది మరియు తొలగించగల ప్రైవేట్ మెటాడేటా తొలగించబడుతుంది. విజయవంతంగా సేవ్ చేసిన తర్వాత, ఎడిటింగ్‌ను వదిలినప్పుడు లేదా సెషన్ ముగిసినప్పుడు తాత్కాలిక ఫైళ్లు తొలగించబడతాయి; సేవ్ విఫలమైతే మళ్లీ ప్రయత్నించడానికి అవసరమైన స్థితి ఉంచబడవచ్చు."},{"question":"అనుమతులు, ప్రకటనలు మరియు ట్రాకింగ్","answer":"మీరు అనుమతించిన చిత్రాలను చూపడానికి మరియు ప్రాసెస్ చేయడానికి మాత్రమే ఫోటో యాక్సెస్ ఉపయోగించబడుతుంది. యాప్‌లో ఫోటో తీయాలని ఎంచుకున్నప్పుడు మాత్రమే కెమెరా ఉపయోగించబడుతుంది. చెల్లుబాటు అయ్యే Premiumతో ఎగుమతిని నిర్ధారించినప్పుడు మాత్రమే ఫోటో లైబ్రరీలో సేవ్ చేసే అనుమతి కోరబడుతుంది. యాప్ స్థానం, పరిచయాలు, మైక్రోఫోన్, Bluetooth లేదా నోటిఫికేషన్ అనుమతులను కోరదు."},{"question":"చెల్లింపు ఉత్పత్తులు మరియు ధరలు","answer":"గుర్తింపు మరియు ఎడిటింగ్‌కు వినియోగ పరిమితులు లేవు. ప్రాసెస్ చేసిన చిత్రాన్ని ఎగుమతి చేయడానికి మాత్రమే చెల్లుబాటు అయ్యే Premium అవసరం. ఉచిత ట్రయల్ లేకుండా స్వయంచాలకంగా పునరుద్ధరించే వారపు మరియు నెలవారీ సభ్యత్వాలు, ఒకసారి కొనుగోలు చేసే జీవితకాల యాక్సెస్ అందుబాటులో ఉంటాయి. App Store మరియు Google Play కొనుగోళ్లు వేర్వేరు; ప్లాట్‌ఫారమ్‌ల మధ్య బదిలీ చేయలేరు."},{"question":"సేవ్ చేయడం మరియు చిత్ర ఫార్మాట్‌లు","answer":"సేవ్ విఫలమైతే ఖాళీ స్థలం, ఫోటో లైబ్రరీలో సేవ్ చేసే అనుమతి మరియు అసలు చిత్రం చదవగలిగే స్థితిలో ఉందో చూసి మళ్లీ ప్రయత్నించండి. యాప్ ఒకేసారి ఒక స్థిర చిత్రాన్ని ప్రాసెస్ చేస్తుంది మరియు సాధారణ ఫార్మాట్‌లలో ఎక్కువ భాగాన్ని మద్దతు ఇస్తుంది; కొన్ని పరికరం మరియు సిస్టమ్ వెర్షన్‌పై ఆధారపడతాయి. వీడియో, PDF, RAW/DNG మరియు బ్యాచ్ ప్రాసెసింగ్ ప్రస్తుతం మద్దతు పొందవు."},{"question":"భాషను ఎలా మార్చాలి?","answer":"యాప్ 40 భాషలకు మద్దతు ఇస్తుంది; యాప్ సెట్టింగ్‌లలో భాషను మార్చవచ్చు. ప్రదర్శన సరిగా లేకపోతే, పరికర భాష మరియు యాప్‌లో ఎంచుకున్న భాషను ఇమెయిల్ చేయండి."},{"question":"పునరుద్ధరణ, రద్దు మరియు రీఫండ్‌లు","answer":"కొనుగోళ్లు మరియు కొనుగోలు పునరుద్ధరణ అధికారిక Apple లేదా Google స్టోర్ ద్వారా పూర్తవుతాయి. స్టోర్ చెల్లుబాటు అయ్యే లావాదేవీని ధృవీకరించిన తర్వాత మాత్రమే హక్కు ఇవ్వబడుతుంది. రద్దు చేయబడిన, విఫలమైన లేదా పెండింగ్ లావాదేవీలు విజయవంతమైన ధృవీకరణకు ముందు హక్కును ఇవ్వవు. కొనుగోలు పునరుద్ధరణ జీవితకాల యాక్సెస్‌ను మరియు ప్రస్తుతం యాక్టివ్‌గా ఉన్న సబ్‌స్క్రిప్షన్‌ను పునరుద్ధరించవచ్చు. App Store మరియు Google Play కొనుగోళ్లు వేర్వేరు; ప్లాట్‌ఫారమ్‌ల మధ్య పునరుద్ధరించడం లేదా బదిలీ చేయడం సాధ్యం కాదు."},{"question":"గోప్యత మరియు డేటా తొలగింపు","answer":"యాప్‌ను అన్‌ఇన్‌స్టాల్ చేయడం ద్వారా పరికరంలోని డేటాను తొలగించండి. Androidలో సిస్టమ్‌లోని డేటాను క్లియర్ చేయి ఎంపికను కూడా ఉపయోగించవచ్చు. స్టోర్ కొనుగోలు రికార్డ్‌లను Apple లేదా Google నిర్వహిస్తుంది. పునరుద్ధరించగల హక్కులు స్టోర్ నియమాల ప్రకారం మళ్లీ ధృవీకరించబడతాయి. అభ్యర్థనను నిర్వహించడానికి మరియు అవసరమైన రికార్డ్ నిర్వహణ అవసరాలను తీర్చడానికి అవసరమైనంత కాలం సహాయ ఇమెయిల్‌లు ఉంచబడతాయి. మేము ఇప్పటికీ ఉంచుకున్న సహాయ ఉత్తరప్రత్యుత్తరాలను తొలగించమని మీరు ఇమెయిల్ ద్వారా అభ్యర్థించవచ్చు."}],"officialHelpTitle":"త్వరిత సహాయం"}},"th":{"linkLabels":{"appleEula":"ข้อตกลงการอนุญาตให้ใช้สิทธิ์สำหรับผู้ใช้ปลายทางมาตรฐาน (EULA) ของ Apple","appleCancel":"คำแนะนำในการยกเลิกการสมัครสมาชิก Apple","googleManage":"วิธียกเลิกใน Google Play","appleRefund":"ขอเงินคืนจากแอปเปิล","googleRefund":"ข้อมูลการคืนเงินของ Google Play"},"nav":{"privacy":"นโยบายความเป็นส่วนตัว","terms":"ข้อกำหนดในการใช้งาน","support":"ฝ่ายสนับสนุน","language":"ภาษา","chooseLanguage":"เลือกภาษาที่จะแสดงผล","navigationLabel":"การนำทางหลัก"},"home":{"eyebrow":"{appName} · Privacy first","title":"รูปภาพของคุณจะไม่ถูกอัปโหลดไปยังเซิร์ฟเวอร์ของเรา","lead":"การเลือกรูปภาพ, OCR, การตรวจหาเนื้อหาที่ละเอียดอ่อน, การแก้ไข และการส่งออกทำบนอุปกรณ์ แอปไม่มีการรู้จำรูปภาพบนคลาวด์ การซิงค์คลาวด์ หรือบัญชี เมื่อส่งออก แอปจะสร้างรูปภาพใหม่และลบข้อมูลเมตาส่วนตัวที่ลบได้ ไฟล์ทำงานชั่วคราวจะถูกลบหลังบันทึกสำเร็จ เมื่อยกเลิกการแก้ไข หรือเมื่อเซสชันสิ้นสุด หากบันทึกล้มเหลว แอปอาจเก็บสถานะที่จำเป็นไว้เพื่อลองอีกครั้ง","points":["ข้อมูลของแอป","ผลิตภัณฑ์แบบชำระเงินและราคา","ฝ่ายสนับสนุน"],"cards":[{"title":"นโยบายความเป็นส่วนตัว","description":"รูปภาพของคุณจะไม่ถูกอัปโหลดไปยังเซิร์ฟเวอร์ของเรา","action":"นโยบายความเป็นส่วนตัว"},{"title":"ข้อกำหนดในการใช้งาน","description":"การรู้จำและการแก้ไขไม่มีการจำกัดจำนวนครั้ง เฉพาะการส่งออกรูปที่ประมวลผลแล้วเท่านั้นที่ต้องมี Premium ที่ถูกต้อง แอปมีการสมัครสมาชิกรายสัปดาห์และรายเดือนแบบต่ออายุอัตโนมัติ และการซื้อสิทธิ์ตลอดชีพครั้งเดียว โดยไม่มีช่วงทดลองใช้ฟรี การซื้อจาก App Store และ Google Play แยกจากกันและโอนข้ามแพลตฟอร์มไม่ได้","action":"ข้อกำหนดในการใช้งาน"},{"title":"ต้องการความช่วยเหลือไหม?","description":"เริ่มจากคำถามที่พบบ่อยด้านล่าง หากปัญหายังคงอยู่ โปรดติดต่อเราผ่านที่อยู่อีเมลช่วยเหลือ","action":"ฝ่ายสนับสนุน"}]},"footer":{"privacy":"นโยบายความเป็นส่วนตัว","terms":"ข้อกำหนดในการใช้งาน","support":"ฝ่ายสนับสนุน"},"privacy":{"title":"นโยบายความเป็นส่วนตัว","lead":"นโยบายนี้อธิบายวิธีที่ {appName} จัดการข้อมูลในเครื่อง ข้อมูลการซื้อจาก App Store และอีเมลช่วยเหลือ","sections":[{"title":"1. ขอบเขตงานและข้อมูลติดต่อ","paragraphs":["นโยบายนี้ใช้กับแอป {appName} สำหรับ iOS, iPadOS และ Android รวมถึงเว็บไซต์ความเป็นส่วนตัว ข้อกำหนด และความช่วยเหลือนี้","สำหรับคำถามเกี่ยวกับความเป็นส่วนตัว โปรดส่งอีเมลไปที่ {email}"]},{"title":"2. ข้อมูลของแอป","callout":{"title":"รูปภาพของคุณจะไม่ถูกอัปโหลดไปยังเซิร์ฟเวอร์ของเรา","body":"การเลือกรูปภาพ, OCR, การตรวจหาเนื้อหาที่ละเอียดอ่อน, การแก้ไข และการส่งออกทำบนอุปกรณ์ แอปไม่มีการรู้จำรูปภาพบนคลาวด์ การซิงค์คลาวด์ หรือบัญชี เมื่อส่งออก แอปจะสร้างรูปภาพใหม่และลบข้อมูลเมตาส่วนตัวที่ลบได้ ไฟล์ทำงานชั่วคราวจะถูกลบหลังบันทึกสำเร็จ เมื่อยกเลิกการแก้ไข หรือเมื่อเซสชันสิ้นสุด หากบันทึกล้มเหลว แอปอาจเก็บสถานะที่จำเป็นไว้เพื่อลองอีกครั้ง"},"paragraphs":[]},{"title":"3. สิทธิ์อนุญาต โฆษณา และการติดตาม","paragraphs":["การเข้าถึงรูปภาพใช้เพื่อแสดงและประมวลผลเฉพาะรูปที่คุณอนุญาต กล้องจะใช้เมื่อคุณเลือกถ่ายภาพในแอปเท่านั้น สิทธิ์บันทึกลงคลังรูปภาพจะขอเมื่อคุณยืนยันการส่งออกพร้อมสิทธิ์ Premium ที่ถูกต้องเท่านั้น แอปไม่ขอตำแหน่ง รายชื่อ ไมโครโฟน Bluetooth หรือการแจ้งเตือน","ไม่ใช้รหัสโฆษณา และไม่ผสานรวม SDK ของบุคคลที่สามสำหรับโฆษณา การวิเคราะห์ การระบุแหล่งที่มา หรือการรายงานข้อขัดข้อง","แอปไม่ผสานรวมเครื่องมือรายงานข้อขัดข้องของบุคคลที่สาม Apple หรือ Google อาจประมวลผลข้อมูลการวินิจฉัยระบบตามกฎความเป็นส่วนตัวของตนและให้ข้อมูลทางเทคนิคที่ใช้ตรวจสอบข้อขัดข้องหรือปัญหาด้านประสิทธิภาพ ทั้งนี้ขึ้นอยู่กับการตั้งค่าอุปกรณ์และร้านค้าของคุณ"]},{"title":"4. บริการ App Store และการเข้าถึงเครือข่าย","paragraphs":["แอปใช้ Apple StoreKit หรือ Google Play Billing เพื่อโหลดผลิตภัณฑ์ แสดงราคาตามภูมิภาคที่ร้านค้าส่งกลับมา ดำเนินการซื้อ กู้คืนการซื้อ จัดการการสมัครสมาชิก และยืนยันสิทธิ์ การเข้าถึงเครือข่ายใช้เฉพาะกับฟังก์ชันร้านค้าอย่างเป็นทางการของ Apple หรือ Google เหล่านี้เท่านั้น","Apple หรือ Google เป็นผู้รับผิดชอบบัญชีร้านค้า การชำระเงิน การเรียกเก็บเงิน ธุรกรรม การคืนเงิน และบริการสมัครสมาชิก แอปประมวลผลเฉพาะข้อมูลร้านค้าที่จำเป็นต่อการยืนยันผลิตภัณฑ์และสิทธิ์ และไม่ได้รับหรือเก็บข้อมูลรับรองการชำระเงินทั้งหมด"]},{"title":"5. อีเมลช่วยเหลือและเว็บไซต์","paragraphs":["แอปไม่อ่านข้อมูลอีเมลของคุณโดยอัตโนมัติ ช่องทางช่วยเหลือจะได้รับที่อยู่อีเมล ข้อความ และภาพหน้าจอ การบันทึกหน้าจอ หมายเลขคำสั่งซื้อ หรือไฟล์แนบอื่นที่คุณส่งโดยสมัครใจ เฉพาะเมื่อคุณเลือกส่งอีเมลขอความช่วยเหลือเท่านั้น ข้อมูลนี้ใช้เพื่อจัดการคำขอของคุณเท่านั้น ไม่ใช้เพื่อการโฆษณาหรือการตลาด อย่าส่งรหัสผ่านบัญชี รหัสผ่านการชำระเงิน หรือหมายเลขบัตรทั้งหมด","เว็บไซต์นี้ไม่ตั้งค่าคุกกี้โฆษณาหรือการวิเคราะห์ และไม่มีการวิเคราะห์การเข้าชมหรือสคริปต์ติดตาม"]},{"title":"6. การเก็บรักษาและการลบ","paragraphs":["ลบข้อมูลในเครื่องโดยถอนการติดตั้งแอป บน Android คุณยังใช้ตัวเลือก \"ล้างข้อมูล\" ของระบบได้","Apple หรือ Google เป็นผู้จัดการบันทึกการซื้อจากร้านค้า สิทธิ์ที่กู้คืนได้จะได้รับการยืนยันอีกครั้งตามกฎของร้านค้า","อีเมลช่วยเหลือจะเก็บไว้เท่าที่จำเป็นต่อการจัดการคำขอและปฏิบัติตามข้อกำหนดที่จำเป็นในการเก็บบันทึก คุณสามารถส่งอีเมลเพื่อขอให้เราลบการติดต่อกับฝ่ายช่วยเหลือที่เรายังเก็บไว้ได้"]},{"title":"7. ความปลอดภัยของข้อมูล","paragraphs":["แอปใช้การประมวลผลในเครื่อง สิทธิ์อนุญาตขั้นต่ำ และขั้นตอนการซื้ออย่างเป็นทางการของ App Store เพื่อลดการถ่ายโอนข้อมูลที่ไม่จำเป็น อีเมลช่วยเหลือใช้เพื่อจัดการคำขอที่ได้รับเท่านั้น พร้อมมาตรการป้องกันที่สมเหตุสมผลและเหมาะกับลักษณะของข้อมูล","ไม่มีอุปกรณ์ เครือข่าย หรือวิธีจัดเก็บข้อมูลอิเล็กทรอนิกส์ใดที่รับประกันได้ว่าปลอดภัยอย่างสมบูรณ์ อย่าใส่ข้อมูลที่ละเอียดอ่อนและไม่เกี่ยวข้องไว้ในอีเมลช่วยเหลือ"]},{"title":"8. เด็กและวัยรุ่น","paragraphs":["แอปไม่ต้องใช้บัญชีและไม่สร้างโปรไฟล์ของเด็กหรือผู้ใช้อื่นผ่านโฆษณาหรือการวิเคราะห์พฤติกรรม ผู้ปกครองหรือผู้ดูแลที่เชื่อว่าเด็กได้ส่งข้อมูลส่วนบุคคลผ่านอีเมลช่วยเหลือสามารถติดต่อเราเพื่อให้ดำเนินการเกี่ยวกับเรื่องดังกล่าวได้"]},{"title":"9. ตัวเลือกและสิทธิ์ของคุณ","paragraphs":["คุณจัดการข้อมูลในเครื่องผ่านอุปกรณ์ของคุณ Apple หรือ Google จัดการบัญชีร้านค้าและบันทึกการซื้อ แอปไม่สามารถแก้ไขหรือลบบันทึกธุรกรรมที่ App Store เก็บไว้แทนคุณได้","หากแนวทางการใช้ข้อมูลของแอป กฎของแพลตฟอร์ม หรือการโฮสต์เว็บไซต์เปลี่ยนแปลง เราจะอัปเดตนโยบายนี้และวันที่ที่แสดงบนหน้านี้ พร้อมแจ้งเพิ่มเติมเมื่อกฎที่ใช้บังคับกำหนด","สำหรับคำถามเกี่ยวกับความเป็นส่วนตัว โปรดส่งอีเมลไปที่ {email}"]}]},"terms":{"title":"ข้อกำหนดในการใช้งาน","lead":"ข้อกำหนดการใช้งานของ {appName}","sections":[{"title":"1. การยอมรับข้อกำหนดและเงื่อนไขและกฎของแพลตฟอร์ม","paragraphs":["โดยการดาวน์โหลด ซื้อ หรือใช้งาน {appName} คุณตกลงที่จะปฏิบัติตามข้อกำหนดเหล่านี้และกฎที่ใช้บังคับกับคุณในแอปสโตร์ที่คุณทำการซื้อ หากคุณไม่เห็นด้วย โปรดอย่าใช้งานแอปต่อหรือทำการซื้อ","ข้อกำหนดเหล่านี้ใช้กับการดาวน์โหลด ซื้อ และใช้แอปของคุณ เวอร์ชัน iOS และ iPadOS ยังอยู่ภายใต้"],"links":["appleEula"]},{"title":"2. ผลิตภัณฑ์แบบชำระเงินและราคา","paragraphs":["การรู้จำและการแก้ไขไม่มีการจำกัดจำนวนครั้ง เฉพาะการส่งออกรูปที่ประมวลผลแล้วเท่านั้นที่ต้องมี Premium ที่ถูกต้อง แอปมีการสมัครสมาชิกรายสัปดาห์และรายเดือนแบบต่ออายุอัตโนมัติ และการซื้อสิทธิ์ตลอดชีพครั้งเดียว โดยไม่มีช่วงทดลองใช้ฟรี การซื้อจาก App Store และ Google Play แยกจากกันและโอนข้ามแพลตฟอร์มไม่ได้","ราคาจริง สกุลเงิน ภาษี รอบการเรียกเก็บเงิน และสิทธิ์ในการซื้อเป็นข้อมูลที่แสดงและยืนยันบนหน้าจอซื้อของระบบ App Store หรือ Google Play แพลตฟอร์มการซื้อจะเรียกเก็บและจัดการการชำระเงินผ่านบัญชีร้านค้าของคุณ แอปไม่มีช่วงทดลองใช้ฟรีสำหรับการสมัครสมาชิกหรือแผนแบบชำระเงินอื่น"]},{"title":"3. การต่ออายุอัตโนมัติและการยกเลิก","paragraphs":["การสมัครสมาชิกรายสัปดาห์และรายเดือนจะต่ออายุอัตโนมัติและเรียกเก็บเงินตามรอบที่แสดงบนหน้าจอซื้อของระบบ จนกว่าคุณจะยกเลิกผ่านแพลตฟอร์มการซื้อ การลบ {appName} ไม่ได้ยกเลิกการสมัครสมาชิกโดยอัตโนมัติ เว้นแต่แพลตฟอร์มการซื้อจะคืนเงินหรือดำเนินการเป็นอย่างอื่น คุณจะยังใช้การสมัครสมาชิกได้จนสิ้นสุดรอบที่ชำระเงินปัจจุบันหลังจากปิดการต่ออายุอัตโนมัติ"],"links":["appleCancel","googleManage"]},{"title":"4. การซื้อ การกู้คืน และการคืนเงิน","paragraphs":["การซื้อและกู้คืนการซื้อดำเนินการผ่านร้านค้าอย่างเป็นทางการของ Apple หรือ Google ระบบจะให้สิทธิ์หลังจากร้านค้ายืนยันธุรกรรมที่ถูกต้องแล้วเท่านั้น ธุรกรรมที่ยกเลิก ไม่สำเร็จ หรือรอดำเนินการจะไม่ให้สิทธิ์ก่อนยืนยันสำเร็จ การกู้คืนการซื้อสามารถกู้คืนสิทธิ์ตลอดชีพและการสมัครสมาชิกที่ยังใช้งานอยู่ได้ การซื้อใน App Store และ Google Play แยกจากกันและไม่สามารถกู้คืนหรือโอนข้ามแพลตฟอร์มได้","การคืนเงินดำเนินการโดย App Store ที่ทำธุรกรรมเสร็จสิ้น ตามกฎของร้านค้า ภูมิภาคที่ซื้อ และกฎหมายที่ใช้บังคับ สิทธิ์ที่เกี่ยวข้องจะถูกนำออกหลังจากร้านค้ายืนยันการคืนเงิน การเพิกถอน การหมดอายุของการสมัครสมาชิก หรือธุรกรรมที่ไม่ถูกต้อง"],"links":["appleRefund","googleRefund"]},{"title":"5. การใช้งานออฟไลน์และความพร้อมให้บริการ","paragraphs":["การเลือกรูปภาพ, OCR, การตรวจหาเนื้อหาที่ละเอียดอ่อน, การแก้ไข และการส่งออกทำบนอุปกรณ์ แอปไม่มีการรู้จำรูปภาพบนคลาวด์ การซิงค์คลาวด์ หรือบัญชี เมื่อส่งออก แอปจะสร้างรูปภาพใหม่และลบข้อมูลเมตาส่วนตัวที่ลบได้ ไฟล์ทำงานชั่วคราวจะถูกลบหลังบันทึกสำเร็จ เมื่อยกเลิกการแก้ไข หรือเมื่อเซสชันสิ้นสุด หากบันทึกล้มเหลว แอปอาจเก็บสถานะที่จำเป็นไว้เพื่อลองอีกครั้ง"]},{"title":"6. การใช้งานที่ยอมรับได้และทรัพย์สินทางปัญญา","paragraphs":["คุณต้องไม่ใช้แอปเพื่อกิจกรรมที่ผิดกฎหมาย หลีกเลี่ยงการยืนยันการซื้อ ทำให้แอปเสียหาย แจกจ่ายโค้ดอันตราย คัดลอกหรือแจกจ่ายแอปโดยไม่ได้รับอนุญาต หรือละเมิดสิทธิ์ในเนื้อหาแอปหรือทรัพย์สินทางปัญญาของบุคคลอื่น","คุณสามารถหยุดใช้และถอนการติดตั้งแอปได้ทุกเมื่อ เราอาจออกอัปเดตเพื่อแก้ปัญหา รองรับระบบปฏิบัติการ เพิ่มความเสถียร หรือปฏิบัติตามข้อกำหนดของแพลตฟอร์ม ปัญหาเกี่ยวกับอุปกรณ์ ระบบ เครือข่าย หรือบริการร้านค้าอาจทำให้บางฟีเจอร์ใช้งานไม่ได้ชั่วคราว","แอปมีให้ตามสภาพพร้อมใช้งานภายในขอบเขตที่กฎหมายอนุญาต ข้อกำหนดเหล่านี้ไม่ยกเว้นความรับผิดที่กฎหมายไม่อนุญาตให้ยกเว้น และไม่จำกัดสิทธิ์ผู้บริโภคภาคบังคับที่คุณมี","หากฟีเจอร์ผลิตภัณฑ์ วิธีชำระเงิน กฎของแพลตฟอร์ม หรือกฎหมายที่ใช้บังคับเปลี่ยนแปลง เราอาจอัปเดตข้อกำหนดเหล่านี้และวันที่ที่แสดงบนหน้า หากการเปลี่ยนแปลงมีผลอย่างมากต่อสิทธิ์ของผู้ใช้ เราจะแจ้งเพิ่มเติมตามที่กำหนด","หากมีข้อสงสัยเกี่ยวกับข้อกำหนดเหล่านี้ การซื้อ หรือการใช้งานแอป โปรดส่งอีเมลมาที่ {email}"]}]},"support":{"title":"ฝ่ายสนับสนุน","lead":"เริ่มจากคำถามที่พบบ่อยด้านล่าง หากปัญหายังคงอยู่ โปรดติดต่อเราผ่านที่อยู่อีเมลช่วยเหลือ","emailTitle":"อีเมลฝ่ายสนับสนุนของ {appName}","emailLead":"เริ่มจากคำถามที่พบบ่อยด้านล่าง หากปัญหายังคงอยู่ โปรดติดต่อเราผ่านที่อยู่อีเมลช่วยเหลือ","beforeEmail":{"title":"ข้อมูลที่ควรระบุในอีเมล","paragraphs":["สำหรับปัญหาการซื้อ คุณสามารถระบุหมายเลขคำสั่งซื้อจาก App Store ได้ แต่อย่าส่งรหัสผ่านบัญชี รหัสผ่านการชำระเงิน หรือข้อมูลบัตรทั้งหมด"],"bullets":["แพลตฟอร์ม รุ่นอุปกรณ์ เวอร์ชันระบบปฏิบัติการ และเวอร์ชันแอปของคุณ","สิ่งที่คุณทำก่อนเกิดปัญหา สิ่งที่คาดหวัง และสิ่งที่เกิดขึ้นจริง และ","หากจำเป็น สามารถแคปหน้าจอหรือบันทึกหน้าจอโดยปิดบังข้อมูลส่วนตัวได้"]},"faqs":[{"question":"รูปภาพถูกอัปโหลดไปยังเซิร์ฟเวอร์หรือไม่","answer":"การเลือกรูปภาพ, OCR, การตรวจหาเนื้อหาที่ละเอียดอ่อน, การแก้ไข และการส่งออกทำบนอุปกรณ์ แอปไม่มีการรู้จำรูปภาพบนคลาวด์ การซิงค์คลาวด์ หรือบัญชี เมื่อส่งออก แอปจะสร้างรูปภาพใหม่และลบข้อมูลเมตาส่วนตัวที่ลบได้ ไฟล์ทำงานชั่วคราวจะถูกลบหลังบันทึกสำเร็จ เมื่อยกเลิกการแก้ไข หรือเมื่อเซสชันสิ้นสุด หากบันทึกล้มเหลว แอปอาจเก็บสถานะที่จำเป็นไว้เพื่อลองอีกครั้ง"},{"question":"สิทธิ์อนุญาต โฆษณา และการติดตาม","answer":"การเข้าถึงรูปภาพใช้เพื่อแสดงและประมวลผลเฉพาะรูปที่คุณอนุญาต กล้องจะใช้เมื่อคุณเลือกถ่ายภาพในแอปเท่านั้น สิทธิ์บันทึกลงคลังรูปภาพจะขอเมื่อคุณยืนยันการส่งออกพร้อมสิทธิ์ Premium ที่ถูกต้องเท่านั้น แอปไม่ขอตำแหน่ง รายชื่อ ไมโครโฟน Bluetooth หรือการแจ้งเตือน"},{"question":"ผลิตภัณฑ์แบบชำระเงินและราคา","answer":"การรู้จำและการแก้ไขไม่มีการจำกัดจำนวนครั้ง เฉพาะการส่งออกรูปที่ประมวลผลแล้วเท่านั้นที่ต้องมี Premium ที่ถูกต้อง แอปมีการสมัครสมาชิกรายสัปดาห์และรายเดือนแบบต่ออายุอัตโนมัติ และการซื้อสิทธิ์ตลอดชีพครั้งเดียว โดยไม่มีช่วงทดลองใช้ฟรี การซื้อจาก App Store และ Google Play แยกจากกันและโอนข้ามแพลตฟอร์มไม่ได้"},{"question":"การบันทึกและรูปแบบภาพ","answer":"หากบันทึกล้มเหลว ให้ตรวจสอบพื้นที่ว่าง สิทธิ์บันทึกลงคลังรูปภาพ และว่ายังอ่านรูปต้นฉบับได้ แล้วลองอีกครั้ง แอปประมวลผลภาพนิ่งครั้งละหนึ่งรูปและรองรับรูปแบบทั่วไปส่วนใหญ่ บางรูปแบบขึ้นอยู่กับอุปกรณ์และเวอร์ชันระบบ ขณะนี้ยังไม่รองรับวิดีโอ PDF, RAW/DNG และการประมวลผลแบบกลุ่ม"},{"question":"จะเปลี่ยนภาษาได้อย่างไร","answer":"แอปรองรับ 40 ภาษาและเปลี่ยนภาษาได้ในการตั้งค่าแอป หากการแสดงผลไม่ถูกต้อง โปรดส่งอีเมลแจ้งภาษาของอุปกรณ์และภาษาที่เลือกในแอป"},{"question":"การกู้คืน การยกเลิก และการคืนเงิน","answer":"การซื้อและกู้คืนการซื้อดำเนินการผ่านร้านค้าอย่างเป็นทางการของ Apple หรือ Google ระบบจะให้สิทธิ์หลังจากร้านค้ายืนยันธุรกรรมที่ถูกต้องแล้วเท่านั้น ธุรกรรมที่ยกเลิก ไม่สำเร็จ หรือรอดำเนินการจะไม่ให้สิทธิ์ก่อนยืนยันสำเร็จ การกู้คืนการซื้อสามารถกู้คืนสิทธิ์ตลอดชีพและการสมัครสมาชิกที่ยังใช้งานอยู่ได้ การซื้อใน App Store และ Google Play แยกจากกันและไม่สามารถกู้คืนหรือโอนข้ามแพลตฟอร์มได้"},{"question":"ความเป็นส่วนตัวและการลบข้อมูล","answer":"ลบข้อมูลในเครื่องโดยถอนการติดตั้งแอป บน Android คุณยังใช้ตัวเลือก \"ล้างข้อมูล\" ของระบบได้ Apple หรือ Google เป็นผู้จัดการบันทึกการซื้อจากร้านค้า สิทธิ์ที่กู้คืนได้จะได้รับการยืนยันอีกครั้งตามกฎของร้านค้า อีเมลช่วยเหลือจะเก็บไว้เท่าที่จำเป็นต่อการจัดการคำขอและปฏิบัติตามข้อกำหนดที่จำเป็นในการเก็บบันทึก คุณสามารถส่งอีเมลเพื่อขอให้เราลบการติดต่อกับฝ่ายช่วยเหลือที่เรายังเก็บไว้ได้"}],"officialHelpTitle":"ความช่วยเหลือด่วน"}},"tr":{"linkLabels":{"appleEula":"Apple Standart Son Kullanıcı Lisans Sözleşmesi’ne (EULA)","appleCancel":"Apple aboneliğini iptal etme talimatları","googleManage":"Google Play iptal talimatları","appleRefund":"Apple'dan para iadesi talep edin.","googleRefund":"Google Play geri ödeme bilgileri"},"nav":{"privacy":"Gizlilik Politikası","terms":"Kullanım Şartları","support":"Destek","language":"Dil","chooseLanguage":"Görüntüleme dilini seçin","navigationLabel":"Birincil navigasyon"},"home":{"eyebrow":"{appName} · Privacy first","title":"Görselleriniz sunucularımıza yüklenmez.","lead":"Görsel seçimi, OCR, hassas içerik algılama, düzenleme ve dışa aktarma cihazınızda gerçekleştirilir. Uygulama bulut tabanlı görsel tanıma, bulut eşitleme veya hesap hizmeti sunmaz. Dışa aktarma sırasında yeni bir görsel oluşturulur ve kaldırılabilen özel meta veriler silinir. Geçici çalışma dosyaları başarılı kaydetme, düzenlemeden vazgeçme veya oturum sonrasında temizlenir; kaydetme başarısız olursa yeniden deneme için gerekli durum korunabilir.","points":["Uygulama verileri","Ücretli ürünler ve fiyatlar","Destek"],"cards":[{"title":"Gizlilik Politikası","description":"Görselleriniz sunucularımıza yüklenmez.","action":"Gizlilik Politikası"},{"title":"Kullanım Şartları","description":"Tanıma ve düzenlemede kullanım sınırı yoktur. Yalnızca işlenen görseli dışa aktarmak için geçerli Premium erişimi gerekir. Ücretsiz deneme olmadan otomatik yenilenen haftalık ve aylık abonelikler ile tek seferlik ömür boyu satın alma sunulur. App Store ve Google Play satın alımları ayrıdır ve platformlar arasında aktarılamaz.","action":"Kullanım Şartları"},{"title":"Yardıma mı ihtiyacınız var?","description":"Önce aşağıdaki sık sorulan sorulara bakın. Sorun sürerse destek e-posta adresinden bize ulaşın.","action":"Destek"}]},"footer":{"privacy":"Gizlilik Politikası","terms":"Kullanım Şartları","support":"Destek"},"privacy":{"title":"Gizlilik Politikası","lead":"Bu Politika, {appName} uygulamasının cihazdaki verileri, mağaza satın alma bilgilerini ve destek e-postalarını nasıl işlediğini açıklar.","sections":[{"title":"1. Kapsam ve iletişim","paragraphs":["Bu Politika, iOS, iPadOS ve Android için {appName} uygulaması ile bu gizlilik, koşullar ve destek web sitesi için geçerlidir.","Gizlilikle ilgili sorularınız için lütfen e-posta gönderin. {email}"]},{"title":"2. Uygulama verileri","callout":{"title":"Görselleriniz sunucularımıza yüklenmez.","body":"Görsel seçimi, OCR, hassas içerik algılama, düzenleme ve dışa aktarma cihazınızda gerçekleştirilir. Uygulama bulut tabanlı görsel tanıma, bulut eşitleme veya hesap hizmeti sunmaz. Dışa aktarma sırasında yeni bir görsel oluşturulur ve kaldırılabilen özel meta veriler silinir. Geçici çalışma dosyaları başarılı kaydetme, düzenlemeden vazgeçme veya oturum sonrasında temizlenir; kaydetme başarısız olursa yeniden deneme için gerekli durum korunabilir."},"paragraphs":[]},{"title":"3. İzinler, reklam ve izleme","paragraphs":["Fotoğraf erişimi yalnızca izin verdiğiniz görselleri göstermek ve işlemek için kullanılır. Kamera yalnızca uygulama içinde fotoğraf çekmeyi seçtiğinizde kullanılır. Fotoğraf arşivine kaydetme izni yalnızca geçerli Premium erişimiyle dışa aktarmayı onayladığınızda istenir. Uygulama konum, kişiler, mikrofon, Bluetooth veya bildirim izinleri istemez.","Reklam tanımlayıcısı kullanmaz ve reklam, analiz, ilişkilendirme ya da kilitlenme raporlama için üçüncü taraf SDK’ları entegre etmez.","Uygulama üçüncü taraf kilitlenme raporlama aracı entegre etmez. Cihaz ve mağaza ayarlarınıza bağlı olarak Apple veya Google, sistem tanılama bilgilerini kendi gizlilik kurallarına göre işleyebilir ve kilitlenme ya da performans sorunlarını araştırmak için kullanılan teknik bilgiler sağlayabilir."]},{"title":"4. Uygulama mağazası hizmetleri ve ağ erişimi","paragraphs":["Uygulama; ürünleri yüklemek, mağazanın döndürdüğü yerel fiyatları göstermek, satın alma işlemlerini tamamlamak ve geri yüklemek, abonelikleri yönetmek ve hakları doğrulamak için Apple StoreKit veya Google Play Billing kullanır. Ağ erişimi yalnızca Apple ya da Google’ın bu resmi mağaza özellikleri için kullanılır.","Mağaza hesapları, ödemeler, faturalandırma, işlemler, geri ödemeler ve abonelik hizmetlerinden Apple veya Google sorumludur. Uygulama yalnızca ürünleri ve hakları doğrulamak için gereken mağaza bilgilerini işler; tam ödeme bilgilerini almaz veya saklamaz."]},{"title":"5. Destek e-postaları ve web sitesi","paragraphs":["Uygulama e-posta bilgilerinizi otomatik olarak okumaz. Destek kanalı yalnızca siz destek e-postası gönderdiğinizde e-posta adresinizi, mesajınızı ve gönüllü olarak eklediğiniz ekran görüntülerini, ekran kayıtlarını, sipariş numarasını veya diğer ekleri alır. Bu bilgiler yalnızca talebinizi ele almak için kullanılır; reklam veya pazarlama amacıyla kullanılmaz. Hesap ya da ödeme parolaları veya tam kart numaraları göndermeyin.","Bu web sitesi reklam veya analiz çerezleri yerleştirmez ve trafik analizi ya da izleme komut dosyaları içermez."]},{"title":"6. Saklama ve silme","paragraphs":["Cihazdaki verileri silmek için uygulamayı kaldırın. Android’de sistemin “Verileri temizle” seçeneğini de kullanabilirsiniz.","Satın alma kayıtları Apple veya Google tarafından yönetilir. Geri yüklenebilir haklar mağaza kurallarına göre yeniden doğrulanır.","Destek e-postaları, talebi ele almak ve gerekli kayıt tutma yükümlülüklerini karşılamak için gereken süre boyunca saklanır. Hâlâ tuttuğumuz destek yazışmalarının silinmesini e-postayla isteyebilirsiniz."]},{"title":"7. Veri güvenliği","paragraphs":["Uygulama, gereksiz veri aktarımını azaltmak için cihaz üzerinde işleme, en az izin ve resmi uygulama mağazası satın alma süreçlerini kullanır. Destek e-postaları yalnızca gelen talepleri ele almak için, bilginin niteliğine uygun makul güvenlik önlemleriyle kullanılır.","Hiçbir cihazın, ağın veya elektronik saklama yönteminin tamamen güvenli olduğu garanti edilemez. Destek e-postasına konuyla ilgisiz hassas bilgiler eklemeyin."]},{"title":"8. Çocuklar ve gençler","paragraphs":["Uygulama hesap gerektirmez ve reklam ya da davranış analizi yoluyla çocukların veya diğer kullanıcıların profilini oluşturmaz. Bir çocuğun destek e-postasıyla kişisel bilgi gönderdiğini düşünen ebeveyn veya vasi, konunun ele alınması için bizimle iletişime geçebilir."]},{"title":"9. Seçimleriniz ve haklarınız","paragraphs":["Cihazdaki verileri cihazınız üzerinden siz yönetirsiniz. Mağaza hesaplarını ve satın alma kayıtlarını Apple veya Google yönetir. Uygulama, uygulama mağazasının tuttuğu işlem kayıtlarını sizin adınıza değiştiremez veya silemez.","Uygulamanın veri uygulamaları, platform kuralları veya web sitesi barındırması değişirse bu Politikayı ve sayfadaki tarihi günceller, geçerli kurallar gerektiriyorsa ek bildirim sağlarız.","Gizlilikle ilgili sorularınız için lütfen e-posta gönderin. {email}"]}]},"terms":{"title":"Kullanım Şartları","lead":"{appName} Kullanım Şartları.","sections":[{"title":"1. Bu Şartları ve platform kurallarını kabul etmek","paragraphs":["{appName} uygulamasını indirerek, satın alarak veya kullanarak bu Şartları ve satın alma işlemini gerçekleştirdiğiniz uygulama mağazasında sizin için geçerli olan kuralları kabul etmiş olursunuz. Kabul etmiyorsanız, uygulamayı kullanmaya veya satın alma işlemi yapmaya devam etmeyin.","Bu Koşullar uygulamanın indirilmesi, satın alınması ve kullanılması için geçerlidir. iOS ve iPadOS sürümleri ayrıca"],"links":["appleEula"]},{"title":"2. Ücretli ürünler ve fiyatlar","paragraphs":["Tanıma ve düzenlemede kullanım sınırı yoktur. Yalnızca işlenen görseli dışa aktarmak için geçerli Premium erişimi gerekir. Ücretsiz deneme olmadan otomatik yenilenen haftalık ve aylık abonelikler ile tek seferlik ömür boyu satın alma sunulur. App Store ve Google Play satın alımları ayrıdır ve platformlar arasında aktarılamaz.","Gerçek fiyat, para birimi, vergiler, faturalandırma dönemi ve satın alma uygunluğu, App Store veya Google Play sistem satın alma ekranında gösterilip onayladığınız bilgilerdir. Satın alma platformu ödemeyi mağaza hesabınız üzerinden tahsil eder ve yönetir. Uygulama ücretsiz abonelik denemesi veya başka ücretli plan sunmaz."]},{"title":"3. Otomatik yenileme ve iptal","paragraphs":["Haftalık ve aylık abonelikler otomatik yenilenir ve satın alma ekranında gösterilen dönem için, satın alma platformu üzerinden iptal edene kadar ücretlendirilir. {appName} uygulamasını silmek aboneliği otomatik olarak iptal etmez. Platform geri ödeme veya başka işlem sağlamazsa otomatik yenilemeyi kapattıktan sonra aboneliği ödenmiş dönemin sonuna kadar kullanabilirsiniz."],"links":["appleCancel","googleManage"]},{"title":"4. Satın alma, geri yükleme ve geri ödemeler","paragraphs":["Satın alma ve geri yükleme işlemleri resmi Apple veya Google mağazası üzerinden yapılır. Hak yalnızca mağaza geçerli bir işlemi doğruladıktan sonra verilir. İptal edilmiş, başarısız veya bekleyen işlemler başarıyla doğrulanmadan hak vermez. Satın alma geri yükleme, ömür boyu erişimi ve halen etkin aboneliği geri getirebilir. App Store ve Google Play satın almaları birbirinden bağımsızdır; platformlar arasında geri yüklenemez veya aktarılamaz.","Geri ödemeler, işlemi tamamlayan uygulama mağazası tarafından kendi kuralları, satın alma bölgesi ve geçerli yasalara göre ele alınır. Mağaza geri ödemeyi, iptali, aboneliğin bitmesini veya geçersiz işlemi doğruladığında ilgili hak kaldırılır."],"links":["appleRefund","googleRefund"]},{"title":"5. Çevrimdışı kullanım ve kullanılabilirlik","paragraphs":["Görsel seçimi, OCR, hassas içerik algılama, düzenleme ve dışa aktarma cihazınızda gerçekleştirilir. Uygulama bulut tabanlı görsel tanıma, bulut eşitleme veya hesap hizmeti sunmaz. Dışa aktarma sırasında yeni bir görsel oluşturulur ve kaldırılabilen özel meta veriler silinir. Geçici çalışma dosyaları başarılı kaydetme, düzenlemeden vazgeçme veya oturum sonrasında temizlenir; kaydetme başarısız olursa yeniden deneme için gerekli durum korunabilir."]},{"title":"6. Kabul edilebilir kullanım ve fikri mülkiyet","paragraphs":["Uygulamayı yasa dışı faaliyetler için kullanamaz, satın alma doğrulamasını atlatamaz, uygulamaya zarar veremez, kötü amaçlı kod dağıtamaz, izinsiz kopyalayamaz veya dağıtamaz ya da uygulama içeriğindeki hakları veya başkalarının fikri mülkiyetini ihlal edemezsiniz.","Uygulamayı kullanmayı istediğiniz zaman bırakıp kaldırabilirsiniz. Sorunları gidermek, işletim sistemlerini desteklemek, kararlılığı artırmak veya platform gereksinimlerini karşılamak için güncellemeler yayımlayabiliriz. Cihaz, sistem, ağ veya mağaza hizmeti sorunları bazı özellikleri geçici olarak kullanılamaz hâle getirebilir.","Geçerli yasaların izin verdiği ölçüde uygulama mevcut hâliyle sunulur. Bu Koşullar yasal olarak hariç tutulamayacak sorumluluğu hariç tutmaz veya zorunlu tüketici haklarınızı sınırlamaz.","Ürün özellikleri, ödeme yöntemleri, platform kuralları veya geçerli yasalar değişirse bu Koşulları ve sayfadaki tarihi güncelleyebiliriz. Değişiklik kullanıcı haklarını önemli ölçüde etkilerse gereken ek bildirimi sağlarız.","Bu Şartlar, satın alımlar veya uygulamanın kullanımıyla ilgili sorularınız için lütfen e-posta gönderin. {email}"]}]},"support":{"title":"Destek","lead":"Önce aşağıdaki sık sorulan sorulara bakın. Sorun sürerse destek e-posta adresinden bize ulaşın.","emailTitle":"{appName} destek e-postası","emailLead":"Önce aşağıdaki sık sorulan sorulara bakın. Sorun sürerse destek e-posta adresinden bize ulaşın.","beforeEmail":{"title":"E-postada belirtilecekler","paragraphs":["Satın alma sorununda uygulama mağazası sipariş numarasını verebilirsiniz; ancak hesap veya ödeme parolanızı ya da kart bilgilerinizin tamamını göndermeyin."],"bullets":["platformunuz, cihaz modeliniz, işletim sistemi sürümünüz ve uygulama sürümünüz;","sorundan önce yaptıklarınız, beklediğiniz sonuç ve gerçekleşen sonuç; ve","Gerekirse, özel bilgilerin gizlendiği bir ekran görüntüsü veya ekran kaydı gönderilebilir."]},"faqs":[{"question":"Görseller bir sunucuya yükleniyor mu?","answer":"Görsel seçimi, OCR, hassas içerik algılama, düzenleme ve dışa aktarma cihazınızda gerçekleştirilir. Uygulama bulut tabanlı görsel tanıma, bulut eşitleme veya hesap hizmeti sunmaz. Dışa aktarma sırasında yeni bir görsel oluşturulur ve kaldırılabilen özel meta veriler silinir. Geçici çalışma dosyaları başarılı kaydetme, düzenlemeden vazgeçme veya oturum sonrasında temizlenir; kaydetme başarısız olursa yeniden deneme için gerekli durum korunabilir."},{"question":"İzinler, reklam ve izleme","answer":"Fotoğraf erişimi yalnızca izin verdiğiniz görselleri göstermek ve işlemek için kullanılır. Kamera yalnızca uygulama içinde fotoğraf çekmeyi seçtiğinizde kullanılır. Fotoğraf arşivine kaydetme izni yalnızca geçerli Premium erişimiyle dışa aktarmayı onayladığınızda istenir. Uygulama konum, kişiler, mikrofon, Bluetooth veya bildirim izinleri istemez."},{"question":"Ücretli ürünler ve fiyatlar","answer":"Tanıma ve düzenlemede kullanım sınırı yoktur. Yalnızca işlenen görseli dışa aktarmak için geçerli Premium erişimi gerekir. Ücretsiz deneme olmadan otomatik yenilenen haftalık ve aylık abonelikler ile tek seferlik ömür boyu satın alma sunulur. App Store ve Google Play satın alımları ayrıdır ve platformlar arasında aktarılamaz."},{"question":"Kaydetme ve görsel biçimleri","answer":"Kaydetme başarısız olursa boş alanı, fotoğraf arşivine kaydetme iznini ve özgün görselin okunabildiğini kontrol edip yeniden deneyin. Uygulama her seferinde bir sabit görsel işler ve yaygın biçimlerin çoğunu destekler; bazı biçimler cihaza ve sistem sürümüne bağlıdır. Video, PDF, RAW/DNG ve toplu işleme şu anda desteklenmez."},{"question":"Dili nasıl değiştiririm?","answer":"Uygulama 40 dili destekler ve dil uygulama ayarlarından değiştirilebilir. Görünüm yanlışsa cihaz dilini ve uygulamada seçilen dili e-postada belirtin."},{"question":"Geri yükleme, iptal ve geri ödemeler","answer":"Satın alma ve geri yükleme işlemleri resmi Apple veya Google mağazası üzerinden yapılır. Hak yalnızca mağaza geçerli bir işlemi doğruladıktan sonra verilir. İptal edilmiş, başarısız veya bekleyen işlemler başarıyla doğrulanmadan hak vermez. Satın alma geri yükleme, ömür boyu erişimi ve halen etkin aboneliği geri getirebilir. App Store ve Google Play satın almaları birbirinden bağımsızdır; platformlar arasında geri yüklenemez veya aktarılamaz."},{"question":"Gizlilik ve veri silme","answer":"Cihazdaki verileri silmek için uygulamayı kaldırın. Android’de sistemin “Verileri temizle” seçeneğini de kullanabilirsiniz. Satın alma kayıtları Apple veya Google tarafından yönetilir. Geri yüklenebilir haklar mağaza kurallarına göre yeniden doğrulanır. Destek e-postaları, talebi ele almak ve gerekli kayıt tutma yükümlülüklerini karşılamak için gereken süre boyunca saklanır. Hâlâ tuttuğumuz destek yazışmalarının silinmesini e-postayla isteyebilirsiniz."}],"officialHelpTitle":"Hızlı yardım"}},"uk":{"linkLabels":{"appleEula":"Стандартна ліцензійна угода Apple із кінцевим користувачем (EULA)","appleCancel":"Інструкції щодо скасування підписки Apple","googleManage":"Інструкції зі скасування в Google Play","appleRefund":"Запит на повернення коштів від Apple","googleRefund":"Інформація про повернення коштів Google Play"},"nav":{"privacy":"Політика конфіденційності","terms":"Умови використання","support":"Підтримка","language":"Мова","chooseLanguage":"Виберіть мову відображення","navigationLabel":"Основна навігація"},"home":{"eyebrow":"{appName} · Privacy first","title":"Ваші зображення не завантажуються на наші сервери.","lead":"Вибір зображень, OCR, виявлення конфіденційного вмісту, редагування та експорт виконуються на пристрої. Застосунок не пропонує хмарного розпізнавання зображень, хмарної синхронізації чи облікових записів. Під час експорту створюється нове зображення та видаляються приватні метадані, які можна вилучити. Тимчасові робочі файли видаляються після успішного збереження, відмови від редагування або завершення сеансу; якщо збереження не вдалося, стан для повторної спроби може бути збережено.","points":["Дані застосунку","Платні продукти та ціни","Підтримка"],"cards":[{"title":"Політика конфіденційності","description":"Ваші зображення не завантажуються на наші сервери.","action":"Політика конфіденційності"},{"title":"Умови використання","description":"Розпізнавання та редагування не мають лімітів використання. Чинний Premium потрібен лише для експорту обробленого зображення. Доступні автоматично поновлювані тижнева й місячна підписки та одноразова довічна покупка без безкоштовного пробного періоду. Покупки в App Store і Google Play незалежні та не переносяться між платформами.","action":"Умови використання"},{"title":"Потрібна допомога?","description":"Спочатку перегляньте поширені запитання нижче. Якщо проблема залишається, напишіть на адресу підтримки.","action":"Підтримка"}]},"footer":{"privacy":"Політика конфіденційності","terms":"Умови використання","support":"Підтримка"},"privacy":{"title":"Політика конфіденційності","lead":"Ця Політика пояснює, як {appName} обробляє дані на пристрої, відомості про покупки в магазині та листи до підтримки.","sections":[{"title":"1. Сфера застосування та контакти","paragraphs":["Ця Політика стосується застосунку {appName} для iOS, iPadOS і Android, а також цього сайту про конфіденційність, умови та підтримку.","З питань конфіденційності пишіть на електронну пошту {email}"]},{"title":"2. Дані застосунку","callout":{"title":"Ваші зображення не завантажуються на наші сервери.","body":"Вибір зображень, OCR, виявлення конфіденційного вмісту, редагування та експорт виконуються на пристрої. Застосунок не пропонує хмарного розпізнавання зображень, хмарної синхронізації чи облікових записів. Під час експорту створюється нове зображення та видаляються приватні метадані, які можна вилучити. Тимчасові робочі файли видаляються після успішного збереження, відмови від редагування або завершення сеансу; якщо збереження не вдалося, стан для повторної спроби може бути збережено."},"paragraphs":[]},{"title":"3. Дозволи, реклама та відстеження","paragraphs":["Доступ до фотографій використовується лише для показу й обробки дозволених вами зображень. Камера використовується тільки коли ви обираєте зйомку в застосунку. Дозвіл на збереження до фототеки запитується лише під час підтвердження експорту з чинним Premium. Застосунок не запитує геопозицію, контакти, мікрофон, Bluetooth чи сповіщення.","Він не використовує рекламний ідентифікатор і не підключає сторонні SDK для реклами, аналітики, атрибуції або звітів про збої.","Застосунок не підключає сторонній інструмент звітів про збої. Залежно від налаштувань пристрою та магазину Apple або Google може обробляти системні діагностичні відомості за власними правилами конфіденційності й надавати технічні дані для вивчення збоїв або проблем продуктивності."]},{"title":"4. Сервіси магазину та доступ до мережі","paragraphs":["Застосунок використовує Apple StoreKit або Google Play Billing для завантаження товарів, показу локальних цін від магазину, здійснення й відновлення покупок, керування підписками та підтвердження прав. Доступ до мережі використовується лише для цих офіційних функцій магазинів Apple або Google.","Apple або Google відповідає за облікові записи магазину, платежі, виставлення рахунків, транзакції, повернення коштів і підписки. Застосунок обробляє лише відомості магазину, потрібні для підтвердження товарів і прав, та не отримує й не зберігає повні платіжні дані."]},{"title":"5. Листи до підтримки та сайт","paragraphs":["Застосунок не читає дані вашої електронної пошти автоматично. Лише коли ви надсилаєте лист до підтримки, канал підтримки отримує вашу адресу, повідомлення та добровільно додані знімки чи записи екрана, номер замовлення або інші вкладення. Ці відомості використовуються тільки для опрацювання запиту, а не для реклами чи маркетингу. Не надсилайте паролі облікового запису або платежу й повні номери карток.","Цей сайт не встановлює рекламні чи аналітичні файли cookie та не містить скриптів аналізу відвідувань або відстеження."]},{"title":"6. Зберігання та видалення","paragraphs":["Щоб видалити дані з пристрою, видаліть застосунок. На Android також можна скористатися системною функцією «Очистити дані».","Записи про покупки керуються Apple або Google. Права, які можна відновити, повторно підтверджуються за правилами магазину.","Листи до підтримки зберігаються стільки, скільки потрібно для опрацювання запиту та виконання необхідних вимог до обліку. Ви можете попросити електронною поштою видалити листування з підтримкою, яке ми ще зберігаємо."]},{"title":"7. Безпека даних","paragraphs":["Застосунок використовує обробку на пристрої, мінімальні дозволи й офіційні процеси покупки в магазинах, щоб зменшити зайву передачу даних. Листи до підтримки використовуються лише для опрацювання звернень і захищаються розумними заходами, що відповідають характеру відомостей.","Неможливо гарантувати абсолютну безпеку пристрою, мережі чи електронного способу зберігання. Не додавайте до листа в підтримку конфіденційні відомості, які не стосуються питання."]},{"title":"8. Діти та підлітки","paragraphs":["Застосунок не вимагає облікового запису й не створює профілі дітей або інших користувачів за допомогою реклами чи поведінкової аналітики. Батьки або опікуни, які вважають, що дитина надіслала персональні дані в листі до підтримки, можуть звернутися до нас для розв’язання питання."]},{"title":"9. Ваш вибір і права","paragraphs":["Ви керуєте локальними даними через пристрій. Apple або Google керує обліковими записами магазину й записами покупок. Застосунок не може від вашого імені змінити чи видалити записи транзакцій, які зберігає магазин.","Якщо зміняться способи обробки даних застосунком, правила платформ або розміщення сайту, ми оновимо цю Політику й дату на сторінці та надамо додаткове повідомлення, якщо цього вимагають застосовні правила.","З питань конфіденційності пишіть на електронну пошту {email}"]}]},"terms":{"title":"Умови використання","lead":"Умови використання {appName}.","sections":[{"title":"1. Прийняття цих Умов та правил платформи","paragraphs":["Завантажуючи, купуючи або використовуючи {appName}, ви погоджуєтеся з цими Умовами та правилами, що застосовуються до вас у магазині додатків, де ви здійснюєте покупку. Якщо ви не погоджуєтеся, не продовжуйте використовувати додаток або здійснювати покупку.","Ці Умови стосуються завантаження, покупки й використання застосунку. До версій для iOS та iPadOS також застосовується"],"links":["appleEula"]},{"title":"2. Платні продукти та ціни","paragraphs":["Розпізнавання та редагування не мають лімітів використання. Чинний Premium потрібен лише для експорту обробленого зображення. Доступні автоматично поновлювані тижнева й місячна підписки та одноразова довічна покупка без безкоштовного пробного періоду. Покупки в App Store і Google Play незалежні та не переносяться між платформами.","Фактична ціна, валюта, податки, розрахунковий період і можливість покупки відповідають відомостям, показаним і підтвердженим на системному екрані покупки App Store або Google Play. Платформа списує платіж через ваш обліковий запис магазину й керує ним. Застосунок не пропонує безкоштовний пробний період підписки або інші платні плани."]},{"title":"3. Автоматичне поновлення та скасування","paragraphs":["Тижнева й місячна підписки поновлюються автоматично й оплачуються за період, указаний на системному екрані покупки, доки ви не скасуєте їх через платформу покупки. Видалення {appName} не скасовує підписку автоматично. Якщо платформа не оформить повернення коштів або інше рішення, після вимкнення автоматичного поновлення підпискою можна користуватися до кінця вже оплаченого періоду."],"links":["appleCancel","googleManage"]},{"title":"4. Покупки, відновлення та повернення коштів","paragraphs":["Покупки та їх відновлення виконуються через офіційний магазин Apple або Google. Право надається лише після підтвердження чинної транзакції магазином. Скасовані, невдалі або очікувані транзакції не дають права до успішного підтвердження. Відновлення покупок може повернути довічний доступ і чинну підписку. Покупки в App Store та Google Play незалежні, і їх не можна відновлювати або переносити між платформами.","Повернення коштів обробляє магазин, який завершив транзакцію, згідно зі своїми правилами, регіоном покупки та застосовним законодавством. Відповідне право видаляється після підтвердження магазином повернення, відкликання, завершення підписки або недійсної транзакції."],"links":["appleRefund","googleRefund"]},{"title":"5. Використання офлайн і доступність","paragraphs":["Вибір зображень, OCR, виявлення конфіденційного вмісту, редагування та експорт виконуються на пристрої. Застосунок не пропонує хмарного розпізнавання зображень, хмарної синхронізації чи облікових записів. Під час експорту створюється нове зображення та видаляються приватні метадані, які можна вилучити. Тимчасові робочі файли видаляються після успішного збереження, відмови від редагування або завершення сеансу; якщо збереження не вдалося, стан для повторної спроби може бути збережено."]},{"title":"6. Допустиме використання та інтелектуальна власність","paragraphs":["Заборонено використовувати застосунок для незаконної діяльності, обходити перевірку покупок, пошкоджувати застосунок, поширювати шкідливий код, копіювати або поширювати застосунок без дозволу чи порушувати права на матеріали застосунку або інтелектуальну власність інших осіб.","Ви можете припинити використання й видалити застосунок у будь-який час. Ми можемо випускати оновлення для виправлення проблем, підтримки систем, підвищення стабільності або дотримання вимог платформ. Проблеми пристрою, системи, мережі чи сервісу магазину можуть тимчасово зробити окремі функції недоступними.","У межах, дозволених застосовним законодавством, застосунок надається в доступному стані. Ці Умови не виключають відповідальність, яку не можна законно виключити, і не обмежують обов’язкові права споживачів.","Якщо зміняться функції, способи оплати, правила платформ або застосовне законодавство, ми можемо оновити ці Умови й дату на сторінці. Якщо зміна істотно впливає на права користувачів, ми надамо потрібне додаткове повідомлення.","Якщо у вас є запитання щодо цих Умов, покупок або використання програми, надсилайте електронні листи на адресу {email}"]}]},"support":{"title":"Підтримка","lead":"Спочатку перегляньте поширені запитання нижче. Якщо проблема залишається, напишіть на адресу підтримки.","emailTitle":"Електронна адреса служби підтримки {appName}","emailLead":"Спочатку перегляньте поширені запитання нижче. Якщо проблема залишається, напишіть на адресу підтримки.","beforeEmail":{"title":"Що вказати в листі","paragraphs":["Щодо покупки можна вказати номер замовлення магазину, але не надсилайте пароль облікового запису або платежу й повні дані картки."],"bullets":["платформу, модель пристрою, версію системи та версію застосунку;","дії перед виникненням проблеми, очікуваний і фактичний результат; та","за потреби, скріншот або запис екрана з прихованою приватною інформацією."]},"faqs":[{"question":"Чи завантажуються зображення на сервер?","answer":"Вибір зображень, OCR, виявлення конфіденційного вмісту, редагування та експорт виконуються на пристрої. Застосунок не пропонує хмарного розпізнавання зображень, хмарної синхронізації чи облікових записів. Під час експорту створюється нове зображення та видаляються приватні метадані, які можна вилучити. Тимчасові робочі файли видаляються після успішного збереження, відмови від редагування або завершення сеансу; якщо збереження не вдалося, стан для повторної спроби може бути збережено."},{"question":"Дозволи, реклама та відстеження","answer":"Доступ до фотографій використовується лише для показу й обробки дозволених вами зображень. Камера використовується тільки коли ви обираєте зйомку в застосунку. Дозвіл на збереження до фототеки запитується лише під час підтвердження експорту з чинним Premium. Застосунок не запитує геопозицію, контакти, мікрофон, Bluetooth чи сповіщення."},{"question":"Платні продукти та ціни","answer":"Розпізнавання та редагування не мають лімітів використання. Чинний Premium потрібен лише для експорту обробленого зображення. Доступні автоматично поновлювані тижнева й місячна підписки та одноразова довічна покупка без безкоштовного пробного періоду. Покупки в App Store і Google Play незалежні та не переносяться між платформами."},{"question":"Збереження та формати зображень","answer":"Якщо збереження не вдалося, перевірте вільне місце, дозвіл на збереження до фототеки та доступність оригінального зображення, а потім повторіть спробу. Застосунок обробляє по одному статичному зображенню та підтримує більшість поширених форматів; деякі залежать від пристрою й версії системи. Відео, PDF, RAW/DNG і пакетна обробка наразі не підтримуються."},{"question":"Як змінити мову?","answer":"Застосунок підтримує 40 мов, які можна вибрати в налаштуваннях. Якщо мова відображається неправильно, укажіть у листі мову пристрою та мову, вибрану в застосунку."},{"question":"Відновлення, скасування та повернення коштів","answer":"Покупки та їх відновлення виконуються через офіційний магазин Apple або Google. Право надається лише після підтвердження чинної транзакції магазином. Скасовані, невдалі або очікувані транзакції не дають права до успішного підтвердження. Відновлення покупок може повернути довічний доступ і чинну підписку. Покупки в App Store та Google Play незалежні, і їх не можна відновлювати або переносити між платформами."},{"question":"Конфіденційність і видалення даних","answer":"Щоб видалити дані з пристрою, видаліть застосунок. На Android також можна скористатися системною функцією «Очистити дані». Записи про покупки керуються Apple або Google. Права, які можна відновити, повторно підтверджуються за правилами магазину. Листи до підтримки зберігаються стільки, скільки потрібно для опрацювання запиту та виконання необхідних вимог до обліку. Ви можете попросити електронною поштою видалити листування з підтримкою, яке ми ще зберігаємо."}],"officialHelpTitle":"Швидка допомога"}},"ur":{"linkLabels":{"appleEula":"Apple کا معیاری آخری صارف لائسنس معاہدہ (EULA)","appleCancel":"ایپل کی رکنیت منسوخی کی ہدایات","googleManage":"Google Play منسوخی کی ہدایات","appleRefund":"ایپل سے رقم کی واپسی کی درخواست کریں۔","googleRefund":"Google Play رقم کی واپسی کی معلومات"},"nav":{"privacy":"رازداری کی پالیسی","terms":"استعمال کی شرائط","support":"معاونت","language":"زبان","chooseLanguage":"ڈسپلے کی زبان منتخب کریں۔","navigationLabel":"بنیادی نیویگیشن"},"home":{"eyebrow":"{appName} · Privacy first","title":"آپ کی تصاویر ہمارے سرورز پر اپ لوڈ نہیں کی جاتیں۔","lead":"تصویر کا انتخاب، OCR، حساس مواد کی شناخت، ترمیم اور برآمد آلے پر ہی ہوتی ہے۔ ایپ کلاؤڈ تصویر شناخت، کلاؤڈ ہم وقت سازی یا اکاؤنٹ فراہم نہیں کرتی۔ برآمد کرتے وقت نئی تصویر بنتی ہے اور حذف کیے جا سکنے والے نجی میٹا ڈیٹا کو ہٹا دیا جاتا ہے۔ کامیاب محفوظ کاری، ترمیم چھوڑنے یا سیشن ختم ہونے کے بعد عارضی فائلیں حذف ہو جاتی ہیں؛ محفوظ کاری ناکام ہو تو دوبارہ کوشش کے لیے ضروری حالت رکھی جا سکتی ہے۔","points":["ایپ ڈیٹا","بامعاوضہ مصنوعات اور قیمتیں","معاونت"],"cards":[{"title":"رازداری کی پالیسی","description":"آپ کی تصاویر ہمارے سرورز پر اپ لوڈ نہیں کی جاتیں۔","action":"رازداری کی پالیسی"},{"title":"استعمال کی شرائط","description":"شناخت اور ترمیم کے استعمال کی کوئی حد نہیں۔ پراسیس شدہ تصویر برآمد کرنے کے لیے ہی درست Premium درکار ہے۔ مفت آزمائش کے بغیر خودکار تجدید والی ہفتہ وار اور ماہانہ رکنیتیں اور ایک بار کی تاحیات خرید دستیاب ہے۔ App Store اور Google Play کی خریداریاں الگ ہیں اور پلیٹ فارموں کے درمیان منتقل نہیں ہو سکتیں۔","action":"استعمال کی شرائط"},{"title":"مدد کی ضرورت ہے؟","description":"پہلے ذیل کے عام سوالات دیکھیں۔ اگر مسئلہ برقرار رہے تو معاونتی ای میل پتے کے ذریعے ہم سے رابطہ کریں۔","action":"معاونت"}]},"footer":{"privacy":"رازداری کی پالیسی","terms":"استعمال کی شرائط","support":"معاونت"},"privacy":{"title":"رازداری کی پالیسی","lead":"یہ پالیسی وضاحت کرتی ہے کہ {appName} ڈیوائس پر موجود ڈیٹا، ایپ اسٹور کی خریداری کی معلومات اور معاونتی ای میلز کو کیسے سنبھالتا ہے۔","sections":[{"title":"1. دائرہ کار اور رابطہ","paragraphs":["یہ پالیسی iOS، iPadOS اور Android کے لیے {appName} ایپ اور اس رازداری، شرائط اور معاونت کی ویب سائٹ پر لاگو ہوتی ہے۔","رازداری کے سوالات کے لیے، ای میل کریں۔ {email}"]},{"title":"2. ایپ ڈیٹا","callout":{"title":"آپ کی تصاویر ہمارے سرورز پر اپ لوڈ نہیں کی جاتیں۔","body":"تصویر کا انتخاب، OCR، حساس مواد کی شناخت، ترمیم اور برآمد آلے پر ہی ہوتی ہے۔ ایپ کلاؤڈ تصویر شناخت، کلاؤڈ ہم وقت سازی یا اکاؤنٹ فراہم نہیں کرتی۔ برآمد کرتے وقت نئی تصویر بنتی ہے اور حذف کیے جا سکنے والے نجی میٹا ڈیٹا کو ہٹا دیا جاتا ہے۔ کامیاب محفوظ کاری، ترمیم چھوڑنے یا سیشن ختم ہونے کے بعد عارضی فائلیں حذف ہو جاتی ہیں؛ محفوظ کاری ناکام ہو تو دوبارہ کوشش کے لیے ضروری حالت رکھی جا سکتی ہے۔"},"paragraphs":[]},{"title":"3. اجازتیں، اشتہارات اور ٹریکنگ","paragraphs":["تصاویر تک رسائی صرف ان تصاویر کو دکھانے اور پراسیس کرنے کے لیے استعمال ہوتی ہے جن کی آپ اجازت دیں۔ کیمرا صرف اس وقت استعمال ہوتا ہے جب آپ ایپ میں تصویر لینے کا انتخاب کریں۔ فوٹو لائبریری میں محفوظ کرنے کی اجازت صرف درست Premium کے ساتھ برآمد کی تصدیق پر مانگی جاتی ہے۔ ایپ مقام، رابطوں، مائیکروفون، Bluetooth یا اطلاعات کی اجازت نہیں مانگتی۔","یہ اشتہاری شناخت کنندہ استعمال نہیں کرتی اور اشتہارات، تجزیات، انتساب یا کریش رپورٹنگ کے لیے فریق ثالث SDK شامل نہیں کرتی۔","ایپ فریق ثالث کا کریش رپورٹنگ ٹول شامل نہیں کرتی۔ آپ کی ڈیوائس اور اسٹور کی ترتیبات کے لحاظ سے Apple یا Google اپنے متعلقہ رازداری کے اصولوں کے تحت سسٹم تشخیصی معلومات پر کارروائی کر سکتا ہے اور کریش یا کارکردگی کے مسائل کی تفتیش کے لیے استعمال ہونے والی تکنیکی معلومات فراہم کر سکتا ہے۔"]},{"title":"4. ایپ اسٹور خدمات اور نیٹ ورک رسائی","paragraphs":["ایپ مصنوعات لوڈ کرنے، اسٹور سے موصول مقامی قیمتیں دکھانے، خریداری مکمل کرنے، خریداری بحال کرنے، سبسکرپشنز کا نظم کرنے اور استحقاقات کی تصدیق کے لیے Apple StoreKit یا Google Play Billing استعمال کرتی ہے۔ نیٹ ورک رسائی صرف Apple یا Google کی ان سرکاری اسٹور سہولیات کے لیے استعمال ہوتی ہے۔","اسٹور اکاؤنٹس، ادائیگیوں، بلنگ، لین دین، رقم کی واپسی اور سبسکرپشن خدمات کی ذمہ داری Apple یا Google کی ہے۔ ایپ صرف مصنوعات اور استحقاقات کی تصدیق کے لیے ضروری اسٹور معلومات پر کارروائی کرتی ہے اور ادائیگی کی مکمل اسناد وصول یا محفوظ نہیں کرتی۔"]},{"title":"5. معاونتی ای میلز اور ویب سائٹ","paragraphs":["ایپ آپ کی ای میل کی معلومات خودکار طور پر نہیں پڑھتی۔ صرف جب آپ معاونتی ای میل بھیجنے کا انتخاب کرتے ہیں، معاونتی ذریعے کو آپ کا ای میل پتہ، پیغام اور آپ کی رضاکارانہ طور پر فراہم کردہ اسکرین شاٹ، اسکرین ریکارڈنگ، آرڈر نمبر یا دوسری منسلکہ فائل موصول ہوتی ہے۔ یہ معلومات صرف آپ کی درخواست سنبھالنے کے لیے استعمال ہوتی ہے، اشتہار یا مارکیٹنگ کے لیے نہیں۔ اکاؤنٹ یا ادائیگی کے پاس ورڈ یا کارڈ کے مکمل نمبر نہ بھیجیں۔","یہ ویب سائٹ اشتہاری یا تجزیاتی کوکیز مقرر نہیں کرتی اور اس میں ٹریفک تجزیات یا ٹریکنگ اسکرپٹس شامل نہیں ہیں۔"]},{"title":"6. برقرار رکھنا اور حذف کرنا","paragraphs":["ایپ ان انسٹال کر کے ڈیوائس پر موجود ڈیٹا حذف کریں۔ Android پر آپ سسٹم کا ڈیٹا صاف کریں اختیار بھی استعمال کر سکتے ہیں۔","اسٹور خریداری کے ریکارڈ Apple یا Google کے زیر انتظام ہیں۔ بحال کیے جا سکنے والے استحقاقات کی اسٹور کے اصولوں کے تحت دوبارہ تصدیق ہوتی ہے۔","معاونتی ای میلز درخواست سنبھالنے اور ضروری ریکارڈ رکھنے کی شرائط پوری کرنے کے لیے جتنی مدت درکار ہو اتنی مدت رکھی جاتی ہیں۔ آپ ہمارے پاس اب بھی موجود معاونتی خط و کتابت حذف کرنے کی درخواست ای میل کے ذریعے کر سکتے ہیں۔"]},{"title":"7. ڈیٹا کی سلامتی","paragraphs":["ایپ غیر ضروری ڈیٹا منتقلی کم کرنے کے لیے ڈیوائس پر کارروائی، کم سے کم اجازتوں اور ایپ اسٹور کے سرکاری خریداری کے طریقوں کا استعمال کرتی ہے۔ معاونتی ای میلز صرف موصول ہونے والی درخواستیں سنبھالنے کے لیے استعمال ہوتی ہیں اور معلومات کی نوعیت کے مطابق مناسب حفاظتی اقدامات اپنائے جاتے ہیں۔","کسی ڈیوائس، نیٹ ورک یا الیکٹرانک ذخیرے کے طریقے کے مکمل طور پر محفوظ ہونے کی ضمانت نہیں دی جا سکتی۔ معاونتی ای میل میں غیر متعلق حساس معلومات شامل نہ کریں۔"]},{"title":"8. بچے اور نوعمر افراد","paragraphs":["ایپ کو اکاؤنٹ درکار نہیں اور یہ اشتہار یا رویّے کے تجزیے کے ذریعے بچوں یا دوسرے صارفین کی پروفائلز نہیں بناتی۔ والدین یا سرپرست جو سمجھتے ہوں کہ بچے نے معاونتی ای میل کے ذریعے ذاتی معلومات فراہم کی ہیں، معاملے کے حل کے لیے ہم سے رابطہ کر سکتے ہیں۔"]},{"title":"9. آپ کے انتخابات اور حقوق","paragraphs":["آپ اپنی ڈیوائس کے ذریعے ڈیوائس پر موجود ڈیٹا کا نظم کرتے ہیں۔ Apple یا Google اسٹور اکاؤنٹس اور خریداری کے ریکارڈز کا نظم کرتا ہے۔ ایپ آپ کی جانب سے ایپ اسٹور کے پاس موجود لین دین کے ریکارڈز میں تبدیلی یا انہیں حذف نہیں کر سکتی۔","اگر ایپ کے ڈیٹا کے طریقے، پلیٹ فارم کے اصول یا ویب سائٹ ہوسٹنگ کے انتظامات بدلتے ہیں تو ہم اس پالیسی اور اس صفحے پر دکھائی گئی تاریخ کو اپ ڈیٹ کریں گے اور قابل اطلاق اصولوں کی ضرورت کے مطابق اضافی اطلاع دیں گے۔","رازداری کے سوالات کے لیے، ای میل کریں۔ {email}"]}]},"terms":{"title":"استعمال کی شرائط","lead":"{appName} استعمال کی شرائط۔","sections":[{"title":"1. ان شرائط اور پلیٹ فارم کے قواعد کو قبول کرنا","paragraphs":["{appName} کو ڈاؤن لوڈ کرکے، خرید کر، یا استعمال کرکے، آپ ان شرائط اور ان قواعد سے اتفاق کرتے ہیں جو ایپ اسٹور میں آپ پر لاگو ہوتے ہیں جہاں آپ خریداری کرتے ہیں۔ اگر آپ متفق نہیں ہیں تو ایپ کا استعمال جاری رکھیں یا خریداری نہ کریں۔","یہ شرائط آپ کے ایپ ڈاؤن لوڈ کرنے، خریدنے اور استعمال کرنے پر لاگو ہوتی ہیں۔ iOS اور iPadOS ورژنز پر یہ بھی لاگو ہوتا ہے:"],"links":["appleEula"]},{"title":"2. بامعاوضہ مصنوعات اور قیمتیں","paragraphs":["شناخت اور ترمیم کے استعمال کی کوئی حد نہیں۔ پراسیس شدہ تصویر برآمد کرنے کے لیے ہی درست Premium درکار ہے۔ مفت آزمائش کے بغیر خودکار تجدید والی ہفتہ وار اور ماہانہ رکنیتیں اور ایک بار کی تاحیات خرید دستیاب ہے۔ App Store اور Google Play کی خریداریاں الگ ہیں اور پلیٹ فارموں کے درمیان منتقل نہیں ہو سکتیں۔","اصل قیمت، کرنسی، ٹیکس، بلنگ کی مدت اور خریداری کی اہلیت وہ معلومات ہیں جو App Store یا Google Play کی سسٹم خریداری اسکرین پر دکھائی اور تصدیق کی جاتی ہیں۔ خریداری کا پلیٹ فارم آپ کے اسٹور اکاؤنٹ کے ذریعے رقم وصول اور ادائیگی کا نظم کرتا ہے۔ ایپ سبسکرپشن کی مفت آزمائش یا کوئی دوسری بامعاوضہ اسکیم پیش نہیں کرتی۔"]},{"title":"3. خودکار تجدید اور منسوخی","paragraphs":["ہفتہ وار اور ماہانہ سبسکرپشنز خودکار طور پر تجدید ہوتی ہیں اور سسٹم خریداری اسکرین پر دکھائی گئی بلنگ کی مدت کے لیے اس وقت تک رقم وصول کی جاتی ہے جب تک آپ خریداری کے پلیٹ فارم کے ذریعے انہیں منسوخ نہ کریں۔ {appName} حذف کرنے سے سبسکرپشن خودکار طور پر منسوخ نہیں ہوتی۔ جب تک خریداری کا پلیٹ فارم رقم واپس یا کوئی دوسری کارروائی نہ کرے، خودکار تجدید بند کرنے کے بعد آپ موجودہ بامعاوضہ مدت کے اختتام تک سبسکرپشن استعمال کر سکتے ہیں۔"],"links":["appleCancel","googleManage"]},{"title":"4. خریداریاں، بحالی اور رقم کی واپسی","paragraphs":["خریداری اور خریداری کی بحالی Apple یا Google کے سرکاری اسٹور کے ذریعے مکمل ہوتی ہے۔ اسٹور کے درست لین دین کی تصدیق کرنے کے بعد ہی استحقاق دیا جاتا ہے۔ منسوخ، ناکام یا زیر التوا لین دین کامیاب تصدیق سے پہلے استحقاق نہیں دیتے۔ خریداری کی بحالی تاحیات رسائی اور فی الحال فعال سبسکرپشن بحال کر سکتی ہے۔ App Store اور Google Play کی خریداریاں الگ ہیں اور انہیں مختلف پلیٹ فارمز کے درمیان بحال یا منتقل نہیں کیا جا سکتا۔","رقم کی واپسی اس ایپ اسٹور کے ذریعے اس کے اصولوں، خریداری کے علاقے اور قابل اطلاق قانون کے مطابق سنبھالی جاتی ہے جس نے لین دین مکمل کیا تھا۔ اسٹور کے رقم کی واپسی، منسوخی، سبسکرپشن کی میعاد ختم ہونے یا غیر درست لین دین کی تصدیق کے بعد متعلقہ استحقاق ہٹا دیا جاتا ہے۔"],"links":["appleRefund","googleRefund"]},{"title":"5. آف لائن استعمال اور دستیابی","paragraphs":["تصویر کا انتخاب، OCR، حساس مواد کی شناخت، ترمیم اور برآمد آلے پر ہی ہوتی ہے۔ ایپ کلاؤڈ تصویر شناخت، کلاؤڈ ہم وقت سازی یا اکاؤنٹ فراہم نہیں کرتی۔ برآمد کرتے وقت نئی تصویر بنتی ہے اور حذف کیے جا سکنے والے نجی میٹا ڈیٹا کو ہٹا دیا جاتا ہے۔ کامیاب محفوظ کاری، ترمیم چھوڑنے یا سیشن ختم ہونے کے بعد عارضی فائلیں حذف ہو جاتی ہیں؛ محفوظ کاری ناکام ہو تو دوبارہ کوشش کے لیے ضروری حالت رکھی جا سکتی ہے۔"]},{"title":"6. قابل قبول استعمال اور دانشورانہ ملکیت","paragraphs":["آپ ایپ کو غیر قانونی سرگرمی کے لیے استعمال نہیں کر سکتے؛ خریداری کی تصدیق سے گریز نہیں کر سکتے؛ ایپ کو نقصان نہیں پہنچا سکتے؛ نقصان دہ کوڈ تقسیم نہیں کر سکتے؛ اجازت کے بغیر ایپ نقل یا تقسیم نہیں کر سکتے؛ یا ایپ کے مواد کے حقوق یا کسی دوسرے شخص کی دانشورانہ ملکیت کی خلاف ورزی نہیں کر سکتے۔","آپ کسی بھی وقت ایپ کا استعمال بند کر کے اسے ان انسٹال کر سکتے ہیں۔ ہم مسائل حل کرنے، آپریٹنگ سسٹمز کی معاونت، استحکام بہتر کرنے یا پلیٹ فارم کی ضروریات پوری کرنے کے لیے اپ ڈیٹس جاری کر سکتے ہیں۔ ڈیوائس، سسٹم، نیٹ ورک یا اسٹور سروس کے مسائل کچھ خصوصیات کو عارضی طور پر غیر دستیاب بنا سکتے ہیں۔","قابل اطلاق قانون کی اجازت کی حد تک، ایپ دستیابی کے مطابق فراہم کی جاتی ہے۔ یہ شرائط ایسی ذمہ داری کو خارج نہیں کرتیں جسے قانونی طور پر خارج نہیں کیا جا سکتا اور آپ کو دستیاب لازمی صارف حقوق کو محدود نہیں کرتیں۔","اگر مصنوعات کی خصوصیات، ادائیگی کے طریقے، پلیٹ فارم کے اصول یا قابل اطلاق قانون بدلتے ہیں تو ہم ان شرائط اور صفحے پر دکھائی گئی تاریخ کو اپ ڈیٹ کر سکتے ہیں۔ اگر کوئی تبدیلی صارفین کے حقوق کو نمایاں طور پر متاثر کرتی ہے تو ہم ضرورت کے مطابق اضافی اطلاع دیں گے۔","ان شرائط، خریداریوں یا ایپ کے استعمال کے بارے میں سوالات کے لیے ای میل کریں۔ {email}"]}]},"support":{"title":"معاونت","lead":"پہلے ذیل کے عام سوالات دیکھیں۔ اگر مسئلہ برقرار رہے تو معاونتی ای میل پتے کے ذریعے ہم سے رابطہ کریں۔","emailTitle":"{appName} سپورٹ ای میل","emailLead":"پہلے ذیل کے عام سوالات دیکھیں۔ اگر مسئلہ برقرار رہے تو معاونتی ای میل پتے کے ذریعے ہم سے رابطہ کریں۔","beforeEmail":{"title":"اپنی ای میل میں کیا شامل کریں","paragraphs":["خریداری کے مسئلے کے لیے آپ ایپ اسٹور آرڈر نمبر شامل کر سکتے ہیں، لیکن اکاؤنٹ یا ادائیگی کا پاس ورڈ یا کارڈ کی مکمل معلومات نہ بھیجیں۔"],"bullets":["اپنا پلیٹ فارم، ڈیوائس ماڈل، آپریٹنگ سسٹم ورژن اور ایپ ورژن؛","مسئلے سے پہلے آپ نے کیا کیا، آپ کو کیا توقع تھی اور دراصل کیا ہوا؛ اور","اگر ضرورت ہو تو، خفیہ معلومات کے ساتھ اسکرین شاٹ یا اسکرین ریکارڈنگ۔"]},"faqs":[{"question":"کیا تصاویر کسی سرور پر اپ لوڈ ہوتی ہیں؟","answer":"تصویر کا انتخاب، OCR، حساس مواد کی شناخت، ترمیم اور برآمد آلے پر ہی ہوتی ہے۔ ایپ کلاؤڈ تصویر شناخت، کلاؤڈ ہم وقت سازی یا اکاؤنٹ فراہم نہیں کرتی۔ برآمد کرتے وقت نئی تصویر بنتی ہے اور حذف کیے جا سکنے والے نجی میٹا ڈیٹا کو ہٹا دیا جاتا ہے۔ کامیاب محفوظ کاری، ترمیم چھوڑنے یا سیشن ختم ہونے کے بعد عارضی فائلیں حذف ہو جاتی ہیں؛ محفوظ کاری ناکام ہو تو دوبارہ کوشش کے لیے ضروری حالت رکھی جا سکتی ہے۔"},{"question":"اجازتیں، اشتہارات اور ٹریکنگ","answer":"تصاویر تک رسائی صرف ان تصاویر کو دکھانے اور پراسیس کرنے کے لیے استعمال ہوتی ہے جن کی آپ اجازت دیں۔ کیمرا صرف اس وقت استعمال ہوتا ہے جب آپ ایپ میں تصویر لینے کا انتخاب کریں۔ فوٹو لائبریری میں محفوظ کرنے کی اجازت صرف درست Premium کے ساتھ برآمد کی تصدیق پر مانگی جاتی ہے۔ ایپ مقام، رابطوں، مائیکروفون، Bluetooth یا اطلاعات کی اجازت نہیں مانگتی۔"},{"question":"بامعاوضہ مصنوعات اور قیمتیں","answer":"شناخت اور ترمیم کے استعمال کی کوئی حد نہیں۔ پراسیس شدہ تصویر برآمد کرنے کے لیے ہی درست Premium درکار ہے۔ مفت آزمائش کے بغیر خودکار تجدید والی ہفتہ وار اور ماہانہ رکنیتیں اور ایک بار کی تاحیات خرید دستیاب ہے۔ App Store اور Google Play کی خریداریاں الگ ہیں اور پلیٹ فارموں کے درمیان منتقل نہیں ہو سکتیں۔"},{"question":"محفوظ کرنا اور تصویری فارمیٹس","answer":"محفوظ کاری ناکام ہو تو خالی جگہ، فوٹو لائبریری میں محفوظ کرنے کی اجازت اور اصل تصویر کے قابل مطالعہ ہونے کی جانچ کر کے دوبارہ کوشش کریں۔ ایپ ایک وقت میں ایک ساکن تصویر پراسیس کرتی ہے اور زیادہ تر عام فارمیٹس کی معاونت کرتی ہے؛ کچھ آلے اور سسٹم ورژن پر منحصر ہیں۔ ویڈیو، PDF، RAW/DNG اور بیچ پراسیسنگ فی الحال معاون نہیں ہیں۔"},{"question":"زبان کیسے تبدیل کریں؟","answer":"ایپ 40 زبانوں کو معاونت دیتی ہے اور زبان ایپ کی ترتیبات میں تبدیل کی جا سکتی ہے۔ ڈسپلے درست نہ ہونے پر ڈیوائس کی زبان اور ایپ میں منتخب کردہ زبان ای میل کریں۔"},{"question":"بحالی، منسوخی اور رقم کی واپسی","answer":"خریداری اور خریداری کی بحالی Apple یا Google کے سرکاری اسٹور کے ذریعے مکمل ہوتی ہے۔ اسٹور کے درست لین دین کی تصدیق کرنے کے بعد ہی استحقاق دیا جاتا ہے۔ منسوخ، ناکام یا زیر التوا لین دین کامیاب تصدیق سے پہلے استحقاق نہیں دیتے۔ خریداری کی بحالی تاحیات رسائی اور فی الحال فعال سبسکرپشن بحال کر سکتی ہے۔ App Store اور Google Play کی خریداریاں الگ ہیں اور انہیں مختلف پلیٹ فارمز کے درمیان بحال یا منتقل نہیں کیا جا سکتا۔"},{"question":"رازداری اور ڈیٹا حذف کرنا","answer":"ایپ ان انسٹال کر کے ڈیوائس پر موجود ڈیٹا حذف کریں۔ Android پر آپ سسٹم کا ڈیٹا صاف کریں اختیار بھی استعمال کر سکتے ہیں۔ اسٹور خریداری کے ریکارڈ Apple یا Google کے زیر انتظام ہیں۔ بحال کیے جا سکنے والے استحقاقات کی اسٹور کے اصولوں کے تحت دوبارہ تصدیق ہوتی ہے۔ معاونتی ای میلز درخواست سنبھالنے اور ضروری ریکارڈ رکھنے کی شرائط پوری کرنے کے لیے جتنی مدت درکار ہو اتنی مدت رکھی جاتی ہیں۔ آپ ہمارے پاس اب بھی موجود معاونتی خط و کتابت حذف کرنے کی درخواست ای میل کے ذریعے کر سکتے ہیں۔"}],"officialHelpTitle":"فوری مدد"}},"vi":{"linkLabels":{"appleEula":"Thỏa thuận cấp phép người dùng cuối tiêu chuẩn (EULA) của Apple","appleCancel":"Hướng dẫn hủy đăng ký Apple","googleManage":"Hướng dẫn hủy trên Google Play","appleRefund":"Yêu cầu hoàn tiền từ Apple","googleRefund":"Thông tin hoàn tiền của Google Play"},"nav":{"privacy":"Chính sách bảo mật","terms":"Điều khoản sử dụng","support":"Hỗ trợ","language":"Ngôn ngữ","chooseLanguage":"Chọn ngôn ngữ hiển thị","navigationLabel":"Điều hướng chính"},"home":{"eyebrow":"{appName} · Privacy first","title":"Hình ảnh của bạn không được tải lên máy chủ của chúng tôi.","lead":"Việc chọn ảnh, OCR, phát hiện nội dung nhạy cảm, chỉnh sửa và xuất ảnh đều được thực hiện trên thiết bị. Ứng dụng không cung cấp nhận dạng ảnh trên đám mây, đồng bộ đám mây hoặc tài khoản. Khi xuất, ứng dụng tạo ảnh mới và xóa các siêu dữ liệu riêng tư có thể loại bỏ. Tệp làm việc tạm thời được xóa sau khi lưu thành công, khi bỏ chỉnh sửa hoặc kết thúc phiên; nếu lưu thất bại, trạng thái cần thiết có thể được giữ lại để thử lại.","points":["Dữ liệu ứng dụng","Sản phẩm trả phí và giá","Hỗ trợ"],"cards":[{"title":"Chính sách bảo mật","description":"Hình ảnh của bạn không được tải lên máy chủ của chúng tôi.","action":"Chính sách bảo mật"},{"title":"Điều khoản sử dụng","description":"Nhận dạng và chỉnh sửa không giới hạn số lần sử dụng. Chỉ việc xuất ảnh đã xử lý mới cần quyền Premium hợp lệ. Ứng dụng cung cấp gói đăng ký tuần và tháng tự động gia hạn cùng một giao dịch mua trọn đời, không có bản dùng thử miễn phí. Giao dịch mua trên App Store và Google Play độc lập và không thể chuyển giữa hai nền tảng.","action":"Điều khoản sử dụng"},{"title":"Bạn cần trợ giúp?","description":"Hãy bắt đầu với các câu hỏi thường gặp bên dưới. Nếu vấn đề vẫn tiếp diễn, hãy liên hệ với chúng tôi qua địa chỉ email hỗ trợ.","action":"Hỗ trợ"}]},"footer":{"privacy":"Chính sách bảo mật","terms":"Điều khoản sử dụng","support":"Hỗ trợ"},"privacy":{"title":"Chính sách bảo mật","lead":"Chính sách này giải thích cách {appName} xử lý dữ liệu trên thiết bị, thông tin giao dịch mua từ cửa hàng ứng dụng và email hỗ trợ.","sections":[{"title":"1. Phạm vi và thông tin liên hệ","paragraphs":["Chính sách này áp dụng cho ứng dụng {appName} trên iOS, iPadOS và Android, cũng như trang web về quyền riêng tư, điều khoản và hỗ trợ này.","Nếu có thắc mắc về vấn đề bảo mật, vui lòng gửi email. {email}"]},{"title":"2. Dữ liệu ứng dụng","callout":{"title":"Hình ảnh của bạn không được tải lên máy chủ của chúng tôi.","body":"Việc chọn ảnh, OCR, phát hiện nội dung nhạy cảm, chỉnh sửa và xuất ảnh đều được thực hiện trên thiết bị. Ứng dụng không cung cấp nhận dạng ảnh trên đám mây, đồng bộ đám mây hoặc tài khoản. Khi xuất, ứng dụng tạo ảnh mới và xóa các siêu dữ liệu riêng tư có thể loại bỏ. Tệp làm việc tạm thời được xóa sau khi lưu thành công, khi bỏ chỉnh sửa hoặc kết thúc phiên; nếu lưu thất bại, trạng thái cần thiết có thể được giữ lại để thử lại."},"paragraphs":[]},{"title":"3. Quyền truy cập, quảng cáo và theo dõi","paragraphs":["Quyền truy cập ảnh chỉ dùng để hiển thị và xử lý ảnh bạn cho phép. Camera chỉ được dùng khi bạn chọn chụp ảnh trong ứng dụng. Quyền lưu vào thư viện ảnh chỉ được yêu cầu khi bạn xác nhận xuất với quyền Premium hợp lệ. Ứng dụng không yêu cầu vị trí, danh bạ, micrô, Bluetooth hoặc thông báo.","Ứng dụng không sử dụng mã nhận dạng quảng cáo hoặc tích hợp SDK của bên thứ ba cho quảng cáo, phân tích, phân bổ hoặc báo cáo sự cố.","Ứng dụng không tích hợp công cụ báo cáo sự cố của bên thứ ba. Tùy theo cài đặt thiết bị và cửa hàng, Apple hoặc Google có thể xử lý thông tin chẩn đoán hệ thống theo quy tắc quyền riêng tư tương ứng và cung cấp thông tin kỹ thuật dùng để điều tra sự cố hoặc vấn đề hiệu suất."]},{"title":"4. Dịch vụ cửa hàng ứng dụng và truy cập mạng","paragraphs":["Ứng dụng sử dụng Apple StoreKit hoặc Google Play Billing để tải sản phẩm, hiển thị giá theo khu vực do cửa hàng trả về, hoàn tất giao dịch mua, khôi phục giao dịch mua, quản lý gói đăng ký và xác nhận quyền lợi. Quyền truy cập mạng chỉ được dùng cho các tính năng chính thức này của cửa hàng Apple hoặc Google.","Apple hoặc Google chịu trách nhiệm về tài khoản cửa hàng, thanh toán, lập hóa đơn, giao dịch, hoàn tiền và dịch vụ đăng ký. Ứng dụng chỉ xử lý thông tin cửa hàng cần thiết để xác nhận sản phẩm và quyền lợi, đồng thời không nhận hoặc lưu thông tin xác thực thanh toán đầy đủ."]},{"title":"5. Email hỗ trợ và trang web","paragraphs":["Ứng dụng không tự động đọc thông tin email của bạn. Chỉ khi bạn chọn gửi email hỗ trợ, kênh hỗ trợ mới nhận địa chỉ email, nội dung tin nhắn và mọi ảnh chụp màn hình, bản ghi màn hình, mã đơn hàng hoặc tệp đính kèm khác mà bạn tự nguyện cung cấp. Thông tin này chỉ được dùng để xử lý yêu cầu của bạn, không được dùng cho quảng cáo hoặc tiếp thị. Không gửi mật khẩu tài khoản, mật khẩu thanh toán hoặc toàn bộ số thẻ.","Trang web này không đặt cookie quảng cáo hoặc phân tích và không chứa công cụ phân tích lưu lượng hay tập lệnh theo dõi."]},{"title":"6. Lưu giữ và xóa","paragraphs":["Xóa dữ liệu trên thiết bị bằng cách gỡ cài đặt ứng dụng. Trên Android, bạn cũng có thể dùng tùy chọn Xóa dữ liệu của hệ thống.","Hồ sơ giao dịch mua của cửa hàng do Apple hoặc Google quản lý. Các quyền lợi có thể khôi phục sẽ được xác nhận lại theo quy tắc của cửa hàng.","Email hỗ trợ được lưu trong thời gian cần thiết để xử lý yêu cầu và đáp ứng các yêu cầu lưu hồ sơ cần thiết. Bạn có thể gửi email yêu cầu chúng tôi xóa thư từ hỗ trợ mà chúng tôi vẫn đang lưu giữ."]},{"title":"7. Bảo mật dữ liệu","paragraphs":["Ứng dụng sử dụng xử lý trên thiết bị, quyền truy cập tối thiểu và quy trình mua chính thức của cửa hàng ứng dụng để giảm việc truyền dữ liệu không cần thiết. Email hỗ trợ chỉ được dùng để xử lý yêu cầu gửi đến, với các biện pháp bảo vệ hợp lý phù hợp với tính chất của thông tin.","Không có thiết bị, mạng hoặc phương thức lưu trữ điện tử nào có thể được đảm bảo an toàn tuyệt đối. Không đưa thông tin nhạy cảm không liên quan vào email hỗ trợ."]},{"title":"8. Trẻ em và thanh thiếu niên","paragraphs":["Ứng dụng không yêu cầu tài khoản và không tạo hồ sơ về trẻ em hoặc người dùng khác thông qua quảng cáo hoặc phân tích hành vi. Phụ huynh hoặc người giám hộ cho rằng trẻ đã cung cấp thông tin cá nhân qua email hỗ trợ có thể liên hệ với chúng tôi để giải quyết vấn đề."]},{"title":"9. Lựa chọn và quyền của bạn","paragraphs":["Bạn quản lý dữ liệu trên thiết bị thông qua thiết bị của mình. Apple hoặc Google quản lý tài khoản cửa hàng và hồ sơ giao dịch mua. Ứng dụng không thể thay mặt bạn sửa đổi hoặc xóa hồ sơ giao dịch do cửa hàng ứng dụng lưu giữ.","Nếu cách ứng dụng xử lý dữ liệu, quy tắc nền tảng hoặc phương thức lưu trữ trang web thay đổi, chúng tôi sẽ cập nhật Chính sách này và ngày hiển thị trên trang, đồng thời cung cấp thông báo bổ sung khi quy tắc hiện hành yêu cầu.","Nếu có thắc mắc về vấn đề bảo mật, vui lòng gửi email. {email}"]}]},"terms":{"title":"Điều khoản sử dụng","lead":"Điều khoản sử dụng của {appName}.","sections":[{"title":"1. Chấp nhận các Điều khoản và quy tắc của nền tảng.","paragraphs":["Bằng cách tải xuống, mua hoặc sử dụng {appName}, bạn đồng ý với các Điều khoản này và các quy tắc áp dụng cho bạn trong cửa hàng ứng dụng nơi bạn thực hiện mua hàng. Nếu bạn không đồng ý, vui lòng không tiếp tục sử dụng ứng dụng hoặc thực hiện mua hàng.","Các Điều khoản này áp dụng cho việc bạn tải xuống, mua và sử dụng ứng dụng. Phiên bản iOS và iPadOS cũng tuân theo"],"links":["appleEula"]},{"title":"2. Sản phẩm trả phí và giá","paragraphs":["Nhận dạng và chỉnh sửa không giới hạn số lần sử dụng. Chỉ việc xuất ảnh đã xử lý mới cần quyền Premium hợp lệ. Ứng dụng cung cấp gói đăng ký tuần và tháng tự động gia hạn cùng một giao dịch mua trọn đời, không có bản dùng thử miễn phí. Giao dịch mua trên App Store và Google Play độc lập và không thể chuyển giữa hai nền tảng.","Giá, đơn vị tiền tệ, thuế, kỳ thanh toán và điều kiện mua thực tế là thông tin được hiển thị và xác nhận trên màn hình mua hàng của hệ thống App Store hoặc Google Play. Nền tảng mua hàng tính phí và quản lý thanh toán qua tài khoản cửa hàng của bạn. Ứng dụng không cung cấp bản dùng thử miễn phí cho gói đăng ký hoặc gói trả phí khác."]},{"title":"3. Tự động gia hạn và hủy","paragraphs":["Gói đăng ký hàng tuần và hàng tháng tự động gia hạn và được tính phí theo kỳ thanh toán hiển thị trên màn hình mua hàng của hệ thống cho đến khi bạn hủy qua nền tảng mua hàng. Việc xóa {appName} không tự động hủy gói đăng ký. Trừ khi nền tảng mua hàng hoàn tiền hoặc có cách xử lý khác, bạn có thể tiếp tục sử dụng gói đăng ký đến hết kỳ đã thanh toán hiện tại sau khi tắt tự động gia hạn."],"links":["appleCancel","googleManage"]},{"title":"4. Giao dịch mua, khôi phục và hoàn tiền","paragraphs":["Giao dịch mua và khôi phục giao dịch mua được thực hiện qua cửa hàng chính thức của Apple hoặc Google. Quyền lợi chỉ được cấp sau khi cửa hàng xác nhận giao dịch hợp lệ. Giao dịch bị hủy, thất bại hoặc đang chờ xử lý không cấp quyền lợi trước khi được xác nhận thành công. Khôi phục giao dịch mua có thể khôi phục quyền truy cập trọn đời và gói đăng ký hiện đang hoạt động. Giao dịch mua trên App Store và Google Play tách biệt và không thể khôi phục hoặc chuyển giữa các nền tảng.","Việc hoàn tiền do cửa hàng ứng dụng đã hoàn tất giao dịch xử lý theo quy tắc của cửa hàng, khu vực mua và pháp luật hiện hành. Quyền lợi tương ứng sẽ bị xóa sau khi cửa hàng xác nhận hoàn tiền, thu hồi, gói đăng ký hết hạn hoặc giao dịch không hợp lệ."],"links":["appleRefund","googleRefund"]},{"title":"5. Sử dụng ngoại tuyến và tính khả dụng","paragraphs":["Việc chọn ảnh, OCR, phát hiện nội dung nhạy cảm, chỉnh sửa và xuất ảnh đều được thực hiện trên thiết bị. Ứng dụng không cung cấp nhận dạng ảnh trên đám mây, đồng bộ đám mây hoặc tài khoản. Khi xuất, ứng dụng tạo ảnh mới và xóa các siêu dữ liệu riêng tư có thể loại bỏ. Tệp làm việc tạm thời được xóa sau khi lưu thành công, khi bỏ chỉnh sửa hoặc kết thúc phiên; nếu lưu thất bại, trạng thái cần thiết có thể được giữ lại để thử lại."]},{"title":"6. Sử dụng được chấp nhận và quyền sở hữu trí tuệ","paragraphs":["Bạn không được sử dụng ứng dụng cho hoạt động trái pháp luật; vượt qua bước xác minh mua hàng; làm hỏng ứng dụng; phân phối mã độc; sao chép hoặc phân phối ứng dụng khi chưa được phép; hoặc xâm phạm quyền đối với nội dung ứng dụng hay quyền sở hữu trí tuệ của người khác.","Bạn có thể ngừng sử dụng và gỡ cài đặt ứng dụng bất cứ lúc nào. Chúng tôi có thể phát hành bản cập nhật để khắc phục sự cố, hỗ trợ hệ điều hành, cải thiện độ ổn định hoặc đáp ứng yêu cầu của nền tảng. Sự cố thiết bị, hệ thống, mạng hoặc dịch vụ cửa hàng có thể khiến một số tính năng tạm thời không khả dụng.","Trong phạm vi pháp luật hiện hành cho phép, ứng dụng được cung cấp theo tình trạng sẵn có. Các Điều khoản này không loại trừ trách nhiệm mà pháp luật không cho phép loại trừ hoặc hạn chế quyền bắt buộc của người tiêu dùng dành cho bạn.","Nếu tính năng sản phẩm, phương thức thanh toán, quy tắc nền tảng hoặc pháp luật hiện hành thay đổi, chúng tôi có thể cập nhật các Điều khoản này và ngày hiển thị trên trang. Nếu thay đổi ảnh hưởng đáng kể đến quyền của người dùng, chúng tôi sẽ cung cấp thông báo bổ sung theo yêu cầu.","Nếu có thắc mắc về các Điều khoản này, việc mua hàng hoặc sử dụng ứng dụng, vui lòng gửi email. {email}"]}]},"support":{"title":"Hỗ trợ","lead":"Hãy bắt đầu với các câu hỏi thường gặp bên dưới. Nếu vấn đề vẫn tiếp diễn, hãy liên hệ với chúng tôi qua địa chỉ email hỗ trợ.","emailTitle":"Email hỗ trợ của {appName}","emailLead":"Hãy bắt đầu với các câu hỏi thường gặp bên dưới. Nếu vấn đề vẫn tiếp diễn, hãy liên hệ với chúng tôi qua địa chỉ email hỗ trợ.","beforeEmail":{"title":"Nội dung cần có trong email","paragraphs":["Đối với vấn đề về giao dịch mua, bạn có thể cung cấp mã đơn hàng của cửa hàng ứng dụng, nhưng không gửi mật khẩu tài khoản, mật khẩu thanh toán hoặc thông tin đầy đủ của thẻ."],"bullets":["nền tảng, mẫu thiết bị, phiên bản hệ điều hành và phiên bản ứng dụng của bạn;","thao tác bạn đã thực hiện trước khi xảy ra vấn đề, điều bạn mong đợi và điều thực tế đã xảy ra; và","Nếu cần, hãy chụp ảnh màn hình hoặc quay video màn hình với thông tin cá nhân được che giấu."]},"faqs":[{"question":"Hình ảnh có được tải lên máy chủ không?","answer":"Việc chọn ảnh, OCR, phát hiện nội dung nhạy cảm, chỉnh sửa và xuất ảnh đều được thực hiện trên thiết bị. Ứng dụng không cung cấp nhận dạng ảnh trên đám mây, đồng bộ đám mây hoặc tài khoản. Khi xuất, ứng dụng tạo ảnh mới và xóa các siêu dữ liệu riêng tư có thể loại bỏ. Tệp làm việc tạm thời được xóa sau khi lưu thành công, khi bỏ chỉnh sửa hoặc kết thúc phiên; nếu lưu thất bại, trạng thái cần thiết có thể được giữ lại để thử lại."},{"question":"Quyền truy cập, quảng cáo và theo dõi","answer":"Quyền truy cập ảnh chỉ dùng để hiển thị và xử lý ảnh bạn cho phép. Camera chỉ được dùng khi bạn chọn chụp ảnh trong ứng dụng. Quyền lưu vào thư viện ảnh chỉ được yêu cầu khi bạn xác nhận xuất với quyền Premium hợp lệ. Ứng dụng không yêu cầu vị trí, danh bạ, micrô, Bluetooth hoặc thông báo."},{"question":"Sản phẩm trả phí và giá","answer":"Nhận dạng và chỉnh sửa không giới hạn số lần sử dụng. Chỉ việc xuất ảnh đã xử lý mới cần quyền Premium hợp lệ. Ứng dụng cung cấp gói đăng ký tuần và tháng tự động gia hạn cùng một giao dịch mua trọn đời, không có bản dùng thử miễn phí. Giao dịch mua trên App Store và Google Play độc lập và không thể chuyển giữa hai nền tảng."},{"question":"Lưu và định dạng hình ảnh","answer":"Nếu lưu thất bại, hãy kiểm tra dung lượng trống, quyền lưu vào thư viện ảnh và khả năng đọc ảnh gốc rồi thử lại. Ứng dụng xử lý mỗi lần một ảnh tĩnh và hỗ trợ hầu hết định dạng phổ biến; một số định dạng phụ thuộc vào thiết bị và phiên bản hệ thống. Hiện chưa hỗ trợ video, PDF, RAW/DNG và xử lý hàng loạt."},{"question":"Làm cách nào để đổi ngôn ngữ?","answer":"Ứng dụng hỗ trợ 40 ngôn ngữ và bạn có thể thay đổi ngôn ngữ trong phần cài đặt của ứng dụng. Nếu hiển thị không đúng, hãy gửi email cho biết ngôn ngữ thiết bị và ngôn ngữ đã chọn trong ứng dụng."},{"question":"Khôi phục, hủy và hoàn tiền","answer":"Giao dịch mua và khôi phục giao dịch mua được thực hiện qua cửa hàng chính thức của Apple hoặc Google. Quyền lợi chỉ được cấp sau khi cửa hàng xác nhận giao dịch hợp lệ. Giao dịch bị hủy, thất bại hoặc đang chờ xử lý không cấp quyền lợi trước khi được xác nhận thành công. Khôi phục giao dịch mua có thể khôi phục quyền truy cập trọn đời và gói đăng ký hiện đang hoạt động. Giao dịch mua trên App Store và Google Play tách biệt và không thể khôi phục hoặc chuyển giữa các nền tảng."},{"question":"Quyền riêng tư và xóa dữ liệu","answer":"Xóa dữ liệu trên thiết bị bằng cách gỡ cài đặt ứng dụng. Trên Android, bạn cũng có thể dùng tùy chọn Xóa dữ liệu của hệ thống. Hồ sơ giao dịch mua của cửa hàng do Apple hoặc Google quản lý. Các quyền lợi có thể khôi phục sẽ được xác nhận lại theo quy tắc của cửa hàng. Email hỗ trợ được lưu trong thời gian cần thiết để xử lý yêu cầu và đáp ứng các yêu cầu lưu hồ sơ cần thiết. Bạn có thể gửi email yêu cầu chúng tôi xóa thư từ hỗ trợ mà chúng tôi vẫn đang lưu giữ."}],"officialHelpTitle":"Hỗ trợ nhanh"}}}};
